# --- the Many: a superposition; members apply elementwise, equal things collapse ---------------
class Many
  attr_accessor :items
  def initialize(items) = @items = items.to_a
  def length = @items.length
  def empty? = @items.empty?
  def to_a = @items
  def each(&b) = @items.each(&b)
  def filter(f) = Ops.many(@items.select { |x| Ops.truthy(f.(x)) })
  def map(&b) = @items.map(&b)
  def any?(&b) = @items.any?(&b)
  def all?(&b) = @items.all?(&b)
  def method_missing(name, *args, &b)
    if name.end_with?("=")
      @items.each { |i| i.public_send(name, *args) }
      return args[0]
    end
    Ops.collapse(@items.map { |i| i.nil? ? nil : i.public_send(name, *args, &b) })
  end
  def respond_to_missing?(*) = true
end

# --- what every emitted class stands on ------------------------------------------------------
class Node
  def initialize(**kw)
    kw.each { |k, v| __put(k.to_s, v) }
  end
  # a field by name: a declared one through its accessor, any other in the node's own slots
  def __get(k)
    k = k.to_s
    return public_send(k) if respond_to?(k) && !(@slots_ && @slots_.key?(k))
    (@slots_ ||= {})[k]
  end
  def __put(k, v)
    k = k.to_s
    return public_send("#{k}=", v) if respond_to?("#{k}=")
    (@slots_ ||= {})[k] = v
  end
  def method_missing(name, *args)
    n = name.to_s
    if n.end_with?("=") && args.length == 1
      (@slots_ ||= {})[n[0..-2]] = args[0]
      return args[0]
    end
    if @slots_ && @slots_.key?(n)
      v = @slots_[n]
      return args.empty? ? v : v.(*args)
    end
    super
  end
  def respond_to_missing?(name, priv = false) = (@slots_ && @slots_.key?(name.to_s)) || super
  def __slots = (@slots_ || {}).dup
  def choose(name) = method("choose_#{name.to_s.gsub(/[^A-Za-z0-9_]/, "_")}")
  # the constants a class body sets, readable as its statics and on its instances, as in every other language
  def self.__exposed
    constants(false).each do |c|
      v = const_get(c)
      next if v.is_a?(Module)
      define_singleton_method(c) { v } unless singleton_class.method_defined?(c)
      define_method(c) { v } unless method_defined?(c)
    end
  end
end

