def self.collect_theorems(theory) = theory.class.constants(false).select { |c| c.to_s.start_with?("THEOREM_") }.map { |c| theory.class.const_get(c) }
def self.collect_rules(theory) = theory.class.constants(false).select { |c| c.to_s.start_with?("RULE_") }.map { |c| theory.class.const_get(c) }

