class Bodies < Node
  def self.begin(holes)
    Ops.list(holes).each do |h|
      h.stepped = false
      h.moved_along = nil
    end
  end
  def self.radiate(of, rules, holes)
    about = Ops.filt(rules, ->(r) {
      return Ops.eq(r.over, "Boundary")
    })
    Ops.list(about).each do |rule|
      Ops.list(holes).each do |h|
        Ops.list(h.cells).each do |cell|
          here = Cell.new(of: of, index: cell.index)
          of.geometry.DEG.times do |a|
            beam = Beam.new(vertex: here, exit: a, count: of.was_at(a, cell.index))
            beam.recoil = h.per_way
            port = Port.new(vertex: here, ray: beam)
            if (Ops.eq(rule.where, nil) || rule.where(port))
              rule.apply(port)
            end
          end
        end
      end
    end
  end
  def self.enter(of, h, c)
    h.world = Around.new(geometry: of.fine_geometry, DEG: of.DEG)
    h.momentum = Vector.new(components: [h.px, h.py])
    h.advance = Vector.zero(2)
    stood = Cell.new(of: of, index: (Ops.lt(c, 0) ? 0 : c))
    stood.fine = true
    h.cells = (Ops.lt(c, 0) ? [] : [stood])
  end
  def self.transport(of, rules, holes)
    about = Ops.filt(rules, ->(r) {
      return Ops.eq(r.over, "Source")
    })
    Ops.list(about).each do |rule|
      Ops.list(holes).each do |h|
        if (Ops.eq(rule.where, nil) || rule.where(h))
          rule.apply(h)
        end
        if h.stepped
          h.moved = Ops.add(h.moved, 1)
          first_ = Ops.elem(h.cells, 0)
          h.x = of.column_of(first_.index)
          h.y = of.row_of(first_.index)
        end
      end
    end
  end
  __exposed
end

