        j = Ops.add(Ops.mul(self.opposite(b), self.cells), h)
        s = (Ops.lt(h, 0) ? 0 : Ops.mul(Ops.elem(self.fold_was, j), self.edge))
        if Ops.gt(s, 1)
          s = 1
        end
        total = Ops.add(total, s)
        r = (Ops.lt(h, 0) ? 0 : Ops.mul((Ops.sub(Ops.elem(self.fold, j), Ops.elem(self.fold_was, j))), self.edge))
        Ops.set_at(self.swallow, Ops.add(Ops.mul(b, self.cells), c), (Ops.lt(r, 0) ? 0 : r))
        now = Ops.add(now, ((Ops.lt(r, 0) ? 0 : r)))
      end
      inside = (Ops.gt(now, 1) ? 1 : now)
      self.A.times do |b|
        Ops.set_at(self.swallow, Ops.add(Ops.mul(b, self.cells), c), (Ops.gt(now, 0) ? Ops.div(Ops.mul(inside, Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c))), now) : 0))
      end
      Ops.set_at(self.alive, c, Ops.sub(1, inside))
    end
  end
  def sinks_at(c)
    x = 0
    y = 0
    self.A.times do |b|
      s = Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c))
      x = Ops.add(x, Ops.div(Ops.mul(s, self.hop_x(b)), self.K))
      y = Ops.add(y, Ops.div(Ops.mul(s, self.hop_y(b)), self.K))
    end
    return Vector.new(components: [x, y])
  end
  def drift_from(c, d)
    x = 0
    y = 0
    came = self.opposite(d)
    self.A.times do |b|
      s = Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c))
      along = (Ops.eq(b, came) ? d : b)
      x = Ops.add(x, Ops.div(Ops.mul(s, self.hop_x(along)), self.K))
      y = Ops.add(y, Ops.div(Ops.mul(s, self.hop_y(along)), self.K))
    end
    return Vector.new(components: [x, y])
  end
  def owns(c, a)
    s = Ops.mul(Ops.elem(self.fold_was, Ops.add(Ops.mul(a, self.cells), c)), self.edge)
    return (Ops.gt(s, 1) ? 1 : s)
  end
  def create(terms)
    Ops.list(terms).each do |t|
      self.cells.times do |c|
        fires = Ops.mul(self.share(t, c), ((Ops.gt(t.degree, 0) ? Ops.power(Ops.elem(self.rho, c), t.degree) : 1)))
        if Ops.gt(fires, 0)
          per = Ops.div(self.count(t, "rays", c), self.DEG)
          self.A.times do |a|
            i = Ops.add(Ops.mul(a, self.cells), c)
            made = (t.doing.sets ? Ops.mul(self.share_at(t, c, i), ((Ops.gt(t.degree, 0) ? Ops.power(Ops.elem(self.rho, c), t.degree) : 1))) : fires)
            Ops.set_at(self.dN, i, Ops.add(Ops.elem(self.dN, i), Ops.mul(made, per)))
          end
          Ops.set_at(self.space, c, Ops.add(Ops.elem(self.space, c), Ops.mul(fires, self.count(t, "space", c))))
          df = Ops.div(Ops.mul(fires, self.count(t, "folds", c)), self.DEG)
          self.A.times do |a|
            f = Ops.add(Ops.elem(self.fold, Ops.add(Ops.mul(a, self.cells), c)), df)
            Ops.set_at(self.fold, Ops.add(Ops.mul(a, self.cells), c), (Ops.lt(f, 0) ? 0 : f))
          end
        end
      end
    end
  end
  def bodily(i)
    whole = Ops.elem(self.was, i)
    if Ops.le(whole, 0)
      return 0
    end
    b = 0
    Ops.sub(self.tags, 1).times do |z|
      b = Ops.add(b, Ops.elem(Ops.elem(self.by, z), i))
    end
    b = Ops.div(b, whole)
    return (Ops.lt(b, 0) ? 0 : ((Ops.gt(b, 1) ? 1 : b)))
  end
  def crossing(i, j, found)
    if Ops.lt(self.tags, 3)
      return 0
    end
    wi = Ops.elem(found, i)
    wj = Ops.elem(found, j)
    if (Ops.le(wi, 0) || Ops.le(wj, 0))
      return 0
    end
    f1i = Ops.div(Ops.elem(Ops.elem(self.by, 0), i), wi)
    f1j = Ops.div(Ops.elem(Ops.elem(self.by, 0), j), wj)
    alli = 0
    allj = 0
    Ops.sub(self.tags, 1).times do |z|
      alli = Ops.add(alli, Ops.elem(Ops.elem(self.by, z), i))
      allj = Ops.add(allj, Ops.elem(Ops.elem(self.by, z), j))
    end
    alli = Ops.div(alli, wi)
    allj = Ops.div(allj, wj)
    return Ops.add(Ops.mul(f1i, (Ops.sub(allj, f1j))), Ops.mul((Ops.sub(alli, f1i)), f1j))
  end
  def meet(terms)
    Ops.list(terms).each do |t|
      found = self.was
      act = Ops.m_map(Ops.rng(Ops.mul(self.cells, self.A)), ->(i) {
        return self.activity(Ops.elem(self.was, i))
      })
      self.A.times do |a|
        o = self.opposite(a)
        self.cells.times do |c|
          i = Ops.add(Ops.mul(a, self.cells), c)
          ts = self.hop(c, a)
          facing = 0
          mixed = 0
          there_b = 0
          Ops.list(ts).each do |tp|
            j = Ops.add(Ops.mul(o, self.cells), Ops.elem(tp, 0))
            facing = Ops.add(facing, Ops.mul(Ops.elem(tp, 1), Ops.elem(act, j)))
            mixed = Ops.add(mixed, Ops.mul(Ops.mul(Ops.elem(tp, 1), Ops.elem(act, j)), self.crossing(i, j, found)))
            there_b = Ops.add(there_b, Ops.mul(Ops.elem(tp, 1), self.bodily(j)))
          end
          beyond = Ops.sub(1, self.inside(ts))
          if Ops.gt(beyond, 0)
            j = Ops.add(Ops.mul(o, self.cells), c)
            facing = Ops.add(facing, Ops.mul(beyond, Ops.elem(act, j)))
            mixed = Ops.add(mixed, Ops.mul(Ops.mul(beyond, Ops.elem(act, j)), self.crossing(i, j, found)))
            there_b = Ops.add(there_b, Ops.mul(beyond, self.bodily(j)))
          end
          w = Ops.mul(Ops.mul(Ops.elem(act, i), facing), self.share(t, c))
          if Ops.gt(w, 0)
            rays = Ops.div(Ops.mul(w, self.count(t, "rays", c)), 2)
            Ops.set_at(self.taken, i, Ops.add(Ops.elem(self.taken, i), rays))
            ds = Ops.div(Ops.mul(w, self.count(t, "space", c)), 2)
            Ops.set_at(self.space, c, Ops.add(Ops.elem(self.space, c), Ops.mul(ds, self.edge)))
            mine = Ops.add(0.5, Ops.mul(0.5, (Ops.sub(self.bodily(i), there_b))))
            f = Ops.add(Ops.elem(self.fold, i), Ops.mul(Ops.mul(w, self.count(t, "folds", c)), mine))
            Ops.set_at(self.fold, i, (Ops.lt(f, 0) ? 0 : f))
            folded = Ops.div(Ops.mul(w, self.count(t, "folds", c)), 2)
            lost = (Ops.gt(folded, 0) ? folded : 0)
            Ops.set_at(self.destroyed, c, Ops.add(Ops.elem(self.destroyed, c), Ops.mul(lost, self.edge)))
            Ops.set_at(self.cross, c, Ops.add(Ops.elem(self.cross, c), Ops.mul(Ops.mul(lost, self.edge), ((Ops.gt(facing, 0) ? Ops.div(mixed, facing) : 0)))))
          end
        end
      end
    end
  end
  def moving(a, c)
    return self.view(Ops.add(Ops.mul(a, self.cells), c))
  end
  def moving_of(z, a, c)
    i = Ops.add(Ops.mul(a, self.cells), c)
    had = Ops.elem(Ops.elem(self.by, z), i)
    whole = Ops.elem(self.was, i)
    if (Ops.le(had, 0) || Ops.le(whole, 0))
      return 0
    end
    f = Ops.div((Ops.add(Ops.add(whole, Ops.elem(self.taken, i)), Ops.elem(self.absorbed, i))), whole)
    if Ops.lt(f, 0)
      f = 0
    end
    return Ops.mul(had, f)
  end
  def turned
    t = self.transport_term
    return (Ops.eq(t, nil) ? "kept" : t.turned)
  end
  def carried(pop)
    out = Ops.filled(Ops.mul(self.cells, self.A), 0)
    onto_way = Ops.eq(self.turned, "way")
    self.A.times do |a|
      self.cells.times do |c|
        got = 0
        Ops.list(self.back(c, a)).each do |tp|
          src = Ops.elem(tp, 0)
          got = Ops.add(got, Ops.mul(Ops.mul(Ops.mul(Ops.elem(tp, 1), pop.(a, src)), Ops.elem(self.keep, src)), (Ops.sub(1, self.owns(src, a)))))
        end
        Ops.list(self.back2(c, a)).each do |tp|
          src = Ops.elem(tp, 0)
          got = Ops.add(got, Ops.mul(Ops.mul(Ops.mul(Ops.elem(tp, 1), pop.(a, src)), Ops.elem(self.keep, src)), self.owns(src, a)))
          if onto_way
            fa = Ops.elem(self.fold_was, Ops.add(Ops.mul(a, self.cells), src))
            if Ops.gt(fa, 0)
              self.A.times do |b|
                got = Ops.add(got, Ops.mul(Ops.mul(Ops.mul(Ops.mul(Ops.elem(tp, 1), pop.(b, src)), fa), Ops.elem(self.keep, src)), self.edge))
              end
            end
          end
        end
        unless onto_way
          self.A.times do |d|
            Ops.list(self.back2(c, d)).each do |tp|
              sd = Ops.elem(tp, 0)
              fd = Ops.elem(self.fold_was, Ops.add(Ops.mul(d, self.cells), sd))
              if Ops.gt(fd, 0)
                got = Ops.add(got, Ops.mul(Ops.mul(Ops.mul(Ops.mul(Ops.elem(tp, 1), pop.(a, sd)), fd), Ops.elem(self.keep, sd)), self.edge))
              end
            end
          end
        end
        Ops.set_at(out, Ops.add(Ops.mul(a, self.cells), c), got)
      end
    end
    return self.funnelled(out)
  end
  def funnelled(landed)
    out = Ops.filled(Ops.mul(self.cells, self.A), 0)
    self.A.times do |a|
      self.cells.times do |c|
        x = Ops.elem(landed, Ops.add(Ops.mul(a, self.cells), c))
        if Ops.gt(x, 0)
          total = 0
          self.A.times do |b|
            if (!Ops.eq(b, self.opposite(a)) && Ops.ge(self.hop_from(c, b), 0))
              total = Ops.add(total, Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c)))
            end
          end
          scale = (Ops.gt(total, 1) ? Ops.div(1, total) : 1)
          stays = 1
          self.A.times do |b|
            s = Ops.mul(Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c)), scale)
            if (Ops.gt(s, 0) && !Ops.eq(b, self.opposite(a)))
              h = self.hop_from(c, b)
              if Ops.ge(h, 0)
                Ops.set_at(out, Ops.add(Ops.mul(a, self.cells), h), Ops.add(Ops.elem(out, Ops.add(Ops.mul(a, self.cells), h)), Ops.mul(x, s)))
                stays = Ops.sub(stays, s)
              end
            end
          end
          Ops.set_at(out, Ops.add(Ops.mul(a, self.cells), c), Ops.add(Ops.elem(out, Ops.add(Ops.mul(a, self.cells), c)), Ops.mul(x, ((Ops.lt(stays, 0) ? 0 : stays)))))
        end
      end
    end
    return out
  end
  def carry
    self.out = self.carried(->(a, c) {
      return self.moving(a, c)
    })
    Ops.sub(self.tags, 1).times do |z|
      Ops.set_at(self.by, z, self.carried(->(a, c) {
        return self.moving_of(z, a, c)
      }))
    end
    self.moved = true
  end
  def settle
    if !(self.moved)
      self.carry
    end
    Ops.mul(self.cells, self.A).times do |i|
      Ops.set_at(self.n, i, Ops.add(Ops.elem(self.out, i), Ops.elem(self.dN, i)))
      Ops.sub(self.tags, 1).times do |z|
        Ops.set_at(Ops.elem(self.by, z), i, Ops.add(Ops.elem(Ops.elem(self.by, z), i), Ops.elem(Ops.elem(self.by_emitted, z), i)))
      end
    end
    self.settled = true
  end
  def moved(*args_)
    @moved = (false) unless instance_variable_defined?(:@moved)
    args_.empty? ? @moved : @moved.(*args_)
  end
  attr_writer :moved
  def settled(*args_)
    @settled = (false) unless instance_variable_defined?(:@settled)
    args_.empty? ? @settled : @settled.(*args_)
  end
  attr_writer :settled
  def arrived(z, c)
    total = 0
    self.A.times do |a|
      total = Ops.add(total, Ops.elem(self.n, Ops.add(Ops.mul(a, self.cells), c)))
    end
    if Ops.eq(z, 0)
      Ops.sub(self.tags, 1).times do |k|
        self.A.times do |a|
          total = Ops.sub(total, Ops.elem(Ops.elem(self.by, k), Ops.add(Ops.mul(a, self.cells), c)))
        end
      end
      return (Ops.lt(total, 0) ? 0 : Ops.mul(total, self.edge))
    end
    got = 0
    self.A.times do |a|
      got = Ops.add(got, Ops.elem(Ops.elem(self.by, Ops.sub(z, 1)), Ops.add(Ops.mul(a, self.cells), c)))
    end
    return Ops.mul(got, self.edge)
  end
  def crossed(c)
    return Ops.elem(self.cross, c)
  end
  def t
    return self.ticks
  end
  def bodies
    return self.holes
  end
  def geometry(*args_)
    @geometry = (Geometry.new(name: "line-#{self.A}", offsets: Ops.m_map(Ops.rng(self.A), ->(a) {
    return Vector.new(components: [Ops.div(self.hop_x(a), self.K), Ops.div(self.hop_y(a), self.K)])
  }))) unless instance_variable_defined?(:@geometry)
    args_.empty? ? @geometry : @geometry.(*args_)
  end
  attr_writer :geometry
  def column_of(c)
    return Ops.mod(c, self.N)
  end
  def row_of(c)
    return Ops.div((Ops.sub(c, Ops.mod(c, self.N))), self.N)
  end
  def self.whole(x)
    y = Ops.div(Ops.m_round((Ops.mul(x, 1000000))), 1000000)
    return (Ops.lt(y, 0) ? Ops.sub(0, Ops.m_floor((Ops.add((Ops.sub(0, y)), 0.5)))) : Ops.m_floor((Ops.add(y, 0.5))))
  end
  def hop_x(d)
    return Field.whole(Ops.mul(self.K, Ops.elem(self.ux, d)))
  end
  def hop_y(d)
    return Field.whole(Ops.mul(self.K, Ops.elem(self.uy, d)))
  end
  def hop_from(c, d)
    return self.at(Ops.add(self.column_of(c), self.hop_x(d)), Ops.add(self.row_of(c), self.hop_y(d)))
  end
  def near_x(d)
    return Field.whole(Ops.elem(self.ux, d))
  end
  def near_y(d)
    return Field.whole(Ops.elem(self.uy, d))
  end
  def near_from(c, d)
    return self.at(Ops.add(self.column_of(c), self.near_x(d)), Ops.add(self.row_of(c), self.near_y(d)))
  end
  def fine_geometry(*args_)
    @fine_geometry = (Geometry.new(name: "cells-#{self.A}", offsets: Ops.m_map(Ops.rng(self.A), ->(a) {
    return Vector.new(components: [Ops.div(self.near_x(a), self.K), Ops.div(self.near_y(a), self.K)])
  }))) unless instance_variable_defined?(:@fine_geometry)
    args_.empty? ? @fine_geometry : @fine_geometry.(*args_)
  end
  attr_writer :fine_geometry
  def blocks_at(c)
    return Ops.elem(self.blocks, c)
  end
  def source_at(c)
    return (Ops.gt(Ops.elem(self.blocks, c), 0) ? Ops.elem(self.holes, Ops.sub(Ops.elem(self.blocks, c), 1)) : nil)
  end
  def was_at(a, c)
    return self.view(Ops.add(Ops.mul(a, self.cells), c))
  end
  def folds_at(c)
    return Ops.m_map(Ops.rng(self.A), ->(e) {
      return Ops.mul(Ops.elem(self.fold_was, Ops.add(Ops.mul(e, self.cells), c)), self.edge)
    })
  end
  def absorb(a, c, count)
    i = Ops.add(Ops.mul(a, self.cells), c)
    Ops.set_at(self.dN, i, Ops.sub(Ops.elem(self.dN, i), count))
    Ops.set_at(self.absorbed, i, Ops.sub(Ops.elem(self.absorbed, i), count))
  end
  def light(a, c, count, tag)
    Ops.list(self.point_of(c)).each do |cell|
      i = Ops.add(Ops.mul(a, self.cells), cell)
      Ops.set_at(self.dN, i, Ops.add(Ops.elem(self.dN, i), count))
      Ops.set_at(self.emitted, i, Ops.add(Ops.elem(self.emitted, i), count))
      if ((!Ops.eq(tag, nil) && Ops.gt(tag, 0)) && Ops.lt(tag, self.tags))
        Ops.set_at(Ops.elem(self.by_emitted, Ops.sub(tag, 1)), i, Ops.add(Ops.elem(Ops.elem(self.by_emitted, Ops.sub(tag, 1)), i), count))
      end
    end
  end
  def point_of(c)
    x = self.column_of(c)
    y = self.row_of(c)
    half = Ops.m_floor((Ops.div((Ops.sub(self.K, 1)), 2)))
    out = []
    self.K.times do |dy|
      self.K.times do |dx|
        cell = self.at(Ops.add(Ops.sub(x, half), dx), Ops.add(Ops.sub(y, half), dy))
        if Ops.ge(cell, 0)
          Ops.m_push(out, cell)
        end
      end
    end
    return out
  end
  def block
    self.cells.times do |c|
      Ops.set_at(self.blocks, c, 0)
    end
    self.holes.length.times do |k|
      Ops.list(Ops.elem(self.holes, k).cells).each do |cell|
        Ops.set_at(self.blocks, cell.index, Ops.add(k, 1))
      end
    end
  end
  def mass(h)
    return h.mass
  end
  def lean_toward(cx, cy, r)
    total = 0
    count = 0
    48.times do |k|
      th = Ops.div(Ops.mul((2 * Math::PI), k), 48)
      c = self.at(Ops.add(cx, Ops.m_round((Ops.mul(Ops.mul(r, self.K), Ops.m_cos(th))))), Ops.add(cy, Ops.m_round((Ops.mul(Ops.mul(r, self.K), Ops.m_sin(th))))))
      if Ops.ge(c, 0)
        inward = 0
        self.A.times do |b|
          inward = Ops.sub(inward, Ops.mul(Ops.elem(self.swallow, Ops.add(Ops.mul(b, self.cells), c)), (Ops.add(Ops.mul(Ops.elem(self.ux, b), Ops.m_cos(th)), Ops.mul(Ops.elem(self.uy, b), Ops.m_sin(th))))))
        end
        total = Ops.add(total, inward)
        count = Ops.add(count, 1)
      end
    end
    return (Ops.eq(count, 0) ? 0 : Ops.div(total, count))
  end
  def thrown(x, y, mx, ways, px, py, tag)
    h = Hole.new(x: x, y: y, mx: mx, ways: ways)
    h.tag = tag
    h.moves = true
    h.px = px
    h.py = py
    self.add(h)
    return self
  end
  def tick
    Ops.mul(self.cells, self.A).times do |i|
      Ops.set_at(self.was, i, Ops.elem(self.n, i))
      Ops.set_at(self.fold_was, i, Ops.elem(self.fold, i))
      Ops.set_at(self.dN, i, 0)
      Ops.set_at(self.taken, i, 0)
      Ops.set_at(self.absorbed, i, 0)
      Ops.set_at(self.emitted, i, 0)
    end
    Ops.sub(self.tags, 1).times do |z|
      Ops.mul(self.cells, self.A).times do |i|
        Ops.set_at(Ops.elem(self.by_emitted, z), i, 0)
      end
    end
    self.cells.times do |c|
      Ops.set_at(self.destroyed, c, 0)
      Ops.set_at(self.cross, c, 0)
    end
    self.moved = false
    self.settled = false
    Bodies.begin(self.holes)
    self.sweep
    self.tally
    Ops.list(self.theory.rules).each do |rule|
      if Ops.eq(rule.over, "Boundary")
        Bodies.radiate(self, [rule], self.holes)
      else
        if Ops.eq(rule.over, "Source")
          Bodies.transport(self, [rule], self.holes)
          self.block
        else
          ts = Ops.filt(self.terms, ->(t) {
            return (!Ops.eq(t.rule, nil) && Ops.eq(t.rule.id, rule.id))
          })
          meetings = Ops.filt(ts, ->(t) {
            return ((!(t.settles) && !(t.transport)) && Ops.eq(t.degree, 2))
          })
          points = Ops.filt(ts, ->(t) {
            return (((!(t.settles) && !(t.transport)) && !Ops.eq(t.degree, 2)) && !(t.outside))
          })
          if !(Ops.m_empty(meetings))
            self.meet(meetings)
          end
          if !(Ops.m_empty(points))
            self.create(points)
          end
          if Ops.m_some(ts, ->(t) {
            return t.transport
          })
            self.locate
            self.carry
          end
        end
      end
    end
    self.settle
    self.sweep_n
    total = 0
    self.cells.times do |c|
      total = Ops.add(total, Ops.elem(self.rho, c))
    end
    self.seen = Ops.add(self.seen, 1)
    span = (Ops.lt(self.seen, 512) ? self.seen : 512)
    self.ambient = Ops.add(self.ambient, Ops.div((Ops.sub(Ops.div(total, self.cells), self.ambient)), span))
    self.ticks = Ops.add(self.ticks, 1)
  end
  def sweep_n
    self.cells.times do |c|
      Ops.set_at(self.rho, c, 0)
    end
    self.A.times do |a|
      base = Ops.mul(a, self.cells)
      self.cells.times do |c|
        Ops.set_at(self.rho, c, Ops.add(Ops.elem(self.rho, c), self.activity(Ops.elem(self.n, Ops.add(base, c)))))
      end
    end
    self.cells.times do |c|
      Ops.set_at(self.rho, c, Ops.div(Ops.elem(self.rho, c), self.A))
    end
  end
  def add(h)
    Ops.m_push(self.holes, h)
    Bodies.enter(self, h, self.at(Ops.m_round(h.x), Ops.m_round(h.y)))
    self.block
    return h
  end
  def density(c)
    return Ops.elem(self.rho, c)
  end
  def mean
    total = 0
    self.cells.times do |c|
      total = Ops.add(total, Ops.elem(self.rho, c))
    end
    return Ops.div(total, self.cells)
  end
  __exposed
end

