class Solve < Node
  def self.settles(_R)
    a = Ops.mul(_R.sigma, _R.F)
    b = _R.nu
    c = Ops.neg(_R.nu)
    if Ops.eq(a, 0)
      return 1
    end
    return Ops.div((Ops.add(Ops.neg(b), Ops.m_sqrt((Ops.sub(Ops.mul(b, b), Ops.mul(Ops.mul(4, a), c)))))), (Ops.mul(2, a)))
  end
  def self.root(s, name, f)
    had = Ops.elem(s, name)
    at = ->(x) {
      Ops.set_at(s, name, x)
      return f.(s)
    }
    lo = 0
    hi = 1
    flo = at.(lo)
    fhi = at.(hi)
    if Ops.gt(Ops.mul(flo, fhi), 0)
      Ops.set_at(s, name, had)
      return (Ops.lt(Ops.m_abs(flo), Ops.m_abs(fhi)) ? lo : hi)
    end
    i = 0
    while Ops.lt(i, 60)
      mid = Ops.div((Ops.add(lo, hi)), 2)
      fm = at.(mid)
      if Ops.le(Ops.mul(fm, flo), 0)
        hi = mid
      else
        lo = mid
        flo = fm
      end
      i = Ops.add(i, 1)
    end
    Ops.set_at(s, name, had)
    return Ops.div((Ops.add(lo, hi)), 2)
  end
  def self.sweep(_R, geometry, radius, size = 41, passes = 400, tol = 0.000000000001)
    _L = size
    _D = geometry.D
    rho = Solve.settles(_R)
    c = Ops.div(Ops.sub(_L, 1), 2)
    cells = Ops.power(_L, _D)
    stride = Ops.m_map(Ops.rng(_D), ->(i) {
      return Ops.power(_L, i)
    })
    step = Ops.m_map(geometry.offsets, ->(v) {
      return Ops.m_map(v.components, ->(x) {
        return Ops.m_round(x)
      })
    })
    _M = step.length
    shift = Ops.m_map(step, ->(v) {
      return Ops.m_sum(Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.mul(Ops.elem(v, i), Ops.elem(stride, i))
      }))
    })
    opp = Ops.m_map(step, ->(v) {
      return Ops.or_else(Ops.m_index_of(step, Ops.m_map(v, ->(x) {
        return Ops.sub(0, x)
      }))) { (-1) }
    })
    coord = ->(k) {
      return Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.mod(Ops.m_floor((Ops.div(k, Ops.elem(stride, i)))), _L)
      })
    }
    is_matter = Ops.m_map(Ops.rng(cells), ->(k) {
      p = coord.(k)
      return Ops.le(Ops.m_sqrt((Ops.m_sum(Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.power((Ops.sub(Ops.elem(p, i), c)), 2)
      })))), radius)
    })
    n = Ops.filled(Ops.mul(cells, _M), Ops.div(rho, _M))
    _next = Ops.filled(Ops.mul(cells, _M), 0)
    s = Ops.filled(cells, 1)
    settled = false
    done = 0
    while (Ops.lt(done, passes) && !(settled))
      Ops.mul(cells, _M).times do |i|
        Ops.set_at(_next, i, 0)
      end
      moved = 0
      cells.times do |k|
        tot = Ops.m_sum(Ops.m_map(Ops.rng(_M), ->(d) {
          return Ops.elem(n, Ops.add(Ops.mul(k, _M), d))
        }))
        made = (Ops.elem(is_matter, k) ? 0 : Ops.mul(_R.nu, ((Ops.gt(Ops.sub(1, tot), 0) ? Ops.sub(1, tot) : 0))))
        sp = Ops.div(1, Ops.elem(s, k))
        _M.times do |d|
          here = Ops.elem(n, Ops.add(Ops.mul(k, _M), d))
          facing = Ops.elem(n, Ops.add(Ops.mul(k, _M), ((Ops.lt(Ops.elem(opp, d), 0) ? d : Ops.elem(opp, d)))))
          killed = Ops.mul(Ops.mul(Ops.mul(Ops.mul(_R.sigma, (Ops.sub(1, _R.g))), here), facing), _R.F)
          left = Ops.sub(Ops.sub(Ops.add(here, Ops.div(made, _M)), killed), ((Ops.elem(is_matter, k) ? here : 0)))
          left = (Ops.lt(left, 0) ? 0 : left)
          p = coord.(k)
          inside = Ops.m_every(Ops.rng(_D), ->(i) {
            return (Ops.ge(Ops.add(Ops.elem(p, i), Ops.elem(Ops.elem(step, d), i)), 0) && Ops.lt(Ops.add(Ops.elem(p, i), Ops.elem(Ops.elem(step, d), i)), _L))
          })
          if inside
            Ops.set_at(_next, Ops.add(Ops.mul((Ops.add(k, Ops.elem(shift, d))), _M), d), Ops.add(Ops.elem(_next, Ops.add(Ops.mul((Ops.add(k, Ops.elem(shift, d))), _M), d)), Ops.mul(left, sp)))
            Ops.set_at(_next, Ops.add(Ops.mul(k, _M), d), Ops.add(Ops.elem(_next, Ops.add(Ops.mul(k, _M), d)), Ops.mul(left, (Ops.sub(1, sp)))))
          end
        end
      end
      Ops.mul(cells, _M).times do |i|
        delta = Ops.m_abs((Ops.sub(Ops.elem(_next, i), Ops.elem(n, i))))
        if Ops.gt(delta, moved)
          moved = delta
        end
        Ops.set_at(n, i, Ops.elem(_next, i))
      end
      settled = Ops.lt(moved, tol)
      done = Ops.add(done, 1)
    end
    dens = Ops.m_map(Ops.rng(cells), ->(k) {
      return Ops.m_sum(Ops.m_map(Ops.rng(_M), ->(d) {
        return Ops.elem(n, Ops.add(Ops.mul(k, _M), d))
      }))
    })
    imbalance = Ops.m_map(Ops.rng(cells), ->(k) {
      p = coord.(k)
      f = Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.m_sum(Ops.m_map(Ops.rng(_M), ->(d) {
          return Ops.mul(Ops.elem(n, Ops.add(Ops.mul(k, _M), d)), Ops.elem(Ops.elem(step, d), i))
        }))
      })
      r = Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.sub(c, Ops.elem(p, i))
      })
      norm = Ops.m_sqrt((Ops.m_sum(Ops.m_map(r, ->(x) {
        return Ops.mul(x, x)
      }))))
      return Ops.div((Ops.m_sum(Ops.m_map(Ops.rng(_D), ->(i) {
        return Ops.mul(Ops.elem(f, i), Ops.elem(r, i))
      }))), ((Ops.gt(norm, 0) ? norm : 1)))
    })
    return Grid.new(L: _L, n: dens, s: s, rho: rho, passes: done, settled: settled, imbalance: imbalance)
  end
  __exposed
end

