  def self.flatten(kind, xs)
    e = Expr.new(kind: kind)
    out = []
    Ops.list(xs).each do |x|
      if Ops.eq(x.kind, kind)
        Ops.list(x.of).each do |y|
          Ops.m_push(out, y)
        end
      else
        Ops.m_push(out, x)
      end
    end
    e.of = out
    return e
  end
  def self.is_integer(x)
    return Ops.eq(x, Ops.m_floor(x))
  end
  def self.finite(x)
