  def self.binom_at(n, k)
    if (Ops.lt(k, 0) || Ops.gt(k, n))
      return 0
    end
    out = 1
    i = 0
    while Ops.lt(i, k)
      out = Ops.div(Ops.mul(out, (Ops.sub(n, i))), (Ops.add(i, 1)))
      i = Ops.add(i, 1)
    end
    return Ops.m_round(out)
  end
  def self.lgamma(z)
