  def self.e1(x)
    if Ops.le(x, 0)
      return Expr.NAN
    end
    if Ops.le(x, 1)
      total_ = 0
      term = 1
      k = 1
      while Ops.le(k, 60)
        term = Ops.div(Ops.mul(term, (Ops.sub(0, x))), k)
        total_ = Ops.add(total_, Ops.div((Ops.sub(0, term)), k))
        k = Ops.add(k, 1)
      end
      return Ops.add(Ops.sub((-0.5772156649015329), Ops.m_ln(x)), total_)
    end
    b = Ops.add(x, 1)
    c = Ops.power(10, 300)
    d = Ops.div(1, b)
    h = d
    i = 1
    while Ops.le(i, 200)
      an = Ops.sub(0, Ops.mul(i, i))
      b = Ops.add(b, 2)
      d = Ops.add(Ops.mul(an, d), b)
      if Ops.lt(Ops.m_abs(d), Ops.power(10, (-300)))
        d = Ops.power(10, (-300))
      end
      c = Ops.add(b, Ops.div(an, c))
      if Ops.lt(Ops.m_abs(c), Ops.power(10, (-300)))
        c = Ops.power(10, (-300))
      end
      d = Ops.div(1, d)
      delta_ = Ops.mul(d, c)
      h = Ops.mul(h, delta_)
      if Ops.lt(Ops.m_abs((Ops.sub(delta_, 1))), 0.00000000000001)
        return Ops.mul(h, Ops.m_exp((Ops.sub(0, x))))
      end
      i = Ops.add(i, 1)
    end
    return Ops.mul(h, Ops.m_exp((Ops.sub(0, x))))
