  def self.gamma_upper(s, x)
    if Ops.lt(x, 0)
      return Expr.NAN
    end
    if Ops.eq(x, 0)
      return ((Ops.gt(s, 0) ? Ops.m_exp(Expr.lgamma(s)) : Expr.INF))
    end
    if Ops.lt(Ops.m_abs(s), 0.000000000001)
      return Expr.e1(x)
    end
    if Ops.lt(x, Ops.add(s, 1))
