        stop = Ops.lt(Ops.m_abs(delta_), Ops.mul(Ops.m_abs(total_), 0.000000000000001))
        n = Ops.add(n, 1)
      end
      lower = Ops.mul(total_, Ops.m_exp((Ops.sub(Ops.add(Ops.sub(0, x), Ops.mul(s, Ops.m_ln(x))), Expr.lgamma(s)))))
      return Ops.mul(Ops.m_exp(Expr.lgamma(s)), (Ops.sub(1, lower)))
    end
    b = Ops.sub(Ops.add(x, 1), s)
    c = Ops.power(10, 300)
    d = Ops.div(1, b)
    h = d
    i = 1
    while Ops.le(i, 500)
      an = Ops.sub(0, Ops.mul(i, (Ops.sub(i, s))))
      b = Ops.add(b, 2)
      d = Ops.add(Ops.mul(an, d), b)
      if Ops.lt(Ops.m_abs(d), Ops.power(10, (-300)))
        d = Ops.power(10, (-300))
      end
      c = Ops.add(b, Ops.div(an, c))
      if Ops.lt(Ops.m_abs(c), Ops.power(10, (-300)))
        c = Ops.power(10, (-300))
      end
      d = Ops.div(1, d)
      delta_ = Ops.mul(d, c)
      h = Ops.mul(h, delta_)
