      i = Ops.add(i, 1)
    end
    return Ops.mul(Ops.m_exp((Ops.add(Ops.sub(0, x), Ops.mul(s, Ops.m_ln(x))))), h)
  end
  def self.gather(e)
    t = Expr.simplify(e)
    if !Ops.eq(t.kind, "add")
      return t
    end
    c = 0
    groups = []
    same = ->(a, b) {
      if !Ops.eq(a.length, b.length)
        return false
      end
      left = Ops.m_map(b, ->(x) {
        return x
      })
      ok = true
      Ops.list(a).each do |x|
        i = Ops.m_index_of(left, x)
        if Ops.eq(i, nil)
          ok = false
        else
          left = Ops.m_concat(Ops.m_take(left, i), Ops.m_drop(left, Ops.add(i, 1)))
        end
      end
      return ok
    }
    add_to = ->(names, e, k) {
      hit = nil
      Ops.list(groups).each do |g|
        if (Ops.eq(hit, nil) && same.(Ops.elem(g, 0), names))
          hit = g
        end
      end
      if Ops.eq(hit, nil)
        return Ops.m_push(groups, [names, e, k])
      else
        Ops.set_at(hit, 2, Ops.add(Ops.elem(hit, 2), k))
      end
    }
    walk = ->(x, sign) {
      y = Expr.simplify(x)
      if Ops.eq(y.kind, "num")
        c = Ops.add(c, Ops.mul(sign, y.value))
      else
        if Ops.eq(y.kind, "add")
          Ops.list(y.of).each do |z|
            walk.(z, sign)
          end
        else
          if Ops.eq(y.kind, "mul")
            k = sign
            rest = []
            Ops.list(y.of).each do |z|
              if Ops.eq(z.kind, "num")
                k = Ops.mul(k, z.value)
              else
                Ops.m_push(rest, z)
              end
            end
            if Ops.m_empty(rest)
              c = Ops.add(c, k)
            else
              if (Ops.eq(rest.length, 1) && Ops.eq(Ops.elem(rest, 0).kind, "add"))
                Ops.list(Ops.elem(rest, 0).of).each do |z|
                  walk.(z, k)
                end
              else
                return add_to.(Ops.m_map(rest, ->(r) {
                  return Expr.show(r)
                }), (Ops.eq(rest.length, 1) ? Ops.elem(rest, 0) : Expr.mul(rest)), k)
              end
            end
          else
            return add_to.([Expr.show(y)], y, sign)
          end
        end
      end
    }
    walk.(t, 1)
    terms = Ops.m_map(Ops.filt(groups, ->(v) {
      return !Ops.eq(Ops.elem(v, 2), 0)
    }), ->(v) {
      return (Ops.eq(Ops.elem(v, 2), 1) ? Ops.elem(v, 1) : Expr.mul([Expr.num(Ops.elem(v, 2)), Ops.elem(v, 1)]))
    })
    if !Ops.eq(c, 0)
      Ops.m_push(terms, Expr.num(c))
    end
    return (Ops.m_empty(terms) ? Expr.num(0) : Expr.simplify(Expr.add(terms)))
