  def self.simplify(e)
    if !Ops.eq(e.simple, nil)
      return e.simple
    end
    got = Expr.simplified(e)
    got.simple = got
    e.simple = got
    return got
  end
  def self.simplified(e)
    k = e.kind
    if ((Ops.eq(k, "num") || Ops.eq(k, "sym")) || Ops.eq(k, "field"))
      return e
    end
    if Ops.eq(k, "grad")
      return Expr.grad(Expr.simplify(e.base))
    end
    if Ops.eq(k, "log")
      x = Expr.simplify(e.base)
      return (((Ops.eq(x.kind, "num") && Ops.gt(x.value, 0))) ? Expr.num(Ops.m_ln(x.value)) : Expr.log(x))
    end
    if Ops.eq(k, "exp")
      x = Expr.simplify(e.base)
      return (Ops.eq(x.kind, "num") ? Expr.num(Ops.m_exp(x.value)) : Expr.exp(x))
    end
    if Ops.eq(k, "choose")
      n = Expr.simplify(e.first_)
      kk = Expr.simplify(e.second_)
      if (Ops.eq(n.kind, "num") && Ops.eq(kk.kind, "num"))
        return Expr.num(Expr.binom_at(n.value, kk.value))
      end
      return Expr.choose(n, kk)
    end
    if Ops.eq(k, "gammaInc")
      a = Expr.simplify(e.first_)
      x = Expr.simplify(e.second_)
      if (Ops.eq(a.kind, "num") && Ops.eq(x.kind, "num"))
        return Expr.num(Expr.gamma_upper(a.value, x.value))
      end
      return Expr.gamma_inc(a, x)
    end
    if Ops.eq(k, "root")
      return Expr.root(Expr.simplify(e.base), e.bound)
    end
    if Ops.eq(k, "limit")
      return Expr.limit(Expr.simplify(e.base), e.bound)
    end
    if Ops.eq(k, "call")
      return Expr.call(e.label, Expr.simplify(e.base))
    end
    if Ops.eq(k, "pow")
      b = Expr.simplify(e.base)
      if !Ops.eq(e.power.kind, "num")
        kk = Expr.gather(e.power)
        if (Ops.eq(b.kind, "num") && Ops.eq(b.value, 1))
          return Expr.num(1)
        end
        if ((Ops.eq(b.kind, "num") && Ops.eq(kk.kind, "num")) && !(((Ops.eq(b.value, 0) && Ops.lt(kk.value, 0)))))
          return Expr.num(Ops.power(b.value, kk.value))
        end
        return Expr.to_power(b, kk)
      end
      by = e.power.value
      if Ops.eq(by, 1)
        return b
      end
      if Ops.eq(by, 0)
        return Expr.num(1)
      end
      if (Ops.eq(b.kind, "num") && !(((Ops.eq(b.value, 0) && Ops.lt(by, 0)))))
        return Expr.num(Ops.power(b.value, by))
      end
      if (Ops.eq(b.kind, "pow") && !Ops.eq(b.by_num, nil))
        return Expr.simplify(Expr.pown(b.base, Ops.mul(b.by_num, by)))
      end
      if Ops.eq(b.kind, "pow")
        return Expr.simplify(Expr.to_power(b.base, Expr.mul([b.power, Expr.num(by)])))
      end
      if (Ops.eq(b.kind, "mul") && Expr.is_integer(by))
        return Expr.simplify(Expr.mul(Ops.m_map(b.of, ->(x) {
          return Expr.pown(x, by)
        })))
      end
      return Expr.pown(b, by)
    end
    if Ops.eq(k, "mul")
      parts = []
      Ops.list(e.of).each do |x|
        y = Expr.simplify(x)
        if Ops.eq(y.kind, "mul")
          Ops.list(y.of).each do |z|
            Ops.m_push(parts, z)
          end
        else
          Ops.m_push(parts, y)
        end
      end
      parts = Ops.filt(parts, ->(x) {
        return !(((Ops.eq(x.kind, "num") && Ops.eq(x.value, 1))))
      })
      c = 1
      rest = []
      Ops.list(parts).each do |x|
        if Ops.eq(x.kind, "num")
          c = Ops.mul(c, x.value)
        else
          Ops.m_push(rest, x)
        end
      end
      if Ops.eq(c, 0)
        return Expr.num(0)
      end
      powers = Keyed.new()
      Ops.list(rest).each do |x|
        b = (Ops.eq(x.kind, "pow") ? x.base : x)
        kk = (Ops.eq(x.kind, "pow") ? x.power : Expr.num(1))
        id = Expr.show(b)
        at = powers.get(id)
        powers.set(id, [b, (Ops.eq(at, nil) ? kk : Expr.add([Ops.elem(at, 1), kk]))])
      end
      gathered = Ops.m_map(Ops.filt(Ops.m_map(powers.values, ->(v) {
        return [Ops.elem(v, 0), Expr.simplify(Expr.gather(Ops.elem(v, 1)))]
      }), ->(v) {
        return !(((Ops.eq(Ops.elem(v, 1).kind, "num") && Ops.eq(Ops.elem(v, 1).value, 0))))
      }), ->(v) {
        return (((Ops.eq(Ops.elem(v, 1).kind, "num") && Ops.eq(Ops.elem(v, 1).value, 1))) ? Ops.elem(v, 0) : Expr.to_power(Ops.elem(v, 0), Ops.elem(v, 1)))
      })
      if Ops.m_empty(gathered)
        return Expr.num(c)
      end
      if Ops.eq(c, 1)
        return ((Ops.eq(gathered.length, 1) ? Ops.elem(gathered, 0) : Expr.mul(gathered)))
      end
      return Expr.mul(Ops.m_concat([Expr.num(c)], gathered))
    end
    if Ops.eq(k, "add")
      flat = []
      Ops.list(e.of).each do |x|
        y = Expr.simplify(x)
        if Ops.eq(y.kind, "add")
          Ops.list(y.of).each do |z|
            Ops.m_push(flat, z)
          end
        else
          if !Ops.eq(y.kind, "mul")
            Ops.m_push(flat, y)
          else
            sums = Ops.filt(y.of, ->(z) {
              return Ops.eq(z.kind, "add")
            })
            nums = Ops.filt(y.of, ->(z) {
              return Ops.eq(z.kind, "num")
            })
            if (!Ops.eq(sums.length, 1) || !Ops.eq(Ops.add(nums.length, sums.length), y.of.length))
              Ops.m_push(flat, y)
            else
              kk = 1
              Ops.list(nums).each do |z|
                kk = Ops.mul(kk, z.value)
              end
              Ops.list(Ops.elem(sums, 0).of).each do |z|
                Ops.m_push(flat, Expr.simplify(Expr.mul([Expr.num(kk), z])))
              end
            end
          end
        end
      end
      parts = Ops.filt(Ops.m_map(flat, ->(x) {
        return Expr.simplify(x)
      }), ->(x) {
        return !(((Ops.eq(x.kind, "num") && Ops.eq(x.value, 0))))
      })
      c = 0
      rest = []
      Ops.list(parts).each do |x|
        if Ops.eq(x.kind, "num")
          c = Ops.add(c, x.value)
        else
          Ops.m_push(rest, x)
        end
      end
      like = Keyed.new()
      Ops.list(rest).each do |x|
        kk = 1
        body = x
        if Ops.eq(x.kind, "mul")
          nums = Ops.filt(x.of, ->(y) {
            return Ops.eq(y.kind, "num")
          })
          if !(Ops.m_empty(nums))
            Ops.list(nums).each do |y|
              kk = Ops.mul(kk, y.value)
            end
            others = Ops.filt(x.of, ->(y) {
              return !Ops.eq(y.kind, "num")
            })
            body = (Ops.eq(others.length, 1) ? Ops.elem(others, 0) : Expr.mul(others))
          end
        end
        id = Expr.show(body)
        at = like.get(id)
        if !Ops.eq(at, nil)
          Ops.set_at(at, 1, Ops.add(Ops.elem(at, 1), kk))
        else
          like.set(id, [body, kk])
        end
      end
      kept = []
      Ops.list(like.values).each do |v|
        if !Ops.eq(Ops.elem(v, 1), 0)
          Ops.m_push(kept, (Ops.eq(Ops.elem(v, 1), 1) ? Ops.elem(v, 0) : Expr.mul([Expr.num(Ops.elem(v, 1)), Ops.elem(v, 0)])))
        end
      end
      if Ops.m_empty(kept)
        return Expr.num(c)
      end
      if Ops.eq(c, 0)
        return ((Ops.eq(kept.length, 1) ? Ops.elem(kept, 0) : Expr.add(kept)))
      end
      return Expr.add(Ops.m_concat(kept, [Expr.num(c)]))
    end
    return e
  end
  def self.ratio(n)
    if Expr.is_integer(n)
      return nil
    end
    sign = (Ops.lt(n, 0) ? "-" : "")
    x = Ops.m_abs(n)
    q = 2
    while Ops.le(q, 12)
      p = Ops.mul(x, q)
      if Ops.lt(Ops.m_abs((Ops.sub(p, Ops.m_round(p)))), 0.000000000001)
        return "#{sign}\\frac{#{Ops.m_round(p)}}{#{q}}"
      end
      q = Ops.add(q, 1)
    end
    return nil
  end
  def self.text_of(n)
    return (Expr.is_integer(n) ? "#{Ops.m_round(n)}" : "#{n}")
  end
  def self.show(e)
    if !Ops.eq(e.shown, nil)
      return e.shown
    end
    got = Expr.shown_as(e)
    e.shown = got
    return got
  end
  def self.shown_as(e)
    k = e.kind
    if Ops.eq(k, "num")
      r = Expr.ratio(e.value)
      return (Ops.eq(r, nil) ? Expr.text_of(e.value) : r)
    end
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      return e.label
    end
    if Ops.eq(k, "log")
      return "\\ln\\paren{#{Expr.show(e.base)}}"
    end
    if Ops.eq(k, "exp")
      return "e^{#{Expr.show(e.base)}}"
    end
    if Ops.eq(k, "choose")
      return "\\binom{#{Expr.show(e.first_)}}{#{Expr.show(e.second_)}}"
    end
    if Ops.eq(k, "gammaInc")
