      })
        rest = Ops.filt(xs, ->(x) {
          return !(own.(x))
        })
        if Ops.m_empty(rest)
          return "l.choose\\paren{\\bar{m}_{x}}"
        end
        return "l.choose\\paren{\\bar{m}_{x·#{Expr.show((Ops.eq(rest.length, 1) ? Ops.elem(rest, 0) : Expr.mul(rest)))}}}"
