          return (((Ops.eq(x.kind, "mul") && Ops.eq(x.of.length, 2)) && Ops.m_some(x.of, ->(y) {
            return (Ops.eq(y.kind, "num") && Ops.eq(y.value, (-1)))
          })) && Ops.m_some(x.of, ->(y) {
            return (y.named && Ops.eq(y.label, e.bound))
