      base = (((((Ops.eq(e.base.kind, "add") || Ops.eq(e.base.kind, "mul")) || Ops.eq(e.base.kind, "root")) || loose)) ? "\\paren{#{Expr.show(e.base)}}" : Expr.show(e.base))
      exponent = (!Ops.eq(kk, nil) ? Expr.text_of(kk) : Expr.show(e.power))
      return "#{base}^{#{exponent}}"
    end
    if Ops.eq(k, "mul")
      flat = []
      Ops.list(e.of).each do |x|
        if (!Ops.eq(x.kind, "num") || Expr.is_integer(x.value))
          Ops.m_push(flat, x)
        else
          sign = (Ops.lt(x.value, 0) ? (-1) : 1)
          v = Ops.m_abs(x.value)
          done = false
          q = 2
