              Ops.m_push(flat, Expr.num(Ops.mul(sign, Ops.m_round(p))))
              Ops.m_push(flat, Expr.pown(Expr.num(q), (-1)))
              done = true
            end
            q = Ops.add(q, 1)
          end
          if !(done)
            Ops.m_push(flat, x)
          end
        end
      end
      neg1 = Ops.m_some(flat, ->(x) {
        return (Ops.eq(x.kind, "num") && Ops.eq(x.value, (-1)))
      })
      rest = Ops.filt(flat, ->(x) {
        return !(((Ops.eq(x.kind, "num") && ((Ops.eq(x.value, (-1)) || Ops.eq(x.value, 1))))))
      })
      neg_pow = ->(x) {
