          return nil
        end
        kk = x.by_num
        return (((!Ops.eq(kk, nil) && Ops.lt(kk, 0))) ? Ops.sub(0, kk) : nil)
      }
      under = Ops.filt(rest, ->(x) {
        return !Ops.eq(neg_pow.(x), nil)
      })
      over = Ops.filt(rest, ->(x) {
        return Ops.eq(neg_pow.(x), nil)
      })
      set = ->(xs) {
        return Ops.m_join(Ops.m_map(((Ops.m_empty(xs) ? [Expr.num(1)] : xs)), ->(x) {
          return (((Ops.eq(x.kind, "add") || Ops.eq(x.kind, "root"))) ? "\\paren{#{Expr.show(x)}}" : Expr.show(x))
        }), "·")
      }
