        kk = neg_pow.(x)
        return (Ops.eq(kk, 1) ? x.base : Expr.pown(x.base, kk))
      })
      ordered = Ops.m_concat(Ops.filt(below, ->(x) {
        return Ops.eq(x.kind, "num")
      }), Ops.filt(below, ->(x) {
        return !Ops.eq(x.kind, "num")
      }))
      bar = (((Ops.eq(ordered.length, 1) && Ops.eq(Ops.elem(ordered, 0).kind, "add"))) ? Expr.show(Ops.elem(ordered, 0)) : set.(ordered))
      top = set.(over)
      drawn = Expr.drawn(top)
