    if Ops.eq(k, "add")
      negative = ->(x) {
        return Ops.m_starts_with(Expr.show(x), "-")
      }
      ordered = Ops.m_concat(Ops.filt(e.of, ->(x) {
        return !(negative.(x))
      }), Ops.filt(e.of, ->(x) {
        return negative.(x)
      }))
