      ordered.length.times do |i|
        x = Ops.elem(ordered, i)
        t = (Ops.eq(x.kind, "root") ? "\\paren{#{Expr.show(x)}}" : Expr.show(x))
        piece = (Ops.eq(i, 0) ? t : ((Ops.m_starts_with(t, "-") ? " - #{Ops.m_drop(t, 1)}" : " + #{t}")))
        out = "#{out}#{piece}"
      end
      return out
    end
    return ""
  end
  def self.drawn(t)
    s = Ops.m_replace(Ops.m_replace(Ops.m_replace(t, "\\paren{", "("), "\\frac{", "("), "\\sqrt{", "(")
    out = 0
    i = 0
    cs = Ops.m_chars(s)
    while Ops.lt(i, cs.length)
      c = Ops.elem(cs, i)
      if Ops.eq(c, 92)
        i = Ops.add(i, 1)
        while (Ops.lt(i, cs.length) && Notation.is_letter(Ops.elem(cs, i)))
          i = Ops.add(i, 1)
        end
        out = Ops.add(out, 1)
      else
        if (!Ops.eq(c, 123) && !Ops.eq(c, 125))
          out = Ops.add(out, 1)
        end
        i = Ops.add(i, 1)
      end
    end
    return out
  end
  def self.d(e, wrt)
    k = e.kind
    if Ops.eq(k, "num")
      return Expr.num(0)
    end
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      return Expr.num((Ops.eq(e.label, wrt) ? 1 : 0))
    end
    if Ops.eq(k, "add")
      return Expr.add(Ops.m_map(e.of, ->(x) {
        return Expr.d(x, wrt)
      }))
    end
    if Ops.eq(k, "mul")
      return Expr.add(Ops.m_map(Ops.rng(e.of.length), ->(i) {
        others = []
        e.of.length.times do |j|
          if !Ops.eq(j, i)
            Ops.m_push(others, Ops.elem(e.of, j))
          end
        end
        return Expr.mul(Ops.m_concat([Expr.d(Ops.elem(e.of, i), wrt)], others))
      }))
    end
    if Ops.eq(k, "pow")
      if Ops.eq(e.power.kind, "num")
        return Expr.mul([e.power, Expr.pown(e.base, Ops.sub(e.power.value, 1)), Expr.d(e.base, wrt)])
      end
      du = Expr.d(e.base, wrt)
      dv = Expr.d(e.power, wrt)
