    end
    if Ops.eq(k, "exp")
      return Expr.mul([Expr.exp(e.base), Expr.d(e.base, wrt)])
    end
    if Ops.eq(k, "choose")
      return Expr.num(0)
    end
    if Ops.eq(k, "gammaInc")
