    end
    return Expr.grad(e)
  end
  def self.has(e, name)
    k = e.kind
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      return Ops.eq(e.label, name)
    end
    if (Ops.eq(k, "add") || Ops.eq(k, "mul"))
      return Ops.m_some(e.of, ->(x) {
        return Expr.has(x, name)
      })
    end
    if Ops.eq(k, "pow")
      return (Expr.has(e.base, name) || Expr.has(e.power, name))
    end
    if (((Ops.eq(k, "grad") || Ops.eq(k, "log")) || Ops.eq(k, "exp")) || Ops.eq(k, "call"))
      return Expr.has(e.base, name)
    end
    if (Ops.eq(k, "choose") || Ops.eq(k, "gammaInc"))
      return (Expr.has(e.first_, name) || Expr.has(e.second_, name))
    end
    return false
  end
  def self.mentions(e, name)
    k = e.kind
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      return Ops.eq(e.label, name)
    end
    if (Ops.eq(k, "add") || Ops.eq(k, "mul"))
      return Ops.m_some(e.of, ->(x) {
        return Expr.mentions(x, name)
