    end
    if Ops.eq(k, "pow")
      return (Expr.mentions(e.base, name) || Expr.mentions(e.power, name))
    end
    if (((Ops.eq(k, "grad") || Ops.eq(k, "log")) || Ops.eq(k, "exp")) || Ops.eq(k, "call"))
      return Expr.mentions(e.base, name)
