    if (Ops.eq(k, "choose") || Ops.eq(k, "gammaInc"))
      return (Expr.mentions(e.first_, name) || Expr.mentions(e.second_, name))
    end
    if (Ops.eq(k, "root") || Ops.eq(k, "limit"))
      return (!Ops.eq(e.bound, name) && Expr.mentions(e.base, name))
    end
