  end
  def self.replace(e, name, by)
    k = e.kind
    if (e.named && Ops.eq(e.label, name))
      return by
    end
    if Ops.eq(k, "add")
      return Expr.add(Ops.m_map(e.of, ->(x) {
        return Expr.replace(x, name, by)
      }))
    end
    if Ops.eq(k, "mul")
      return Expr.mul(Ops.m_map(e.of, ->(x) {
        return Expr.replace(x, name, by)
      }))
    end
    if Ops.eq(k, "pow")
      return Expr.to_power(Expr.replace(e.base, name, by), Expr.replace(e.power, name, by))
    end
    if Ops.eq(k, "grad")
      return Expr.grad(Expr.replace(e.base, name, by))
    end
    if Ops.eq(k, "log")
      return Expr.log(Expr.replace(e.base, name, by))
    end
    if Ops.eq(k, "exp")
      return Expr.exp(Expr.replace(e.base, name, by))
    end
    if Ops.eq(k, "choose")
      return Expr.choose(Expr.replace(e.first_, name, by), Expr.replace(e.second_, name, by))
    end
    if Ops.eq(k, "call")
      return Expr.call(e.label, Expr.replace(e.base, name, by))
    end
    if Ops.eq(k, "gammaInc")
      return Expr.gamma_inc(Expr.replace(e.first_, name, by), Expr.replace(e.second_, name, by))
    end
    if Ops.eq(k, "root")
      return ((Ops.eq(e.bound, name) ? e : Expr.root(Expr.replace(e.base, name, by), e.bound)))
    end
    if Ops.eq(k, "limit")
      return ((Ops.eq(e.bound, name) ? e : Expr.limit(Expr.replace(e.base, name, by), e.bound)))
    end
    return e
  end
  def self.power_in(e, of)
    t = Expr.simplify(e)
    if (Ops.eq(t.kind, "sym") && Ops.eq(t.label, of))
      return Expr.num(1)
    end
    if ((Ops.eq(t.kind, "pow") && Ops.eq(t.base.kind, "sym")) && Ops.eq(t.base.label, of))
      return t.power
    end
    if Ops.eq(t.kind, "mul")
      return Expr.simplify(Expr.add(Ops.m_map(t.of, ->(x) {
        return Expr.power_in(x, of)
      })))
    end
    if (Ops.eq(t.kind, "pow") && Ops.eq(t.power.kind, "num"))
      return Expr.simplify(Expr.mul([Expr.power_in(t.base, of), t.power]))
    end
    return Expr.num(0)
  end
  def self.bigger(a, b)
    seen = nil
    undecided = false
    Ops.list([2, 3, 4, 5, 7]).each do |_D|
      unless undecided
        at = Node.new
        Ops.setattr(at, "D", _D)
        x = Expr.evaluate(a, at)
        y = Expr.evaluate(b, at)
        if (!Ops.eq(x.kind, "num") || !Ops.eq(y.kind, "num"))
          undecided = true
        else
          if !Ops.eq(x.value, y.value)
            here = Ops.gt(x.value, y.value)
            if Ops.eq(seen, nil)
              seen = here
            else
              if !Ops.eq(seen, here)
                undecided = true
              end
            end
          end
        end
      end
    end
    return (undecided ? nil : seen)
  end
  def self.leading(e, of)
    t = Expr.simplify(e)
    if Ops.eq(t.kind, "add")
      parts = Ops.m_map(t.of, ->(x) {
        return Expr.leading(x, of)
      })
      best = Ops.elem(parts, 0)
      stuck = false
      Ops.list(Ops.m_drop(Ops.rng(parts.length), 1)).each do |i|
        unless stuck
          cmp = Expr.bigger(Expr.power_in(Ops.elem(parts, i), of), Expr.power_in(best, of))
          if Ops.eq(cmp, nil)
            stuck = true
          else
            if cmp
              best = Ops.elem(parts, i)
            end
          end
        end
      end
      return (stuck ? t : best)
    end
    if (((Ops.eq(t.kind, "pow") && Ops.eq(t.power.kind, "num")) && Ops.gt(t.power.value, 0)) && Ops.lt(t.power.value, 1))
      return Expr.simplify(Expr.to_power(Expr.leading(t.base, of), t.power))
    end
    if Ops.eq(t.kind, "mul")
      return Expr.simplify(Expr.mul(Ops.m_map(t.of, ->(x) {
        return Expr.leading(x, of)
      })))
    end
    return t
  end
  def self.spread(e)
    t = Expr.simplify(e)
    if (Ops.eq(t.kind, "pow") && Ops.eq(t.base.kind, "mul"))
      return Expr.simplify(Expr.mul(Ops.m_map(t.base.of, ->(x) {
        return Expr.spread(Expr.to_power(x, t.power))
      })))
    end
    if (Ops.eq(t.kind, "pow") && Ops.eq(t.base.kind, "pow"))
      return Expr.spread(Expr.to_power(t.base.base, Expr.simplify(Expr.mul([t.base.power, t.power]))))
    end
    if Ops.eq(t.kind, "mul")
      return Expr.simplify(Expr.mul(Ops.m_map(t.of, ->(x) {
        return Expr.spread(x)
      })))
    end
    return t
  end
  def self.swap(e, piece, by)
    want = Expr.show(piece)
    go = ->(x) {
      if Ops.eq(Expr.show(x), want)
        return by
      end
      k = x.kind
      if Ops.eq(k, "add")
        return Expr.add(Ops.m_map(x.of, ->(y) {
          return go.(y)
        }))
      end
      if Ops.eq(k, "mul")
        return Expr.mul(Ops.m_map(x.of, ->(y) {
          return go.(y)
        }))
      end
      if Ops.eq(k, "pow")
        return Expr.to_power(go.(x.base), go.(x.power))
      end
      if Ops.eq(k, "log")
        return Expr.log(go.(x.base))
      end
      if Ops.eq(k, "exp")
        return Expr.exp(go.(x.base))
      end
      if Ops.eq(k, "root")
        return Expr.root(go.(x.base), x.bound)
      end
      if Ops.eq(k, "limit")
        return Expr.limit(go.(x.base), x.bound)
      end
      if Ops.eq(k, "call")
        return Expr.call(x.label, go.(x.base))
      end
      return x
    }
    return go.(e)
  end
  def self.numeric(e, at)
    k = e.kind
    if Ops.eq(k, "num")
      return e.value
    end
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      v = Ops.elem(at, e.label)
      return (Ops.eq(v, nil) ? Expr.NAN : v)
    end
    if Ops.eq(k, "add")
      total_ = 0
      Ops.list(e.of).each do |x|
        total_ = Ops.add(total_, Expr.numeric(x, at))
      end
      return total_
    end
    if Ops.eq(k, "mul")
      prod = 1
      Ops.list(e.of).each do |x|
        prod = Ops.mul(prod, Expr.numeric(x, at))
      end
      return prod
    end
    if Ops.eq(k, "pow")
      return Ops.power(Expr.numeric(e.base, at), Expr.numeric(e.power, at))
    end
    if Ops.eq(k, "log")
      return Ops.m_ln(Expr.numeric(e.base, at))
    end
    if Ops.eq(k, "exp")
      return Ops.m_exp(Expr.numeric(e.base, at))
    end
    if Ops.eq(k, "gammaInc")
      return Expr.gamma_upper(Expr.numeric(e.first_, at), Expr.numeric(e.second_, at))
    end
    if Ops.eq(k, "choose")
      n = Expr.numeric(e.first_, at)
      kk = Expr.numeric(e.second_, at)
      r = 1
      i = 0
      while Ops.lt(i, kk)
        r = Ops.div(Ops.mul(r, (Ops.sub(n, i))), (Ops.add(i, 1)))
        i = Ops.add(i, 1)
      end
      return r
    end
    if Ops.eq(k, "root")
      return Expr.solve_root(e.base, e.bound, at)
    end
    if Ops.eq(k, "limit")
      return Expr.to_infinity(e.base, e.bound, at)
    end
    return Expr.NAN
  end
  def self.to_infinity(of, name, at)
    had = Ops.elem(at, name)
    out = Expr.NAN
    was = Expr.NAN
    k = 1
    stop = false
    while (Ops.le(k, 20) && !(stop))
      Ops.set_at(at, name, Ops.power(10, k))
      got = Expr.numeric(of, at)
      if !(Expr.finite(got))
        stop = true
      else
        if (Expr.finite(was) && Ops.le(Ops.m_abs((Ops.sub(got, was))), Ops.mul(0.000000000001, ((Ops.gt(Ops.m_abs(got), 1) ? Ops.m_abs(got) : 1)))))
          out = got
          stop = true
        else
          was = got
        end
      end
      k = Ops.add(k, 1)
    end
    Ops.set_at(at, name, had)
    return out
  end
  def self.solve_root(of, name, at)
    had = Ops.elem(at, name)
    got = Expr.solving(of, name, at)
    Ops.set_at(at, name, had)
    return got
  end
  def self.solving(of, name, env)
    f = ->(v) {
      Ops.set_at(env, name, v)
      return Expr.numeric(of, env)
    }
    if ((!(Expr.finite(f.(0.5))) && !(Expr.finite(f.(1)))) && !(Expr.finite(f.(0.1))))
      return Expr.NAN
    end
    points = []
    i = 1
    while Ops.le(i, 120)
      Ops.m_push(points, Ops.div(i, 120))
      i = Ops.add(i, 1)
    end
    ex = 0
    while Ops.le(ex, 24)
      k = 1
      while Ops.lt(k, 8)
        Ops.m_push(points, Ops.mul((Ops.power(10, (Ops.sub(ex, 12)))), (Ops.add(1, Ops.div(k, 2)))))
        k = Ops.add(k, 1)
      end
      ex = Ops.add(ex, 1)
    end
    points = Expr.sorted(points)
    lo = nil
    hi = nil
    px = Ops.elem(points, 0)
    pf = f.(px)
    j = 1
    while (Ops.lt(j, points.length) && Ops.eq(lo, nil))
      cx = Ops.elem(points, j)
      cf = f.(cx)
      if ((Expr.finite(pf) && Expr.finite(cf)) && Ops.le(Ops.mul(pf, cf), 0))
        lo = px
        hi = cx
      end
      px = cx
      pf = cf
      j = Ops.add(j, 1)
    end
    if Ops.eq(lo, nil)
      return Expr.NAN
    end
    flo = f.(lo)
    n = 0
    stop = false
    while (Ops.lt(n, 80) && !(stop))
      mid = Ops.div((Ops.add(lo, hi)), 2)
      fm = f.(mid)
      if !(Expr.finite(fm))
        stop = true
      else
        if Ops.le(Ops.mul(flo, fm), 0)
          hi = mid
        else
          lo = mid
          flo = fm
        end
        stop = Ops.le(Ops.sub(hi, lo), Ops.mul(0.000000000000001, ((Ops.gt(Ops.m_abs(hi), 1) ? Ops.m_abs(hi) : 1))))
      end
      n = Ops.add(n, 1)
    end
    return Ops.div((Ops.add(lo, hi)), 2)
  end
  def self.sorted(xs)
    out = []
    Ops.list(xs).each do |x|
      i = 0
      while (Ops.lt(i, out.length) && Ops.le(Ops.elem(out, i), x))
        i = Ops.add(i, 1)
      end
      out = Ops.m_concat(Ops.m_concat(Ops.m_take(out, i), [x]), Ops.m_drop(out, i))
    end
    return out
  end
  def self.integrate(e, of)
    s = Expr.spread(e)
    if Ops.eq(s.kind, "grad")
      return s.base
    end
    if Ops.eq(s.kind, "mul")
      g = Ops.m_first(Ops.filt(s.of, ->(x) {
        return Ops.eq(x.kind, "grad")
      }))
      inv = Ops.m_first(Ops.filt(s.of, ->(x) {
        return (Ops.eq(x.kind, "pow") && Ops.eq(x.by_num, (-1)))
      }))
      if (!Ops.eq(g, nil) && !Ops.eq(inv, nil))
        inner = Expr.simplify(g.base)
        den = Expr.simplify(inv.base)
        if Ops.eq(Expr.show(Expr.simplify(Expr.d(den, of))), Expr.show(Expr.simplify(Expr.d(inner, of))))
          return Expr.log(den)
        end
      end
    end
    pow_ = ->(base, by) {
      if (!Ops.eq(base.kind, "sym") || !Ops.eq(base.label, of))
        return nil
      end
      k1 = Expr.simplify(Expr.add([by, Expr.num(1)]))
      if (Ops.eq(k1.kind, "num") && Ops.eq(k1.value, 0))
        return Expr.log(Expr.sym(of))
      end
      return Expr.simplify(Expr.mul([Expr.to_power(Expr.sym(of), k1), Expr.pown(k1, (-1))]))
    }
    if (Ops.eq(s.kind, "sym") && Ops.eq(s.label, of))
      return pow_.(s, Expr.num(1))
    end
    if Ops.eq(s.kind, "pow")
      return pow_.(s.base, s.power)
    end
    if Ops.eq(s.kind, "add")
      parts = Ops.m_map(s.of, ->(x) {
        return Expr.integrate(x, of)
      })
      if Ops.m_some(parts, ->(x) {
        return Ops.eq(x, nil)
      })
        return nil
      end
      return Expr.simplify(Expr.add(parts))
    end
    if Ops.eq(s.kind, "mul")
      free = Ops.filt(s.of, ->(x) {
        return !(Expr.has(x, of))
      })
      rest = Ops.filt(s.of, ->(x) {
        return Expr.has(x, of)
      })
      if Ops.eq(rest.length, 2)
        decay = Ops.m_first(Ops.filt(rest, ->(x) {
          return (((Ops.eq(x.kind, "pow") && !(Expr.has(x.base, of))) && Ops.eq(x.power.kind, "sym")) && Ops.eq(x.power.label, of))
        }))
        other = Ops.m_first(Ops.filt(rest, ->(x) {
          return !Ops.eq(x, decay)
        }))
        if (!Ops.eq(decay, nil) && !Ops.eq(other, nil))
          k = Expr.power_in(other, of)
          if !(Expr.has(Expr.simplify(Expr.mul([other, Expr.to_power(Expr.sym(of), Expr.simplify(Expr.mul([k, Expr.num((-1))])))])), of))
            ell = Expr.simplify(Expr.mul([Expr.num((-1)), Expr.pown(Expr.log(decay.base), (-1))]))
            s1 = Expr.simplify(Expr.add([k, Expr.num(1)]))
            return Expr.simplify(Expr.mul(Ops.m_concat(free, [Expr.num((-1)), Expr.to_power(ell, s1), Expr.gamma_inc(s1, Expr.mul([Expr.sym(of), Expr.pown(ell, (-1))]))])))
          end
        end
      end
      if !Ops.eq(rest.length, 1)
        return nil
      end
      inner = Expr.integrate(Ops.elem(rest, 0), of)
      return (Ops.eq(inner, nil) ? nil : Expr.simplify(Expr.mul(Ops.m_concat(free, [inner]))))
    end
    return nil
  end
  def self.factored(e)
    t = Expr.simplify(e)
    if (!Ops.eq(t.kind, "add") || Ops.lt(t.of.length, 2))
      return t
    end
    parts = Ops.m_map(t.of, ->(x) {
      m = Keyed.new()
      bits = (Ops.eq(x.kind, "mul") ? x.of : [x])
      Ops.list(bits).each do |b|
        base = (Ops.eq(b.kind, "pow") ? b.base : b)
        k = (Ops.eq(b.kind, "pow") ? b.power : Expr.num(1))
        if !Ops.eq(base.kind, "num")
          m.set(Expr.show(base), [base, k])
        end
      end
      return m
    })
    common = []
    Ops.list(Ops.elem(parts, 0).keys).each do |id|
      if Ops.m_every(parts, ->(p) {
        return p.has(id)
      })
        head_ = Ops.elem(parts, 0).get(id)
        ks = Ops.m_map(parts, ->(p) {
          return Ops.elem(p.get(id), 1)
        })
        nums = (Ops.m_every(ks, ->(k) {
          return Ops.eq(Expr.simplify(k).kind, "num")
        }) ? Ops.m_map(ks, ->(k) {
          return Expr.simplify(k).value
        }) : nil)
        ok = true
        k = Ops.elem(head_, 1)
        if !Ops.eq(nums, nil)
          lo = Ops.elem(nums, 0)
          hi = Ops.elem(nums, 0)
          Ops.list(nums).each do |v|
            if Ops.lt(v, lo)
              lo = v
            end
            if Ops.gt(v, hi)
              hi = v
            end
          end
          ok = Ops.eq((Ops.le(lo, 0)), (Ops.le(hi, 0)))
          least = Ops.elem(nums, 0)
          Ops.list(nums).each do |v|
            if Ops.lt(Ops.m_abs(v), Ops.m_abs(least))
              least = v
            end
          end
          k = Expr.num(least)
        end
        if ok
          Ops.m_push(common, [Ops.elem(head_, 0), k])
        end
      end
    end
    if Ops.m_empty(common)
      return t
    end
    out = Expr.mul(Ops.m_map(common, ->(c) {
      return Expr.to_power(Ops.elem(c, 0), Ops.elem(c, 1))
    }))
    inv = Expr.mul(Ops.m_map(common, ->(c) {
      return Expr.to_power(Ops.elem(c, 0), Expr.gather(Expr.neg(Ops.elem(c, 1))))
    }))
    return Expr.simplify(Expr.mul([out, Expr.add(Ops.m_map(t.of, ->(x) {
      return Expr.simplify(Expr.mul([x, inv]))
    }))]))
  end
  def self.collected(e)
    if !Ops.eq(e.kind, "add")
      return e
    end
    terms = []
    Ops.list(e.of).each do |x|
      if Ops.eq(x.kind, "add")
        Ops.list(x.of).each do |y|
          Ops.m_push(terms, y)
        end
      else
        Ops.m_push(terms, x)
      end
    end
    groups = Keyed.new()
    loose = []
    Ops.list(terms).each do |x|
      bits = (Ops.eq(x.kind, "mul") ? x.of : [x])
      brackets = Ops.filt(bits, ->(b) {
        return Ops.eq(b.kind, "add")
      })
      if Ops.eq(brackets.length, 1)
        a = Ops.elem(brackets, 0)
        rest = Ops.filt(bits, ->(b) {
          return !Ops.eq(b.kind, "add")
        })
        id = Expr.show(a)
        at = groups.get(id)
        rests = (Ops.eq(at, nil) ? [] : Ops.elem(at, 1))
        Ops.m_push(rests, (Ops.m_empty(rest) ? Expr.num(1) : Expr.mul(rest)))
        groups.set(id, [a, rests])
      else
        Ops.m_push(loose, x)
      end
    end
    unless Ops.m_empty(loose)
      Ops.list(groups.values).each do |g|
        unless Ops.m_empty(loose)
          la = Expr.gather(Expr.expand(Expr.add(loose)))
          n = (Ops.eq(la.kind, "add") ? la.of.length : 1)
          less = Expr.gather(Expr.expand(Expr.sub(la, Ops.elem(g, 0))))
          more = Expr.gather(Expr.expand(Expr.add([la, Ops.elem(g, 0)])))
          m_less = (Ops.eq(less.kind, "add") ? less.of.length : ((((Ops.eq(less.kind, "num") && Ops.eq(less.value, 0))) ? 0 : 1)))
          m_more = (Ops.eq(more.kind, "add") ? more.of.length : ((((Ops.eq(more.kind, "num") && Ops.eq(more.value, 0))) ? 0 : 1)))
          if Ops.lt(m_less, n)
            Ops.m_push(Ops.elem(g, 1), Expr.num(1))
            loose = (Ops.eq(m_less, 0) ? [] : [less])
          else
            if Ops.lt(m_more, n)
              Ops.m_push(Ops.elem(g, 1), Expr.num((-1)))
              loose = (Ops.eq(m_more, 0) ? [] : [more])
            end
          end
        end
      end
    end
    out = Ops.filt(Ops.m_map(groups.values, ->(g) {
      by = Expr.gather(Expr.add(Ops.elem(g, 1)))
      if (Ops.eq(by.kind, "num") && Ops.eq(by.value, 0))
        return Expr.num(0)
      end
      return Expr.mul([by, Ops.elem(g, 0)])
    }), ->(t) {
      return !(((Ops.eq(t.kind, "num") && Ops.eq(t.value, 0))))
    })
    if !(Ops.m_empty(loose))
      Ops.m_push(out, Expr.gather(Expr.add(loose)))
    end
    return (Ops.m_empty(out) ? Expr.num(0) : Expr.add(out))
  end
  def self.split(e, name)
    t = Expr.expand(e)
    terms = (Ops.eq(t.kind, "add") ? t.of : [t])
    coef = []
    rest = []
    ok = true
    Ops.list(terms).each do |x|
      bits = (Ops.eq(x.kind, "mul") ? x.of : [x])
      mine = Ops.filt(bits, ->(b) {
        return (Ops.eq(b.kind, "field") && Ops.eq(b.label, name))
      })
      if Ops.m_empty(mine)
        Ops.m_push(rest, x)
        if Expr.mentions(x, name)
          ok = false
        end
      else
        if Ops.eq(mine.length, 1)
          others = Ops.filt(bits, ->(b) {
            return !(((Ops.eq(b.kind, "field") && Ops.eq(b.label, name))))
          })
          if Ops.m_some(others, ->(b) {
            return Expr.mentions(b, name)
          })
            ok = false
          end
          Ops.m_push(coef, (Ops.m_empty(others) ? Expr.num(1) : Expr.mul(others)))
        else
          ok = false
        end
      end
    end
    if (!(ok) || Ops.m_empty(coef))
      return nil
    end
    return [Expr.simplify(Expr.add(coef)), Expr.simplify((Ops.m_empty(rest) ? Expr.num(0) : Expr.add(rest)))]
  end
  def self.linear(e, name)
    parts = Ops.m_split(Expr, e, name)
    if Ops.eq(parts, nil)
      return nil
    end
    return Expr.simplify(Expr.div(Expr.neg(Ops.elem(parts, 1)), Ops.elem(parts, 0)))
  end
  def self.flip(e)
    if Ops.eq(e.kind, "add")
      return Expr.simplify(Expr.add(Ops.m_map(e.of, ->(x) {
        return Expr.neg(x)
      })))
    end
    if Ops.eq(e.kind, "mul")
      done = false
      out = Ops.m_map(e.of, ->(x) {
        if done
          return x
        end
        if (Ops.eq(x.kind, "add") || Ops.eq(x.kind, "num"))
          done = true
          return (Ops.eq(x.kind, "add") ? Expr.flip(x) : Expr.num((-x.value)))
        end
        return x
      })
      return (done ? Expr.mul(out) : Expr.neg(e))
    end
    return Expr.neg(e)
  end
  def self.reduced(e)
    t = Expr.simplify(e)
    terms = (Ops.eq(t.kind, "add") ? t.of : [t])
    under = ->(b) {
      return ((Ops.eq(b.kind, "pow") && Ops.eq(b.power.kind, "num")) && Ops.lt(b.power.value, 0))
    }
    groups = Keyed.new()
    order = []
    Ops.list(terms).each do |x|
      bits = (Ops.eq(x.kind, "mul") ? x.of : [x])
      dens = Ops.filt(bits, ->(b) {
        return under.(b)
      })
      nums = Ops.filt(bits, ->(b) {
        return !(under.(b))
      })
      id = Ops.m_join(Ops.m_map(dens, ->(d) {
        return Expr.show(d)
      }), "·")
      at = groups.get(id)
      tops = (Ops.eq(at, nil) ? [] : Ops.elem(at, 1))
      Ops.m_push(tops, (Ops.m_empty(nums) ? Expr.num(1) : Expr.mul(nums)))
      if Ops.eq(at, nil)
        Ops.m_push(order, id)
      end
      groups.set(id, [dens, tops])
    end
    out = Ops.m_map(order, ->(id) {
      g = groups.get(id)
      num = Expr.deep_factored(Expr.gather(Expr.expand(Expr.add(Ops.elem(g, 1)))))
      if Ops.m_empty(Ops.elem(g, 0))
        return num
      end
      bases = Ops.m_map(Ops.elem(g, 0), ->(d) {
        return Expr.show(d.base)
      })
      sign = 1
      fixed = Ops.m_map(((Ops.eq(num.kind, "mul") ? num.of : [num])), ->(a) {
        if (Ops.eq(a.kind, "add") && Ops.m_contains(bases, Expr.show(Expr.flip(a))))
          sign = (-sign)
          return Expr.flip(a)
        end
        return a
      })
      return Expr.simplify(Expr.mul(Ops.m_concat(Ops.m_concat([Expr.num(sign)], fixed), Ops.elem(g, 0))))
    })
    return Expr.simplify(Expr.add(out))
  end
  def self.quotient_d(n, d, wrt)
    top = Expr.sub(Expr.mul([Expr.d(n, wrt), d]), Expr.mul([n, Expr.d(d, wrt)]))
    return Expr.div(Expr.deep_factored(Expr.simplify(Expr.expand(top))), Expr.to_power(d, Expr.num(2)))
  end
  def self.expand(e)
    t = Expr.simplify(e)
    if Ops.eq(t.kind, "add")
      return Expr.simplify(Expr.add(Ops.m_map(t.of, ->(x) {
        return Expr.expand(x)
      })))
    end
    if Ops.eq(t.kind, "mul")
      parts = Ops.m_map(t.of, ->(x) {
        return Expr.expand(x)
      })
      out = [Expr.num(1)]
      Ops.list(parts).each do |p|
        terms = (Ops.eq(p.kind, "add") ? p.of : [p])
        _next = []
        Ops.list(out).each do |a|
          Ops.list(terms).each do |b|
            Ops.m_push(_next, Expr.mul([a, b]))
          end
        end
        out = _next
      end
      return Expr.simplify(Expr.add(out))
    end
    return t
  end
  def self.deep_factored(e, depth = 0)
    if Ops.gt(depth, 6)
      return Expr.simplify(e)
    end
    inner = (Ops.eq(e.kind, "add") ? Expr.add(Ops.m_map(e.of, ->(x) {
      return Expr.deep_factored(x, Ops.add(depth, 1))
    })) : ((Ops.eq(e.kind, "mul") ? Expr.mul(Ops.m_map(e.of, ->(x) {
      return Expr.deep_factored(x, Ops.add(depth, 1))
    })) : e)))
    t = Expr.factored(Expr.simplify(inner))
    if Ops.eq(t.kind, "mul")
      return Expr.simplify(Expr.mul(Ops.m_map(t.of, ->(x) {
        return (Ops.eq(x.kind, "add") ? Expr.add(Ops.m_map(x.of, ->(y) {
          return Expr.deep_factored(y, Ops.add(depth, 1))
        })) : x)
      })))
    end
    if Ops.eq(t.kind, "add")
      return Expr.simplify(Expr.add(Ops.m_map(t.of, ->(x) {
        return Expr.deep_factored(x, Ops.add(depth, 1))
      })))
    end
    return t
  end
  def self.evaluate(e, at)
    go = ->(x) {
      k = x.kind
      if (Ops.eq(k, "field") || Ops.eq(k, "sym"))
        return ((!Ops.eq(Ops.elem(at, x.label), nil) ? Expr.num(Ops.elem(at, x.label)) : x))
      end
      if Ops.eq(k, "add")
        return Expr.add(Ops.m_map(x.of, ->(y) {
          return go.(y)
        }))
      end
      if Ops.eq(k, "mul")
        return Expr.mul(Ops.m_map(x.of, ->(y) {
          return go.(y)
        }))
      end
      if Ops.eq(k, "pow")
        return Expr.to_power(go.(x.base), go.(x.power))
      end
      if Ops.eq(k, "grad")
        return Expr.grad(go.(x.base))
      end
      if Ops.eq(k, "gammaInc")
        a = go.(x.first_)
        b = go.(x.second_)
        return (((Ops.eq(a.kind, "num") && Ops.eq(b.kind, "num"))) ? Expr.num(Expr.gamma_upper(a.value, b.value)) : Expr.gamma_inc(a, b))
      end
      if Ops.eq(k, "log")
        return Expr.log(go.(x.base))
      end
      if Ops.eq(k, "exp")
        return Expr.exp(go.(x.base))
      end
      if Ops.eq(k, "choose")
        return Expr.choose(go.(x.first_), go.(x.second_))
      end
      if Ops.eq(k, "root")
        v = Expr.solve_root(x.base, x.bound, at)
        return (Expr.finite(v) ? Expr.num(v) : Expr.root(go.(x.base), x.bound))
      end
      if Ops.eq(k, "limit")
        v = Expr.to_infinity(x.base, x.bound, at)
        return (Expr.finite(v) ? Expr.num(v) : Expr.limit(go.(x.base), x.bound))
      end
      if Ops.eq(k, "call")
        return Expr.call(x.label, go.(x.base))
      end
      return x
    }
    return Expr.simplify(go.(e))
  end
  def self.name_of(symbol)
    i = Ops.m_index_of(Expr.SYMBOLS, symbol)
    return (Ops.eq(i, nil) ? symbol : Ops.elem(Expr.NAMES, i))
  end
  def self.of_node(n)
    c = n.construct
    if Ops.eq(c, "number")
      return Expr.num(Algebra.number_of(n))
    end
    if Ops.eq(c, "member")
      s = Algebra.symbol_of(n)
      if !Ops.eq(s, nil)
        return Expr.field(Expr.name_of(s))
      end
    end
    if Ops.eq(c, "dynamic")
      return Expr.field(Expr.name_of(Ops.m_take(Ops.m_drop(n.name.source, 1), Ops.sub(n.name.source.length, 2))))
    end
    if Ops.eq(c, "paren")
      return Expr.of_node(n.inner)
    end
    if Ops.eq(c, "unary")
      if Ops.eq(n.operator, "-")
        return Expr.neg(Expr.of_node(n.operand))
      end
    end
    if Ops.eq(c, "binary")
      l = Expr.of_node(n.left)
      r = Expr.of_node(n.right)
      op = n.operator
      if Ops.eq(op, "+")
        return Expr.add([l, r])
      end
      if Ops.eq(op, "-")
        return Expr.sub(l, r)
      end
      if Ops.eq(op, "*")
        return Expr.mul([l, r])
      end
      if Ops.eq(op, "/")
        return Expr.div(l, r)
      end
      if Ops.eq(op, "^")
        return Expr.to_power(l, r)
      end
    end
    if Ops.eq(c, "method")
      if Ops.eq(n.method, "root")
        nm = Ops.elem(n.arguments, 1).value.source
        return Expr.root(Expr.of_node(Ops.elem(n.arguments, 2).value.body), Expr.name_of(Ops.m_take(Ops.m_drop(nm, 1), Ops.sub(nm.length, 2))))
      end
      if Ops.eq(n.method, "ln")
        return Expr.log(Expr.of_node(n.receiver))
      end
      return Expr.call(n.method, Expr.of_node((Ops.m_empty(n.arguments) ? n.receiver : Ops.elem(n.arguments, 0).value)))
    end
    return Expr.field(n.source)
  end
  def self.of_source(text)
    r = ExprReader.new(text: text)
    return r.addition
  end
  __exposed
end

class ExprReader < Node
  def text(*args_)
    args_.empty? ? @text : @text.(*args_)
  end
  attr_writer :text
  def at(*args_)
    @at = (0) unless instance_variable_defined?(:@at)
    args_.empty? ? @at : @at.(*args_)
  end
  attr_writer :at
  def peek
    return (Ops.lt(self.at, self.text.length) ? Ops.elem(Ops.m_chars(self.text), self.at) : 0)
  end
  def skip
    while Ops.eq(self.peek, 32)
      self.at = Ops.add(self.at, 1)
    end
  end
  def eat(n)
    got = Notation.sub_(self.text, self.at, Ops.add(self.at, n))
    self.at = Ops.add(self.at, n)
    return got
  end
  def starts(s)
    return Ops.eq(Notation.sub_(self.text, self.at, Ops.add(self.at, s.length)), s)
  end
  def addition
    left = self.product
    self.skip
    while (Ops.eq(self.peek, 43) || ((Ops.eq(self.peek, 45) && !(self.starts("->")))))
      op = self.eat(1)
      right = self.product
      left = (Ops.eq(op, "+") ? Expr.add([left, right]) : Expr.sub(left, right))
      self.skip
    end
    return left
  end
  def product
    left = self.power
    self.skip
