      self.word
      self.skip
      self.eat(1)
      self.skip
      self.eat(1)
      k = self.at
      while (Ops.lt(k, self.text.length) && !Ops.eq(Ops.elem(Ops.m_chars(self.text), k), 34))
        k = Ops.add(k, 1)
      end
      name = self.eat(Ops.sub(k, self.at))
      self.eat(1)
      self.skip
      self.eat(1)
      self.skip
      self.eat(1)
      self.word
      self.eat(1)
      self.skip
      self.eat(2)
