    return Ops.m_map(self.proved, ->(p) {
      return p.theorem
    })
  end
  def json
    sep = ", "
    items = Ops.m_join(Ops.m_map(self.proved, ->(p) {
      return p.registry
    }), sep)
    return "#{Ops.quoted(self.theory)}: {#{items}}"
  end
  __exposed
end

class TermInfo < Node
  def term(*args_)
    args_.empty? ? @term : @term.(*args_)
  end
  attr_writer :term
  def rules
    return (((Ops.eq(self.term.rule, nil) || self.outside)) ? [] : [Ops.m_upper(self.term.rule.name)])
  end
  def rule_id
    return (Ops.eq(self.term.rule, nil) ? nil : self.term.rule.id)
  end
  def rate
    return (Ops.eq(self.term.rate, nil) ? nil : Expr.name_of(self.term.rate))
  end
  def degree
    return self.term.degree
  end
  def facing
    return Ops.ge(self.term.degree, 2)
  end
  def outside
    return self.term.outside
  end
  def settles
    return self.term.settles
  end
  def carries
    return self.term.doing.carries
  end
  def transport
    return self.term.transport
  end
  def side
    return (((self.settles || self.transport)) ? "left" : "right")
  end
  def share
    return (Ops.eq(self.term.doing.share.source, "1") ? nil : Expr.of_source(self.term.doing.share.source))
  end
  def asked
    return (Ops.eq(self.term.doing.asked.source, "1") ? nil : Expr.of_source(self.term.doing.asked.source))
  end
  def around
    return (Ops.eq(self.term.doing.around.source, "1") ? nil : Expr.of_source(self.term.doing.around.source))
  end
  def ray_count
    return Expr.of_source(self.term.doing.rays.source)
  end
  def space_count
    return Expr.of_source(self.term.doing.space.source)
  end
  def fold_count
    return Expr.of_source(self.term.doing.folds.source)
  end
  def rays
    return Expr.show(Expr.simplify(self.ray_count))
  end
  def space
    return Expr.show(Expr.simplify(self.space_count))
  end
  def folds
    return Expr.show(Expr.simplify(self.fold_count))
  end
  def net
    return Expr.numeric(Expr.evaluate(self.ray_count, TermInfo.COUNTS), TermInfo.COUNTS)
  end
  def space_net
    return Expr.numeric(Expr.evaluate(self.space_count, TermInfo.COUNTS), TermInfo.COUNTS)
  end
  def sign
    return (Ops.lt(self.net, 0) ? (-1) : 1)
  end
  def over
    return (Ops.eq(self.term.rule, nil) ? "World" : ((Ops.eq(self.term.rule.over, "Vertex") ? "Local" : self.term.rule.over)))
  end
  def says
    return (Ops.eq(self.term.rule, nil) ? "put in from outside" : self.term.rule.source)
  end
  def draws
    return !Ops.eq(self.term.doing.draws, nil)
  end
  def grown
    return self.term.doing.grown
  end
  def grew_count
    return Expr.of_source(self.term.doing.grew.source)
  end
  def grew_apart_count
    return (Ops.eq(self.term.doing.grew_apart, nil) ? Expr.num(0) : Expr.of_source(self.term.doing.grew_apart.source))
  end
  def held_count
    return Expr.simplify(Expr.sub(self.space_count, self.grew_count))
  end
  def held
    return Expr.show(Expr.simplify(self.held_count))
  end
  def grows
    return Expr.show(Expr.simplify(self.grew_count))
  end
  def kernel
    return !Ops.eq(self.term.leans, nil)
  end
  def keeps
    return Expr.pown(Expr.add([Expr.num(1), Expr.field("n_{f}")]), (-1))
  end
  def drifts
    return Expr.grad(Expr.field("n_{f}"))
  end
  def self.COUNTS
    s = Node.new
    Ops.setattr(s, "DEG", 8)
    return s
  end
  def expr
    parts = []
    if self.outside
      Ops.m_push(parts, Expr.field("l.\\bar{m}"))
      if !Ops.eq(self.around, nil)
        Ops.m_push(parts, self.around)
      end
    else
      if !Ops.eq(self.rate, nil)
        Ops.m_push(parts, Expr.field(self.rate))
      end
      if !Ops.eq(self.share, nil)
        Ops.m_push(parts, self.share)
      end
      if Ops.gt(self.degree, 0)
        Ops.m_push(parts, Expr.pown(Expr.field("n"), self.degree))
      end
    end
    return (Ops.m_empty(parts) ? Expr.num(1) : Expr.mul(parts))
  end
  def gate
    s = (self.outside ? self.around : self.share)
    if Ops.eq(s, nil)
      return ""
    end
    return (Ops.eq(Expr.simplify(s).kind, "add") ? "\\paren{#{Expr.show(s)}}" : Expr.show(s))
  end
  def operator
    if self.settles
      return "\\partial_{t}"
    end
    if self.transport
      carry = "\\hat{d}·\\nabla_{l}"
      return (self.kernel ? "#{carry} + \\paren{#{Expr.show(self.drifts)}}·\\nabla_{\\hat{d}}" : carry)
    end
    return nil
  end
  def self.powers(n, degree)
    return (Ops.eq(degree, 0) ? "" : ((Ops.eq(degree, 1) ? n : ((Ops.eq(degree, 2) ? "#{n}\\tilde{#{n}}" : "#{n}^{#{degree}}")))))
  end
  def symbol
    population = "n"
    if self.outside
      return "#{self.gate}l.\\bar{m}"
    end
    if self.settles
      return "\\partial_{t}#{population}"
    end
    if self.transport
      return "#{self.operator}#{population}"
    end
    rate = Ops.or_else(self.rate) { "" }
    room = self.gate
    pw = TermInfo.powers(population, self.degree)
    gap = ((((!(Ops.m_empty(rate)) && Ops.m_empty(room)) && !(Ops.m_empty(pw)))) ? " " : "")
    return "#{rate}#{room}#{gap}#{pw}"
  end
  __exposed
end

class Prover < Node
  def theory(*args_)
    args_.empty? ? @theory : @theory.(*args_)
  end
  attr_writer :theory
  def self.PROOFS
    @PROOFS = (Node.new) unless instance_variable_defined?(:@PROOFS)
    @PROOFS
  end
  def self.PROOFS=(v)
    @PROOFS = v
  end
  def population_line(*args_)
    @population_line = (nil) unless instance_variable_defined?(:@population_line)
    args_.empty? ? @population_line : @population_line.(*args_)
  end
  attr_writer :population_line
  def record_line(*args_)
    @record_line = (nil) unless instance_variable_defined?(:@record_line)
    args_.empty? ? @record_line : @record_line.(*args_)
  end
  attr_writer :record_line
  def store(*args_)
    @store = (Store.new()) unless instance_variable_defined?(:@store)
    args_.empty? ? @store : @store.(*args_)
  end
  attr_writer :store
  def equation
    return self.theory.equation
  end
  def infos
    return Ops.m_map(self.equation.terms, ->(t) {
      return TermInfo.new(term: t)
    })
  end
  def acting
    return Ops.filt(self.infos, ->(t) {
      return ((!Ops.eq(t.side, "left") && !(Ops.m_empty(t.rules))) && !Ops.eq(t.rate, nil))
    })
  end
  def self.rho
    return Expr.field("\\rho")
  end
  def self.text(f)
    return (Ops.eq(f.to, nil) ? "-" : Expr.show(f.to))
  end
  def self.body_of(t)
    parts = [Expr.field(t.rate)]
    if !Ops.eq(t.share, nil)
      Ops.m_push(parts, t.share)
    end
    if Ops.gt(t.degree, 0)
      Ops.m_push(parts, Expr.pown(Prover.rho, t.degree))
    end
    return Expr.simplify(Expr.mul(parts))
  end
  def premises
    out = []
    equation = self.equation
    infos = self.infos
    acting = self.acting
    a = Expr.num(0)
    steps = []
    Ops.list(acting).each do |t|
      body = Prover.body_of(t)
      slope = Expr.simplify(Expr.d(body, "\\rho"))
      signed = Expr.simplify(Expr.mul([Expr.num((Ops.eq(t.sign, (-1)) ? 1 : (-1))), slope]))
      a = Expr.simplify(Expr.add([a, signed]))
      nm = Ops.m_join(t.rules, ", ")
      how = (Ops.eq(t.sign, (-1)) ? "subtracted" : "added")
      leaf = Step.of(Fact.stands("how #{t.symbol} answers a change in the density", signed), "differentiating a term", [Fact.key_of("is", t.symbol)], "#{nm} contributes #{t.symbol}, which is its rate times what its gates let through times the density to the power its quantifier gives. How that answers a small change in the density is the DERIVATIVE - the product rule, on what the rule already said the term was. A term that shrinks as the density rises pushes a shortfall back, so the sign is turned about what the term itself carries", ["#{t.symbol} = #{Expr.show(body)}", "d/d\\rho = #{Expr.show(slope)}", "the term is #{how}, so it restores by #{Expr.show(signed)}"])
      leaf.rule = Ops.elem(t.rules, 0)
      term = self.from_rule(t)
      leaf.derivation = Ops.m_concat(term.nodes, [leaf])
      Ops.m_push(steps, leaf)
    end
    restored = Step.of(Fact.new(kind: "restored", of: "\\rho", to: a), "and so the rate", Ops.m_map(steps, ->(x) {
      return x.fact.key
    }), "every term that depends on the density answers a change in it, and they do not consult one another - so what the line does back to A CHANGE IN THE DENSITY is their sum", Ops.m_concat(Ops.m_map(Ops.rng(acting.length), ->(i) {
      return "#{Ops.elem(acting, i).symbol}: #{Expr.show(Ops.elem(steps, i).fact.to)}"
    }), ["a = #{Expr.show(a)}"]))
    restored.derivation = steps
    Ops.m_push(out, restored)
    reaching = Ops.filt(infos, ->(t) {
      return (!(Ops.m_empty(t.rules)) && t.outside)
    })
    if Ops.m_empty(reaching)
      count = Ops.filt(infos, ->(t) {
        return !(Ops.m_empty(t.rules))
      }).length
      Ops.m_push(out, Step.of(Fact.new(kind: "conserved", of: "\\delta"), "every rule is a function of its own match", [], "a rule reads the refs its match handed over and nothing else, so two worlds that agree about a match agree after it - a difference between them can be moved and cannot be made or unmade. What a meeting takes from the disturbed world it leaves as a hole in the undisturbed one, and the difference is the same size. So as much of the shortfall crosses a far shell as a near one, which is what the dilution argument wants", ["every one of the #{count} terms the line carries is a rule acting on the match it was handed", "none of them consults anything outside it, so agreement is carried and disagreement is only moved", "the DENSITY is pushed back at a = #{Expr.show(a)}, which is a different quantity"]))
    end
    turning = Ops.m_first(Ops.filt(infos, ->(t) {
      return t.kernel
    }))
    if !Ops.eq(turning, nil)
      g = Expr.simplify(turning.keeps)
      tr = Expr.simplify(Expr.mul([Expr.field("\\sigma"), Expr.sub(Expr.num(1), turning.keeps)]))
      via = Ops.m_join(turning.rules, ", ")
      gs = Step.of(Fact.stands("g", g), (Ops.m_empty(via) ? "the turn" : via), [], "the rule's body chooses where a ray goes next, and what is left of a heading after one such choice is its cosine moment - one way straight on against the folded ones", ["the choice is 1 way straight on against n_{f} folded", "g = #{Expr.show(g)}"])
      gs.rule = Ops.elem(turning.rules, 0)
      st = Step.of(Fact.stands("\\sigma_{tr}", tr), "the kernel", [], "what removes a DIRECTION is not what removes a ray: a turn that sends it on nearly the way it was going has hardly removed it, so the transport cross section is sigma times what the turn does NOT keep", [])
      st.derivation = [gs, Step.of(Fact.stands("\\sigma_{tr}", tr), "and so the transport cross section", [Fact.key_of("is", "g")], "what removes a RAY is not what removes a DIRECTION: a turn that sends it on nearly the way it was going has hardly removed it, so what attenuates a shadow is the rate times what the turn does NOT keep", ["g = #{Expr.show(g)}", "\\sigma_{tr} = \\sigma(1-g) = #{Expr.show(tr)}"])]
      Ops.m_push(out, st)
      sw = Step.of(Fact.stands("what swings a heading", turning.drifts), "the kernel", [], "the line's direction term is the kernel's first moment - which way a turn leans on average", [])
      inner = Step.of(Fact.stands("what swings a heading", turning.drifts), (Ops.m_empty(via) ? "the turn" : via), [], "the same choice, read as a first moment rather than as a cosine: where the cosine says how much of a heading survives, this says which way what is left of it leans - and it leans toward where the folds are, since those are the ways the choice offers besides straight on", ["the choice is 1 way straight on against n_{f} folded", "<d^> = #{Expr.show(Expr.simplify(turning.drifts))}"])
      inner.rule = Ops.elem(turning.rules, 0)
      sw.derivation = [inner]
      Ops.m_push(out, sw)
    end
    rates = []
    Ops.list(infos).each do |t|
      if (!Ops.eq(t.rate, nil) && !(Ops.m_contains(rates, t.rate)))
        Ops.m_push(rates, t.rate)
      end
    end
    Ops.list(rates).each do |name|
      Ops.m_push(out, Step.of(Fact.stands(name, Expr.num(1)), "the rewrite", [], "a rewrite fires on every match it has, once a tick - that is what a rule of this model is. So its rate is ONE per match per tick, and the name on it says which rewrite rather than how often: there is nothing here to choose or to fit", ["#{name} = 1 per match per tick"]))
    end
    Ops.list(["rays", "space", "folds"]).each do |ledger|
      parts = []
      Ops.list(acting).each do |t|
        c = (Ops.eq(ledger, "rays") ? t.ray_count : ((Ops.eq(ledger, "space") ? t.space_count : t.fold_count)))
        Ops.m_push(parts, Expr.simplify(Expr.mul([Prover.body_of(t), c])))
      end
      unless Ops.m_empty(parts)
        Ops.m_push(out, Step.of(Fact.stands("the #{ledger} line nets", Expr.simplify(Expr.add(parts))), "the line", [], "every term of the line does something to the #{ledger} ledger - its rate, times what its gates let through, times the count one firing puts in - and what the ledger does per point per tick is those added up. Nothing is left out and nothing is counted twice, which is the whole reason for reading it off the line rather than assembling it again wherever it is wanted", Ops.m_map(acting, ->(t) {
          c = (Ops.eq(ledger, "rays") ? t.ray_count : ((Ops.eq(ledger, "space") ? t.space_count : t.fold_count)))
          return "#{Ops.m_join(t.rules, Physics.sep2)}: #{t.symbol} into #{ledger} #{Expr.show(c)}"
        })))
      end
    end
    meetings = Ops.filt(infos, ->(t) {
      return ((!(t.outside) && !Ops.eq(t.term.rule, nil)) && Ops.eq(t.term.rule.over, "Edge"))
    })
    unless Ops.m_empty(meetings)
      named = Ops.m_first(Ops.m_first(meetings).rules)
      grown = Expr.simplify(Expr.add(Ops.m_map(meetings, ->(t) {
        return t.grew_apart_count
      })))
      Ops.m_push(out, Step.of(Fact.stands("what bodies' rays grow where they meet", grown), named, [], "#{named} read on two bodies' rays: each still leaves the point behind it where the way behind is dark, and behind a body's ray - lit by a source, not by CREATE, and met in the vacuum's dark half - nothing stands, so both gates are open", ["behind a vacuum ray: the ray CREATE lit with it, so nothing is grown", "behind a body's ray in the dark half: nothing, so a point is grown", "grown a meeting = #{Expr.show(grown)}"]))
      rho_ = Prover.rho
      Ops.m_push(out, Step.of(Fact.stands("\\bar{n}", Expr.num(0)), "the world", [], "how much of a way carries some body's ray, on the world's mean - a fact about what the world holds, not about its rules, so it is put in; in the settled vacuum, with no body in it, it is nought", ["\\bar{n} = 0 in the empty vacuum, an input where a world is asked about"]))
      eps = Expr.simplify(Expr.mul([Expr.num(2), Expr.field("\\sigma"), Expr.field("F"), Expr.sub(Expr.num(1), rho_), Expr.pown(rho_, 2)]))
      Ops.m_push(out, Step.of(Fact.stands("\\varepsilon", eps), "the vacuum", [], "what the empty vacuum grows on its own, per point per tick: a vacuum ray meeting with the way behind it not lit in the same event. Not yet derived from the rules - put in, at the rate the meetings were read to grow at before", ["\\varepsilon = #{Expr.show(eps)}, a placeholder until derived"]))
      matter = Expr.simplify(Expr.mul([Expr.field("\\sigma"), Expr.field("F"), Expr.pown(Expr.field("\\bar{n}"), 2), grown]))
      Ops.m_push(out, Step.of(Fact.stands("the world's matter grows", matter), named, [Fact.key_of("is", "what bodies' rays grow where they meet"), Fact.key_of("is", "\\bar{n}")], "two bodies' rays meet as any two rays do - at the rate, facing, each end carrying - and each such meeting grows what the rule read on bodies' rays says: per point per tick, that is how much the world grows", ["\\sigma F \\bar{n}^{2}: two bodies' rays facing on a way", "times #{Expr.show(grown)} grown a meeting", "= #{Expr.show(matter)}"]))
    end
    Ops.list(acting).each do |t|
      body = Prover.body_of(t)
      which = (Ops.lt(t.sign, 0) ? "taken" : "made")
      nm = Ops.m_join(t.rules, ", ")
      verb = (Ops.lt(t.sign, 0) ? "takes" : "makes")
      if !Ops.eq(t.rays, "0")
        made = Step.of(Fact.stands("what is #{which}", body), Ops.elem(t.rules, 0), [], "#{nm} #{verb} at #{Expr.show(body)} - its rate, times what its gates let through, times the density to the power its quantifier gives", [])
        made.rule = Ops.elem(t.rules, 0)
        Ops.m_push(out, made)
      end
      if ((Ops.eq(t.rays, "0") && Ops.gt(t.space_net, 0)) && t.carries)
        w = Step.of(Fact.stands("what the waiting makes", body), Ops.elem(t.rules, 0), [], "#{nm} hands the ray to itself and grows the world - no ray made, destroyed or moved, and a point of space where there was none. That is a carrier standing still to make the room it could not step into, and the rate it does so at is #{Expr.show(body)}", ["no rays, #{Expr.show(t.space_count)} of space", "the waiting makes #{Expr.show(body)}"])
        w.rule = Ops.elem(t.rules, 0)
        Ops.m_push(out, w)
      end
      Ops.list(Ops.filt([["rays", t.ray_count], ["space", t.space_count], ["folds", t.fold_count]], ->(_) {
        return !Ops.eq(t.rays, "0")
      })).each do |pair|
        ledger = Ops.elem(pair, 0)
        per = Ops.elem(pair, 1)
        c = Step.of(Fact.stands("the #{ledger} count of what is #{which}", per), Ops.elem(t.rules, 0), [], "#{nm} fires at #{Expr.show(body)}, and ONE firing of it puts #{Expr.show(per)} into the #{ledger} ledger - counted off the body, not written down. The two ledgers get different counts from the same firing, which is why they do not settle at the same density", ["fires at #{Expr.show(body)}", "#{ledger} per firing: #{Expr.show(per)}"])
        c.rule = Ops.elem(t.rules, 0)
        Ops.m_push(out, c)
      end
    end
    maker = Ops.m_first(Ops.filt(acting, ->(t) {
      return Ops.gt(t.sign, 0)
    }))
    if !Ops.eq(maker, nil)
      parts = [Expr.field(maker.rate)]
      if !Ops.eq(maker.share, nil)
        Ops.m_push(parts, maker.share)
      end
      s = Step.of(Fact.stands("S", Expr.simplify(Expr.mul(parts))), Ops.elem(maker.rules, 0), [], "#{Ops.m_join(maker.rules, Physics.sep2)} fires because a point is neutral, and matter is not - so what a body puts into the medium is exactly the making that did not happen where it sits. Its strength is that term, and is not a quantity of its own", [])
      s.rule = Ops.elem(maker.rules, 0)
      Ops.m_push(out, s)
    end
    lit = Ops.m_first(Ops.filt(acting, ->(t) {
      return (Ops.gt(t.sign, 0) && !Ops.eq(t.rays, "0"))
    }))
    if !Ops.eq(lit, nil)
      w = Step.of(Fact.stands("the ways out of a point", Expr.field(lit.rays)), Ops.elem(lit.rules, 0), [], "#{Ops.m_join(lit.rules, Physics.sep2)} lights every exit a point has, so the count its body ran over is how many ways out there are - #{lit.rays}. A shortfall is ways out that are missing, so that count is also its ceiling", ["the body lit #{lit.rays} exits", "so a point has #{lit.rays} ways out"])
      w.rule = Ops.elem(lit.rules, 0)
      Ops.m_push(out, w)
    end
    source = Ops.m_first(Ops.filt(infos, ->(t) {
      return t.outside
    }))
    if !Ops.eq(source, nil)
      chosen = [Expr.field("\\bar{m}_{x}"), Expr.field("l.DEG")]
      if !Ops.eq(source.asked, nil)
        Ops.m_push(chosen, source.asked)
      end
      mass = Expr.call("l.choose", Expr.simplify(Expr.mul(chosen)))
      Ops.m_push(out, Step.of(Fact.stands("l.\\bar{m}", mass), "put in from outside", [], "the line is written at a local, l, and what a source puts in there is its mass - a choice over that local's ways out: which of its l.DEG exits it lights, at \\bar{m}_{x} apiece, on the ticks its own rule leaves it. The gate the rule asked of the source is inside the choice because it is a statement about which exits, and the line carries nothing of the source but this", ["the term is #{source.symbol}", "l.\\bar{m} = #{Expr.show(mass)}"]))
      parts = [mass]
      if !Ops.eq(source.around, nil)
        Ops.m_push(parts, source.around)
      end
      sigma = Expr.simplify(Expr.mul(parts))
      Ops.m_push(out, Step.of(Fact.stands("what a body puts out", sigma), "put in from outside", [], "what a body puts out is the term no rewrite puts there, scaled by what its gates let through - and a body going somewhere has spent that share of its ticks moving rather than shining, which is the whole of why a moving source is shifted. AND IT IS NAMED \\bar{m}_{x} BECAUSE THAT IS ITS NAME - how often per tick a source activates one direction, a fraction of \\bar{c} whose period is 1/\\bar{m}_{x}. Calling the same number \\Sigma_{0} here made the medium's ledger and the source's own rate look like two quantities, and every law that touched both then carried the seam between them", ["the term is #{source.symbol}"]))
      Ops.m_push(out, Step.of(Fact.new(kind: "conserved", of: "what a body puts out"), "the kernel", [], "what a source puts out survives its own transport for the same reason a shortfall does - a turn that keeps the heading loses none of it", []))
      Ops.m_push(out, Step.of(Fact.new(kind: "isotropic", of: "what a body puts out"), "put in from outside", [], "a body lights its exits alike, so what leaves it goes every way alike", []))
      feels = Step.of(Fact.stands("what a body feels", Expr.field("\\sum\\hat{d}")), "EMISSION", [], "the rule adds the ray's own exit to the body's momentum, once per ray taken - so what a body feels is the vector sum of the directions that arrived at it, and a count of them would be a different quantity that is not what any rule computes", ["each absorbed ray adds its exit", "force = \\sum \\hat{d} over what arrives"])
      feels.rule = "EMISSION"
      Ops.m_push(out, feels)
    end
    carrying = Ops.filt(infos, ->(t) {
      return t.transport
    })
    moving = Ops.m_first(carrying)
    if !Ops.eq(moving, nil)
      if !Ops.eq(moving.share, nil)
        advancing = Expr.simplify(Expr.add(Ops.m_map(Ops.filt(carrying, ->(t) {
          return !Ops.eq(t.share, nil)
        }), ->(t) {
          return t.share
        })))
        st = Step.of(Fact.stands("what share of a step advances", advancing), Ops.elem(moving.rules, 0), [], "the streaming term is gated: a ray hands over only where the way it drew leads somewhere, and where it does not it makes the room and waits instead. That gate is on the transport, so it is on the speed - and its complement is on the waiting, which is the other arm of the same either and the only other thing in these rules that makes space. One share, both lines", [])
        st.rule = Ops.elem(moving.rules, 0)
        Ops.m_push(out, st)
      end
      c = Step.of(Fact.stands("\\bar{c}", Expr.num(1)), Ops.elem(moving.rules, 0), [], "every active ray goes ONE CELL along its own exit in one tick, which is what the streaming term says - so a step is one cell, and that is the only length the lattice has to measure anything else against", [])
      c.rule = Ops.elem(moving.rules, 0)
      Ops.m_push(out, c)
    end
    Ops.m_push(out, Step.of(Fact.stands("\\omega", Expr.num(1)), "a way always leads somewhere", [], "`outward` finds the point across the way, and where that point has been folded it follows it through to the hub it was folded into - so a way that led somewhere still does, hub or point. It comes back with nothing only where there is no point across the way at all, which is the edge of a finite world. The vacuum the line is written in is infinite: every way has a point across it, and the share of ways with room ahead is all of them", ["outward(d): the point across d; folded, the hub it is in; None only across the world's edge", "an infinite vacuum has no edge", "\\omega = 1"]))
    Ops.m_push(out, Step.of(Fact.new(kind: "isotropic", of: "\\delta"), "the lattice", [], "the tiling has no preferred direction, so what spreads through it goes every way alike", []))
    return out
  end
  def from_rule(t)
    s = Store.new()
    name = Ops.elem(t.rules, 0)
    body = t.says
    pieces = []
    if !Ops.eq(t.rays, "0")
      Ops.m_push(pieces, "#{t.rays} rays")
    end
    if !Ops.eq(t.space, "0")
      Ops.m_push(pieces, "#{t.space} points of space")
    end
    if t.carries
      Ops.m_push(pieces, "carries the population")
    end
    if t.settles
      Ops.m_push(pieces, "settles the tick")
    end
    both = (Ops.m_empty(pieces) ? "nothing to either ledger" : Ops.m_join(pieces, ", "))
    top = "what the body does"
    b = Step.of(Fact.stands(top, t.ray_count), "the body", [], "#{body} - #{both}. The reading follows the body down through the methods it calls, and the ledgers it moves are counted off the assignments it makes", ["rays: #{t.rays}", "space: #{t.space}", "folds: #{t.folds}"])
    b.rule = name
    s.add(b)
    degree_of = (Ops.eq(t.degree, 0) ? "no power of the density" : ((Ops.eq(t.degree, 1) ? "the density once" : "the density to the power #{t.degree}")))
    facing = (t.facing ? " - and the two are across an edge, so the rate goes against the oncoming current, which is the facing factor F" : "")
    q = Step.of(Fact.stands("what #{name} is about", Expr.num(t.degree)), "the quantifier", [], "the rule is quantified over #{t.degree} population-bearing refs, so its term carries #{degree_of}#{facing}", [])
    q.rule = name
    s.add(q)
    gates = self.gates_of(t)
    Ops.list(gates).each do |g|
      gs = Step.of(Fact.stands("what #{Ops.elem(g, 0)} lets through", Ops.elem(g, 1)), "a gate", [], "the rule fires only where #{Ops.elem(g, 0)}, so whatever it does it does on that share of its matches and the term carries it", [])
      gs.rule = name
      s.add(gs)
    end
    shares = Ops.m_map(gates, ->(g) {
      return Ops.elem(g, 1)
    })
    rate = Ops.or_else(t.rate) { "nothing" }
    term = Step.of(Fact.stands(t.symbol, Expr.simplify(Expr.mul((Ops.m_empty(shares) ? [Expr.num(1)] : shares)))), "and so the term", Ops.m_concat([Fact.key_of("is", top), Fact.key_of("is", "what #{name} is about")], Ops.m_map(gates, ->(g) {
      return Fact.key_of("is", "what #{Ops.elem(g, 0)} lets through")
    })), "the rate it fires at is called #{rate}, and it fires on the share its gates let through, once per thing it is quantified over. Multiplied out, that is the term", Ops.m_concat(Ops.m_concat([(Ops.eq(t.rate, nil) ? "no rate - it neither makes nor takes" : "rate: #{t.rate}")], Ops.m_map(shares, ->(x) {
      return "share: #{Expr.show(x)}"
    })), ["degree: #{degree_of}", "term: #{t.symbol}"]))
    term.rule = name
    s.add(term)
    return s
  end
  def gates_of(t)
    if Ops.eq(t.share, nil)
      return []
    end
    where = ((Ops.eq(t.term.rule, nil) || Ops.eq(t.term.rule.where, nil)) ? "the match holds" : t.term.rule.where.source)
    return [[where, t.share]]
  end
  def self.saturate(s, rules, cap = 40)
    idle = Node.new
    round = 1
    while Ops.le(round, cap)
      s.round_ = round
      grew = 0
      rules.length.times do |i|
        rule = Ops.elem(rules, i)
        if !Ops.eq(Ops.elem(idle, i), s.version)
          before = s.version
          any = false
          Ops.list(rule.fire(s)).each do |st|
            if s.add(st)
              grew = Ops.add(grew, 1)
              any = true
            end
          end
          if !(any)
            Ops.set_at(idle, i, before)
          end
        end
      end
      if Ops.eq(grew, 0)
        return nil
      end
      round = Ops.add(round, 1)
    end
    return fail.("the rules are still producing facts - something in them feeds itself")
  end
  def model_step
    infos = self.infos
    right = Ops.filt(infos, ->(t) {
      return (Ops.eq(t.side, "right") && ((Ops.m_empty(t.rules) || !Ops.eq(t.rays, "0"))))
    })
    right = Ops.m_concat(Ops.filt(right, ->(t) {
      return !(Ops.m_empty(t.rules))
    }), Ops.filt(right, ->(t) {
      return Ops.m_empty(t.rules)
    }))
    rhs = Expr.add(Ops.m_map(right, ->(t) {
      return Expr.mul([t.ray_count, t.expr])
    }))
    st = Step.of(Fact.stands("the continuous model", rhs), "the reading", [], "the rules, read as a line: every rule of the theory is a term, the reading having run each rule's program on a symbolic match and counted what it does to the population - what it makes, what it takes, what it carries, what a body puts in - so the line is what the rules come to as a crowd rather than a description of them. Everything a theorem of this theory stands on is a term of this line or a reading of one, so every premise below is read off it, and every derivation passes through it", [self.line_text, self.space_text])
    st.derivation = self.line_steps
    return st
  end
  def self.not_the_lines(st)
    return (Ops.eq(st.fact.of, "what a body feels") || Ops.eq(st.via, "the lattice"))
  end
  def closure
    model = self.model_step
    self.store.add(model)
    infos = self.infos
    Ops.list(self.premises).each do |st|
      if (Ops.m_empty(st.upon) && !(Prover.not_the_lines(st)))
        term = (Ops.eq(st.rule, nil) ? nil : Ops.m_first(Ops.filt(infos, ->(t) {
          return (!(Ops.m_empty(t.rules)) && Ops.eq(Ops.elem(t.rules, 0), st.rule))
        })))
        if !Ops.eq(term, nil)
          sign = (Ops.lt(term.sign, 0) ? "-" : "+")
          share = (Ops.eq(term.share, nil) ? "1" : Expr.show(term.share))
          rate = Ops.or_else(term.rate) { "1" }
          how = "the term #{sign} #{term.symbol} of the continuous model: #{term.rays} rays a firing, at rate #{rate}, on the share #{share} of the matches, of degree #{term.degree} in the density"
          st.working = Ops.m_concat(["read off #{how}"], st.working)
          st.because = "READ OFF THE CONTINUOUS MODEL - #{how}; what this fact takes from it is below. #{st.because}"
        else
          st.working = Ops.m_concat(["read off the continuous model: #{st.fact.of}, which stands on every term of it alike"], st.working)
          st.because = "READ OFF THE CONTINUOUS MODEL - not one term of it but all of them, since this is about how the line is made. #{st.because}"
        end
        st.upon = [model.fact.key]
        st.via = "read off the continuous model"
        st.rule = nil
        st.derivation = []
      end
      self.store.add(st)
    end
    Prover.saturate(self.store, Inferences.RULES)
    return self.store
  end
  def missing(s)
    out = []
    if Ops.m_empty(s.all("conserved"))
      Ops.m_push(out, "nothing says the shortfall survives its own transport")
    end
    if !(Ops.m_some(s.all("is"), ->(f) {
      return Ops.eq(f.of, "N")
    }))
      Ops.m_push(out, "nothing in the line swings a heading, so there is no index")
    end
    return out
  end
  def self.behind(s, about)
    out = []
    seen = Node.new
    walk = ->(k) {
      unless Ops.eq(Ops.elem(seen, k), true)
        st = Ops.elem(s.steps, k)
        unless Ops.eq(st, nil)
          Ops.set_at(seen, k, true)
          Ops.list(st.upon).each do |f|
            walk.(f)
          end
          Ops.m_push(out, st)
        end
      end
    }
    if Ops.m_empty(about)
      return s.nodes
    end
    Ops.list(s.keys).each do |k|
      if Ops.eq(Ops.elem(s.steps, k).fact.of, about)
        walk.(k)
      end
    end
    return out
  end
  def line_steps
    out = []
    infos = self.infos
    Ops.list(infos).each do |t|
      name = (Ops.m_empty(t.rules) ? nil : Ops.elem(t.rules, 0))
      rays = t.rays
      does = (Ops.eq(rays, "0") ? "moves the population without making or taking any" : "comes to #{rays} rays and #{t.space} points of space")
      power = (Ops.eq(t.degree, 0) ? "carry no power of the density" : "of degree #{t.degree} in the density")
      edge = (t.facing ? " across an edge, which is the facing factor" : "")
      edge2 = (t.facing ? ", across an edge" : "")
      sign = (Ops.lt(t.sign, 0) ? "-" : "+")
      why = (Ops.m_empty(t.rules) ? "no rewrite of the model puts it there - it is what is put into the box from outside, and the only place anything about a particular problem can be written" : "#{Ops.m_join(t.rules, Physics.sep2)} contributes it: its body #{does}, its quantifier makes it #{power}#{edge}, and its gates let through what they let through")
      st = Step.of(Fact.stands(t.symbol, Expr.simplify(Expr.mul([Expr.num(t.sign), Expr.sym((Ops.eq(rays, "0") ? "carried" : rays))]))), Ops.or_else(name) { "put in from outside" }, [], why, ["rays: #{rays}", "space: #{t.space}", "degree: #{t.degree}#{edge2}", "term: #{sign} #{t.symbol}"])
      st.rule = name
      st.derivation = (Ops.eq(name, nil) ? [] : self.from_rule(t).nodes)
      Ops.m_push(out, st)
    end
    rhs = Ops.filt(infos, ->(t) {
      return Ops.eq(t.side, "right")
    })
    lhs = Ops.m_join(Ops.m_map(Ops.filt(infos, ->(t) {
      return Ops.eq(t.side, "left")
    }), ->(t) {
      return Ops.or_else(t.operator) { t.symbol }
    }), " + ")
    equation = self.equation
    Ops.m_push(out, Step.of(Fact.stands("#{lhs}n", Expr.simplify(Expr.add(Ops.m_map(rhs, ->(t) {
      return Expr.mul([Expr.num(t.sign), Expr.sym(t.symbol)])
    })))), "and the terms add", Ops.m_map(infos, ->(t) {
      return Fact.key_of("is", t.symbol)
    }), "the rules do not consult one another - each fires on its own matches once a tick - so what they do to the population adds, and the line is what they come to rather than a description of them. A theory with a rule taken out writes one term fewer here without anything else changing", Ops.m_concat(Ops.m_map(infos, ->(t) {
      sign = (Ops.lt(t.sign, 0) ? "-" : "+")
      by = (Ops.m_empty(t.rules) ? "not a rule" : Ops.m_join(t.rules, Physics.sep2))
      return "#{sign} #{t.symbol}   (#{by})"
    }), [self.line_text, self.space_text])))
    return out
  end
  def line_text
    infos = self.infos
    left = Ops.filt(infos, ->(t) {
      return Ops.eq(t.side, "left")
    })
    left = Ops.m_concat(Ops.filt(left, ->(t) {
      return Ops.eq(t.operator, "\\partial_{t}")
    }), Ops.filt(left, ->(t) {
      return !Ops.eq(t.operator, "\\partial_{t}")
    }))
    right = Ops.filt(infos, ->(t) {
      return (Ops.eq(t.side, "right") && ((Ops.m_empty(t.rules) || !Ops.eq(t.rays, "0"))))
    })
    right = Ops.m_concat(Ops.filt(right, ->(t) {
      return !(Ops.m_empty(t.rules))
    }), Ops.filt(right, ->(t) {
      return Ops.m_empty(t.rules)
    }))
    lhs = (Ops.m_empty(left) ? "n" : "(#{Ops.m_join(Ops.m_map(left, ->(t) {
      return Ops.or_else(t.operator) { t.symbol }
    }), Physics.plus)})n")
    rhs = ""
    right.length.times do |i|
      t = Ops.elem(right, i)
      piece = (Ops.eq(i, 0) ? ((Ops.eq(t.sign, (-1)) ? "-" : "")) : ((Ops.eq(t.sign, (-1)) ? " - " : " + ")))
      rhs = "#{rhs}#{piece}#{t.symbol}"
    end
    if Ops.m_empty(right)
      rhs = "0"
    end
    return "#{lhs} = #{rhs}"
  end
  def self.POPULATION
    return Expr.field("\\rho")
  end
  def isotropic_population
    return Step.of(Fact.stands("n", Prover.POPULATION), "the density is the share of ways lit", [], "\\rho is not a second population: it is the lit ways of a point over all DEG of them, each way's count clamped to one before it is counted and the whole averaged over the headings - which is what the field computes at every cell. The line's n is the count on one heading. So the two are one name on two conditions. ISOTROPIC: the rules light every exit of a point alike and turn a heading by a record that is the same from every side, so nothing picks a heading out and the average over the headings is the count on any one. DILUTE: a way holds at most one ray, so clamping it to one changes nothing. Both hold in the vacuum the line is about; where a way carries more than one ray, \\rho saturates at one while n keeps counting, and the meeting term the reading writes as n^{2} is the field's \\rho^{2} - one pair per edge per tick. Read per point rather than per heading, n would be the rays over all the ways and the same statement is \\rho = n/DEG, the lattice's count of ways being exactly the factor that stands in l.choose and in front of the creation term", ["\\rho = \\langle \\min(1, n_{d}) \\rangle_{d} - the lit ways over all DEG of them", "isotropic: every heading alike, so \\langle n_{d} \\rangle_{d} = n", "dilute: at most one ray a way, so \\min(1, n) = n", "so \\rho = n on a heading, and \\rho = n/DEG per point"])
  end
  def self.tidy(e)
    return Expr.deep_factored(Expr.simplify(Expr.expand(Expr.simplify(e))))
  end
  def self.neat(e)
    return Expr.deep_factored(Expr.simplify(e))
  end
  def filled_term(t, fill)
    return Prover.neat(Expr.replace(Expr.evaluate(t.expr, fill), "n", Prover.POPULATION))
  end
  def operators_on(name)
    left = Ops.filt(self.infos, ->(t) {
      return Ops.eq(t.side, "left")
    })
    left = Ops.m_concat(Ops.filt(left, ->(t) {
      return Ops.eq(t.operator, "\\partial_{t}")
    }), Ops.filt(left, ->(t) {
      return !Ops.eq(t.operator, "\\partial_{t}")
    }))
    return (Ops.m_empty(left) ? name : "(#{Ops.m_join(Ops.m_map(left, ->(t) {
      return Ops.or_else(t.operator) { t.symbol }
    }), Physics.plus)})#{name}")
  end
  def line_filled(s)
    fill = Prover.settled(s)
    infos = self.infos
    right = Ops.filt(infos, ->(t) {
      return (Ops.eq(t.side, "right") && ((Ops.m_empty(t.rules) || !Ops.eq(t.rays, "0"))))
    })
    right = Ops.m_concat(Ops.filt(right, ->(t) {
      return !(Ops.m_empty(t.rules))
    }), Ops.filt(right, ->(t) {
      return Ops.m_empty(t.rules)
    }))
    used = Prover.constants_in(s, fill, right)
    rhs = Expr.add(Ops.m_map(right, ->(t) {
      return Prover.neat(Expr.mul([t.ray_count, self.filled_term(t, fill)]))
    }))
    lhs = self.operators_on(Expr.show(Prover.POPULATION))
    return Step.of(Fact.stands(lhs, rhs), "with every factor written in", Ops.m_concat(Ops.m_map(used, ->(n) {
      return Fact.key_of("is", n)
    }), [Fact.key_of("is", "n")]), "a name that has a law of its own is not a primitive - it is what that law shows it to be, so it stands in for itself. The constants the rules fix - a rate, which is one per match per tick, the facing factor, which is what isotropy leaves - are filled in here and nowhere earlier, so the line above is what the rules say and this is what it comes to", Ops.m_concat(Ops.m_map(used, ->(n) {
      return "#{n} = #{Expr.show(Expr.num(Ops.elem(fill, n)))}"
    }), ["#{lhs} = #{Expr.show(rhs)}"]))
  end
  def self.constants_in(s, fill, terms)
    used = []
    Ops.list(s.all("is")).each do |f|
      unless (Ops.eq(Ops.elem(fill, f.of), nil) || Ops.m_contains(used, f.of))
        if Ops.m_some(terms, ->(t) {
          return Expr.mentions(t.expr, f.of)
        })
          Ops.m_push(used, f.of)
        end
      end
    end
    return used
  end
  def ledger_filled(s, ledger)
    fill = Prover.settled(s)
    moving = Ops.filt(self.infos, ->(t) {
      return ((Ops.eq(ledger, "space") ? !Ops.eq(t.held, "0") : !Ops.eq(t.folds, "0")))
    })
    used = Prover.constants_in(s, fill, moving)
    counted = ->(t) {
      return (Ops.eq(ledger, "space") ? Expr.neg(t.held_count) : t.fold_count)
    }
    rhs = (Ops.m_empty(moving) ? Expr.num(0) : Expr.add(Ops.m_map(moving, ->(t) {
      return Prover.neat(Expr.mul([counted.(t), self.filled_term(t, fill)]))
    })))
    lhs = (Ops.eq(ledger, "space") ? "\\partial_{t}s" : "\\partial_{t}n_{f}")
    what = (Ops.eq(ledger, "space") ? "a point held at the local - the world's count read from the hub's side, so a swallow is one more here and a hand-back one fewer, and a point the world grows is a new local rather than one held here" : "a fold of the record")
    return Step.of(Fact.stands(lhs, rhs), "with every factor written in", Ops.m_concat(Ops.m_map(used, ->(n) {
      return Fact.key_of("is", n)
    }), [Fact.key_of("is", "n")]), "the same rules, read on another ledger: every term that makes or takes #{what} does so at its own rate, through its own gates, and the count one firing moves is written on it. The constants are the same facts as on the population's line, filled in here the same way", Ops.m_concat(Ops.m_map(used, ->(n) {
      return "#{n} = #{Expr.show(Expr.num(Ops.elem(fill, n)))}"
    }), ["#{lhs} = #{Expr.show(rhs)}"]))
  end
  def growth_filled(s)
