  def aggregate(general_, one, s)
    inf = s.fact("is", "\\rho_{\\infty}")
    if Ops.eq(inf, nil)
      return nil
    end
    rho = Prover.POPULATION
    terms = (Ops.eq(one.fact.to.kind, "add") ? one.fact.to.of : [one.fact.to])
    balance = Expr.gather(Expr.add(Ops.filt(terms, ->(t) {
      return !(Expr.mentions(t, "l.\\bar{m}"))
    })))
    kept = Expr.collected(Expr.add(Ops.filt(terms, ->(t) {
      return Expr.mentions(t, "l.\\bar{m}")
    })))
    fill = Prover.settled(s)
    flat = ->(x) {
      return Expr.show(Expr.gather(Expr.expand(Expr.evaluate(x, fill))))
    }
    same = (Ops.eq(inf.to.kind, "root") && ((Ops.eq(flat.(balance), flat.(inf.to.base)) || Ops.eq(flat.(balance), flat.(Expr.neg(inf.to.base))))))
    unless same
      env = Model.copy(fill)
      Ops.setattr(env, "DEG", 8)
      at = Expr.numeric(Expr.evaluate(inf.to, env), env)
      Ops.setattr(env, "\\rho", at)
      v = Expr.numeric(Expr.evaluate(balance, env), env)
      if ((!(Expr.finite(at)) || !(Expr.finite(v))) || Ops.gt(Ops.m_abs(v), 0.000001))
        return nil
      end
    end
    return Step.of(Fact.stands(general_.fact.of, kept), "the vacuum settled", [general_.fact.key, one.fact.key, inf.key], "with the record written as the density, everything on the right that is not a body's mass is the vacuum's own making against its own taking - the balance that fixes \\rho_{\\infty}, and nought exactly there. The continuous aggregate is the settled vacuum: at that density the growth the general line kept has gone, the record is the settled one, and what is left is CONSERVED up to what carries it and what the bodies put in. The record's gradient stays on the left because that is what bends a heading; every place the record departs from the settled one is the small-scale dynamics the general line keeps", ["the vacuum's balance: #{Expr.show(balance)}", "\\rho_{\\infty} = #{Expr.show(inf.to)}: the same balance, at nought", "#{general_.fact.of} = #{Expr.show(kept)}"])
  end
  def settled_record(folds)
    parts = Ops.m_split(Expr, folds.fact.to, "n_{f}")
    if Ops.eq(parts, nil)
      return nil
    end
    top = Prover.tidy(Expr.neg(Ops.elem(parts, 1)))
    bottom = Prover.tidy(Ops.elem(parts, 0))
    if Ops.m_starts_with(Expr.show(top), "-")
      top = Prover.tidy(Expr.neg(top))
      bottom = Expr.flip(bottom)
    end
    nf = Expr.div(top, bottom)
    st = Step.of(Fact.stands("n_{f}", nf), "the record settled against the density", [folds.fact.key], "the record's line is linear in the record: folds are written at the meeting rate and taken off at the creation rate times how many there are to take. On the continuous aggregate the record has stopped moving against the density - what a meeting writes a creation takes off - so its line is at nought and the record is a function of the density alone. That is the aggregate: not that the record is conserved, but that it has settled, and every place where it has not is the small-scale dynamics the line above keeps", ["#{folds.fact.of} = #{Expr.show(folds.fact.to)} = 0", "n_{f} = #{Expr.show(nf)}"])
    st.parts_ = [top, bottom]
