      making_with_body = Expr.simplify(Expr.replace(made.to, "\\rho", total))
      root = Expr.root(Expr.simplify(Expr.add([Expr.mul([mkC.to, making_with_body]), Expr.mul([tkC.to, with_body])])), "\\rho")
      via = "the density where a body is, which is not the density of empty space"
