  def self.closing
    return Inference.new(name: "the phase between the two pulses, which the body's own acceleration keeps from cancelling", because: "the vacuum pulses every other tick and a source moves or pulses and never both, so moving shifts the phase between them - and an accelerating body keeps changing that shift, so it accumulates instead of averaging away", fire: ->(s) {
