  def self.writing_out(of)
    return Inference.new(name: "with every factor written in", because: "a name that has a law of its own is not a primitive - it is what that law shows it to be, so it stands in for itself", fire: ->(s) {
      _F = s.fact("is", of)
      if (Ops.eq(_F, nil) || s.has("is", "#{of} in full"))
        return []
      end
      about = ->(e) {
        return Ops.m_some(["R", "m", "A", "\\beta", "\\bar{m}_{x}"], ->(n) {
          return Expr.mentions(e, n)
        })
      }
      laws = Keyed.new()
      Ops.list(s.nodes).each do |n|
        f = n.fact
        if ((Ops.eq(f.kind, "is") && !(Prover.in_r(f.of))) && (((Ops.m_empty(n.upon) || Ops.eq(Expr.simplify(f.to).kind, "num")) || about.(f.to))))
          if !(laws.has(f.of))
            laws.set(f.of, f.to)
          end
        end
      end
      Ops.set_at(laws.vals, of, nil)
      told = s.fact("is", "g_{N} in bodies and transport")
      if !Ops.eq(told, nil)
        laws.set("g_{N}", told.to)
      end
      Ops.setattr(laws.vals, "T_{vac}", nil)
      Ops.setattr(laws.vals, "T_{met}", nil)
      steps = ["#{of} = #{Expr.show(_F.to)}"]
      seen = Node.new
      written = ->(start) {
        e = start
        i = 0
        stop = false
        while (Ops.lt(i, 24) && !(stop))
          was = Expr.show(e)
          Ops.list(laws.keys).each do |name|
            law = Ops.elem(laws.vals, name)
            unless ((Ops.eq(law, nil) || !(Expr.mentions(e, name))) || Expr.mentions(law, name))
              put = Expr.deep_factored(law)
              e = Expr.simplify(Expr.replace(e, name, put))
              if Ops.eq(Ops.elem(seen, name), nil)
                Ops.set_at(seen, name, true)
                Ops.m_push(steps, "#{name} = #{Expr.show(put)}")
              end
            end
          end
          stop = Ops.eq(Expr.show(e), was)
          i = Ops.add(i, 1)
        end
        return Inferences.folded(Expr.deep_factored(e))
      }
      a = written.(Inferences.folded(_F.to))
      b = written.(Inferences.cleared(_F.to))
      e = (Ops.lt(Expr.show(b).length, Expr.show(a).length) ? b : a)
      Ops.m_push(steps, "#{of} = #{Expr.show(e)}")
      return [Inferences.step("#{of} in full", e, "with every factor written in", [_F.key], "what is read straight off a rewrite is written in, because a reader could not have known it; what has a theorem of its own KEEPS ITS NAME and is cited, because writing it in would replace a proof with its answer. What is left standing is the rules' own rates, the counts of the tiling, the two bodies, and the handful of quantities that have pages of their own", steps)]
    })
  end
