  attr_writer :reaches
  def tabled(table, _R)
    u = Ops.div(_R, self.STEP)
    i = Ops.m_floor(u)
    if Ops.ge(i, Ops.sub(table.length, 1))
      return Ops.elem(table, Ops.sub(table.length, 1))
    end
    if Ops.lt(i, 0)
      return Ops.elem(table, 0)
    end
    f = Ops.sub(u, i)
    return Ops.add(Ops.mul(Ops.elem(table, i), (Ops.sub(1, f))), Ops.mul(Ops.elem(table, Ops.add(i, 1)), f))
  end
  def shell(_R)
    return (Ops.gt(_R, self.FAR) ? self.shell_at(_R) : self.tabled(self.shells, _R))
