  def value(e, at, masses, _Rs, skip)
    k = e.kind
    if (Ops.eq(k, "call") && Ops.m_starts_with(e.label, "\\sum"))
      total = 0
      names = self.per_body
      kinds = self.per_body_kinds
      masses.length.times do |i|
        unless Ops.eq(i, skip)
          _R = Ops.elem(_Rs, i)
          names.length.times do |j|
            Ops.set_at(at, Ops.elem(names, j), self.per_body_value(Ops.elem(kinds, j), Ops.elem(masses, i), _R))
          end
          total = Ops.add(total, self.value(e.base, at, masses, _Rs, skip))
          Ops.list(names).each do |nm|
            Ops.set_at(at, nm, nil)
          end
        end
      end
      return total
    end
    if Ops.eq(k, "num")
      return e.value
    end
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      v = Ops.elem(at, e.label)
      return (Ops.eq(v, nil) ? Float::NAN : v)
    end
    if Ops.eq(k, "add")
      total = 0
      Ops.list(e.of).each do |p|
        total = Ops.add(total, self.value(p, at, masses, _Rs, skip))
      end
      return total
    end
    if Ops.eq(k, "mul")
      prod = 1
      Ops.list(e.of).each do |p|
        prod = Ops.mul(prod, self.value(p, at, masses, _Rs, skip))
      end
      return prod
    end
    if Ops.eq(k, "pow")
      return Ops.power(self.value(e.base, at, masses, _Rs, skip), self.value(e.power, at, masses, _Rs, skip))
    end
    if Ops.eq(k, "log")
      return Ops.m_ln(self.value(e.base, at, masses, _Rs, skip))
    end
    if Ops.eq(k, "exp")
      return Ops.m_exp(self.value(e.base, at, masses, _Rs, skip))
    end
    return Aggregate.numeric_of(e, at)
  end
  def lean_at(masses, xs, ys, x, y, skip)
    h = 0.25
    gx = Ops.div((Ops.sub(self.record_at(masses, xs, ys, Ops.add(x, h), y, skip), self.record_at(masses, xs, ys, Ops.sub(x, h), y, skip))), (Ops.mul(2, h)))
    gy = Ops.div((Ops.sub(self.record_at(masses, xs, ys, x, Ops.add(y, h), skip), self.record_at(masses, xs, ys, x, Ops.sub(y, h), skip))), (Ops.mul(2, h)))
    return [gx, gy]
