  def read_at(hx, hy, x, y)
    last = Ops.sub(hx.length, 1)
    _R = Fmt.hypot(Ops.sub(Ops.elem(hx, last), x), Ops.sub(Ops.elem(hy, last), y))
    px = Ops.elem(hx, last)
    py = Ops.elem(hy, last)
    Aggregate.ROUNDS.times do |r|
      back = Ops.m_round(_R)
      if Ops.gt(back, last)
        back = last
      end
      at = Ops.sub(last, back)
      vx = (Ops.gt(at, 0) ? Ops.sub(Ops.elem(hx, at), Ops.elem(hx, Ops.sub(at, 1))) : 0)
      vy = (Ops.gt(at, 0) ? Ops.sub(Ops.elem(hy, at), Ops.elem(hy, Ops.sub(at, 1))) : 0)
      px = Ops.add(Ops.elem(hx, at), Ops.mul(vx, back))
      py = Ops.add(Ops.elem(hy, at), Ops.mul(vy, back))
      _R = Fmt.hypot(Ops.sub(px, x), Ops.sub(py, y))
