    gx = Ops.div((Ops.sub(self.record_history(masses, hx, hy, Ops.add(x, h), y, skip), self.record_history(masses, hx, hy, Ops.sub(x, h), y, skip))), (Ops.mul(2, h)))
    gy = Ops.div((Ops.sub(self.record_history(masses, hx, hy, x, Ops.add(y, h), skip), self.record_history(masses, hx, hy, x, Ops.sub(y, h), skip))), (Ops.mul(2, h)))
    return [gx, gy]
