  end
  attr_writer :pulls
  def linear(*args_)
    @linear = (Ops.lt(Ops.m_abs((Ops.sub(self.pull(2, 5), Ops.mul(2, self.pull(1, 5))))), Ops.mul(0.000000001, (Ops.add(Ops.m_abs(self.pull(1, 5)), 0.000000000001))))) unless instance_variable_defined?(:@linear)
    args_.empty? ? @linear : @linear.(*args_)
  end
  attr_writer :linear
  def quick(m, _R)
    if !(self.linear)
      fail.("the record is not linear in a body's mass under this derivation: the tabled pull cannot stand in for it")
    end
    return (Ops.gt(_R, self.FAR) ? self.pull(m, _R) : Ops.mul(m, self.tabled(self.pulls, _R)))
  end
  def circling(m, _R, rho)
    a = self.pull(m, _R)
    return (Ops.gt(a, 0) ? Ops.m_sqrt((Ops.mul(a, rho))) : Float::NAN)
