  def well(m, _R)
    step = 0.05
    total = 0
    r = _R
    while Ops.lt(r, self.FAR)
      total = Ops.add(total, Ops.div(Ops.mul(step, (Ops.add(self.quick(m, r), self.quick(m, Ops.add(r, step))))), 2))
      r = Ops.add(r, step)
    end
    return Ops.sub(0, total)
