  def arriving(m, _R_far, _R_near, twins)
    both = (twins ? 2 : 1)
    drop = Ops.mul(both, (Ops.sub(self.well(m, _R_far), self.well(m, _R_near))))
    ratio = Ops.sub(Ops.power((Ops.div(_R_far, _R_near)), 2), 1)
    if (!((Ops.gt(drop, 0))) || !((Ops.gt(ratio, 0))))
      return Float::NAN
    end
    v_rel = Ops.m_sqrt((Ops.div(Ops.mul(2, drop), ratio)))
    return (twins ? Ops.div(v_rel, 2) : v_rel)
