  def step_bodies(ms, hx, hy, vx, vy, moving)
    n = ms.length
    xs = Ops.m_map(hx, ->(h) {
      return Ops.m_last(h)
    })
    ys = Ops.m_map(hy, ->(h) {
      return Ops.m_last(h)
    })
    n.times do |i|
      if Ops.elem(moving, i)
        ax = 0
        ay = 0
        n.times do |j|
          if !Ops.eq(j, i)
            got = self.read_at(Ops.elem(hx, j), Ops.elem(hy, j), Ops.elem(xs, i), Ops.elem(ys, i))
            _R = Ops.elem(got, 2)
            dx = Ops.sub(Ops.elem(got, 0), Ops.elem(xs, i))
            dy = Ops.sub(Ops.elem(got, 1), Ops.elem(ys, i))
            there = Fmt.hypot(dx, dy)
            if Ops.gt(there, 0)
              a = self.quick(Ops.elem(ms, j), _R)
              ax = Ops.add(ax, Ops.div(Ops.mul(a, dx), there))
              ay = Ops.add(ay, Ops.div(Ops.mul(a, dy), there))
            end
          end
        end
        Ops.set_at(vx, i, Ops.add(Ops.elem(vx, i), ax))
        Ops.set_at(vy, i, Ops.add(Ops.elem(vy, i), ay))
        speed = Fmt.hypot(Ops.elem(vx, i), Ops.elem(vy, i))
        if Ops.gt(speed, 1)
          Ops.set_at(vx, i, Ops.div(Ops.elem(vx, i), speed))
          Ops.set_at(vy, i, Ops.div(Ops.elem(vy, i), speed))
        end
      end
    end
    n.times do |i|
      Ops.m_push(Ops.elem(hx, i), Ops.add(Ops.elem(xs, i), ((Ops.elem(moving, i) ? Ops.elem(vx, i) : 0))))
      Ops.m_push(Ops.elem(hy, i), Ops.add(Ops.elem(ys, i), ((Ops.elem(moving, i) ? Ops.elem(vy, i) : 0))))
    end
  end
  def nearest(ms, fars, speeds, k, held, limit)
    n = ms.length
    hx = Ops.m_map(fars, ->(f) {
      return [f]
    })
    hy = Ops.m_map(fars, ->(f) {
      return [0]
    })
    vx = Ops.m_map(fars, ->(f) {
      return 0
    })
    vy = Ops.m_map(speeds, ->(v) {
      return Ops.sub(0, v)
    })
    moving = Ops.m_map(Ops.rng(n), ->(i) {
      return (Ops.gt(i, 0) || !(held))
    })
    Ops.set_at(vy, 0, (held ? 0 : Ops.elem(speeds, 1)))
    least = Fmt.hypot(Ops.sub(Ops.m_last(Ops.elem(hx, k)), Ops.m_last(Ops.elem(hx, 0))), Ops.sub(Ops.m_last(Ops.elem(hy, k)), Ops.m_last(Ops.elem(hy, 0))))
    was = least
    t = 0
    turned = false
    while (Ops.lt(t, limit) && !(turned))
      self.step_bodies(ms, hx, hy, vx, vy, moving)
      d = Fmt.hypot(Ops.sub(Ops.m_last(Ops.elem(hx, k)), Ops.m_last(Ops.elem(hx, 0))), Ops.sub(Ops.m_last(Ops.elem(hy, k)), Ops.m_last(Ops.elem(hy, 0))))
      if Ops.lt(d, least)
        least = d
      end
      if (Ops.gt(d, was) && Ops.lt(d, Ops.add(Ops.mul(0.75, Ops.elem(fars, k)), Ops.mul(0.25, least))))
        turned = true
      end
      was = d
      t = Ops.add(t, 1)
    end
    return least
  end
  def launches(ms, fars, nears, held, rounds)
    n = ms.length
    speeds = Ops.m_map(Ops.rng(n), ->(k) {
      return (Ops.eq(k, 0) ? 0 : self.arriving(Ops.elem(ms, 0), Ops.elem(fars, k), Ops.elem(nears, k), !(held)))
    })
    n.times do |k|
      if !(Fmt.finite(Ops.elem(speeds, k)))
        Ops.set_at(speeds, k, 0)
      end
    end
    rounds.times do |r|
      n.times do |k|
        if Ops.gt(k, 0)
          lo = Ops.mul(Ops.elem(speeds, k), 0.5)
          hi = Ops.mul(Ops.elem(speeds, k), 1.5)
          if Ops.gt(hi, 1)
            hi = 1
          end
          limit = Ops.m_round((Ops.div(Ops.mul(20, Ops.elem(fars, k)), ((Ops.gt(Ops.elem(speeds, k), 0.001) ? Ops.elem(speeds, k) : 0.001)))))
          if Ops.gt(limit, 40000)
            limit = 40000
          end
          14.times do |b|
            mid = Ops.div((Ops.add(lo, hi)), 2)
            Ops.set_at(speeds, k, mid)
            got = self.nearest(ms, fars, speeds, k, held, limit)
            if Ops.lt(got, Ops.elem(nears, k))
              lo = mid
            else
              hi = mid
            end
          end
          Ops.set_at(speeds, k, Ops.div((Ops.add(lo, hi)), 2))
        end
      end
    end
    return speeds
  end
  def self.kind_of(name)
    if Ops.m_starts_with(name, "l.shell")
      return "shell"
    end
    if Ops.m_starts_with(name, "l.reach")
      return "reach"
    end
    if Ops.m_contains(name, "\\bar{m}")
      return "mass"
    end
    if Ops.m_contains(name, "\\bar{R}")
      return "distance"
    end
    return "constant"
  end
  def per_body
    return Ops.filt(Model.unbound(self.summand), ->(n) {
      return !Ops.eq(Aggregate.kind_of(n), "constant")
    })
  end
  def per_body_kinds
    return Ops.m_map(self.per_body, ->(n) {
      return Aggregate.kind_of(n)
    })
  end
  def per_body_value(kind, m, _R)
    if Ops.eq(kind, "mass")
      return m
    end
    if Ops.eq(kind, "distance")
      return _R
    end
    if Ops.eq(kind, "shell")
      return self.shell(_R)
    end
    return self.reach(_R)
  end
  def self.summing(e)
    k = e.kind
    if (Ops.eq(k, "call") && Ops.m_starts_with(e.label, "\\sum"))
      return e
    end
