              Ops.set_at(rest, 7, Fmt.max(0, Ops.sub(Ops.elem(m, 7), Ops.mul(Ops.mul(Ops.div(Ops.mul(Ops.elem(rest, 0), Ops.elem(mine, 0)), Ops.elem(m, 0)), along), along))))
