  def expanded(m, ux, uy, dx, dy)
    s = self.now_from(m, ux, uy)
    ex = Ops.sub(ux, Ops.elem(s, 0))
    ey = Ops.sub(uy, Ops.elem(s, 1))
    r2 = Ops.add(Ops.mul(ex, ex), Ops.mul(ey, ey))
    _Dd = self.D
    _C = Ops.mul(Ops.mul(Ops.elem(m, 0), (Ops.power(self.K, (Ops.sub(_Dd, 1))))), self.spread_of(m, Ops.m_sqrt(r2)))
    rD = Ops.power(r2, (Ops.div(_Dd, 2)))
    a = Ops.div(_C, rD)
    b = Ops.div(Ops.mul(_Dd, _C), (Ops.mul(rD, r2)))
    c = Ops.div(Ops.mul(Ops.mul(_Dd, (Ops.add(_Dd, 2))), _C), (Ops.mul(Ops.mul(rD, r2), r2)))
    jxx = Ops.sub(a, Ops.mul(Ops.mul(b, ex), ex))
    jxy = Ops.sub(0, Ops.mul(Ops.mul(b, ex), ey))
    jyy = Ops.sub(a, Ops.mul(Ops.mul(b, ey), ey))
    hxxx = Ops.add(Ops.sub(0, Ops.mul(Ops.mul(3, b), ex)), Ops.mul(Ops.mul(Ops.mul(c, ex), ex), ex))
    hxxy = Ops.add(Ops.sub(0, Ops.mul(b, ey)), Ops.mul(Ops.mul(Ops.mul(c, ex), ex), ey))
    hxyy = Ops.add(Ops.sub(0, Ops.mul(b, ex)), Ops.mul(Ops.mul(Ops.mul(c, ex), ey), ey))
    hyyy = Ops.add(Ops.sub(0, Ops.mul(Ops.mul(3, b), ey)), Ops.mul(Ops.mul(Ops.mul(c, ey), ey), ey))
    fx = Ops.add(Ops.add(Ops.add(Ops.mul(a, ex), Ops.mul(jxx, dx)), Ops.mul(jxy, dy)), Ops.div((Ops.add(Ops.add(Ops.mul(Ops.mul(hxxx, dx), dx), Ops.mul(Ops.mul(Ops.mul(2, hxxy), dx), dy)), Ops.mul(Ops.mul(hxyy, dy), dy))), 2))
    fy = Ops.add(Ops.add(Ops.add(Ops.mul(a, ey), Ops.mul(jxy, dx)), Ops.mul(jyy, dy)), Ops.div((Ops.add(Ops.add(Ops.mul(Ops.mul(hxxy, dx), dx), Ops.mul(Ops.mul(Ops.mul(2, hxyy), dx), dy)), Ops.mul(Ops.mul(hyyy, dy), dy))), 2))
