      end
      Ops.set_at(sums, 0, Ops.add(Ops.elem(sums, 0), Ops.elem(self.middle, c)))
      self.meet_bins(c, s, sums, wx, wy)
    end
  end
  def meet_bins(c, s, sums, wx, wy)
    _B = self.gather
    _B.times do |a|
      if Ops.gt(Ops.elem(sums, a), 0)
        na = Fmt.hypot(Ops.elem(wx, a), Ops.elem(wy, a))
        ax = (Ops.gt(na, 0) ? Ops.div(Ops.elem(wx, a), na) : 0)
        ay = (Ops.gt(na, 0) ? Ops.div(Ops.elem(wy, a), na) : 0)
        _B.times do |b|
          if (!Ops.eq(b, a) && Ops.gt(Ops.elem(sums, b), 0))
            nb = Fmt.hypot(Ops.elem(wx, b), Ops.elem(wy, b))
            over = (Ops.gt(nb, 0) ? self.facing_share(ax, ay, Ops.div(Ops.elem(wx, b), nb), Ops.div(Ops.elem(wy, b), nb)) : 0)
            if Ops.gt(over, 0)
              Ops.list(self.meets).each do |t|
                w = Ops.mul(Ops.mul(Ops.mul(self.share(t, s), self.activity(Ops.elem(sums, a))), self.activity(Ops.elem(sums, b))), over)
                Ops.set_at(self.fold, c, Fmt.max(0, Ops.add(Ops.elem(self.fold, c), Ops.div(Ops.mul(w, t.doing.folds.at(s)), 2))))
                Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.div(Ops.mul(w, t.doing.space.at(s)), 2)))
                Ops.set_at(self.gone, c, Ops.add(Ops.elem(self.gone, c), Ops.div(Ops.mul(w, Ops.m_abs(t.doing.folds.at(s))), 2)))
              end
            end
          end
        end
        if self.vacuum
          Ops.list(self.meets).each do |t|
            w = Ops.div(Ops.mul(Ops.mul(self.share(t, s), self.activity(Ops.elem(sums, a))), self.activity(self.rho_inf)), self.DEG)
            Ops.set_at(self.fold, c, Fmt.max(0, Ops.add(Ops.elem(self.fold, c), Ops.div(Ops.mul(w, t.doing.folds.at(s)), 2))))
            Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.div(Ops.mul(w, t.doing.space.at(s)), 2)))
            Ops.set_at(self.gone, c, Ops.add(Ops.elem(self.gone, c), Ops.div(Ops.mul(w, Ops.m_abs(t.doing.folds.at(s))), 2)))
          end
        end
      end
    end
  end
  def meet
    if self.local_rays
      return self.meet_local
    end
    if self.apart
      return self.meet_gathered
    end
    cells = self.cells
    _P = self.planes
    cells.times do |c|
      x = self.column_of(c)
      y = self.row_of(c)
      s = self.symbols(Ops.elem(self.rho_was, c), Ops.elem(self.nf_was, c))
      Ops.sub(_P, 1).times do |i|
        z = Ops.add(i, 1)
        ours = self.sent_to(z, x, y)
        if Ops.gt(Ops.elem(ours, 0), 0)
          Ops.sub(_P, 1).times do |j|
            yy = Ops.add(j, 1)
            if !Ops.eq(yy, z)
              theirs = self.sent_to(yy, x, y)
              if Ops.gt(Ops.elem(theirs, 0), 0)
                over = self.facing_share(Ops.elem(ours, 1), Ops.elem(ours, 2), Ops.elem(theirs, 1), Ops.elem(theirs, 2))
                if Ops.gt(over, 0)
                  Ops.list(self.meets).each do |t|
                    w = Ops.mul(Ops.mul(Ops.mul(self.share(t, s), self.activity(Ops.elem(ours, 0))), self.activity(Ops.elem(theirs, 0))), over)
                    Ops.set_at(self.fold, c, Fmt.max(0, Ops.add(Ops.elem(self.fold, c), Ops.div(Ops.mul(w, t.doing.folds.at(s)), 2))))
                    Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.div(Ops.mul(w, t.doing.space.at(s)), 2)))
                    Ops.set_at(self.gone, c, Ops.add(Ops.elem(self.gone, c), Ops.div(Ops.mul(w, Ops.m_abs(t.doing.folds.at(s))), 2)))
                  end
                end
              end
            end
          end
        end
        if self.vacuum
          theirs = self.rho_inf
          Ops.list(self.meets).each do |t|
            w = Ops.div(Ops.mul(Ops.mul(self.share(t, s), self.activity(Ops.elem(ours, 0))), self.activity(theirs)), self.DEG)
            Ops.set_at(self.fold, c, Fmt.max(0, Ops.add(Ops.elem(self.fold, c), Ops.div(Ops.mul(w, t.doing.folds.at(s)), 2))))
            Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.div(Ops.mul(w, t.doing.space.at(s)), 2)))
            Ops.set_at(self.gone, c, Ops.add(Ops.elem(self.gone, c), Ops.div(Ops.mul(w, Ops.m_abs(t.doing.folds.at(s))), 2)))
          end
        end
      end
    end
  end
  def unfold
    cells = self.cells
    self.stand = Ops.m_map(Ops.rng(cells), ->(c) {
      return Ops.elem(self.nf_was, c)
    })
    unless self.lit
      cells.times do |c|
        s = self.symbols(Ops.elem(self.rho_was, c), Ops.elem(self.nf_was, c))
        Ops.setattr(s, "n_f", Ops.elem(self.nf_was, c))
        Ops.list(self.points).each do |t|
          back = t.doing.folds.at(s)
          if !Ops.eq(back, 0)
            h = Ops.mul(self.share(t, s), back)
            Ops.set_at(self.fold, c, Fmt.max(0, Ops.add(Ops.elem(self.fold, c), h)))
            Ops.set_at(self.stand, c, Fmt.max(0, Ops.add(Ops.elem(self.stand, c), h)))
          end
        end
      end
    end
  end
  def stream
    Ops.sub(self.planes, 1).times do |i|
      z = Ops.add(i, 1)
      near = self.face_of(self.body_of(z))
      was = Ops.m_map(Ops.rng(self.rungs), ->(r) {
        return Ops.elem(Ops.elem(self.beam, z), r)
      })
      self.rungs.times do |r|
        here = Fmt.max(near, r)
        back = Fmt.max(near, Ops.sub(r, 1))
        Ops.set_at(Ops.elem(self.beam, z), r, (Ops.eq(r, 0) ? 0 : Ops.mul(Ops.elem(was, Ops.sub(r, 1)), (Ops.power((Ops.div(back, here)), Ops.sub(self.D, 1))))))
      end
    end
  end
  def vac(*args_)
    @vac = (Ops.filled(self.cells, self.aggregate.rho_inf)) unless instance_variable_defined?(:@vac)
    args_.empty? ? @vac : @vac.(*args_)
  end
  attr_writer :vac
  def nets(rho, nf)
    s = self.symbols(rho, nf)
    got = 0
    Ops.list(self.points).each do |t|
      got = Ops.add(got, Ops.mul(self.share(t, s), t.doing.rays.at(s)))
    end
    Ops.list(self.singles).each do |t|
      got = Ops.add(got, Ops.mul(Ops.mul(self.share(t, s), Ops.getattr(s, "ρ")), t.doing.rays.at(s)))
    end
    Ops.list(self.meets).each do |t|
      got = Ops.add(got, Ops.mul(Ops.mul(Ops.mul(self.share(t, s), Ops.getattr(s, "ρ")), Ops.getattr(s, "ρ")), t.doing.rays.at(s)))
    end
    return got
  end
  def settle_rho
    if !(self.vacuum)
      return
    end
    self.cells.times do |c|
      mine = Ops.sub(Ops.elem(self.rho_was, c), Ops.elem(self.vac, c))
      theirs = (Ops.lt(mine, 0) ? 0 : mine)
      nf = Ops.elem(self.nf_was, c)
      lo = 0
      hi = 1
      24.times do |i|
        mid = Ops.div((Ops.add(lo, hi)), 2)
        both = Ops.add(mid, theirs)
        if Ops.gt(self.nets((Ops.gt(both, 1) ? 1 : both), nf), 0)
          lo = mid
        else
          hi = mid
        end
      end
      Ops.set_at(self.vac, c, Ops.div((Ops.add(lo, hi)), 2))
    end
  end
  def make
    cells = self.cells
    cells.times do |c|
      s = self.symbols(Ops.elem(self.rho_was, c), Ops.elem(self.nf_was, c))
      Ops.list(self.points).each do |t|
        Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.mul(self.share(t, s), t.doing.space.at(s))))
      end
      Ops.list(self.singles).each do |t|
        Ops.set_at(self.growth, c, Ops.add(Ops.elem(self.growth, c), Ops.mul(Ops.mul(self.share(t, s), Ops.elem(self.rho_was, c)), t.doing.space.at(s))))
      end
    end
  end
  def phase(*args_)
    @phase = (false) unless instance_variable_defined?(:@phase)
    args_.empty? ? @phase : @phase.(*args_)
  end
  attr_writer :phase
  def lit_at(x, y)
    return Ops.eq(Ops.mod((Ops.add(Ops.add(self.ticks, Ops.m_round(x)), Ops.m_round(y))), 2), 0)
  end
  def shine
    Ops.list(self.holes).each do |h|
      z = self.plane_of(h)
      Ops.set_at(Ops.elem(self.beam, z), 0, Ops.add(Ops.elem(Ops.elem(self.beam, z), 0), self.per_way(h)))
    end
    self.planes.times do |z|
      self.rungs.times do |r|
        Ops.set_at(Ops.elem(self.beam, z), r, Fmt.min(1, Ops.elem(Ops.elem(self.beam, z), r)))
      end
    end
  end
  def recur_at(x, y, gn)
    if (!Ops.eq(self.own, 2) || !((Ops.gt(gn, 0))))
      return 1
    end
    a0 = self.a0_at_place(x, y)
    if !((Ops.gt(a0, 0)))
      return 1
    end
    gx = self.tap(self.lean_x, 0, x, y, 0)
    gy = self.tap(self.lean_y, 0, x, y, 0)
    was = Fmt.hypot(gx, gy)
    return Ops.div(Ops.power((Ops.mul(gn, (Ops.add(was, a0)))), 0.5), gn)
  end
  def crowd(*args_)
    @crowd = (true) unless instance_variable_defined?(:@crowd)
    args_.empty? ? @crowd : @crowd.(*args_)
  end
  attr_writer :crowd
  def pull_at(x, y, zown, vx, vy)
    held = (self.local_rays ? self.pull_local(x, y, zown) : [0, 0])
    if self.local_rays
      return self.recurred(x, y, held)
    end
    half = Ops.div(Ops.sub(self.K, 1), 2)
    gx = 0
    gy = 0
    self.K.times do |dy|
      self.K.times do |dx|
        px = Ops.add(Ops.sub(x, half), dx)
        py = Ops.add(Ops.sub(y, half), dy)
        s = self.symbols(self.tap(self.rho_was, 0, px, py, 0), self.tap(self.nf_was, 0, px, py, 0))
        rate = 0
        Ops.list(self.meets).each do |t|
          rate = Ops.add(rate, Ops.div(Ops.mul(self.share(t, s), t.doing.folds.at(s)), 2))
        end
        stood = self.tap(self.stand, 0, px, py, 0)
        Ops.sub(self.planes, 1).times do |i|
          z = Ops.add(i, 1)
          unless Ops.eq(z, zown)
            came = self.sent_to(z, px, py)
            share = Ops.div(Ops.mul(rate, self.activity(Ops.elem(came, 0))), ((self.crowd ? Ops.add(1, stood) : 1)))
            gx = Ops.sub(gx, Ops.mul(share, Ops.elem(came, 1)))
            gy = Ops.sub(gy, Ops.mul(share, Ops.elem(came, 2)))
          end
        end
      end
    end
    return self.recurred(x, y, [gx, gy])
  end
  def cell_pull(*args_)
    @cell_pull = (true) unless instance_variable_defined?(:@cell_pull)
    args_.empty? ? @cell_pull : @cell_pull.(*args_)
  end
  attr_writer :cell_pull
  def own_gathering(h)
    if ((Ops.eq(h, nil) || !(self.cell_pull)) || !Ops.eq(self.shone.length, self.cells))
      return nil
    end
    c = self.at(Ops.m_round(h.x), Ops.m_round(h.y))
    if Ops.lt(c, 0)
      return nil
    end
    e = Ops.elem(self.shone, c)
    if Ops.eq(e, nil)
      return nil
    end
    return ((Ops.eq(Ops.elem(e, 6), Ops.sub((-2), c)) && Ops.gt(Ops.elem(e, 0), 0)) ? e : nil)
  end
  def recurred(x, y, g)
    n = Ops.mul(self.K, self.K)
    f = self.recur_at(x, y, Fmt.hypot(Ops.div(Ops.elem(g, 0), n), Ops.div(Ops.elem(g, 1), n)))
    return [Ops.mul(Ops.div(Ops.elem(g, 0), n), f), Ops.mul(Ops.div(Ops.elem(g, 1), n), f)]
  end
  def per_at(px, py)
    s = self.symbols(self.tap(self.rho_was, 0, px, py, 0), self.tap(self.nf_was, 0, px, py, 0))
    rate = 0
    Ops.list(self.meets).each do |t|
      rate = Ops.add(rate, Ops.div(Ops.mul(self.share(t, s), t.doing.folds.at(s)), 2))
    end
    return Ops.div(rate, ((self.crowd ? Ops.add(1, self.tap(self.stand, 0, px, py, 0)) : 1)))
  end
  def pull_local(x, y, zown)
    half = Ops.div(Ops.sub(self.K, 1), 2)
    whole = self.own_gathering(((Ops.ge(zown, 1) && Ops.le(zown, self.holes.length)) ? Ops.elem(self.holes, Ops.sub(zown, 1)) : nil))
    cx = (Ops.eq(whole, nil) ? x : Ops.div(Ops.elem(whole, 1), Ops.elem(whole, 0)))
    cy = (Ops.eq(whole, nil) ? y : Ops.div(Ops.elem(whole, 2), Ops.elem(whole, 0)))
    gx = 0
    gy = 0
    self.K.times do |dy|
      self.K.times do |dx|
        px = Ops.add(Ops.sub(cx, half), dx)
        py = Ops.add(Ops.sub(cy, half), dy)
        per = self.per_at(px, py)
        came = self.arriving_at(px, py, zown)
        gx = Ops.sub(gx, Ops.mul(per, Ops.elem(came, 1)))
        gy = Ops.sub(gy, Ops.mul(per, Ops.elem(came, 2)))
      end
    end
    return [gx, gy]
  end
  def lean
    self.cells.times do |c|
      own = (Ops.gt(Ops.elem(self.blocks, c), 0) ? self.plane_of(Ops.elem(self.holes, Ops.sub(Ops.elem(self.blocks, c), 1))) : 0)
      g = self.pull_at(self.column_of(c), self.row_of(c), own, 0, 0)
      Ops.set_at(self.lean_x, c, Ops.elem(g, 0))
      Ops.set_at(self.lean_y, c, Ops.elem(g, 1))
    end
  end
  def swept(*args_)
    @swept = (Ops.m_map(Ops.rng(self.planes), ->(z) {
    return Ops.filled(self.cells, 0)
  })) unless instance_variable_defined?(:@swept)
    args_.empty? ? @swept : @swept.(*args_)
  end
  attr_writer :swept
  def sweep
    if self.local_rays
      self.cells.times do |c|
        Ops.set_at(Ops.elem(self.swept, 1), c, self.held_at(c))
      end
    end
    if self.local_rays
      return
    end
    Ops.sub(self.planes, 1).times do |i|
      z = Ops.add(i, 1)
      self.cells.times do |c|
        Ops.set_at(Ops.elem(self.swept, z), c, Ops.elem(self.sent_to(z, self.column_of(c), self.row_of(c)), 0))
      end
    end
  end
  def tick
    if self.local_rays
      self.stream_local
      self.shine_local
    else
      self.stream
      self.shine
    end
    self.open
    self.meet
    self.unfold
    self.make
    self.settle_rho
    self.keep_track
    self.move
    self.lean
    self.sweep
    self.ticks = Ops.add(self.ticks, 1)
  end
  def lean_under(h)
    return self.pull_at(h.x, h.y, self.plane_of(h), Ops.div(Ops.elem(h.momentum.components, 0), h.mass), Ops.div(Ops.elem(h.momentum.components, 1), h.mass))
  end
  def pulled(*args_)
    @pulled = ([]) unless instance_variable_defined?(:@pulled)
    args_.empty? ? @pulled : @pulled.(*args_)
  end
  attr_writer :pulled
  def move
    self.pulled = Ops.m_map(self.holes, ->(h) {
      return self.lean_under(h)
    })
    self.holes.length.times do |i|
      h = Ops.elem(self.holes, i)
      if h.moves
        g = Ops.elem(self.pulled, i)
        h.momentum = Ops.add(h.momentum, Vector.new(components: [Ops.mul(Ops.elem(g, 0), h.mass), Ops.mul(Ops.elem(g, 1), h.mass)]))
        if Ops.gt(h.momentum.norm, h.mass)
          h.momentum = Ops.mul(h.momentum.unit, h.mass)
        end
        h.x = Ops.add(h.x, Ops.mul(Ops.div(Ops.elem(h.momentum.components, 0), h.mass), self.K))
        h.y = Ops.add(h.y, Ops.mul(Ops.div(Ops.elem(h.momentum.components, 1), h.mass), self.K))
        h.moved = Ops.add(h.moved, 1)
      end
    end
    return self.block
  end
  def arrived(z, c)
    return (self.local_rays ? Ops.elem(Ops.elem(self.swept, (Ops.ge(z, 1) ? 1 : 0)), c) : Ops.elem(Ops.elem(self.swept, (Ops.lt(z, self.planes) ? z : Ops.sub(self.planes, 1))), c))
  end
  def record_at(c)
    return Ops.elem(self.fold, c)
  end
  def record
    return Ops.m_map(Ops.rng(self.cells), ->(c) {
