    })
  end
  def seed
    if self.local_rays
      return self.seed_local
    end
    self.planes.times do |z|
      self.rungs.times do |r|
        Ops.set_at(Ops.elem(self.beam, z), r, 0)
      end
    end
    Ops.list(self.holes).each do |h|
      z = self.plane_of(h)
      per = self.per_way(h)
      near = self.face_of(h)
      self.rungs.times do |r|
        here = Fmt.max(near, r)
        Ops.set_at(Ops.elem(self.beam, z), r, Fmt.min(1, Ops.add(Ops.elem(Ops.elem(self.beam, z), r), Ops.mul(per, (Ops.power((Ops.div(near, here)), Ops.sub(self.D, 1)))))))
      end
    end
  end
  def settle
    self.seed
    before = 0
    done = false
    Ops.mul(4, self.crossing).times do |i|
      unless done
        self.tick
        if Ops.eq(Ops.mod(self.ticks, 2), 0)
          now = 0
          Ops.list(self.holes).each do |h|
            g = self.lean_under(h)
            now = Ops.add(now, Fmt.hypot(Ops.elem(g, 0), Ops.elem(g, 1)))
          end
          if ((Ops.gt(i, 2) && Ops.gt(now, 0)) && Ops.lt(Ops.m_abs((Ops.sub(now, before))), Ops.div(now, 1000)))
            done = true
          end
          before = now
        end
      end
    end
  end
  def crossing
    return Ops.mul(2, (Ops.add(Ops.m_floor((Ops.div(self.N, self.K))), 1)))
  end
  def record_above(c)
    return self.record_at(c)
  end
  def pull_toward(x, y, mx, my, zown)
    dx = Ops.sub(mx, x)
    dy = Ops.sub(my, y)
    d = Fmt.hypot(dx, dy)
    if Ops.le(d, 0)
      return 0
    end
    g = self.pull_at(x, y, zown, 0, 0)
    return Ops.div((Ops.add(Ops.mul(Ops.elem(g, 0), dx), Ops.mul(Ops.elem(g, 1), dy))), d)
  end
  def pull_x(c)
    return Ops.elem(self.lean_x, c)
  end
  def pull_y(c)
    return Ops.elem(self.lean_y, c)
  end
  def grown(c)
    return self.record_at(c)
  end
  def crossed(c)
    return Ops.elem(self.gone, c)
  end
  def rho_at(c)
    got = 0
    self.planes.times do |z|
      got = Ops.add(got, Ops.elem(Ops.elem(self.swept, z), c))
    end
    return self.activity(got)
  end
  def rho
    return Ops.m_map(Ops.rng(self.cells), ->(c) {
      return self.rho_at(c)
    })
  end
  def mean
    return Ops.div(Ops.m_sum(self.rho), self.cells)
  end
  def state
    return Ops.m_map(Ops.rng(self.cells), ->(c) {
      return self.rho_at(c)
    })
  end
  def bodies
    return self.holes
  end
  def mass(h)
    return h.mass
  end
  def under_vacuum
    self.vacuum = true
    return self
  end
  def thrown(x, y, mx, ways, px, py, tag)
    h = Hole.new(x: x, y: y, mx: mx, ways: ways)
    h.px = px
    h.py = py
    h.tag = tag
    h.moves = true
    self.add(h)
    return self
  end
  __exposed
end

