    @started = (false) unless instance_variable_defined?(:@started)
    args_.empty? ? @started : @started.(*args_)
  end
  attr_writer :started
  def at(frame_at)
    unless self.started
      self.recording.names.length.times do |i|
        Ops.set_at(self.buf, Ops.elem(self.recording.names, i), Ops.filled(Ops.elem(self.recording.sizes, i), 0))
      end
      self.recording.start
      self.started = true
    end
    if Ops.lt(frame_at, Ops.sub(self.next, 1))
      fail.("frame #{frame_at} was asked for after #{Ops.sub(self.next, 1)}, and a world that is being run cannot go back - record it first")
    end
    while Ops.le(self.next, frame_at)
      self.recording.frame(self.buf)
      self.next = Ops.add(self.next, 1)
    end
    return self.buf
  end
  __exposed
end

