class Fmt < Node
  def self.log10(x)
    return Ops.div(Ops.m_ln(x), Ops.m_ln(10))
  end
  def self.finite(x)
    return (Ops.eq(x, x) && Ops.lt(Ops.m_abs(x), Ops.power(10, 300)))
  end
  def self.fixed(x, d)
    if !Ops.eq(x, x)
      return "NaN"
    end
    scale = Ops.power(10, d)
    r = Ops.m_round((Ops.mul(Ops.m_abs(x), scale)))
    whole = Ops.m_floor((Ops.div(r, scale)))
    frac = Ops.sub(r, Ops.mul(whole, scale))
    sign = ((Ops.lt(x, 0) && Ops.gt(r, 0)) ? "-" : "")
    if Ops.eq(d, 0)
      return "#{sign}#{whole}"
    end
    digits = "#{frac}"
    while Ops.lt(digits.length, d)
      digits = "0#{digits}"
    end
    return "#{sign}#{whole}.#{digits}"
  end
  def self.exponential(x, d)
    if !Ops.eq(x, x)
      return "NaN"
    end
    zeros = "0".repeat(d)
    if Ops.eq(x, 0)
      return (Ops.gt(d, 0) ? "0.#{zeros}e+0" : "0e+0")
    end
    e = Ops.m_floor(Fmt.log10(Ops.m_abs(x)))
    m = Ops.div(Ops.m_abs(x), Ops.power(10, e))
    if Ops.ge(Ops.m_round((Ops.mul(m, Ops.power(10, d)))), Ops.power(10, (Ops.add(d, 1))))
      m = Ops.div(m, 10)
      e = Ops.add(e, 1)
    end
    if Ops.lt(m, 1)
      m = Ops.mul(m, 10)
      e = Ops.sub(e, 1)
    end
    sign = (Ops.lt(x, 0) ? "-" : "")
    mant = Fmt.fixed(m, d)
    return (Ops.ge(e, 0) ? "#{sign}#{mant}e+#{e}" : "#{sign}#{mant}e-#{Ops.m_abs(e)}")
  end
  def self.min(p, q)
    return (Ops.lt(p, q) ? p : q)
  end
  def self.max(p, q)
    return (Ops.gt(p, q) ? p : q)
  end
  def self.hypot(x, y)
    return Ops.m_sqrt((Ops.add(Ops.mul(x, x), Ops.mul(y, y))))
  end
  def self.median(xs_)
    if Ops.m_empty(xs_)
      return Float::NAN
    end
    s = Expr.sorted(xs_)
    return Ops.elem(s, Ops.m_floor((Ops.div(s.length, 2))))
  end
  __exposed
end

