    cy = Ops.add(Ops.m_round((Ops.div(y, self.PIX))), self.VIEW)
    if Ops.lt(cx, 0)
      cx = 0
    end
    if Ops.lt(cy, 0)
      cy = 0
    end
    if Ops.gt(cx, Ops.sub(self.coarse_side, 1))
      cx = Ops.sub(self.coarse_side, 1)
    end
    if Ops.gt(cy, Ops.sub(self.coarse_side, 1))
