    end
    m = 0
    x = 0
    y = 0
    holes.length.times do |i|
      if (!Ops.eq(i, k) && ((!(held) || !(Ops.elem(holes, i).moves))))
        m = Ops.add(m, Ops.elem(holes, i).mass)
        x = Ops.add(x, Ops.mul(Ops.elem(holes, i).x, Ops.elem(holes, i).mass))
        y = Ops.add(y, Ops.mul(Ops.elem(holes, i).y, Ops.elem(holes, i).mass))
