      d = Ops.add(near, Ops.div(Ops.mul((Ops.sub(far, near)), i), steps))
      return [d, Ops.add(Ops.elem(rest, 1), Ops.mul(Ops.mul(ux, d), _K)), Ops.add(Ops.elem(rest, 2), Ops.mul(Ops.mul(uy, d), _K))]
