      return Ops.elem(Ops.elem(pulls, 0), 1)
    end
    if Ops.ge(r, Ops.elem(Ops.elem(pulls, Ops.sub(n, 1)), 0))
      return Ops.elem(Ops.elem(pulls, Ops.sub(n, 1)), 1)
    end
    got = Ops.elem(Ops.elem(pulls, Ops.sub(n, 1)), 1)
    found = false
    Ops.sub(n, 1).times do |i|
      unless found
        if (Ops.le(Ops.elem(Ops.elem(pulls, i), 0), r) && Ops.le(r, Ops.elem(Ops.elem(pulls, Ops.add(i, 1)), 0)))
          span = Ops.sub(Ops.elem(Ops.elem(pulls, Ops.add(i, 1)), 0), Ops.elem(Ops.elem(pulls, i), 0))
          f = (Ops.gt(span, 0) ? Ops.div((Ops.sub(r, Ops.elem(Ops.elem(pulls, i), 0))), span) : 0)
          got = Ops.add(Ops.mul(Ops.elem(Ops.elem(pulls, i), 1), (Ops.sub(1, f))), Ops.mul(Ops.elem(Ops.elem(pulls, Ops.add(i, 1)), 1), f))
          found = true
        end
      end
    end
    return got
  end
  def self.nearest(pulls, v, far, near, both, kappa, ticks)
    x = far
    y = 0
    vx = 0
    vy = v
    best = far
    done = false
    ticks.times do |i|
      unless done
        r = Fmt.hypot(x, y)
        best = Fmt.min(best, r)
        if (Ops.lt(best, far) && Ops.gt(r, Ops.mul(best, 1.02)))
          done = true
        end
        if Ops.lt(r, Ops.div(near, 2))
          done = true
        end
        if Ops.gt(r, Ops.mul(far, 1.05))
          done = true
        end
        less = Ops.sub(1, Ops.mul(kappa, Fmt.hypot(vx, vy)))
        g = Ops.mul(Ops.mul(Setup.pull_at_r(pulls, r), both), ((Ops.gt(less, 0) ? less : 0)))
        if Ops.gt(r, 0)
          vx = Ops.sub(vx, Ops.div(Ops.mul(g, x), r))
          vy = Ops.sub(vy, Ops.div(Ops.mul(g, y), r))
        end
        x = Ops.add(x, vx)
        y = Ops.add(y, vy)
      end
    end
    return best
  end
  def self.thrown(pulls, far, near, both, kappa, guess)
    if !((((Ops.gt(guess, 0) && Ops.gt(far, 0)) && Ops.gt(near, 0))))
      return guess
    end
    lo = 0
    hi = Ops.mul(guess, 2)
    40.times do |i|
      mid = Ops.div((Ops.add(lo, hi)), 2)
      turn = Ops.m_round((Ops.div(Ops.mul(Ops.mul(8, Math::PI), far), ((Ops.gt(mid, 0) ? mid : 1)))))
      ticks = (Ops.gt(turn, 400000) ? 400000 : ((Ops.lt(turn, 16) ? 16 : turn)))
      if Ops.lt(Setup.nearest(pulls, mid, far, near, both, kappa, ticks), near)
        lo = mid
      else
        hi = mid
      end
    end
    return Ops.div((Ops.add(lo, hi)), 2)
  end
  def self.slower(rest_far, moving_far, v)
    if !(((Ops.gt(rest_far, 0) && Ops.gt(v, 0))))
      return 0
    end
    return Ops.div((Ops.sub(rest_far, moving_far)), (Ops.mul(rest_far, v)))
  end
  def self.orbit(h, rest, pulls, e, px, py, _K, kappa)
    dx = Ops.sub(Ops.elem(rest, 1), h.x)
    dy = Ops.sub(Ops.elem(rest, 2), h.y)
    far = Ops.div(Fmt.hypot(dx, dy), _K)
    if ((Ops.le(far, 0) || Ops.lt(pulls.length, 2)) || Ops.le(Ops.elem(rest, 0), 0))
      return [px, py]
    end
    near = Ops.div(Ops.mul(far, (Ops.sub(1, e))), (Ops.add(1, e)))
    both = Ops.div((Ops.add(h.mass, Ops.elem(rest, 0))), Ops.elem(rest, 0))
    w = Ops.mul(Setup.work(pulls), both)
    ratio = Ops.mul((Ops.div(far, near)), (Ops.div(far, near)))
    circle = Ops.mul(Ops.mul(Ops.elem(Ops.elem(pulls, Ops.sub(pulls.length, 1)), 1), both), far)
    between = (Ops.gt(ratio, 1.000001) ? ((Ops.gt(w, 0) ? Ops.m_sqrt((Ops.div(Ops.mul(2, w), (Ops.sub(ratio, 1))))) : 0)) : ((Ops.gt(circle, 0) ? Ops.m_sqrt(circle) : 0)))
    run = Setup.thrown(pulls, far, near, both, kappa, between)
    speed = Ops.div(Ops.mul(run, Ops.elem(rest, 0)), (Ops.add(h.mass, Ops.elem(rest, 0))))
    tx = Ops.sub(0, Ops.div(dy, (Ops.mul(far, _K))))
    ty = Ops.div(dx, (Ops.mul(far, _K)))
    way = (Ops.lt(Ops.add(Ops.mul(tx, px), Ops.mul(ty, py)), 0) ? Ops.sub(0, 1) : 1)
    return [Ops.mul(Ops.mul(Ops.mul(way, tx), speed), h.mass), Ops.mul(Ops.mul(Ops.mul(way, ty), speed), h.mass)]
  end
  __exposed
end

