class FieldRecording < Recording
  def p(*args_)
    args_.empty? ? @p : @p.(*args_)
  end
  attr_writer :p
  def W(*args_)
    @W = (nil) unless instance_variable_defined?(:@W)
    args_.empty? ? @W : @W.(*args_)
  end
  attr_writer :W
  def gone(*args_)
    @gone = (Ops.filled(Ops.mul(self.p.side, self.p.side), 0)) unless instance_variable_defined?(:@gone)
    args_.empty? ? @gone : @gone.(*args_)
  end
  attr_writer :gone
  def lx(*args_)
    @lx = (Ops.filled(Ops.mul(self.p.side, self.p.side), 0)) unless instance_variable_defined?(:@lx)
    args_.empty? ? @lx : @lx.(*args_)
  end
  attr_writer :lx
  def ly(*args_)
    @ly = (Ops.filled(Ops.mul(self.p.side, self.p.side), 0)) unless instance_variable_defined?(:@ly)
    args_.empty? ? @ly : @ly.(*args_)
  end
  attr_writer :ly
  def beat(*args_)
    @beat = (Ops.filled(Ops.mul(self.p.side, self.p.side), 0)) unless instance_variable_defined?(:@beat)
    args_.empty? ? @beat : @beat.(*args_)
  end
  attr_writer :beat
  def beat2(*args_)
    @beat2 = (Ops.filled(Ops.mul(self.p.side, self.p.side), 0)) unless instance_variable_defined?(:@beat2)
    args_.empty? ? @beat2 : @beat2.(*args_)
  end
  attr_writer :beat2
  def per_tag(*args_)
    @per_tag = (Ops.m_map(Ops.rng((Ops.gt(self.p.tags, 2) ? Ops.sub(self.p.tags, 2) : 1)), ->(z) {
    return Ops.filled(Ops.mul(self.p.side, self.p.side), 0)
  })) unless instance_variable_defined?(:@per_tag)
    args_.empty? ? @per_tag : @per_tag.(*args_)
  end
  attr_writer :per_tag
  def spanned(*args_)
    @spanned = (0) unless instance_variable_defined?(:@spanned)
    args_.empty? ? @spanned : @spanned.(*args_)
  end
  attr_writer :spanned
  def lay
    p = self.p
    w = p.theory.medium(p.side, p.A, p.K, p.DEG, p.tags, p.D)
    placed = p.place(p)
    Ops.list(placed).each do |b|
      h = Hole.new(x: Ops.add(p.centre, Ops.mul(b.x, p.K)), y: Ops.add(p.centre, Ops.mul(b.y, p.K)), mx: b.mx, ways: b.ways)
      h.tag = b.tag
      h.moves = false
      w.add(h)
    end
    if Ops.eq(p.RANGE, "instant")
      w.settle
    else
      p.BURN.times do |i|
        w.tick
      end
    end
    if Ops.m_some(placed, ->(b) {
      return Ops.eq(b.launch, "orbit")
    })
      w.tick
    end
    placed.length.times do |k|
      Ops.elem(w.holes, k).moves = Ops.elem(placed, k).moves
    end
    reads = Ops.m_map(Ops.rng(placed.length), ->(k) {
      return (Ops.eq(Ops.elem(placed, k).launch, "orbit") ? Setup.pulls_between(w, Ops.elem(w.holes, k), Setup.rest_of(w.holes, k), Ops.elem(placed, k).ecc, p.K, 64) : [])
    })
    placed.length.times do |k|
      h = Ops.elem(w.holes, k)
      b = Ops.elem(placed, k)
      v = (Ops.eq(b.launch, "orbit") ? Setup.orbit(h, Setup.rest_of(w.holes, k), Ops.elem(reads, k), b.ecc, b.px, b.py, p.K, 0) : [b.px, b.py])
      h.px = Ops.elem(v, 0)
      h.py = Ops.elem(v, 1)
      h.momentum = Vector.new(components: [Ops.elem(v, 0), Ops.elem(v, 1)])
    end
    w.seed
    placed.length.times do |k|
      b = Ops.elem(placed, k)
      if Ops.eq(b.launch, "orbit")
        h = Ops.elem(w.holes, k)
        rest = Setup.rest_of(w.holes, k)
        moving = Setup.pulls_between(w, h, rest, b.ecc, p.K, 64)
        at = Ops.sub(Ops.elem(reads, k).length, 1)
        vrel = Ops.div(Ops.mul(Ops.div(Fmt.hypot(h.px, h.py), h.mass), (Ops.add(h.mass, Ops.elem(rest, 0)))), Ops.elem(rest, 0))
        kappa = Setup.slower(Ops.elem(Ops.elem(Ops.elem(reads, k), at), 1), Ops.elem(Ops.elem(moving, at), 1), vrel)
        v = Setup.orbit(h, rest, Ops.elem(reads, k), b.ecc, b.px, b.py, p.K, kappa)
        h.px = Ops.elem(v, 0)
        h.py = Ops.elem(v, 1)
        h.momentum = Vector.new(components: [Ops.elem(v, 0), Ops.elem(v, 1)])
      end
    end
    self.W = w
  end
  def start
    return self.lay
  end
  def begin_frame
    cells = Ops.mul(self.p.side, self.p.side)
    cells.times do |c|
      Ops.set_at(self.gone, c, 0)
      Ops.set_at(self.lx, c, 0)
      Ops.set_at(self.ly, c, 0)
      Ops.set_at(self.beat, c, 0)
      Ops.set_at(self.beat2, c, 0)
    end
    Ops.list(self.per_tag).each do |e|
      cells.times do |c|
        Ops.set_at(e, c, 0)
      end
    end
    self.spanned = 0
  end
  def take(w)
    p = self.p
    cells = Ops.mul(p.side, p.side)
    cells.times do |c|
      Ops.set_at(self.gone, c, Ops.add(Ops.elem(self.gone, c), w.crossed(c)))
      Ops.set_at(self.lx, c, Ops.add(Ops.elem(self.lx, c), w.pull_x(c)))
      Ops.set_at(self.ly, c, Ops.add(Ops.elem(self.ly, c), w.pull_y(c)))
      Ops.set_at(self.beat, c, Ops.add(Ops.elem(self.beat, c), w.arrived(1, c)))
      (Ops.gt(p.tags, 2) ? Ops.sub(p.tags, 2) : 1).times do |k|
        v = w.arrived(Ops.add(k, 2), c)
        Ops.set_at(self.beat2, c, Ops.add(Ops.elem(self.beat2, c), v))
        Ops.set_at(Ops.elem(self.per_tag, k), c, Ops.add(Ops.elem(Ops.elem(self.per_tag, k), c), v))
      end
    end
    self.spanned = Ops.add(self.spanned, 1)
  end
  def positions(w)
    return Ops.m_map(w.holes, ->(h) {
      return Body.new(x: Ops.div((Ops.sub(h.x, self.p.centre)), self.p.K), y: Ops.div((Ops.sub(h.y, self.p.centre)), self.p.K), mx: h.mx, ways: h.ways)
    })
  end
  def finish(into, w)
    p = self.p
    level = 0
    seen = 0
    _R = p.reach
    step = Ops.div(p.K, p.PIX)
    one = Ops.getattr(into, "one")
    two = Ops.getattr(into, "two")
    gone = Ops.getattr(into, "gone")
    bys = Ops.m_map(Ops.rng(self.per_tag.length), ->(k) {
      return Ops.getattr(into, "by#{k}")
    })
    marks = Ops.getattr(into, "marks")
    span = (Ops.lt(self.spanned, 1) ? 1 : self.spanned)
    Ops.add(Ops.mul(2, _R), 1).times do |yi|
      y = Ops.sub(yi, _R)
      Ops.add(Ops.mul(2, _R), 1).times do |xi|
        x = Ops.sub(xi, _R)
        c = w.at(Ops.m_round((Ops.add(p.centre, Ops.mul(x, step)))), Ops.m_round((Ops.add(p.centre, Ops.mul(y, step)))))
        i = p.box(x, y)
        if Ops.lt(c, 0)
          Ops.set_at(one, i, 0)
          Ops.set_at(two, i, 0)
          Ops.set_at(gone, i, 0)
          bys.length.times do |k|
            if ((!Ops.eq(Ops.elem(bys, k), nil) && Ops.eq(Ops.mod((Ops.add(x, _R)), p.PIX), 0)) && Ops.eq(Ops.mod((Ops.add(y, _R)), p.PIX), 0))
              Ops.set_at(Ops.elem(bys, k), p.coarse(x, y), 0)
            end
          end
        else
          blocked = Ops.gt(Ops.elem(w.blocks, c), 0)
          Ops.set_at(one, i, (blocked ? (-1) : Ops.div(Ops.elem(self.beat, c), span)))
          Ops.set_at(two, i, (blocked ? (-1) : Ops.div(Ops.elem(self.beat2, c), span)))
          bys.length.times do |k|
            if ((!Ops.eq(Ops.elem(bys, k), nil) && Ops.eq(Ops.mod((Ops.add(x, _R)), p.PIX), 0)) && Ops.eq(Ops.mod((Ops.add(y, _R)), p.PIX), 0))
              Ops.set_at(Ops.elem(bys, k), p.coarse(x, y), Ops.div(Ops.elem(Ops.elem(self.per_tag, k), c), span))
            end
          end
          Ops.set_at(gone, i, Ops.elem(self.gone, c))
          unless blocked
            level = Ops.add(level, Ops.elem(self.gone, c))
            seen = Ops.add(seen, 1)
          end
        end
      end
    end
    Ops.set_at(marks, Ops.mul(6, p.bodies), (Ops.gt(seen, 0) ? Ops.div(level, seen) : 0))
    w.holes.length.times do |k|
      if Ops.lt(k, p.bodies)
        b = Ops.elem(w.holes, k)
        Ops.set_at(marks, Ops.mul(k, 6), Ops.div((Ops.sub(b.x, p.centre)), p.K))
        Ops.set_at(marks, Ops.add(Ops.mul(k, 6), 1), Ops.div((Ops.sub(b.y, p.centre)), p.K))
        Ops.set_at(marks, Ops.add(Ops.mul(k, 6), 2), b.px_now)
        Ops.set_at(marks, Ops.add(Ops.mul(k, 6), 3), b.py_now)
        Ops.set_at(marks, Ops.add(Ops.mul(k, 6), 4), w.t)
        Ops.set_at(marks, Ops.add(Ops.mul(k, 6), 5), b.mass)
      end
    end
  end
  def frame(into)
    p = self.p
    self.begin_frame
    p.TICKS.times do |i|
      w = self.W
      if (!Ops.eq(p.spent, nil) && p.spent(self.positions(w)))
        self.lay
      else
        w.tick
        Ops.m_take(self, w)
      end
    end
    return self.finish(into, self.W)
  end
  __exposed
end

