      gone = Ops.getattr(ch, "gone")
      self.accumulated.length.times do |i|
        Ops.set_at(self.accumulated, i, Ops.add(Ops.elem(self.accumulated, i), Ops.elem(gone, i)))
      end
      self.count = Ops.add(self.count, 1)
      marks = Ops.getattr(ch, "marks")
      self.p.bodies.times do |k|
        Ops.m_push(Ops.elem(self.trail, k), Ops.elem(marks, Ops.mul(k, 6)))
        Ops.m_push(Ops.elem(self.trail, k), Ops.elem(marks, Ops.add(Ops.mul(k, 6), 1)))
      end
      Panel.paint(self.p, s, ch, Ops.mul(self.at_frame, self.p.TICKS), self.accumulated, self.count, self.trail)
    end
    self.at_frame = Ops.add(self.at_frame, 1)
  end
