class Panel < Node
  def self.BACK
    @BACK = ("\#08090d") unless instance_variable_defined?(:@BACK)
    @BACK
  end
  def self.BACK=(v)
    @BACK = v
  end
  def self.SEEN
    @SEEN = ("\#eef0f5") unless instance_variable_defined?(:@SEEN)
    @SEEN
  end
  def self.SEEN=(v)
    @SEEN = v
  end
  def self.ONE
    @ONE = ("\#4aa8eb") unless instance_variable_defined?(:@ONE)
    @ONE
  end
  def self.ONE=(v)
    @ONE = v
  end
  def self.TWO
    @TWO = ("\#8bd48b") unless instance_variable_defined?(:@TWO)
    @TWO
  end
  def self.TWO=(v)
    @TWO = v
  end
  def self.PAIR
    @PAIR = ("\#eef0f5") unless instance_variable_defined?(:@PAIR)
    @PAIR
  end
  def self.PAIR=(v)
    @PAIR = v
  end
  def self.lg(v, floor)
    return (Ops.le(v, 0) ? 0 : Ops.div(Ops.m_ln((Ops.add(1, Ops.div(v, floor)))), Ops.m_ln((Ops.add(1, Ops.div(1, floor))))))
  end
  def self.hex(c, at)
    hi = Panel.digit(Ops.elem(Ops.m_chars(c), at))
    lo = Panel.digit(Ops.elem(Ops.m_chars(c), Ops.add(at, 1)))
    return Ops.add(Ops.mul(hi, 16), lo)
  end
  def self.digit(c)
    return (Ops.ge(c, 97) ? Ops.sub(c, 87) : ((Ops.ge(c, 65) ? Ops.sub(c, 55) : Ops.sub(c, 48))))
  end
  def self.mix(a, b, f)
    r = Ops.m_round((Ops.add(Ops.mul(Panel.hex(a, 1), (Ops.sub(1, f))), Ops.mul(Panel.hex(b, 1), f))))
    g = Ops.m_round((Ops.add(Ops.mul(Panel.hex(a, 3), (Ops.sub(1, f))), Ops.mul(Panel.hex(b, 3), f))))
    bl = Ops.m_round((Ops.add(Ops.mul(Panel.hex(a, 5), (Ops.sub(1, f))), Ops.mul(Panel.hex(b, 5), f))))
    return "rgb(#{r},#{g},#{bl})"
  end
  def self.blend(p, bys, i)
    r = 0
    g = 0
    b = 0
    total = 0
    bys.length.times do |k|
      w = (Ops.eq(Ops.elem(bys, k), nil) ? 0 : Fmt.max(0, Ops.elem(Ops.elem(bys, k), i)))
      c = Ops.or_else(Ops.elem(p.colours, k)) { Panel.TWO }
      r = Ops.add(r, Ops.mul(w, Panel.hex(c, 1)))
      g = Ops.add(g, Ops.mul(w, Panel.hex(c, 3)))
      b = Ops.add(b, Ops.mul(w, Panel.hex(c, 5)))
      total = Ops.add(total, w)
    end
    if !((Ops.gt(total, 0)))
      return Panel.TWO
    end
    return "\##{Panel.hex2(Ops.m_round((Ops.div(r, total))))}#{Panel.hex2(Ops.m_round((Ops.div(g, total))))}#{Panel.hex2(Ops.m_round((Ops.div(b, total))))}"
  end
  def self.hex2(v)
    digits = "0123456789abcdef"
    n = (Ops.lt(v, 0) ? 0 : ((Ops.gt(v, 255) ? 255 : v)))
    hi = Ops.m_floor((Ops.div(n, 16)))
    lo = Ops.sub(n, Ops.mul(hi, 16))
    return "#{[Ops.elem(Ops.m_chars(digits), hi)].pack("U*")}#{[Ops.elem(Ops.m_chars(digits), lo)].pack("U*")}"
  end
  def self.paint(p, s, ch, t, accumulated, count, trail)
    width = s.width
    _H = s.height
    s.clear_rect(0, 0, width, _H)
    s.fill_style(Panel.BACK)
    s.fill_rect(0, 0, width, _H)
    _TOP = 14
    _BOT = 14
    _GAP2 = 10
    cw = Ops.div((Ops.sub(width, _GAP2)), 2)
    side = Fmt.min(cw, Ops.sub(Ops.sub(_H, _TOP), _BOT))
    view = p.view(t)
    pz = Ops.div(side, (Ops.add(Ops.mul(Ops.mul(2, view), p.PIX), 1)))
    top = Ops.add(_TOP, Fmt.max(0, Ops.div((Ops.sub(Ops.sub(Ops.sub(_H, _TOP), _BOT), side)), 2)))
    one = Ops.getattr(ch, "one")
    two = Ops.getattr(ch, "two")
    bys = Ops.m_map(Ops.rng((Ops.gt(p.tags, 2) ? Ops.sub(p.tags, 2) : 1)), ->(k) {
      return Ops.getattr(ch, "by#{k}")
    })
    marks = Ops.getattr(ch, "marks")
    peakA = 0.000000000000000000000000000001
    peakB = peakA
    peakG = peakA
    _R = Ops.m_round((Ops.mul(view, p.PIX)))
    Ops.add(Ops.mul(2, _R), 1).times do |yi|
      y = Ops.sub(yi, _R)
      Ops.add(Ops.mul(2, _R), 1).times do |xi|
        x = Ops.sub(xi, _R)
        i = p.box(x, y)
        unless Ops.lt(Ops.elem(one, i), 0)
          peakA = Fmt.max(peakA, Ops.elem(one, i))
          peakB = Fmt.max(peakB, Ops.elem(two, i))
          peakG = Fmt.max(peakG, Ops.div(Ops.elem(accumulated, i), count))
        end
      end
    end
    floorAB = 0.0015
    Ops.add(Ops.mul(2, _R), 1).times do |yi|
      y = Ops.sub(yi, _R)
      Ops.add(Ops.mul(2, _R), 1).times do |xi|
        x = Ops.sub(xi, _R)
        i = p.box(x, y)
        unless Ops.lt(Ops.elem(one, i), 0)
          tot = Ops.add(Ops.div(Fmt.max(0, Ops.elem(one, i)), peakA), Ops.div(Fmt.max(0, Ops.elem(two, i)), peakB))
          if Ops.gt(tot, 0)
            floorAB = Fmt.min(floorAB, tot)
          end
        end
      end
    end
    centre = 0
    p.bodies.times do |k|
      if Ops.gt(Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)), Ops.elem(marks, Ops.add(Ops.mul(centre, 6), 5)))
        centre = k
      end
    end
    weight = 0
    p.bodies.times do |k|
      weight = Ops.add(weight, Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)))
    end
    frames = Ops.div(Ops.elem(trail, centre).length, 2)
    midx = Ops.m_map(Ops.rng(frames), ->(i) {
      return 0
    })
    midy = Ops.m_map(Ops.rng(frames), ->(i) {
      return 0
    })
    frames.times do |i|
      mx = 0
      my = 0
      p.bodies.times do |k|
        mx = Ops.add(mx, Ops.mul(Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)), Ops.elem(Ops.elem(trail, k), Ops.mul(2, i))))
        my = Ops.add(my, Ops.mul(Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)), Ops.elem(Ops.elem(trail, k), Ops.add(Ops.mul(2, i), 1))))
      end
      Ops.set_at(midx, i, (Ops.gt(weight, 0) ? Ops.div(mx, weight) : 0))
      Ops.set_at(midy, i, (Ops.gt(weight, 0) ? Ops.div(my, weight) : 0))
    end
    biggest = 0
    nears = Ops.m_map(Ops.rng(p.bodies), ->(k) {
      return 0
    })
    fars = Ops.m_map(Ops.rng(p.bodies), ->(k) {
      return 0
    })
    p.bodies.times do |k|
      near = 0
      far = 0
      frames.times do |i|
        d = Fmt.hypot(Ops.sub(Ops.elem(Ops.elem(trail, k), Ops.mul(2, i)), Ops.elem(midx, i)), Ops.sub(Ops.elem(Ops.elem(trail, k), Ops.add(Ops.mul(2, i), 1)), Ops.elem(midy, i)))
        near = (Ops.eq(i, 0) ? d : Fmt.min(near, d))
        far = Fmt.max(far, d)
      end
      Ops.set_at(nears, k, near)
      Ops.set_at(fars, k, far)
      biggest = Fmt.max(biggest, far)
    end
    goes = Ops.m_map(Ops.rng(p.bodies), ->(k) {
      return (Ops.gt(Ops.elem(fars, k), Ops.div(biggest, 50)) && Ops.gt(Ops.elem(fars, k), Ops.add(Ops.elem(nears, k), 0.0001)))
    })
    Ops.list([0, 1]).each do |col|
      cx = (Ops.eq(col, 0) ? Ops.div(cw, 2) : Ops.add(Ops.add(cw, _GAP2), Ops.div(cw, 2)))
      cy = Ops.add(top, Ops.div(side, 2))
      s.fill_style("\#0b1119")
      s.fill_rect(Ops.sub(cx, Ops.div(side, 2)), Ops.sub(cy, Ops.div(side, 2)), side, side)
      Ops.add(Ops.mul(2, _R), 1).times do |yi|
        y = Ops.sub(yi, _R)
        Ops.add(Ops.mul(2, _R), 1).times do |xi|
          x = Ops.sub(xi, _R)
          i = p.box(x, y)
          unless Ops.lt(Ops.elem(one, i), 0)
            if Ops.eq(col, 1)
              ink = Panel.lg(Ops.div(Fmt.max(0, Ops.div(Ops.elem(accumulated, i), count)), peakG), 0.004)
              if Ops.gt(ink, 0.015)
                s.alpha(Fmt.min(1, ink))
                s.fill_style(Panel.PAIR)
                s.fill_rect(Ops.sub(Ops.add(cx, Ops.mul(x, pz)), Ops.div(pz, 2)), Ops.sub(Ops.add(cy, Ops.mul(y, pz)), Ops.div(pz, 2)), Ops.add(pz, 0.6), Ops.add(pz, 0.6))
              end
            else
              a = Ops.div(Fmt.max(0, Ops.elem(one, i)), peakA)
              b = Ops.div(Fmt.max(0, Ops.elem(two, i)), peakB)
              tot = Ops.add(a, b)
              if Ops.gt(tot, 0)
                shade = Panel.lg(tot, floorAB)
                if Ops.gt(shade, 0.012)
                  f = Ops.div(b, tot)
                  other = (((Ops.m_empty(p.colours) || Ops.eq(Ops.elem(bys, 0), nil))) ? Panel.TWO : Panel.blend(p, bys, p.coarse(x, y)))
                  s.alpha(Fmt.min(1, shade))
                  s.fill_style(Panel.mix(Panel.ONE, other, f))
                  s.fill_rect(Ops.sub(Ops.add(cx, Ops.mul(x, pz)), Ops.div(pz, 2)), Ops.sub(Ops.add(cy, Ops.mul(y, pz)), Ops.div(pz, 2)), Ops.add(pz, 0.6), Ops.add(pz, 0.6))
                end
              end
            end
          end
        end
      end
      p.bodies.times do |k|
        n = Ops.div(Ops.elem(trail, k).length, 2)
        if (Ops.gt(n, 1) && Ops.elem(goes, k))
          colour = (Ops.eq(p.ring, nil) ? Panel.SEEN : p.ring(k))
          s.stroke_style(colour)
          s.line_width(1)
          s.alpha(0.3)
          s.dash([3, 4])
          s.begin_path
          s.arc(Ops.add(cx, Ops.mul(Ops.mul(Ops.elem(midx, Ops.sub(frames, 1)), p.PIX), pz)), Ops.add(cy, Ops.mul(Ops.mul(Ops.elem(midy, Ops.sub(frames, 1)), p.PIX), pz)), Ops.mul(Ops.mul(Ops.elem(fars, k), p.PIX), pz), 0, Ops.mul(2, Math::PI))
          s.stroke
          if Ops.gt(Ops.elem(nears, k), 0)
            s.begin_path
            s.arc(Ops.add(cx, Ops.mul(Ops.mul(Ops.elem(midx, Ops.sub(frames, 1)), p.PIX), pz)), Ops.add(cy, Ops.mul(Ops.mul(Ops.elem(midy, Ops.sub(frames, 1)), p.PIX), pz)), Ops.mul(Ops.mul(Ops.elem(nears, k), p.PIX), pz), 0, Ops.mul(2, Math::PI))
            s.stroke
          end
          s.dash([])
          s.alpha(0.65)
          s.begin_path
          n.times do |i|
            px = Ops.add(cx, Ops.mul(Ops.mul(Ops.elem(Ops.elem(trail, k), Ops.mul(2, i)), p.PIX), pz))
            py = Ops.add(cy, Ops.mul(Ops.mul(Ops.elem(Ops.elem(trail, k), Ops.add(Ops.mul(2, i), 1)), p.PIX), pz))
            if Ops.eq(i, 0)
              s.move_to(px, py)
            else
              s.line_to(px, py)
            end
          end
          s.stroke
        end
      end
      s.alpha(1)
      heaviest = 0.000000000000000000000000000001
      p.bodies.times do |k|
        heaviest = Fmt.max(heaviest, Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)))
      end
      p.bodies.times do |k|
        bx = Ops.mul(Ops.elem(marks, Ops.mul(k, 6)), p.PIX)
        by = Ops.mul(Ops.elem(marks, Ops.add(Ops.mul(k, 6), 1)), p.PIX)
        heavy = Ops.div(Ops.elem(marks, Ops.add(Ops.mul(k, 6), 5)), heaviest)
        r = Ops.mul(Ops.mul(Fmt.max(1.6, Ops.mul(3.5, Ops.m_sqrt(heavy))), pz), p.PIX)
        s.stroke_style((Ops.eq(p.ring, nil) ? Panel.SEEN : p.ring(k)))
        s.line_width(1.1)
        s.begin_path
        s.arc(Ops.add(cx, Ops.mul(bx, pz)), Ops.add(cy, Ops.mul(by, pz)), r, 0, Ops.mul(2, Math::PI))
        s.stroke
      end
    end
  end
  def self.of(p)
    _BOX = Ops.mul(p.box_side, p.box_side)
    names = ["one", "two", "gone"]
    sizes = [_BOX, _BOX, _BOX]
    _COARSE = Ops.mul(p.coarse_side, p.coarse_side)
    unless Ops.m_empty(p.colours)
      (Ops.gt(p.tags, 2) ? Ops.sub(p.tags, 2) : 1).times do |k|
        Ops.m_push(names, "by#{k}")
        Ops.m_push(sizes, _COARSE)
      end
    end
    Ops.m_push(names, "marks")
    Ops.m_push(sizes, Ops.add(Ops.mul(6, p.bodies), 1))
    r = FieldRecording.new(stamp: "#{p.stamp}/shares", names: names, sizes: sizes, p: p)
    v = Picture.new(id: p.id, what: p.what, width: p.width, height: p.height, frames: p.RUN, paint: ->(played) {
      return FieldPainter.new(p: p, played: played)
    })
    v.record = r
    return v
  end
  __exposed
end

class Ink < Node
  def self.BACK
    @BACK = ("\#08090d") unless instance_variable_defined?(:@BACK)
    @BACK
  end
