  end
  attr_writer :dot
  def line(*args_)
    @line = (0.16) unless instance_variable_defined?(:@line)
    args_.empty? ? @line : @line.(*args_)
  end
  attr_writer :line
  def every(*args_)
    @every = (false) unless instance_variable_defined?(:@every)
