class Strip < Node
  def self.PAD
    @PAD = (12) unless instance_variable_defined?(:@PAD)
    @PAD
  end
  def self.PAD=(v)
    @PAD = v
  end
  def self.MID
    @MID = (30) unless instance_variable_defined?(:@MID)
    @MID
  end
  def self.MID=(v)
    @MID = v
  end
  def self.PANE
    @PANE = (Ops.add(Ops.div((Ops.sub(Ops.sub(900, Ops.mul(2, 12)), 30)), 2), Ops.mul(2, 12))) unless instance_variable_defined?(:@PANE)
    @PANE
  end
  def self.PANE=(v)
    @PANE = v
  end
  def self.line(theory, _N)
    return theory.seed(Physics.LINE2, _N, 0, 250000, 2)
  end
  def self.exit_toward(w, sign)
    return Ops.m_first(Ops.filt(Ops.rng(w.geometry.DEG), ->(d) {
      return Ops.gt(Ops.mul(Ops.elem(w.geometry.V(d).components, 0), sign), 0)
    }))
  end
  def self.point_at(w, at)
    return w.at(Vector.new(components: [at]))
  end
  def self.light(w, at, sign)
    return Ops.elem(Strip.point_at(w, at).rays, Strip.exit_toward(w, sign)).activate
  end
  def self.meeting(theory)
    w = Strip.line(theory, 2)
    Strip.light(w, 0, 1)
    Strip.light(w, 1, Ops.sub(0, 1))
    return w
  end
  def self.left(theory, laying, ids)
    w = laying.(theory)
    Strip.run(w, ids)
    return w
  end
  def self.point(theory)
    return theory.seed(Physics.LINE2, 1, 0, 250000, 16)
  end
  def self.heading(theory, sign)
    w = Strip.line(theory, 3)
    Strip.light(w, 1, sign)
    return w
  end
  def self.run(w, ids)
    Ops.list(ids).each do |rid|
      rule = Ops.m_first(Ops.filt(w.theory.rules, ->(r) {
        return Ops.eq(r.id, rid)
      }))
      if Ops.eq(rule, nil)
        fail.("#{w.theory.name} has no rule #{rid}")
      end
      Ops.list(rule.matches(w)).each do |x|
        rule.apply(x)
      end
    end
  end
  def self.begin(w)
    w.ticks = Ops.add(w.ticks, 1)
    Ops.list(w.sources).each do |s|
      s.stepped = false
      s.moved_along = nil
    end
  end
  def self.lit(was, now)
    return Ops.filt(now.sides, ->(sd) {
      return Ops.m_every(was.sides, ->(o) {
        return (!Ops.eq(o.at, sd.at) || !Ops.eq(o.sign, sd.sign))
      })
    })
  end
  def self.emitting(was, now)
    new_rays = Strip.lit(was, now)
    left = Ops.m_some(new_rays, ->(sd) {
      return Ops.lt(sd.sign, 0)
    })
    right = Ops.m_some(new_rays, ->(sd) {
      return Ops.gt(sd.sign, 0)
    })
    if (left && right)
      return "emits both ways"
    end
    if left
      return "emits left"
    end
    if right
      return "emits right"
    end
    return ""
  end
  def self.lane(w, ink)
    pts = Ops.m_map(w.live, ->(v) {
      return Ops.elem(v.at.components, 0)
    })
    sides = []
    Ops.list(w.live).each do |v|
      Ops.list(v.rays).each do |r|
        if r.active
          Ops.m_push(sides, Side.new(at: Ops.elem(v.at.components, 0), sign: Ops.elem(r.along.components, 0), ink: ink.ink_of(r)))
        end
      end
    end
    l = Lane.new(points: pts, sides: sides)
    Ops.list(w.sources).each do |s|
      Ops.list(s.cells).each do |c|
        Ops.m_push(l.sources, Ops.elem(c.at.components, 0))
      end
    end
    return l
  end
  def self.of(id, what, theory, ids, seeds, ink)
    rows = Ops.m_map(seeds, ->(laying) {
      w = laying.(theory)
      before = Strip.lane(w, ink)
      Strip.run(w, ids)
      return [before, Strip.lane(w, ink)]
    })
    _H = Ops.mul(70, rows.length)
    pic = Picture.still(id, what, 900, _H, ->(s) {
      return Strip.paint(s, rows, ink, [0, 1])
    })
    pic.panes = [Pane.new(name: "before", width: Strip.PANE, height: _H, paints: ->(s) {
      return Strip.paint(s, rows, ink, [0])
    }), Pane.new(name: "after", width: Strip.PANE, height: _H, paints: ->(s) {
      return Strip.paint(s, rows, ink, [1])
    })]
    return pic
  end
  def self.history(theory, laying, ticks, ink)
    w = laying.(theory)
    lanes = [Strip.lane(w, ink)]
    ticks.times do |t|
      w.tick
      Ops.m_push(lanes, Strip.lane(w, ink))
    end
    return lanes
  end
  def self.film(id, what, theory, laying, ticks, ink)
    lanes = Strip.history(theory, laying, ticks, ink)
    ink.centre = Strip.centre_of(lanes)
    _PER = 14
    _HOLD = 3
    return Picture.new(id: id, what: what, width: 900, height: 90, frames: Ops.mul((Ops.add(Ops.add(ticks, 1), _HOLD)), _PER), paint: ->(played) {
      return Unrolling.new(lanes: lanes, ink: ink, per: _PER)
    })
  end
  def self.tell(id, what, lanes, ink)
    ink.centre = Strip.centre_of(lanes)
    _PER = 40
    _HOLD = 1
    return Picture.new(id: id, what: what, width: 900, height: 110, frames: Ops.mul((Ops.add(lanes.length, _HOLD)), _PER), paint: ->(played) {
      return Unrolling.new(lanes: lanes, ink: ink, per: _PER)
    })
  end
  def self.relevant(pair)
    rel = Node.new
    Ops.list(pair).each do |l|
      Ops.list(l.sides).each do |sd|
        Ops.setattr(rel, "#{sd.at}", true)
        Ops.setattr(rel, "#{Ops.add(sd.at, sd.sign)}", true)
      end
    end
    Ops.list(pair).each do |l|
      Ops.list(l.sources).each do |p|
        Ops.setattr(rel, "#{p}", true)
      end
    end
    has0 = Node.new
    has1 = Node.new
    Ops.list(Ops.elem(pair, 0).points).each do |p|
      Ops.setattr(has0, "#{p}", true)
    end
    Ops.list(Ops.elem(pair, 1).points).each do |p|
      Ops.setattr(has1, "#{p}", true)
    end
    Ops.list(Ops.elem(pair, 0).points).each do |p|
      if Ops.eq(Ops.getattr(has1, "#{p}"), nil)
        Ops.setattr(rel, "#{p}", true)
      end
    end
    Ops.list(Ops.elem(pair, 1).points).each do |p|
      if Ops.eq(Ops.getattr(has0, "#{p}"), nil)
        Ops.setattr(rel, "#{p}", true)
      end
    end
    return rel
  end
  def self.centre_of(lanes)
    xs = []
    Ops.list(lanes).each do |l|
      Ops.list(l.sources).each do |p|
        Ops.m_push(xs, p)
      end
    end
    if Ops.m_empty(xs)
      xs = Ops.m_first(lanes).points
    end
    if Ops.m_empty(xs)
      return 0
    end
    return Ops.div((Ops.add(Ops.m_reduce(xs, Ops.m_first(xs), ->(a_, b_) {
      return Fmt.min(a_, b_)
    }), Ops.m_reduce(xs, Ops.m_first(xs), ->(a_, b_) {
      return Fmt.max(a_, b_)
    }))), 2)
  end
  def self.paint(s, rows, ink, lanes)
    width = s.width
    _H = s.height
    s.clear_rect(0, 0, width, _H)
    s.fill_style(Ink.BACK)
    s.fill_rect(0, 0, width, _H)
    if Ops.m_empty(rows)
      return
    end
    seen = false
    lo = 0
    hi = 0
    Ops.list(rows).each do |pair|
      Ops.list(pair).each do |l|
        Ops.list(l.sides).each do |sd|
          to = Ops.add(sd.at, sd.sign)
          unless seen
            lo = sd.at
            hi = sd.at
            seen = true
          end
          lo = Fmt.min(lo, Fmt.min(sd.at, to))
          hi = Fmt.max(hi, Fmt.max(sd.at, to))
        end
      end
    end
    Ops.list(rows).each do |pair|
      Ops.list(pair).each do |l|
        Ops.list(l.sources).each do |p|
          unless seen
            lo = p
            hi = p
            seen = true
          end
          lo = Fmt.min(lo, Ops.sub(p, 1))
          hi = Fmt.max(hi, Ops.add(p, 1))
        end
      end
    end
    unless ink.every
      Ops.list(rows).each do |pair|
        rel = Strip.relevant(pair)
        Ops.list(pair).each do |l|
          Ops.list(l.points).each do |p|
            if !Ops.eq(Ops.getattr(rel, "#{p}"), nil)
              unless seen
                lo = p
                hi = p
                seen = true
              end
              lo = Fmt.min(lo, p)
              hi = Fmt.max(hi, p)
            end
          end
        end
      end
    end
    unless seen
      lo = Ops.sub(0, 1)
      hi = 0
    end
    _EXT = Ops.add(Ops.div((Ops.sub(hi, lo)), 2), 0.4)
    if !Ops.eq(ink.centre, nil)
      _EXT = Ops.add(Fmt.max(Ops.sub(ink.centre, lo), Ops.sub(hi, ink.centre)), 0.4)
    end
    _HEAD = ink.top
    _PAD = Strip.PAD
    _MID = Strip.MID
    lanew = Ops.div((Ops.sub(Ops.sub(width, Ops.mul(2, _PAD)), Ops.mul(_MID, (Ops.sub(lanes.length, 1))))), lanes.length)
    origin = ->(k_) {
      return Ops.add(_PAD, Ops.mul(k_, (Ops.add(lanew, _MID))))
    }
    rowH = Ops.div((Ops.sub(_H, _HEAD)), rows.length)
    _CELL = Ops.div(lanew, (Ops.add(Ops.mul(2, _EXT), 1)))
    _MID_AT = 0
    _X = ->(k_, x) {
      return Ops.add(Ops.add(origin.(k_), Ops.div(lanew, 2)), Ops.mul((Ops.sub(x, _MID_AT)), _CELL))
    }
    rows.length.times do |r|
      pair = Ops.elem(rows, r)
      y = Ops.add(_HEAD, Ops.mul(rowH, (Ops.add(r, 0.5))))
      rel = Strip.relevant(pair)
      lanes.length.times do |k_|
        fi = Ops.elem(lanes, k_)
        l = Ops.elem(pair, fi)
        ox = origin.(k_)
        if !Ops.eq(ink.centre, nil)
          _MID_AT = ink.centre
        else
          xs = []
          Ops.list(l.sides).each do |sd|
            Ops.m_push(xs, Ops.sub(sd.at, 0.25))
            Ops.m_push(xs, Ops.add(sd.at, 0.25))
          end
          Ops.list(l.sources).each do |p|
            Ops.m_push(xs, Ops.sub(p, 0.3))
            Ops.m_push(xs, Ops.add(p, 0.3))
          end
          Ops.list(l.points).each do |p|
            if (ink.every || !Ops.eq(Ops.getattr(rel, "#{p}"), nil))
              Ops.m_push(xs, p)
            end
          end
          _MID_AT = (Ops.m_empty(xs) ? Ops.div((Ops.add(lo, hi)), 2) : Ops.div((Ops.add(Ops.m_reduce(xs, Ops.m_first(xs), ->(a_, b_) {
            return Fmt.min(a_, b_)
          }), Ops.m_reduce(xs, Ops.m_first(xs), ->(a_, b_) {
            return Fmt.max(a_, b_)
          }))), 2))
        end
        s.stroke_style("rgba(#{Ink.NEUTRAL},#{ink.line})")
        s.line_width(1)
        s.begin_path
        s.move_to(ox, y)
        s.line_to(Ops.add(ox, lanew), y)
        s.stroke
        Ops.list(l.points).each do |p|
          if (ink.every || !Ops.eq(Ops.getattr(rel, "#{p}"), nil))
            s.fill_style("rgba(#{Ink.NEUTRAL},#{ink.dot})")
            s.begin_path
            s.arc(_X.(k_, p), y, 2.6, 0, Ops.mul(2, Math::PI))
            s.fill
          end
        end
        Ops.list(l.sources).each do |p|
          half = Fmt.max(9, Fmt.min(18, Ops.mul(_CELL, 0.3)))
          sx = _X.(k_, p)
          s.fill_style("rgba(#{Ink.SOURCE},0.14)")
          s.fill_rect(Ops.sub(sx, half), Ops.sub(y, half), Ops.mul(2, half), Ops.mul(2, half))
          s.stroke_style("rgba(#{Ink.SOURCE},0.9)")
          s.line_width(1.5)
          s.stroke_rect(Ops.sub(sx, half), Ops.sub(y, half), Ops.mul(2, half), Ops.mul(2, half))
          unless Ops.m_empty(l.says)
            s.stroke_style("rgba(#{Ink.SOURCE},0.9)")
            s.line_width(1)
            s.begin_path
            s.move_to(sx, Ops.sub(y, half))
            s.line_to(sx, Ops.sub(Ops.sub(y, half), 16))
            s.stroke
            s.fill_style("rgba(#{Ink.SOURCE},1)")
            s.font("13px ui-monospace, monospace")
            s.text_align("center")
            s.text_baseline("bottom")
            s.fill_text(l.says, sx, Ops.sub(Ops.sub(y, half), 20))
          end
        end
        _HEADW = Fmt.max(7, Fmt.min(12, Ops.mul(_CELL, 0.20)))
        _REACH = Ops.mul(_CELL, 0.25)
        _BAR = Fmt.max(2.5, Fmt.min(4.5, Ops.mul(_CELL, 0.075)))
        _BASE = Ops.mul(_HEADW, 0.45)
        _TIP = Ops.mul(_HEADW, 0.55)
        _LEN = Ops.sub(_REACH, _BASE)
        _SEEN = Ops.sub(_TIP, Ops.div(_BAR, 0.84))
        Ops.list(l.sides).each do |sd|
          px = _X.(k_, sd.at)
          s.stroke_style("rgba(#{sd.ink},#{ink.behind})")
          s.line_width(_BAR)
          s.begin_path
          s.move_to(Ops.sub(px, Ops.mul(sd.sign, (Ops.add(_BASE, _LEN)))), y)
          s.line_to(Ops.sub(px, Ops.mul(sd.sign, _BASE)), y)
          s.stroke
          s.stroke_style("rgba(#{sd.ink},#{ink.front})")
          s.begin_path
          s.move_to(px, y)
          s.line_to(Ops.add(px, Ops.mul(sd.sign, (Ops.add(_SEEN, _LEN)))), y)
          s.stroke
        end
        Ops.list(l.sides).each do |sd|
          px = _X.(k_, sd.at)
          s.fill_style("rgba(#{sd.ink},#{ink.head})")
          s.begin_path
          s.move_to(Ops.add(px, Ops.mul(sd.sign, _TIP)), y)
          s.line_to(Ops.sub(px, Ops.mul(sd.sign, _BASE)), Ops.sub(y, Ops.mul(_HEADW, 0.42)))
          s.line_to(Ops.sub(px, Ops.mul(sd.sign, _BASE)), Ops.add(y, Ops.mul(_HEADW, 0.42)))
          s.fill
        end
      end
    end
  end
  __exposed
end

class Unrolling < Painter
  def lanes(*args_)
    args_.empty? ? @lanes : @lanes.(*args_)
  end
  attr_writer :lanes
  def ink(*args_)
    args_.empty? ? @ink : @ink.(*args_)
  end
  attr_writer :ink
  def per(*args_)
    args_.empty? ? @per : @per.(*args_)
  end
  attr_writer :per
  def at(*args_)
    @at = (0) unless instance_variable_defined?(:@at)
    args_.empty? ? @at : @at.(*args_)
  end
  attr_writer :at
  def frame(s, dt)
    k = Fmt.min(Ops.sub(self.lanes.length, 1), Ops.m_floor((Ops.div(self.at, self.per))))
    Strip.paint(s, [[Ops.elem(self.lanes, k), Ops.m_last(self.lanes)]], self.ink, [0])
    self.at = Ops.add(self.at, 1)
  end
  __exposed
end

class Scripted < Source
  def plan(*args_)
    args_.empty? ? @plan : @plan.(*args_)
  end
  attr_writer :plan
  def weight(*args_)
    args_.empty? ? @weight : @weight.(*args_)
  end
  attr_writer :weight
  def choose_emit_(exit)
    ways = Ops.or_else(Ops.elem(self.plan, Ops.sub(self.world.ticks, 1))) { "" }
    return (Ops.gt(Ops.elem(self.world.geometry.V(exit).components, 0), 0) ? Ops.m_contains(ways, "+") : Ops.m_contains(ways, "-"))
  end
  def choose_mass()
    return self.weight
  end
  __exposed
end

