class Sparc < Node
  def self.KPC
    @KPC = (Ops.mul(3.0856775814913673, Ops.power(10, 19))) unless instance_variable_defined?(:@KPC)
    @KPC
  end
  def self.KPC=(v)
    @KPC = v
  end
  def self.KMS
    @KMS = (1000) unless instance_variable_defined?(:@KMS)
    @KMS
  end
  def self.KMS=(v)
    @KMS = v
  end
  def self.MSUN
    @MSUN = (Ops.mul(1.98892, Ops.power(10, 30))) unless instance_variable_defined?(:@MSUN)
    @MSUN
  end
  def self.MSUN=(v)
    @MSUN = v
  end
  def self.G_NEWTON
    @G_NEWTON = (Ops.div(6.67430, Ops.power(10, 11))) unless instance_variable_defined?(:@G_NEWTON)
    @G_NEWTON
  end
  def self.G_NEWTON=(v)
    @G_NEWTON = v
  end
  def self.C_LIGHT
    @C_LIGHT = (299792458) unless instance_variable_defined?(:@C_LIGHT)
    @C_LIGHT
  end
  def self.C_LIGHT=(v)
    @C_LIGHT = v
  end
  def self.YD
    @YD = (0.5) unless instance_variable_defined?(:@YD)
    @YD
  end
  def self.YD=(v)
    @YD = v
  end
  def self.YB
    @YB = (0.7) unless instance_variable_defined?(:@YB)
    @YB
  end
  def self.YB=(v)
    @YB = v
  end
  def self.CACHE
    @CACHE = (Node.new) unless instance_variable_defined?(:@CACHE)
    @CACHE
  end
  def self.CACHE=(v)
    @CACHE = v
  end
  def self.sample
    if Ops.eq(Ops.getattr(Sparc.CACHE, "sample"), nil)
      Ops.setattr(Sparc.CACHE, "sample", Measured.of("sparc-galaxies"))
    end
    if Ops.eq(Ops.getattr(Sparc.CACHE, "sample"), nil)
      fail.("sparc-galaxies is not on disk - run `npx ray data` and try again")
    end
    return Ops.getattr(Sparc.CACHE, "sample")
  end
  def self.curves
    if Ops.eq(Ops.getattr(Sparc.CACHE, "curves"), nil)
      Ops.setattr(Sparc.CACHE, "curves", Measured.of("sparc-curves"))
    end
    if Ops.eq(Ops.getattr(Sparc.CACHE, "curves"), nil)
      fail.("sparc-curves is not on disk - run `npx ray data` and try again")
    end
    return Ops.getattr(Sparc.CACHE, "curves")
  end
  def self.names
    return Ops.getattr(Sparc.sample.header, "names")
  end
  def self.usable(g)
    _S = Sparc.sample.columns
    return (Ops.lt(Ops.elem(Ops.getattr(_S, "Q"), g), 3) && Ops.ge(Ops.elem(Ops.getattr(_S, "Inc"), g), 30))
  end
  def self.mass_of(g)
    _S = Sparc.sample.columns
    return Ops.mul(Ops.mul((Ops.add(Ops.mul(0.5, Ops.elem(Ops.getattr(_S, "L[3.6]"), g)), Ops.mul(1.33, Ops.elem(Ops.getattr(_S, "MHI"), g)))), Ops.power(10, 9)), Sparc.MSUN)
  end
  def self.rar
    if !Ops.eq(Ops.getattr(Sparc.CACHE, "rar"), nil)
      return Ops.getattr(Sparc.CACHE, "rar")
    end
    Ops.setattr(Sparc.CACHE, "rar", Sparc.rar_at(Sparc.YD))
    return Ops.getattr(Sparc.CACHE, "rar")
  end
  def self.rar_at(_YD)
    t = Sparc.curves
    _C = t.columns
    out = []
    t.rows.times do |i|
      g = Ops.elem(Ops.getattr(_C, "galaxy"), i)
      _R = Ops.mul(Ops.elem(Ops.getattr(_C, "R"), i), Sparc.KPC)
      v = Ops.mul(Ops.elem(Ops.getattr(_C, "Vobs"), i), Sparc.KMS)
      if (((Sparc.usable(g) && Ops.gt(_R, 0)) && Ops.gt(v, 0)) && Ops.le(Ops.elem(Ops.getattr(_C, "e_Vobs"), i), Ops.mul(0.1, Ops.elem(Ops.getattr(_C, "Vobs"), i))))
        gas = Ops.mul(Ops.elem(Ops.getattr(_C, "Vgas"), i), Sparc.KMS)
        disk = Ops.mul(Ops.elem(Ops.getattr(_C, "Vdisk"), i), Sparc.KMS)
        bul = Ops.mul(Ops.elem(Ops.getattr(_C, "Vbul"), i), Sparc.KMS)
        _YB = (Ops.gt(Sparc.YD, 0) ? Ops.div(Ops.mul(_YD, Sparc.YB), Sparc.YD) : _YD)
        gbar = Ops.div((Ops.add(Ops.add(Ops.mul(gas, Ops.m_abs(gas)), Ops.mul(Ops.mul(_YD, disk), Ops.m_abs(disk))), Ops.mul(Ops.mul(_YB, bul), Ops.m_abs(bul)))), _R)
        if Ops.gt(gbar, 0)
          Ops.m_push(out, RarPoint.new(gbar: gbar, gobs: Ops.div(Ops.mul(v, v), _R), galaxy: g, R: _R))
        end
      end
    end
    return out
  end
  def self.flat
    if !Ops.eq(Ops.getattr(Sparc.CACHE, "flat"), nil)
      return Ops.getattr(Sparc.CACHE, "flat")
    end
    best = Node.new
    Ops.list(Sparc.rar).each do |p|
      had = Ops.elem(best, p.galaxy)
      if (Ops.eq(had, nil) || Ops.gt(p.R, had.R))
        Ops.set_at(best, p.galaxy, p)
      end
    end
    out = []
    names = Sparc.names
    names.length.times do |g|
      p = Ops.elem(best, g)
      if !Ops.eq(p, nil)
        q = RarPoint.new(gbar: p.gbar, gobs: p.gobs, galaxy: p.galaxy, R: p.R)
        q.name = Ops.elem(names, g)
        Ops.m_push(out, q)
      end
    end
    Ops.setattr(Sparc.CACHE, "flat", out)
    return out
  end
  def self.btfr
    if !Ops.eq(Ops.getattr(Sparc.CACHE, "btfr"), nil)
      return Ops.getattr(Sparc.CACHE, "btfr")
    end
    t = Measured.of("sparc-btfr")
    if Ops.eq(t, nil)
      fail.("sparc-btfr is not on disk - run `npx ray data` and try again")
    end
    c = t.columns
    names = Ops.getattr(t.header, "names")
    out = []
    t.rows.times do |i|
      if Ops.gt(Ops.elem(Ops.getattr(c, "Vf"), i), 0)
        Ops.m_push(out, Btfr.new(name: Ops.elem(names, i), galaxy: Ops.elem(Ops.getattr(c, "galaxy"), i), vf: Ops.elem(Ops.getattr(c, "Vf"), i), err: Ops.elem(Ops.getattr(c, "e_Vf"), i), mass: Ops.mul(Ops.power(10, Ops.elem(Ops.getattr(c, "log(Mb)"), i)), Sparc.MSUN), err_mass: Ops.elem(Ops.getattr(c, "e_log(Mb)"), i)))
      end
    end
    Ops.setattr(Sparc.CACHE, "btfr", out)
    return out
  end
  def self.discs
    if !Ops.eq(Ops.getattr(Sparc.CACHE, "discs"), nil)
      return Ops.getattr(Sparc.CACHE, "discs")
    end
    d = Measured.of("genzel-discs")
    if Ops.eq(d, nil)
      fail.("genzel-discs is not on disk - run `npx ray data` and try again")
    end
    c = d.columns
    names = Ops.getattr(d.header, "names")
    out = Ops.m_map(Ops.rng(names.length), ->(i) {
      return HighZ.new(name: Ops.elem(names, i), redshift: Ops.elem(Ops.getattr(c, "z"), i), Mb: Ops.elem(Ops.getattr(c, "Mb"), i), Re: Ops.elem(Ops.getattr(c, "Re"), i), fraction: Ops.elem(Ops.getattr(c, "fDM"), i), err: Ops.elem(Ops.getattr(c, "e_fDM"), i), limit: Ops.gt(Ops.elem(Ops.getattr(c, "limit"), i), 0.5))
    })
    Ops.setattr(Sparc.CACHE, "discs", out)
    return out
  end
  def self.disc_arrival(d)
    return Ops.div(Ops.mul(Ops.mul(Ops.mul(Sparc.G_NEWTON, d.Mb), Ops.power(10, 11)), Sparc.MSUN), Ops.power((Ops.mul(d.Re, Sparc.KPC)), 2))
  end
  def self.disc_felt(d)
    return (Ops.lt(d.fraction, 1) ? Ops.div(Sparc.disc_arrival(d), (Ops.sub(1, d.fraction))) : Float::NAN)
  end
  __exposed
end

class Law < Node
  def self.CACHE
    @CACHE = (Node.new) unless instance_variable_defined?(:@CACHE)
    @CACHE
  end
  def self.CACHE=(v)
    @CACHE = v
  end
  def self.law
    if Ops.eq(Ops.getattr(Law.CACHE, "law"), nil)
      Ops.setattr(Law.CACHE, "law", Measured.of("law"))
    end
    if Ops.eq(Ops.getattr(Law.CACHE, "law"), nil)
      fail.("law is not on disk - run `npx ray measure` and try again")
    end
    return Ops.getattr(Law.CACHE, "law")
  end
  def self.a0
    return Ops.getattr(Law.law.header, "a0")
  end
  def self.carries
    return Ops.or_else(Ops.getattr(Law.law.header, "carries")) { 0 }
  end
  def self.theory
    return Ops.or_else(Ops.getattr(Law.law.header, "theory")) { "G" }
  end
  def self.boost(gN, scale)
    _A0 = Law.a0
    xs_ = Ops.getattr(Law.law.columns, "gN")
    ys_ = Ops.getattr(Law.law.columns, "g")
    want = Ops.mul((Ops.div(gN, scale)), _A0)
    lo = 0
    hi = Ops.sub(Law.law.rows, 1)
    if Ops.le(want, Ops.elem(xs_, 0))
      return Ops.mul((Ops.div(Ops.elem(ys_, 0), _A0)), scale)
    end
    if Ops.ge(want, Ops.elem(xs_, hi))
      return Ops.mul((Ops.div(Ops.elem(ys_, hi), _A0)), scale)
    end
    while Ops.gt(Ops.sub(hi, lo), 1)
      mid = Ops.m_floor((Ops.div((Ops.add(lo, hi)), 2)))
      if Ops.le(Ops.elem(xs_, mid), want)
        lo = mid
      else
        hi = mid
      end
    end
    t = Ops.div((Ops.sub(Ops.m_ln(want), Ops.m_ln(Ops.elem(xs_, lo)))), (Ops.sub(Ops.m_ln(Ops.elem(xs_, hi)), Ops.m_ln(Ops.elem(xs_, lo)))))
    return Ops.mul((Ops.div(Ops.m_exp((Ops.add(Ops.m_ln(Ops.elem(ys_, lo)), Ops.mul(t, (Ops.sub(Ops.m_ln(Ops.elem(ys_, hi)), Ops.m_ln(Ops.elem(ys_, lo)))))))), _A0)), scale)
  end
  __exposed
end

