  def self.bit(mask, at)
    return Ops.eq((Ops.mod(Ops.m_floor((Ops.div(mask, Ops.power(2, at)))), 2)), 1)
  end
  def self.tint_of(mask)
    if Ops.eq(mask, 0)
      return Galaxies.SEVERAL
    end
    r = 0
    g = 0
    bl = 0
    n = 0
    Galaxies.FREEDOMS.length.times do |i|
      if Galaxies.bit(mask, i)
        r = Ops.add(r, Ops.elem(Ops.elem(Galaxies.TINTS, i), 0))
        g = Ops.add(g, Ops.elem(Ops.elem(Galaxies.TINTS, i), 1))
        bl = Ops.add(bl, Ops.elem(Ops.elem(Galaxies.TINTS, i), 2))
        n = Ops.add(n, 1)
      end
    end
    return (Ops.gt(n, 0) ? [Ops.div(r, n), Ops.div(g, n), Ops.div(bl, n)] : Galaxies.SEVERAL)
  end
  def self.name_of(mask)
    if Ops.eq(mask, 0)
      return "the source as it starts"
    end
    parts = []
    Galaxies.NAMES_NOW.length.times do |i|
      if Galaxies.bit(mask, i)
        Ops.m_push(parts, Ops.elem(Galaxies.NAMES_NOW, i))
      end
    end
    joined = Ops.m_join(parts, " + ")
    return "needs #{joined}"
  end
  def self.rgb(c)
    r = Ops.m_round(Ops.elem(c, 0))
    g = Ops.m_round(Ops.elem(c, 1))
    bl = Ops.m_round(Ops.elem(c, 2))
    return "rgb(#{r},#{g},#{bl})"
  end
  def self.discs_at(lx)
    best = Float::NAN
    far = 0
    Ops.list(Sparc.discs).each do |d|
      x = Fmt.log10(Ops.div(Sparc.disc_arrival(d), Galaxies.A0_DATA))
      y = Fmt.log10(Ops.div(Sparc.disc_felt(d), Galaxies.A0_DATA))
      if (Fmt.finite(y) && ((!(Fmt.finite(best)) || Ops.lt(Ops.m_abs((Ops.sub(x, lx))), far))))
        best = y
        far = Ops.m_abs((Ops.sub(x, lx)))
      end
    end
    return best
  end
  def self.mass_text(level)
    if Ops.eq(level, 0)
      return "×1 mass"
    end
    if Ops.eq(level, 1)
      return "×10 mass"
    end
    return "×10^#{Fmt.fixed(level, 0)} mass"
  end
  def self.law_at(lx)
    a0 = Law.a0
    return Fmt.log10(Ops.div(Law.boost(Ops.mul(Ops.power(10, lx), a0), a0), a0))
  end
  def self.carries
    return Law.carries
  end
  def self.band_at(lx)
    return [Galaxies.law_at(lx), Galaxies.law_at(Ops.sub(lx, Galaxies.carries))]
  end
  def self.offsets(_YD)
    t = Sparc.curves
    _C = t.columns
    out = []
    _YB = (Ops.gt(Sparc.YD, 0) ? Ops.div(Ops.mul(_YD, Sparc.YB), Sparc.YD) : _YD)
    t.rows.times do |i|
      g = Ops.elem(Ops.getattr(_C, "galaxy"), i)
      _R = Ops.mul(Ops.elem(Ops.getattr(_C, "R"), i), Sparc.KPC)
      v = Ops.mul(Ops.elem(Ops.getattr(_C, "Vobs"), i), Sparc.KMS)
      if (((Sparc.usable(g) && Ops.gt(_R, 0)) && Ops.gt(v, 0)) && Ops.le(Ops.elem(Ops.getattr(_C, "e_Vobs"), i), Ops.mul(0.1, Ops.elem(Ops.getattr(_C, "Vobs"), i))))
        gas = Ops.mul(Ops.elem(Ops.getattr(_C, "Vgas"), i), Sparc.KMS)
        disk = Ops.mul(Ops.elem(Ops.getattr(_C, "Vdisk"), i), Sparc.KMS)
        bul = Ops.mul(Ops.elem(Ops.getattr(_C, "Vbul"), i), Sparc.KMS)
        gbar = Ops.div((Ops.add(Ops.add(Ops.mul(gas, Ops.m_abs(gas)), Ops.mul(Ops.mul(_YD, disk), Ops.m_abs(disk))), Ops.mul(Ops.mul(_YB, bul), Ops.m_abs(bul)))), _R)
        if Ops.gt(gbar, 0)
          Ops.m_push(out, Ops.sub(Fmt.log10(Ops.div(Ops.div(Ops.mul(v, v), _R), Galaxies.A0_DATA)), Galaxies.law_at(Fmt.log10(Ops.div(gbar, Galaxies.A0_DATA)))))
        end
      end
    end
    return out
  end
  def self.middle(xs)
    if Ops.m_empty(xs)
      return Float::NAN
    end
    sorted = Expr.sorted(xs)
    return Ops.elem(sorted, Ops.m_floor((Ops.div(sorted.length, 2))))
  end
  def self.asks
    lo = 0.05
    hi = 2
    30.times do |i|
      mid = Ops.div((Ops.add(lo, hi)), 2)
      if Ops.gt(Galaxies.middle(Galaxies.offsets(mid)), 0)
        lo = mid
      else
        hi = mid
      end
    end
    return Ops.div((Ops.add(lo, hi)), 2)
  end
  def self.medium_at(lx)
    m = Measured.of(Galaxies.MEDIUM_ID)
    if Ops.eq(m, nil)
      return Float::NAN
    end
    xs_ = Ops.getattr(m.columns, "gN")
    ys_ = Ops.getattr(m.columns, "g")
    a0 = Law.a0
    want = Ops.mul(Ops.power(10, lx), a0)
    n = m.rows
    if ((Ops.lt(n, 2) || Ops.lt(want, Ops.elem(xs_, 0))) || Ops.gt(want, Ops.elem(xs_, Ops.sub(n, 1))))
      return Float::NAN
    end
    lo = 0
    hi = Ops.sub(n, 1)
    while Ops.gt(Ops.sub(hi, lo), 1)
      mid = Ops.m_floor((Ops.div((Ops.add(lo, hi)), 2)))
      if Ops.le(Ops.elem(xs_, mid), want)
        lo = mid
      else
        hi = mid
      end
    end
    span = Ops.sub(Ops.elem(xs_, hi), Ops.elem(xs_, lo))
    f = (Ops.gt(span, 0) ? Ops.div((Ops.sub(want, Ops.elem(xs_, lo))), span) : 0)
    got = Ops.add(Ops.mul(Ops.elem(ys_, lo), (Ops.sub(1, f))), Ops.mul(Ops.elem(ys_, hi), f))
    return (Ops.gt(got, 0) ? Fmt.log10(Ops.div(got, a0)) : Float::NAN)
  end
  def self.along(s, at, t, text, colour, lift, leans)
    p0 = leans.(Ops.sub(t, 0.01))
    p1 = leans.(Ops.add(t, 0.01))
    c = at.(t)
    angle = Ops.m_atan2((Ops.sub(Ops.elem(p1, 1), Ops.elem(p0, 1))), Ops.sub(Ops.elem(p1, 0), Ops.elem(p0, 0)))
    s.save
    s.translate(Ops.elem(c, 0), Ops.elem(c, 1))
    s.rotate(angle)
    s.font("11px ui-monospace, monospace")
    s.text_align("center")
    s.text_baseline("alphabetic")
    w = s.measure(text)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(Ops.sub(Ops.sub(0, Ops.div(w, 2)), 4), Ops.sub(lift, 9), Ops.add(w, 8), 12)
    s.fill_style(colour)
    s.fill_text(text, 0, lift)
    s.restore
    return s.text_baseline("alphabetic")
  end
  def self.ceiling_of(data)
    x = Ops.getattr(data.columns, "x")
    y = Ops.getattr(data.columns, "y")
    p = Ops.getattr(data.columns, "p")
    grid = Ops.getattr(data.header, "grid")
    _XS = Ops.getattr(Ops.getattr(grid, "arrives"), "n")
    _YS = Ops.getattr(Ops.getattr(grid, "felt"), "n")
    from_x = Ops.getattr(Ops.getattr(grid, "arrives"), "from")
    dx = Ops.div((Ops.sub(Ops.getattr(Ops.getattr(grid, "arrives"), "to"), from_x)), (Ops.sub(_XS, 1)))
    top = Ops.filled(_XS, Float::NAN)
    _XS.times do |gx|
      gy = Ops.sub(_YS, 1)
      while Ops.ge(gy, 0)
        if Ops.gt(Ops.elem(p, Ops.add(Ops.mul(gy, _XS), gx)), 0)
          Ops.set_at(top, gx, Ops.elem(y, Ops.add(Ops.mul(gy, _XS), gx)))
          gy = (-1)
        else
          gy = Ops.sub(gy, 1)
        end
      end
    end
    return ->(lx, fallback) {
      gx = Ops.m_round((Ops.div((Ops.sub(lx, from_x)), dx)))
      if ((Ops.lt(gx, 0) || Ops.ge(gx, _XS)) || !(Fmt.finite(Ops.elem(top, gx))))
        return fallback
      end
      return Fmt.max(Ops.elem(top, gx), fallback)
    }
  end
  def self.possible_at(deg)
    got = Measured.of("galaxy.possible")
    if Ops.eq(got, nil)
      fail.("galaxy.possible is not on disk - run the galaxies (`#{Galaxies.SIMULATED}`) and try again")
    end
    ds = Ops.getattr(got.columns, "deg")
    k = 0
    got.rows.times do |i|
      if Ops.lt(Ops.m_abs((Ops.sub(Ops.elem(ds, i), deg))), Ops.m_abs((Ops.sub(Ops.elem(ds, k), deg))))
        k = i
      end
    end
    return Ops.elem(Ops.getattr(got.header, "bins"), k)
  end
  def self.panel(s, data, what, deg, support, possible)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    s.font("12px ui-monospace, monospace")
    a0 = Law.a0
    bx0 = 92
    bx1 = Ops.sub(s.width, 26)
    by0 = 82
    by1 = Ops.sub(s.height, 132)
    _XMIN = Galaxies.XMIN
    _XMAX = Galaxies.XMAX
    _YMIN = Galaxies.YMIN
    _YMAX = Galaxies.YMAX
    _X = ->(l) {
      return Ops.add(bx0, Ops.mul(Ops.div((Ops.sub(l, _XMIN)), (Ops.sub(_XMAX, _XMIN))), (Ops.sub(bx1, bx0))))
    }
    _Y = ->(l) {
      return Ops.sub(by1, Ops.mul(Ops.div((Ops.sub(l, _YMIN)), (Ops.sub(_YMAX, _YMIN))), (Ops.sub(by1, by0))))
    }
    Galaxies.NAMES_NOW = Galaxies.freedoms_of(data)
    shift = Galaxies.shift_at(data, deg)
    law_drawn = ->(t) {
      return Ops.add(Galaxies.law_at(Ops.sub(t, shift)), shift)
    }
    s.stroke_style(Galaxies.GRID)
    s.line_width(1)
    s.fill_style(Galaxies.FAINT)
    s.text_align("center")
    l = _XMIN
    while Ops.le(l, _XMAX)
      s.begin_path
      s.move_to(_X.(l), by0)
      s.line_to(_X.(l), by1)
      s.stroke
      s.fill_text("10^#{l}", _X.(l), Ops.add(by1, 17))
      l = Ops.add(l, 1)
    end
    s.text_align("right")
    l = _YMIN
    while Ops.le(l, _YMAX)
      s.begin_path
      s.move_to(bx0, _Y.(l))
      s.line_to(bx1, _Y.(l))
      s.stroke
      s.fill_text("10^#{l}", Ops.sub(bx0, 8), Ops.add(_Y.(l), 4))
      l = Ops.add(l, 1)
    end
    implied = []
    Ops.list(Sparc.btfr).each do |g|
      _M = g.mass
      v = Ops.mul(g.vf, 1000)
      if (Ops.gt(_M, 0) && Ops.gt(v, 0))
        Ops.m_push(implied, Fmt.log10(Ops.div(Ops.div(Ops.mul(Ops.mul(Ops.mul(v, v), v), v), (Ops.mul(Sparc.G_NEWTON, _M))), Galaxies.A0_DATA)))
      end
    end
    implied = Expr.sorted(implied)
    med = (Ops.m_empty(implied) ? Float::NAN : Ops.elem(implied, Ops.m_floor((Ops.div(implied.length, 2)))))
    s.line_width(1)
    Ops.list(implied).each do |o|
      s.gradient_stroke(_X.(_XMIN), _X.(0.2), ["rgba(205,92,92,0.62)", "rgba(205,92,92,0.40)", "rgba(205,92,92,0)"], [0, 0.62, 1])
      s.begin_path
      s.move_to(_X.(_XMIN), _Y.(Ops.mul(0.5, (Ops.add(_XMIN, o)))))
      s.line_to(_X.(0.2), _Y.(Ops.mul(0.5, (Ops.add(0.2, o)))))
      s.stroke
    end
    x = Ops.getattr(data.columns, "x")
    y = Ops.getattr(data.columns, "y")
    p = Ops.getattr(data.columns, "p")
    by = Ops.getattr(data.columns, "by")
    grid = Ops.getattr(data.header, "grid")
    most = 0
    Ops.list(p).each do |v|
      if (Fmt.finite(v) && Ops.gt(v, most))
        most = v
      end
    end
    if Ops.gt(most, 0)
      wpx = Ops.div(Ops.mul(Ops.div((Ops.sub(bx1, bx0)), (Ops.sub(Ops.getattr(Ops.getattr(grid, "arrives"), "n"), 1))), (Ops.sub(Ops.getattr(Ops.getattr(grid, "arrives"), "to"), Ops.getattr(Ops.getattr(grid, "arrives"), "from")))), (Ops.sub(_XMAX, _XMIN)))
      hpx = Ops.div(Ops.mul(Ops.div((Ops.sub(by1, by0)), (Ops.sub(Ops.getattr(Ops.getattr(grid, "felt"), "n"), 1))), (Ops.sub(Ops.getattr(Ops.getattr(grid, "felt"), "to"), Ops.getattr(Ops.getattr(grid, "felt"), "from")))), (Ops.sub(_YMAX, _YMIN)))
      live = []
      Ops.list(p).each do |v|
        if Ops.gt(v, 0)
          Ops.m_push(live, v)
        end
      end
      live = Ops.m_sorted_by(live, ->(v) {
        return v
      })
      rank = ->(v) {
        lo = 0
        hi = live.length
        while Ops.lt(lo, hi)
          mid = Ops.m_floor((Ops.div((Ops.add(lo, hi)), 2)))
          if Ops.lt(Ops.elem(live, mid), v)
            lo = Ops.add(mid, 1)
          else
            hi = mid
          end
        end
        return Ops.div(lo, live.length)
      }
      p.length.times do |i|
        if Ops.gt(Ops.elem(p, i), 0)
          t = rank.(Ops.elem(p, i))
          px = _X.(Ops.add(Ops.elem(x, i), shift))
          py = _Y.(Ops.add(Ops.elem(y, i), shift))
          unless (((Ops.lt(px, Ops.sub(bx0, wpx)) || Ops.gt(px, bx1)) || Ops.lt(py, by0)) || Ops.gt(py, Ops.add(by1, hpx)))
            tint = Galaxies.tint_of((Ops.eq(by, nil) ? 0 : Ops.m_round(Ops.elem(by, i))))
            k = Ops.add(0.60, Ops.mul(0.40, t))
            r = Ops.m_round((Ops.mul(Ops.elem(tint, 0), k)))
            g = Ops.m_round((Ops.mul(Ops.elem(tint, 1), k)))
            bl = Ops.m_round((Ops.mul(Ops.elem(tint, 2), k)))
            al = Fmt.fixed(Ops.add(0.38, Ops.mul(0.47, t)), 3)
            s.fill_style("rgba(#{r},#{g},#{bl},#{al})")
            s.fill_rect(Ops.sub(px, Ops.div(wpx, 2)), Ops.sub(py, Ops.div(hpx, 2)), Ops.add(wpx, 1), Ops.add(hpx, 1))
          end
        end
      end
    end
    _XS = Ops.getattr(Ops.getattr(grid, "arrives"), "n")
    _YS = Ops.getattr(Ops.getattr(grid, "felt"), "n")
    reach = ->(what, holds, ink, text_ink, text) {
      s.stroke_style(ink)
      s.begin_path
      started = false
      last_x = 0
      last_y = 0
      _XS.times do |gx|
        top = (-1)
        gy = Ops.sub(_YS, 1)
        while Ops.ge(gy, 0)
          if (Ops.gt(Ops.elem(p, Ops.add(Ops.mul(gy, _XS), gx)), 0) && holds.(Ops.elem(what, Ops.add(Ops.mul(gy, _XS), gx))))
            top = gy
            gy = (-1)
          else
            gy = Ops.sub(gy, 1)
          end
        end
        if Ops.ge(top, 0)
          px = _X.(Ops.add(Ops.elem(x, Ops.add(Ops.mul(top, _XS), gx)), shift))
          py = _Y.(Ops.add(Ops.elem(y, Ops.add(Ops.mul(top, _XS), gx)), shift))
          unless (((Ops.lt(px, bx0) || Ops.gt(px, bx1)) || Ops.lt(py, by0)) || Ops.gt(py, by1))
            if started
              s.line_to(px, py)
            else
              s.move_to(px, py)
            end
            started = true
            last_x = px
            last_y = py
          end
        end
      end
      s.stroke
      if started
        s.fill_style(text_ink)
        return s.fill_text(text, Ops.add(last_x, 4), Ops.add(last_y, 3))
      end
    }
    nds = Ops.getattr(data.columns, "needs")
    szs = Ops.getattr(data.columns, "size")
    s.line_width(1)
    s.font("9px ui-monospace, monospace")
    s.text_align("left")
    if !Ops.eq(nds, nil)
      Ops.list(Galaxies.LEVELS).each do |level|
        reach.(nds, ->(v) {
          return Ops.le(v, level)
        }, "rgba(238,240,245,0.30)", "rgba(238,240,245,0.45)", Galaxies.mass_text(level))
      end
    end
    if !Ops.eq(szs, nil)
      s.dash([4, 3])
      Ops.list(Galaxies.WIDTHS).each do |level|
        reach.(szs, ->(v) {
          return Ops.le(v, level)
        }, "rgba(139,233,253,0.35)", "rgba(139,233,253,0.55)", "#{Galaxies.mass_text(level)}, spread")
      end
      s.dash([])
    end
    s.dash([])
    s.font("12px ui-monospace, monospace")
    s.fill_style(Galaxies.POINTS)
    shown = 0
    Ops.list(Sparc.rar).each do |q|
      if (Ops.gt(q.gbar, 0) && Ops.gt(q.gobs, 0))
        px = _X.(Fmt.log10(Ops.div(q.gbar, Galaxies.A0_DATA)))
        py = _Y.(Fmt.log10(Ops.div(q.gobs, Galaxies.A0_DATA)))
        unless (((Ops.lt(px, bx0) || Ops.gt(px, bx1)) || Ops.lt(py, by0)) || Ops.gt(py, by1))
          s.fill_rect(Ops.sub(px, 0.7), Ops.sub(py, 0.7), 1.4, 1.4)
          shown = Ops.add(shown, 1)
        end
      end
    end
    galaxies = 0
    Ops.list(Sparc.flat).each do |q|
      px = _X.(Fmt.log10(Ops.div(q.gbar, Galaxies.A0_DATA)))
      py = _Y.(Fmt.log10(Ops.div(q.gobs, Galaxies.A0_DATA)))
      unless (((Ops.lt(px, bx0) || Ops.gt(px, bx1)) || Ops.lt(py, by0)) || Ops.gt(py, by1))
        s.begin_path
        s.arc(px, py, 2.6, 0, 7)
        s.fill_style(Galaxies.GALAXY)
        s.fill
        s.stroke_style("rgba(8,9,13,0.85)")
        s.line_width(0.9)
        s.stroke
        galaxies = Ops.add(galaxies, 1)
      end
    end
    s.stroke_style(Galaxies.NEWT)
    s.line_width(1.5)
    s.dash([6, 5])
    n0 = Fmt.max(_XMIN, _YMIN)
    n1 = Fmt.min(_XMAX, _YMAX)
    s.begin_path
    s.move_to(_X.(n0), _Y.(n0))
    s.line_to(_X.(n1), _Y.(n1))
    s.stroke
    s.dash([])
    s.stroke_style(Galaxies.BTFRC)
    s.line_width(1.5)
    s.dash([2, 4])
    s.begin_path
    l = _XMIN
    while Ops.le(l, Ops.add(_XMAX, 0.000001))
      if Ops.eq(l, _XMIN)
        s.move_to(_X.(l), _Y.(Ops.mul(0.5, l)))
      else
        s.line_to(_X.(l), _Y.(Ops.mul(0.5, l)))
      end
      l = Ops.add(l, 0.05)
    end
    s.stroke
    s.dash([])
    s.stroke_style(Galaxies.MODEL)
    s.line_width(1.2)
    s.alpha(0.4)
    s.dash([5, 4])
    s.begin_path
    l = _XMIN
    while Ops.le(l, Ops.add(_XMAX, 0.000001))
      if Ops.eq(l, _XMIN)
        s.move_to(_X.(l), _Y.(law_drawn.(l)))
      else
        s.line_to(_X.(l), _Y.(law_drawn.(l)))
      end
      l = Ops.add(l, 0.02)
    end
    s.stroke
    s.dash([])
    s.alpha(1)
    landed = Ops.elem(possible, 0)
    mid = Ops.elem(possible, 1)
    step = Simulation.BIN
    s.fill_style("rgba(74,168,235,0.35)")
    mid.length.times do |i|
      if Ops.gt(Ops.elem(landed, i), 0)
        px = _X.(Ops.add(Galaxies.XMIN, Ops.mul(i, step)))
        top_ = _Y.(Ops.elem(Ops.elem(possible, 3), i))
        low_ = _Y.(Ops.elem(Ops.elem(possible, 2), i))
        s.fill_rect(Ops.sub(px, 1.5), Ops.sub(top_, 1.5), 3, Ops.add(Ops.sub(low_, top_), 3))
      end
    end
    s.stroke_style(Galaxies.MODEL)
    s.line_width(3)
    s.begin_path
    started = false
    mid.length.times do |i|
      v = Ops.elem(mid, i)
      if (Ops.gt(Ops.elem(landed, i), 0) && Fmt.finite(v))
        px = _X.(Ops.add(Galaxies.XMIN, Ops.mul(i, step)))
        py = _Y.(v)
        if started
          s.line_to(px, py)
        else
          s.move_to(px, py)
        end
        started = true
      end
    end
    s.stroke
    Ops.list(Sparc.discs).each do |d|
      lx = Fmt.log10(Ops.div(Sparc.disc_arrival(d), Galaxies.A0_DATA))
      ly = Fmt.log10(Ops.div(Sparc.disc_felt(d), Galaxies.A0_DATA))
      s.fill_style(Galaxies.DISCC)
      s.begin_path
      s.arc(_X.(lx), _Y.(ly), 4, 0, 7)
      s.fill
      s.stroke_style(Galaxies.BACK)
      s.line_width(1.2)
      s.stroke
    end
    s.stroke_style("\#1b2130")
    s.line_width(1)
    s.stroke_rect(bx0, by0, Ops.sub(bx1, bx0), Ops.sub(by1, by0))
    s.text_align("left")
    s.fill_style(Galaxies.SEEN)
    s.font("13px ui-monospace, monospace")
    s.fill_text(what, bx0, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    a0_text = Fmt.exponential(Ops.mul(Galaxies.A0_DATA, Ops.power(10, shift)), 3)
    ratio_text = Fmt.fixed(Galaxies.ratio_at(data, deg), 4)
    deg_text = Fmt.fixed(deg, 1)
    inside_text = Fmt.fixed(Ops.mul(100, Galaxies.inside(data, support, shift)), 1)
    h0_text = Fmt.fixed(Galaxies.H0, 1)
    s.fill_text("DEG #{deg_text}: a₀ = #{ratio_text} cH₀ = #{a0_text} m/s² (H₀ #{h0_text}), data in 1.2e-10 — #{inside_text}% of SPARC inside the space", bx0, 41)
    vv = 0
    c2 = Ops.mul(Sparc.C_LIGHT, Sparc.C_LIGHT)
    Ops.list(Sparc.rar).each do |q|
      vv = Fmt.max(vv, Ops.div(Ops.mul(q.gobs, q.R), c2))
    end
    Ops.list(Sparc.discs).each do |d|
      vv = Fmt.max(vv, Ops.div(Ops.mul(Ops.mul(Sparc.disc_arrival(d), d.Re), Sparc.KPC), c2))
    end
    dex = Fmt.log10(Ops.add(1, vv))
    pxs = Ops.mul(Ops.div(dex, (Ops.sub(_XMAX, _XMIN))), (Ops.sub(bx1, bx0)))
    vv_text = Fmt.exponential(vv, 1)
    dex_text = Fmt.exponential(dex, 1)
    px_text = Fmt.exponential(pxs, 1)
    s.fill_text("GR is the same line: largest v²/c² here #{vv_text}, so at most #{dex_text} dex off the diagonal — #{px_text} px of a 1.5 px line", bx0, 55)
    diagonal = ->(t) {
      return [_X.(t), _Y.(t)]
    }
    Galaxies.along(s, diagonal, (-2.2), "Newton + GR", Galaxies.NEWT, (-9), diagonal)
    ceiling = Galaxies.ceiling_of(data)
    possible_line = ->(t) {
      i = Ops.m_round((Ops.div((Ops.sub(t, Galaxies.XMIN)), step)))
      return ((((Ops.ge(i, 0) && Ops.lt(i, mid.length)) && Ops.gt(Ops.elem(landed, i), 0)) && Fmt.finite(Ops.elem(mid, i))) ? Ops.elem(mid, i) : law_drawn.(t))
    }
    on_law = ->(t) {
      return [_X.(t), _Y.(possible_line.(t))]
    }
    on_top = ->(t) {
      return [_X.(t), _Y.(Ops.add(ceiling.(Ops.sub(t, shift), Ops.sub(law_drawn.(t), shift)), shift))]
    }
    Galaxies.along(s, on_top, (-1.15), "SPARC mass models", Galaxies.POINTS_LABEL, (-14), on_law)
    gs = Expr.sorted(Ops.m_map(Sparc.flat, ->(q) {
      return Fmt.log10(Ops.div(q.gbar, Galaxies.A0_DATA))
    }))
    Galaxies.along(s, on_law, Ops.elem(gs, Ops.m_floor((Ops.mul(gs.length, 0.25)))), "SPARC galaxy sample", Galaxies.GALAXY_LABEL, 34, on_law)
    offset = (Fmt.finite(med) ? med : 0)
    tully = ->(t) {
      return [_X.(t), _Y.(Ops.mul(0.5, (Ops.add(t, offset))))]
    }
    Galaxies.along(s, tully, (-3.05), "Tully–Fisher", Galaxies.BTFRC, (-9), tully)
    ds = Expr.sorted(Ops.m_map(Sparc.discs, ->(d) {
      return Fmt.log10(Ops.div(Sparc.disc_arrival(d), Galaxies.A0_DATA))
    }))
    on_discs = ->(t) {
      return [_X.(t), _Y.(Galaxies.discs_at(t))]
    }
    Galaxies.along(s, on_discs, Ops.elem(ds, Ops.m_floor((Ops.div(ds.length, 2)))), "Genzel high-z discs", Galaxies.DISCC, (-14), on_discs)
    Galaxies.along(s, on_law, (-3.3), "#{Law.theory}: every galaxy, run", Galaxies.MODEL, (-12), on_law)
    deep = ->(t) {
      return [_X.(t), _Y.(Ops.mul(0.5, t))]
    }
    Galaxies.along(s, deep, 2.0, "deep limit  g = √(g_N a₀)", Galaxies.BTFRC, 11, deep)
    tally = Node.new
    masks = []
    if !Ops.eq(by, nil)
      p.length.times do |i|
        if Ops.gt(Ops.elem(p, i), 0)
          m = Ops.m_round(Ops.elem(by, i))
          if Ops.eq(Ops.elem(tally, m), nil)
            Ops.set_at(tally, m, 0)
            Ops.m_push(masks, m)
          end
          Ops.set_at(tally, m, Ops.add(Ops.elem(tally, m), 1))
        end
      end
    end
    total = 0
    Ops.list(masks).each do |m|
      total = Ops.add(total, Ops.elem(tally, m))
    end
    if Ops.eq(total, 0)
      total = 1
    end
    counts = Expr.sorted(Ops.m_map(masks, ->(m) {
      return Ops.sub(0, Ops.elem(tally, m))
    }))
    ranked = []
    Ops.list(counts).each do |cn|
      Ops.list(masks).each do |m|
        if (Ops.eq(Ops.elem(tally, m), Ops.sub(0, cn)) && !(Ops.m_contains(ranked, m)))
          Ops.m_push(ranked, m)
        end
      end
    end
    singles = Ops.filt(ranked, ->(m) {
      return (Ops.eq(m, 0) || Galaxies.single(m))
    })
    rest = Ops.filt(ranked, ->(m) {
      return (!Ops.eq(m, 0) && !(Galaxies.single(m)))
    })
    shown_sets = Ops.m_concat(singles, rest)
    s.font("10px ui-monospace, monospace")
    s.text_align("left")
    lx = bx0
    s.fill_style(Galaxies.FAINT)
    intro = "coloured by the fewest freedoms that reach a cell:  "
    s.fill_text(intro, lx, Ops.sub(by0, 8))
    lx = Ops.add(lx, s.measure(intro))
    stop = false
    Ops.list(shown_sets).each do |mask|
      unless stop
        share = Ops.m_round((Ops.div(Ops.mul(100, Ops.elem(tally, mask)), total)))
        named = Ops.m_replace(Galaxies.name_of(mask), "needs ", "")
        label = "#{named} #{share}%"
        if Ops.gt(Ops.add(Ops.add(lx, s.measure(label)), 14), bx1)
          stop = true
        else
          s.fill_style(Galaxies.rgb(Galaxies.tint_of(mask)))
          s.fill_rect(lx, Ops.sub(by0, 16), 8, 8)
          lx = Ops.add(lx, 11)
          s.fill_text(label, lx, Ops.sub(by0, 8))
          lx = Ops.add(Ops.add(lx, s.measure(label)), 10)
        end
      end
    end
    rar_n = Sparc.rar.length
    names_n = Sparc.names.length
    cut = Ops.sub(names_n, Sparc.flat.length)
    btfr_n = implied.length
    med_sign = (Ops.ge(med, 0) ? "+" : "")
    med_fixed = Fmt.fixed(med, 2)
    med_text = (Fmt.finite(med) ? "#{med_sign}#{med_fixed}" : "—")
    key = [[Galaxies.POINTS, "SPARC mass models (Table2.mrt) — #{shown} of #{rar_n} in frame, one point per measured radius (borrowed)"], [Galaxies.GALAXY, "SPARC galaxy sample (Table1.mrt) — #{galaxies} of #{names_n}, each at its outermost radius (#{cut} cut, borrowed)"], [Galaxies.BTFRC, "Tully–Fisher (Lelli+2019): #{btfr_n} galaxies, one line each (a₀ = v_f⁴/GM), median #{med_text} dex from the theory's"], [Galaxies.DISCC, "Genzel high-z discs (borrowed)"]]
    ky = Ops.add(by1, 52)
    s.font("11px ui-monospace, monospace")
    Ops.list(key).each do |row|
      if Ops.le(ky, Ops.sub(s.height, 8))
        s.fill_style(Ops.elem(row, 0))
        s.fill_rect(bx0, Ops.sub(ky, 7), 9, 9)
        s.fill_style(Galaxies.FAINT)
        s.fill_text(Ops.elem(row, 1), Ops.add(bx0, 15), Ops.add(ky, 1))
        ky = Ops.add(ky, 15)
      end
    end
    s.fill_style(Galaxies.FAINT)
    s.text_align("center")
    s.fill_text("g_baryons / a₀", Ops.div((Ops.add(bx0, bx1)), 2), Ops.add(by1, 34))
    s.save
    s.translate(16, Ops.div((Ops.add(by0, by1)), 2))
    s.rotate(Ops.sub(0, Ops.div(Math::PI, 2)))
    s.fill_text("g_observed / a₀", 0, 0)
    s.restore
    return s.text_align("left")
  end
  def self.single(m)
    n = 0
    Galaxies.FREEDOMS.length.times do |i|
      if Galaxies.bit(m, i)
        n = Ops.add(n, 1)
      end
    end
    return Ops.eq(n, 1)
  end
  def self.ratio_at(data, deg)
    table = Ops.getattr(data.header, "coincidence")
    if Ops.eq(table, nil)
      fail.("the space carries no a_0/cH table - rerun it (record.gpu RAY_SPACE)")
    end
    ds = Ops.getattr(table, "deg")
    rs = Ops.getattr(table, "ratio")
    if Ops.le(deg, Ops.elem(ds, 0))
      return Ops.elem(rs, 0)
    end
    if Ops.ge(deg, Ops.elem(ds, Ops.sub(ds.length, 1)))
      return Ops.elem(rs, Ops.sub(ds.length, 1))
    end
    k = 0
    while Ops.lt(Ops.elem(ds, Ops.add(k, 1)), deg)
      k = Ops.add(k, 1)
    end
    f = Ops.div((Ops.sub(deg, Ops.elem(ds, k))), (Ops.sub(Ops.elem(ds, Ops.add(k, 1)), Ops.elem(ds, k))))
    return Ops.add(Ops.mul(Ops.elem(rs, k), (Ops.sub(1, f))), Ops.mul(Ops.elem(rs, Ops.add(k, 1)), f))
  end
  def self.shift_at(data, deg)
    _H = Ops.div(Ops.mul(Galaxies.H0, 1000), (Ops.mul(Sparc.KPC, 1000)))
    return Fmt.log10(Ops.div(Ops.mul(Ops.mul(Galaxies.ratio_at(data, deg), Sparc.C_LIGHT), _H), Galaxies.A0_DATA))
  end
  def self.frame_of(solved, k)
    grid = Ops.getattr(solved.header, "grid")
    _XS = Ops.getattr(Ops.getattr(grid, "arrives"), "n")
    _YS = Ops.getattr(Ops.getattr(grid, "felt"), "n")
    fx = Ops.getattr(Ops.getattr(grid, "arrives"), "from")
    fy = Ops.getattr(Ops.getattr(grid, "felt"), "from")
    dx = Ops.div((Ops.sub(Ops.getattr(Ops.getattr(grid, "arrives"), "to"), fx)), (Ops.sub(_XS, 1)))
    dy = Ops.div((Ops.sub(Ops.getattr(Ops.getattr(grid, "felt"), "to"), fy)), (Ops.sub(_YS, 1)))
    x = Ops.filled(Ops.mul(_XS, _YS), 0)
    y = Ops.filled(Ops.mul(_XS, _YS), 0)
    p = Ops.filled(Ops.mul(_XS, _YS), 0)
    by = Ops.filled(Ops.mul(_XS, _YS), 0)
    needs = Ops.filled(Ops.mul(_XS, _YS), Float::NAN)
    across = Ops.filled(Ops.mul(_XS, _YS), Float::NAN)
    _YS.times do |gy|
      _XS.times do |gx|
        Ops.set_at(x, Ops.add(Ops.mul(gy, _XS), gx), Ops.add(fx, Ops.mul(gx, dx)))
        Ops.set_at(y, Ops.add(Ops.mul(gy, _XS), gx), Ops.add(fy, Ops.mul(gy, dy)))
      end
    end
    cells = Ops.getattr(solved.columns, "cell")
    ps = Ops.getattr(solved.columns, "p")
    bys = Ops.getattr(solved.columns, "by")
    nds = Ops.getattr(solved.columns, "needs")
    szs = Ops.getattr(solved.columns, "size")
    starts = Ops.getattr(solved.header, "starts")
    stop = (Ops.lt(Ops.add(k, 1), starts.length) ? Ops.elem(starts, Ops.add(k, 1)) : solved.rows)
    i = Ops.elem(starts, k)
    while Ops.lt(i, stop)
      c = Ops.m_round(Ops.elem(cells, i))
      Ops.set_at(p, c, Ops.elem(ps, i))
      Ops.set_at(by, c, Ops.elem(bys, i))
      if !Ops.eq(nds, nil)
        Ops.set_at(needs, c, Ops.elem(nds, i))
      end
      if !Ops.eq(szs, nil)
        Ops.set_at(across, c, Ops.elem(szs, i))
      end
      i = Ops.add(i, 1)
    end
    header = Node.new
    Ops.setattr(header, "grid", grid)
    Ops.setattr(header, "coincidence", Ops.getattr(solved.header, "coincidence"))
    Ops.setattr(header, "rows", Ops.mul(_XS, _YS))
    columns = Node.new
    Ops.setattr(columns, "x", x)
    Ops.setattr(columns, "y", y)
    Ops.setattr(columns, "p", p)
    Ops.setattr(columns, "by", by)
    Ops.setattr(columns, "needs", needs)
    Ops.setattr(columns, "size", across)
    return Measured.new(header: header, columns: columns)
  end
  def self.support_at(solved, k)
    grid = Ops.getattr(solved.header, "grid")
    _XS = Ops.getattr(Ops.getattr(grid, "arrives"), "n")
    _YS = Ops.getattr(Ops.getattr(grid, "felt"), "n")
    out = Ops.filled(Ops.mul(_XS, _YS), 0)
    cells = Ops.getattr(solved.columns, "cell")
    starts = Ops.getattr(solved.header, "starts")
    stop = (Ops.lt(Ops.add(k, 1), starts.length) ? Ops.elem(starts, Ops.add(k, 1)) : solved.rows)
    i = Ops.elem(starts, k)
    while Ops.lt(i, stop)
      c = Ops.m_round(Ops.elem(cells, i))
      gx = Ops.mod(c, _XS)
      gy = Ops.div((Ops.sub(c, gx)), _XS)
      5.times do |j|
        5.times do |m|
          xx = Ops.sub(Ops.add(gx, m), 2)
          yy = Ops.sub(Ops.add(gy, j), 2)
          if (((Ops.ge(xx, 0) && Ops.ge(yy, 0)) && Ops.lt(xx, _XS)) && Ops.lt(yy, _YS))
            Ops.set_at(out, Ops.add(Ops.mul(yy, _XS), xx), 1)
          end
        end
      end
      i = Ops.add(i, 1)
    end
    return out
  end
  def self.inside(data, support, shift)
    grid = Ops.getattr(data.header, "grid")
    _XS = Ops.getattr(Ops.getattr(grid, "arrives"), "n")
    _YS = Ops.getattr(Ops.getattr(grid, "felt"), "n")
    fx = Ops.getattr(Ops.getattr(grid, "arrives"), "from")
    fy = Ops.getattr(Ops.getattr(grid, "felt"), "from")
    dx = Ops.div((Ops.sub(Ops.getattr(Ops.getattr(grid, "arrives"), "to"), fx)), (Ops.sub(_XS, 1)))
    dy = Ops.div((Ops.sub(Ops.getattr(Ops.getattr(grid, "felt"), "to"), fy)), (Ops.sub(_YS, 1)))
    n = 0
    hit = 0
    Ops.list(Sparc.rar).each do |q|
      if (Ops.gt(q.gbar, 0) && Ops.gt(q.gobs, 0))
        gx = Ops.m_round((Ops.div((Ops.sub(Ops.sub(Fmt.log10(Ops.div(q.gbar, Galaxies.A0_DATA)), shift), fx)), dx)))
        gy = Ops.m_round((Ops.div((Ops.sub(Ops.sub(Fmt.log10(Ops.div(q.gobs, Galaxies.A0_DATA)), shift), fy)), dy)))
        n = Ops.add(n, 1)
        if ((((Ops.ge(gx, 0) && Ops.ge(gy, 0)) && Ops.lt(gx, _XS)) && Ops.lt(gy, _YS)) && Ops.gt(Ops.elem(support, Ops.add(Ops.mul(gy, _XS), gx)), 0))
          hit = Ops.add(hit, 1)
        end
      end
    end
    return (Ops.gt(n, 0) ? Ops.div(hit, n) : 0)
  end
  def self.sweep_of(solved)
    ds = Ops.getattr(solved.header, "degs")
    n = ds.length
    home = Ops.or_else(Ops.getattr(solved.header, "theory_deg")) { 18 }
    rest = 0
    n.times do |k|
      if Ops.lt(Ops.m_abs((Ops.sub(Ops.elem(ds, k), home))), Ops.m_abs((Ops.sub(Ops.elem(ds, rest), home))))
        rest = k
      end
    end
    out = []
    n.times do |k|
      Ops.m_push(out, Ops.sub(Ops.sub(n, 1), k))
    end
    Galaxies.SETTLE.times do |k|
      f = Ops.div((Ops.add(k, 1)), Galaxies.SETTLE)
      Ops.m_push(out, Ops.m_round((Ops.mul(Ops.mul(Ops.mul(rest, f), f), (Ops.sub(3, Ops.mul(2, f)))))))
    end
    return out
  end
  def self.of(id, what, title)
    solved = Measured.of("#{id}.solved")
    if Ops.eq(solved, nil)
      fail.("#{id}.solved is not on disk - solve the space (record.gpu RAY_SOLVE) and try again")
    end
    ks = Galaxies.sweep_of(solved)
    return Picture.new(id: id, what: what, width: 960, height: 720, frames: ks.length, paint: ->(played) {
      return Sweeping.new(solved: solved, title: title, ks: ks)
    })
  end
  def self.a0_at(deg)
    space = Measured.of("galaxy.many.solved")
    if Ops.eq(space, nil)
      fail.("galaxy.many.solved is not on disk - solve the space (record.gpu RAY_SOLVE) and try again")
    end
    _H = Ops.div(Ops.mul(Galaxies.H0, 1000), (Ops.mul(Sparc.KPC, 1000)))
    return Ops.mul(Ops.mul(Galaxies.ratio_at(space, deg), Sparc.C_LIGHT), _H)
  end
  def self.curve_pick
    return Galaxies.pick(Ops.mul(Galaxies.CURVE_ROWS, Galaxies.CURVE_COLS))
  end
  def self.pick(want)
    t = Sparc.curves
    _C = t.columns
    counts = Node.new
    t.rows.times do |i|
      g = Ops.elem(Ops.getattr(_C, "galaxy"), i)
      if ((Sparc.usable(g) && Ops.gt(Ops.elem(Ops.getattr(_C, "R"), i), 0)) && Ops.gt(Ops.elem(Ops.getattr(_C, "Vobs"), i), 0))
        Ops.setattr(counts, "#{g}", Ops.add((Ops.or_else(Ops.getattr(counts, "#{g}")) { 0 }), 1))
      end
    end
    ids = []
    Sparc.names.length.times do |g|
      if Ops.ge((Ops.or_else(Ops.getattr(counts, "#{g}")) { 0 }), 12)
        Ops.m_push(ids, g)
      end
    end
    tops = Node.new
    t.rows.times do |i|
      g = Ops.elem(Ops.getattr(_C, "galaxy"), i)
      Ops.setattr(tops, "#{g}", Fmt.max(Ops.or_else(Ops.getattr(tops, "#{g}")) { 0 }, Ops.elem(Ops.getattr(_C, "Vobs"), i)))
    end
    sorted = Ops.m_sorted_by(ids, ->(g) {
      return Ops.getattr(tops, "#{g}")
    })
    out = []
    want.times do |k|
      Ops.m_push(out, Ops.elem(sorted, Ops.m_round((Ops.div(Ops.mul((Ops.sub(sorted.length, 1)), k), (Ops.sub(want, 1)))))))
    end
    return out
  end
  def self.simulated
    got = Measured.of("galaxy.simulated")
    if Ops.eq(got, nil)
      fail.("galaxy.simulated is not on disk - run the galaxies (`#{Galaxies.SIMULATED}`) and try again")
    end
    return got
  end
  def self.fields
    got = Measured.of("galaxy.fields")
    if Ops.eq(got, nil)
      fail.("galaxy.fields is not on disk - run the galaxies (`#{Galaxies.SIMULATED}`) and try again")
    end
    return got
  end
  def self.rows_in(m, g)
    col = Ops.getattr(m.columns, "galaxy")
    out = []
    m.rows.times do |i|
      if Ops.eq(Ops.elem(col, i), g)
        Ops.m_push(out, i)
      end
    end
    return out
  end
  def self.off_of(g, fitted)
    sim = Galaxies.simulated
    j = Ops.m_index_of(Ops.getattr(sim.header, "ids"), g)
    if Ops.eq(j, nil)
      return Float::NAN
    end
    return (fitted ? Ops.elem(Ops.getattr(sim.header, "rms1"), j) : Ops.elem(Ops.getattr(sim.header, "rms0"), j))
  end
  def self.percent(dex)
    return (Fmt.finite(dex) ? "#{Fmt.fixed(Ops.mul(100, (Ops.sub(Ops.power(10, dex), 1))), 0)}%" : "—")
  end
  def self.curve_box(s, g, bx0, by0, bx1, by1)
    sim = Galaxies.simulated
    fld = Galaxies.fields
    _S = sim.columns
    _F = fld.columns
    rows = Galaxies.rows_in(sim, g)
    tab = Galaxies.rows_in(fld, g)
    top = 0
    reach = 0
    Ops.list(rows).each do |i|
      top = Fmt.max(top, Ops.add(Ops.elem(Ops.getattr(_S, "Vobs"), i), Ops.elem(Ops.getattr(_S, "e_Vobs"), i)))
      reach = Fmt.max(reach, Ops.elem(Ops.getattr(_S, "R"), i))
    end
    top = Ops.mul(top, 1.15)
    reach = Ops.mul(reach, 1.05)
    _X = ->(r) {
      return Ops.add(bx0, Ops.mul(Ops.div(r, reach), (Ops.sub(bx1, bx0))))
    }
    _Y = ->(v) {
      return Ops.sub(by1, Ops.mul(Ops.div(v, top), (Ops.sub(by1, by0))))
    }
    s.stroke_style(Galaxies.GRID)
    s.line_width(1)
    s.stroke_rect(bx0, by0, Ops.sub(bx1, bx0), Ops.sub(by1, by0))
    line = ->(column) {
      s.begin_path
      started = false
      Ops.list(tab).each do |i|
        r = Ops.elem(Ops.getattr(_F, "r"), i)
        v = Ops.elem(Ops.elem(_F, column), i)
        if (Ops.le(r, reach) && Fmt.finite(v))
          if started
            s.line_to(_X.(r), _Y.(Fmt.min(v, top)))
          else
            s.move_to(_X.(r), _Y.(Fmt.min(v, top)))
          end
          started = true
        end
      end
      return s.stroke
    }
    s.stroke_style(Galaxies.NEWT)
    s.line_width(1)
    s.dash([5, 4])
    line.("vN")
    s.dash([3, 3])
    s.stroke_style(Galaxies.FITTED)
    line.("v1")
    s.dash([])
    s.stroke_style(Galaxies.MODEL)
    s.line_width(2)
    line.("v0")
    s.stroke_style(Galaxies.MODEL)
    s.line_width(1)
    Ops.list(rows).each do |i|
      v = Ops.elem(Ops.getattr(_S, "vs"), i)
      if Fmt.finite(v)
        s.begin_path
        s.arc(_X.(Ops.elem(Ops.getattr(_S, "R"), i)), _Y.(Fmt.min(v, top)), 2.4, 0, 7)
        s.stroke
      end
    end
    s.stroke_style(Galaxies.POINTS)
    s.fill_style(Galaxies.POINTS)
    Ops.list(rows).each do |i|
      px = _X.(Ops.elem(Ops.getattr(_S, "R"), i))
      s.begin_path
      s.move_to(px, _Y.(Ops.sub(Ops.elem(Ops.getattr(_S, "Vobs"), i), Ops.elem(Ops.getattr(_S, "e_Vobs"), i))))
      s.line_to(px, _Y.(Fmt.min(Ops.add(Ops.elem(Ops.getattr(_S, "Vobs"), i), Ops.elem(Ops.getattr(_S, "e_Vobs"), i)), top)))
      s.stroke
      s.fill_rect(Ops.sub(px, 1.4), Ops.sub(_Y.(Ops.elem(Ops.getattr(_S, "Vobs"), i)), 1.4), 2.8, 2.8)
    end
    s.font("10px ui-monospace, monospace")
    s.text_align("left")
    s.fill_style(Galaxies.SEEN)
    s.fill_text("#{Ops.elem(Sparc.names, g)}", Ops.add(bx0, 4), Ops.add(by0, 12))
    off0 = Galaxies.percent(Galaxies.off_of(g, false))
    off1 = Galaxies.percent(Galaxies.off_of(g, true))
    s.fill_style(Galaxies.MODEL)
    s.fill_text("#{off0} off", Ops.add(bx0, 4), Ops.add(by0, 24))
    s.fill_style(Galaxies.FITTED)
    s.fill_text("#{off1} fitted", Ops.add(Ops.add(bx0, 4), s.measure("#{off0} off  ")), Ops.add(by0, 24))
    s.fill_style(Galaxies.FAINT)
    s.fill_text("#{Fmt.fixed(top, 0)}", Ops.sub(bx0, 32), Ops.add(by0, 8))
    s.fill_text("0", Ops.sub(bx0, 32), by1)
    s.text_align("right")
    s.fill_text("#{Fmt.fixed(reach, 0)} kpc", bx1, Ops.add(by1, 14))
    return s.text_align("left")
  end
  def self.curve_key(s, y)
    s.font("11px ui-monospace, monospace")
    s.text_align("left")
    s.fill_style(Galaxies.POINTS)
    s.fill_text("■ measured (SPARC, borrowed)", 22, y)
    s.fill_style(Galaxies.MODEL)
    s.fill_text("— run, SPARC's own Υ, D, i   ○ its tracers", 232, y)
    s.fill_style(Galaxies.FITTED)
    s.fill_text("-- run, the data's freedoms fitted", 560, y)
    s.fill_style(Galaxies.NEWT)
    return s.fill_text("-- Newton", 820, y)
  end
  def self.sample_off(fitted)
    _S = Galaxies.simulated.columns
    n = Galaxies.simulated.rows
    s = 0
    m = 0
    n.times do |i|
      v = (fitted ? Ops.elem(Ops.getattr(_S, "v1"), i) : Ops.elem(Ops.getattr(_S, "v0"), i))
      if (Ops.gt(Ops.elem(Ops.getattr(_S, "kept"), i), 0) && Ops.gt(v, 0))
        d = Fmt.log10(Ops.div(v, Ops.elem(Ops.getattr(_S, "Vobs"), i)))
        s = Ops.add(s, Ops.mul(d, d))
        m = Ops.add(m, 1)
      end
    end
    return (Ops.gt(m, 0) ? Ops.m_sqrt((Ops.div(s, m))) : Float::NAN)
  end
  def self.curves_panel(s)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    sim = Galaxies.simulated
    picked = Galaxies.curve_pick
    s.font("13px ui-monospace, monospace")
    s.fill_style(Galaxies.SEEN)
    s.text_align("left")
    s.fill_text("ROTATION CURVES, EACH GALAXY RUN", 22, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    a0_text = Fmt.exponential(Ops.getattr(sim.header, "a0"), 3)
    deg_text = Fmt.fixed(Ops.getattr(sim.header, "deg"), 1)
    whole0 = Galaxies.percent(Galaxies.sample_off(false))
    whole1 = Galaxies.percent(Galaxies.sample_off(true))
    s.fill_text("each laid from its own gas, disc and bulge and run; a₀ #{a0_text} m/s² (DEG #{deg_text}); all #{whole0} off, #{whole1} with Υ, D, i fitted", 22, 44)
    _W = Ops.div((Ops.sub(s.width, 44)), Galaxies.CURVE_COLS)
    _H = Ops.div((Ops.sub(s.height, 96)), Galaxies.CURVE_ROWS)
    picked.length.times do |k|
      col = Ops.mod(k, Galaxies.CURVE_COLS)
      row = Ops.m_round((Ops.div((Ops.sub(k, col)), Galaxies.CURVE_COLS)))
      ox = Ops.add(22, Ops.mul(col, _W))
      oy = Ops.add(62, Ops.mul(row, _H))
      Galaxies.curve_box(s, Ops.elem(picked, k), Ops.add(ox, 34), Ops.add(oy, 16), Ops.sub(Ops.add(ox, _W), 10), Ops.sub(Ops.add(oy, _H), 26))
    end
    return Galaxies.curve_key(s, Ops.sub(s.height, 16))
  end
  def self.curves
    return Picture.still("galaxy.curves", "the rotation curves themselves: twelve galaxies across the sample, each laid from its own gas, disc and bulge and run - the speed a circle needs on its field, what its tracers moved at, and the same with the data's own freedoms fitted, against what was measured", 960, 720, ->(s) {
      return Galaxies.curves_panel(s)
    })
  end
  def self.simulation
    stars = Measured.of("galaxy.stars")
    if Ops.eq(stars, nil)
      fail.("galaxy.stars is not on disk - run the galaxies (`#{Galaxies.SIMULATED}`) and try again")
    end
    return Picture.new(id: "galaxy.simulation", what: "galaxies run: each laid from its own gas, disc and bulge, its tracers followed on the field the model gives it, and beside it the curve they trace against what was measured", width: 960, height: 720, frames: Ops.getattr(stars.header, "frames"), paint: ->(played) {
      return Orbiting.new(stars: stars)
    })
  end
  def self.orbit_panel(s, stars, frame_at)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    film = Ops.getattr(stars.header, "film")
    _NS = Ops.getattr(stars.header, "stars")
    _FR = Ops.getattr(stars.header, "frames")
    _X_ = Ops.getattr(stars.columns, "x")
    _Y_ = Ops.getattr(stars.columns, "y")
    sim = Galaxies.simulated
    s.font("13px ui-monospace, monospace")
    s.fill_style(Galaxies.SEEN)
    s.text_align("left")
    s.fill_text("GALAXIES, RUN", 22, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    a0_text = Fmt.exponential(Ops.getattr(sim.header, "a0"), 3)
    deg_text = Fmt.fixed(Ops.getattr(sim.header, "deg"), 1)
    s.fill_text("laid from the gas, disc and bulge SPARC measured; every tracer pulled at what is felt where it is (a₀ #{a0_text} m/s², DEG #{deg_text})", 22, 44)
    rows = Ops.add(Ops.m_floor((Ops.div(film.length, 2))), Ops.mod(film.length, 2))
    _H = Ops.div((Ops.sub(s.height, 96)), Fmt.max(rows, 1))
    _W = Ops.div((Ops.sub(s.width, 44)), 2)
    film.length.times do |k|
      g = Ops.elem(film, k)
      col = Ops.mod(k, 2)
      row = Ops.m_round((Ops.div((Ops.sub(k, col)), 2)))
      ox = Ops.add(22, Ops.mul(col, _W))
      oy = Ops.add(58, Ops.mul(row, _H))
      side = Fmt.min(Ops.sub(_H, 20), Ops.mul(_W, 0.48))
      cx = Ops.add(Ops.add(ox, Ops.div(side, 2)), 4)
      cy = Ops.add(Ops.add(oy, Ops.div(side, 2)), 6)
      reach = Ops.elem(Ops.getattr(stars.header, "reach"), k)
      scale = Ops.div(Ops.div(side, 2), reach)
      s.stroke_style(Galaxies.GRID)
      s.line_width(1)
      s.stroke_rect(Ops.sub(cx, Ops.div(side, 2)), Ops.sub(cy, Ops.div(side, 2)), side, side)
      _NS.times do |q|
        at = Ops.add(Ops.mul((Ops.add(Ops.mul(k, _NS), q)), _FR), Fmt.min(frame_at, Ops.sub(_FR, 1)))
        x = Ops.elem(_X_, at)
        y = Ops.elem(_Y_, at)
        r = Ops.div(Fmt.hypot(x, y), reach)
        if (Fmt.finite(x) && Ops.lt(r, 1.4))
          warm = Fmt.min(1, r)
          red = Ops.m_round((Ops.add(120, Ops.mul(120, (Ops.sub(1, warm))))))
          green = Ops.m_round((Ops.add(170, Ops.mul(50, (Ops.sub(1, warm))))))
          s.fill_style("rgba(#{red},#{green},245,0.55)")
          px = Ops.add(cx, Ops.mul(x, scale))
          py = Ops.sub(cy, Ops.mul(y, scale))
          if (((Ops.gt(px, Ops.sub(cx, Ops.div(side, 2))) && Ops.lt(px, Ops.add(cx, Ops.div(side, 2)))) && Ops.gt(py, Ops.sub(cy, Ops.div(side, 2)))) && Ops.lt(py, Ops.add(cy, Ops.div(side, 2))))
            s.fill_rect(Ops.sub(px, 0.6), Ops.sub(py, 0.6), 1.2, 1.2)
          end
        end
      end
      s.fill_style(Galaxies.FAINT)
      s.font("10px ui-monospace, monospace")
      across = Fmt.fixed(Ops.mul(2, reach), 0)
      s.fill_text("#{across} kpc across", Ops.add(Ops.sub(cx, Ops.div(side, 2)), 4), Ops.sub(Ops.add(cy, Ops.div(side, 2)), 6))
      span = Ops.getattr(stars.header, "span")
      source = Ops.getattr(stars.header, "source")
      if !Ops.eq(span, nil)
        myr = Fmt.fixed(Ops.div(Ops.mul(Ops.elem(span, k), Fmt.min(frame_at, Ops.sub(_FR, 1))), Ops.sub(_FR, 1)), 0)
        s.fill_text("#{Ops.elem(source, k)}, +#{myr} Myr", Ops.add(Ops.sub(cx, Ops.div(side, 2)), 4), Ops.add(Ops.sub(cy, Ops.div(side, 2)), 12))
      end
      Galaxies.curve_box(s, g, Ops.add(Ops.add(cx, Ops.div(side, 2)), 40), Ops.add(oy, 12), Ops.sub(Ops.add(ox, _W), 12), Ops.add(oy, side))
    end
    return Galaxies.curve_key(s, Ops.sub(s.height, 16))
  end
  def self.formed
    got = Measured.of("galaxy.formed")
    if Ops.eq(got, nil)
      fail.("galaxy.formed is not on disk - run the galaxies (`#{Galaxies.SIMULATED}`) and try again")
    end
    return Picture.new(id: "galaxy.formed", what: "discs of stars left to themselves: every star pulled by every other through the law, nothing else holding them - smooth at the start, then whatever forms", width: 960, height: 720, frames: Ops.getattr(got.header, "frames"), paint: ->(played) {
      return Forming.new(formed: got)
    })
  end
  def self.medium
    got = Measured.of("galaxy.medium")
    if Ops.eq(got, nil)
      fail.("galaxy.medium is not on disk - run it (deno run --unstable-webgpu --allow-all implementation/ray/bootstrap/galaxy.gpu.ts . with RAY_ONLY=medium-galaxy) and try again")
    end
    return Picture.new(id: "galaxy.medium", what: "a disc of stars in the medium itself, every star its own body and every step local: launched circling at what the medium pulls it with, then left to the medium - whatever forms", width: 960, height: 900, frames: Ops.getattr(got.header, "frames"), paint: ->(played) {
      return HeldDisc.new(formed: got)
    })
