  def self.medium_panel(s, formed, frame_at)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    _H = formed.header
    _G = Ops.getattr(_H, "grid")
    _FR = Ops.getattr(_H, "frames")
    f = Fmt.min(frame_at, Ops.sub(_FR, 1))
    _D = Ops.getattr(formed.columns, "density")
    s.font("13px ui-monospace, monospace")
    s.fill_style(Galaxies.SEEN)
    s.text_align("left")
    s.fill_text("A GALAXY IN THE MEDIUM, EVERY STAR ITS OWN", 22, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    stars_n = Ops.getattr(_H, "stars")
    tick = Ops.elem(Ops.getattr(_H, "ticks"), f)
    deg = Ops.getattr(_H, "deg")
    side_n = Ops.getattr(_H, "side")
    s.fill_text("#{stars_n} stars, each its own body, held where the rays are - every step local, nothing but the medium (DEG #{deg}, a #{side_n}-cell box) - tick #{tick}", 22, 44)
    side = Fmt.min(Ops.sub(s.width, 44), Ops.sub(s.height, 230))
    ox = Ops.div((Ops.sub(s.width, side)), 2)
    oy = 60
    base = Ops.mul(Ops.mul(f, _G), _G)
    top = 0
    Ops.mul(_G, _G).times do |c|
      top = Fmt.max(top, Ops.elem(_D, Ops.add(base, c)))
    end
    cell = Ops.div(side, _G)
    _G.times do |cy|
      _G.times do |cx|
        v = Ops.elem(_D, Ops.add(Ops.add(base, Ops.mul(cy, _G)), cx))
        if Ops.gt(v, 0)
          t = Fmt.min(1, Ops.div(Ops.m_ln((Ops.add(1, v))), Ops.m_ln((Ops.add(1, top)))))
          r = Ops.m_round((Ops.add(40, Ops.mul(Ops.mul(215, t), t))))
          gr = Ops.m_round((Ops.add(60, Ops.mul(190, t))))
          b = Ops.m_round((Ops.add(110, Ops.mul(145, Fmt.min(1, Ops.mul(1.6, t))))))
          s.fill_style("rgb(#{r},#{gr},#{b})")
          s.fill_rect(Ops.add(ox, Ops.mul(cx, cell)), Ops.add(oy, Ops.mul((Ops.sub(Ops.sub(_G, 1), cy)), cell)), Ops.add(cell, 0.5), Ops.add(cell, 0.5))
        end
      end
    end
    s.stroke_style(Galaxies.GRID)
    s.stroke_rect(ox, oy, side, side)
    rd = Fmt.fixed(Ops.elem(Ops.getattr(_H, "scale"), 0), 1)
    across = Fmt.fixed(Ops.mul(2, Ops.elem(Ops.getattr(_H, "span"), 0)), 0)
    speed = Fmt.fixed(Ops.getattr(_H, "speed"), 4)
    s.fill_style(Galaxies.SEEN)
    s.fill_text("R_d #{rd} c-bar, #{across} c-bar across; circling at R_d #{speed} c-bar a tick", ox, Ops.add(Ops.add(oy, side), 18))
    series = Galaxies.arms_of(formed, 0)
    sx0 = ox
    sx1 = Ops.add(ox, side)
    sy0 = Ops.add(Ops.add(oy, side), 46)
    sy1 = Ops.add(Ops.add(oy, side), 136)
    topA = 0.6
    s.stroke_style(Galaxies.GRID)
    s.stroke_rect(sx0, sy0, Ops.sub(sx1, sx0), Ops.sub(sy1, sy0))
    inks = ["\#4aa8eb", "\#f2e05a", "\#eb964a"]
    3.times do |k|
      s.stroke_style(Ops.elem(inks, k))
      s.line_width(1.5)
      s.begin_path
      Ops.add(f, 1).times do |j|
        px = Ops.add(sx0, Ops.div(Ops.mul((Ops.sub(sx1, sx0)), j), Ops.sub(_FR, 1)))
        py = Ops.sub(sy1, Ops.mul((Ops.sub(sy1, sy0)), Fmt.min(Ops.div(Ops.elem(Ops.elem(series, j), Ops.add(k, 2)), topA), 1)))
        if Ops.eq(j, 0)
          s.move_to(px, py)
        else
          s.line_to(px, py)
        end
      end
      s.stroke
    end
    s.line_width(1)
    s.font("10px ui-monospace, monospace")
    now = Ops.elem(series, f)
    a2 = Fmt.fixed(Ops.elem(now, 2), 3)
    a3 = Fmt.fixed(Ops.elem(now, 3), 3)
    a4 = Fmt.fixed(Ops.elem(now, 4), 3)
    s.fill_style(Ops.elem(inks, 0))
    s.fill_text("m=2 #{a2}", sx0, Ops.sub(sy0, 4))
    s.fill_style(Ops.elem(inks, 1))
    s.fill_text("m=3 #{a3}", Ops.add(sx0, 90), Ops.sub(sy0, 4))
    s.fill_style(Ops.elem(inks, 2))
    s.fill_text("m=4 #{a4}", Ops.add(sx0, 176), Ops.sub(sy0, 4))
    s.fill_style(Galaxies.FAINT)
    s.fill_text("arm strength, 1-3 R_d, 0 to 0.6 (smooth ≈ 1/sqrt of the stars)", sx0, Ops.add(sy1, 14))
    return s.font("11px ui-monospace, monospace")
  end
  def self.formed_panel(s, formed, frame_at)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    _H = formed.header
    _G = Ops.getattr(_H, "grid")
    _FR = Ops.getattr(_H, "frames")
    f = Fmt.min(frame_at, Ops.sub(_FR, 1))
    _D = Ops.getattr(formed.columns, "density")
    names = Ops.getattr(_H, "names")
    s.font("13px ui-monospace, monospace")
    s.fill_style(Galaxies.SEEN)
    s.text_align("left")
    s.fill_text("GALAXIES LEFT TO THEMSELVES", 22, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    gyr = Fmt.fixed(Ops.div(Ops.mul(Ops.getattr(_H, "gyr"), f), Ops.sub(_FR, 1)), 2)
    stars_n = Ops.getattr(_H, "stars")
    q_text = Fmt.fixed(Ops.getattr(_H, "Q"), 1)
    a0_text = Fmt.exponential(Ops.getattr(_H, "a0"), 3)
    s.fill_text("#{stars_n} stars each, every one pulled by every other through the law (a₀ #{a0_text} m/s²), no halo; launched smooth at Q #{q_text} — t = #{gyr} Gyr", 22, 44)
    side = Fmt.min(Ops.div((Ops.sub(s.width, 66)), 2), Ops.sub(s.height, 110))
    names.length.times do |g|
      ox = Ops.add(22, Ops.mul(g, (Ops.add(side, 22))))
      oy = 60
      base = Ops.mul(Ops.mul((Ops.add(Ops.mul(g, _FR), f)), _G), _G)
      top = 0
      Ops.mul(_G, _G).times do |c|
        top = Fmt.max(top, Ops.elem(_D, Ops.add(base, c)))
      end
      cell = Ops.div(side, _G)
      _G.times do |cy|
        _G.times do |cx|
          v = Ops.elem(_D, Ops.add(Ops.add(base, Ops.mul(cy, _G)), cx))
          if Ops.gt(v, 0)
            t = Fmt.min(1, Ops.div(Ops.m_ln((Ops.add(1, v))), Ops.m_ln((Ops.add(1, top)))))
            r = Ops.m_round((Ops.add(40, Ops.mul(Ops.mul(215, t), t))))
            gr = Ops.m_round((Ops.add(60, Ops.mul(190, t))))
            b = Ops.m_round((Ops.add(110, Ops.mul(145, Fmt.min(1, Ops.mul(1.6, t))))))
            s.fill_style("rgb(#{r},#{gr},#{b})")
            s.fill_rect(Ops.add(ox, Ops.mul(cx, cell)), Ops.add(oy, Ops.mul((Ops.sub(Ops.sub(_G, 1), cy)), cell)), Ops.add(cell, 0.5), Ops.add(cell, 0.5))
          end
        end
      end
      s.stroke_style(Galaxies.GRID)
      s.stroke_rect(ox, oy, side, side)
      mass = Fmt.exponential(Ops.elem(Ops.getattr(_H, "mass"), g), 1)
      rd = Fmt.fixed(Ops.elem(Ops.getattr(_H, "scale"), g), 1)
      across = Fmt.fixed(Ops.mul(2, Ops.elem(Ops.getattr(_H, "span"), g)), 0)
      s.fill_style(Galaxies.SEEN)
      s.fill_text("#{Ops.elem(names, g)}: #{mass} suns, R_d #{rd} kpc", ox, Ops.add(Ops.add(oy, side), 18))
      s.fill_style(Galaxies.FAINT)
      mids = Ops.getattr(_H, "middles")
      moved = ""
      if !Ops.eq(mids, nil)
        m = Ops.elem(Ops.elem(mids, f), g)
        gone = Fmt.fixed(Fmt.hypot(Ops.elem(m, 0), Ops.elem(m, 1)), 1)
        speed = Fmt.fixed(Fmt.hypot(Ops.elem(m, 2), Ops.elem(m, 3)), 1)
        moved = "; followed - moved #{gone} kpc, going #{speed} km/s"
      end
      s.fill_text("#{across} kpc across#{moved}", ox, Ops.add(Ops.add(oy, side), 34))
      series = Galaxies.arms_of(formed, g)
      sx0 = ox
      sx1 = Ops.add(ox, side)
      sy0 = Ops.add(Ops.add(oy, side), 58)
      sy1 = Ops.add(Ops.add(oy, side), 148)
      topA = 0.6
      s.stroke_style(Galaxies.GRID)
      s.stroke_rect(sx0, sy0, Ops.sub(sx1, sx0), Ops.sub(sy1, sy0))
      inks = ["\#4aa8eb", "\#f2e05a", "\#eb964a"]
      3.times do |k|
        s.stroke_style(Ops.elem(inks, k))
        s.line_width(1.5)
        s.begin_path
        Ops.add(f, 1).times do |j|
          px = Ops.add(sx0, Ops.div(Ops.mul((Ops.sub(sx1, sx0)), j), Ops.sub(_FR, 1)))
          py = Ops.sub(sy1, Ops.mul((Ops.sub(sy1, sy0)), Fmt.min(Ops.div(Ops.elem(Ops.elem(series, j), Ops.add(k, 2)), topA), 1)))
          if Ops.eq(j, 0)
            s.move_to(px, py)
          else
            s.line_to(px, py)
          end
        end
        s.stroke
      end
      s.line_width(1)
      s.font("10px ui-monospace, monospace")
      now = Ops.elem(series, f)
      a2 = Fmt.fixed(Ops.elem(now, 2), 3)
      a3 = Fmt.fixed(Ops.elem(now, 3), 3)
      a4 = Fmt.fixed(Ops.elem(now, 4), 3)
      s.fill_style(Ops.elem(inks, 0))
      s.fill_text("m=2 #{a2}", sx0, Ops.sub(sy0, 4))
      s.fill_style(Ops.elem(inks, 1))
      s.fill_text("m=3 #{a3}", Ops.add(sx0, 90), Ops.sub(sy0, 4))
      s.fill_style(Ops.elem(inks, 2))
      s.fill_text("m=4 #{a4}", Ops.add(sx0, 176), Ops.sub(sy0, 4))
      s.fill_style(Galaxies.FAINT)
      s.text_align("left")
      s.fill_text("arm strength, 1-3 R_d, 0 to 0.6 (smooth ≈ 0.01)", sx0, Ops.add(sy1, 14))
      s.text_align("left")
      s.font("11px ui-monospace, monospace")
    end
  end
  def self.arms_of(formed, g)
    _H = formed.header
    about = Ops.getattr(_H, "about")
    key = "#{g}:#{about}"
    if !Ops.eq(Ops.elem(Galaxies.ARMS, key), nil)
      return Ops.elem(Galaxies.ARMS, key)
    end
    _G = Ops.getattr(_H, "grid")
    _FR = Ops.getattr(_H, "frames")
    _D = Ops.getattr(formed.columns, "density")
    per_scale = Ops.div(_G, (Ops.div(Ops.mul(2, Ops.elem(Ops.getattr(_H, "span"), g)), Ops.elem(Ops.getattr(_H, "scale"), g))))
    out = Ops.m_map(Ops.rng(_FR), ->(f) {
      base = Ops.mul(Ops.mul((Ops.add(Ops.mul(g, _FR), f)), _G), _G)
      w = 0
      mx = 0
      my = 0
      _G.times do |cy|
        _G.times do |cx|
          v = Ops.elem(_D, Ops.add(Ops.add(base, Ops.mul(cy, _G)), cx))
          w = Ops.add(w, Ops.mul(v, v))
          mx = Ops.add(mx, Ops.mul(Ops.mul(v, v), cx))
          my = Ops.add(my, Ops.mul(Ops.mul(v, v), cy))
        end
      end
      mx = (Ops.gt(w, 0) ? Ops.div(mx, w) : Ops.div(_G, 2))
      my = (Ops.gt(w, 0) ? Ops.div(my, w) : Ops.div(_G, 2))
      re = [0, 0, 0, 0, 0]
      im = [0, 0, 0, 0, 0]
      total = 0
      _G.times do |cy|
        _G.times do |cx|
          v = Ops.elem(_D, Ops.add(Ops.add(base, Ops.mul(cy, _G)), cx))
          dx = Ops.sub(Ops.add(cx, 0.5), mx)
          dy = Ops.sub(Ops.add(cy, 0.5), my)
          r = Ops.div(Fmt.hypot(dx, dy), per_scale)
          if ((Ops.gt(v, 0) && Ops.ge(r, 1)) && Ops.le(r, 3))
            th = Ops.m_atan2(dy, dx)
            total = Ops.add(total, v)
            5.times do |m|
              Ops.set_at(re, m, Ops.add(Ops.elem(re, m), Ops.mul(v, Ops.m_cos((Ops.mul(m, th))))))
              Ops.set_at(im, m, Ops.add(Ops.elem(im, m), Ops.mul(v, Ops.m_sin((Ops.mul(m, th))))))
            end
          end
        end
      end
      return Ops.m_drop(Ops.m_map(Ops.rng(5), ->(m) {
        return (Ops.gt(total, 0) ? Ops.div(Fmt.hypot(Ops.elem(re, m), Ops.elem(im, m)), total) : 0)
      }), 0)
    })
    Ops.set_at(Galaxies.ARMS, key, out)
    return out
  end
  def self.rar
    pic = Picture.still("galaxy.rar", "the radial acceleration relation, simulated: every galaxy run at every measured radius, against the data at SPARC's own freedoms and with them fitted", 960, 720, ->(s) {
      return Galaxies.rar_panel(s)
    })
    pic.on_request = true
    return pic
  end
  def self.rar_panel(s)
    s.fill_style(Galaxies.BACK)
    s.fill_rect(0, 0, s.width, s.height)
    sim = Galaxies.simulated
    _S = sim.columns
    unit = Ops.getattr(sim.header, "unit")
    ids = Ops.getattr(sim.header, "ids")
    bx0 = 92
    bx1 = Ops.sub(s.width, 26)
    by0 = 70
    by1 = Ops.sub(s.height, 80)
    _XMIN = (-4)
    _XMAX = 2
    _YMIN = (-3)
    _YMAX = 2
    _X = ->(l) {
      return Ops.add(bx0, Ops.mul(Ops.div((Ops.sub(l, _XMIN)), (Ops.sub(_XMAX, _XMIN))), (Ops.sub(bx1, bx0))))
    }
    _Y = ->(l) {
      return Ops.sub(by1, Ops.mul(Ops.div((Ops.sub(l, _YMIN)), (Ops.sub(_YMAX, _YMIN))), (Ops.sub(by1, by0))))
    }
    s.stroke_style(Galaxies.GRID)
    s.line_width(1)
    s.fill_style(Galaxies.FAINT)
    s.font("11px ui-monospace, monospace")
    s.text_align("center")
    l = _XMIN
    while Ops.le(l, _XMAX)
      s.begin_path
      s.move_to(_X.(l), by0)
      s.line_to(_X.(l), by1)
      s.stroke
      s.fill_text("10^#{l}", _X.(l), Ops.add(by1, 16))
      l = Ops.add(l, 1)
    end
    s.text_align("right")
    l = _YMIN
    while Ops.le(l, _YMAX)
      s.begin_path
      s.move_to(bx0, _Y.(l))
      s.line_to(bx1, _Y.(l))
      s.stroke
      s.fill_text("10^#{l}", Ops.sub(bx0, 8), Ops.add(_Y.(l), 4))
      l = Ops.add(l, 1)
    end
    lg = ->(v) {
      return Fmt.log10(Ops.div(v, Galaxies.A0_DATA))
    }
    spread0 = []
    spread1 = []
    sim.rows.times do |i|
      if Ops.gt(Ops.elem(Ops.getattr(_S, "kept"), i), 0)
        g = Ops.elem(Ops.getattr(_S, "galaxy"), i)
        j = Ops.m_index_of(ids, g)
        _R = Ops.elem(Ops.getattr(_S, "R"), i)
        _V = Ops.elem(Ops.getattr(_S, "Vobs"), i)
        gbar0 = Ops.mul((Ops.add(Ops.add(Ops.mul(Sparc.YD, Ops.elem(Ops.getattr(_S, "gd"), i)), Ops.mul(Sparc.YB, Ops.elem(Ops.getattr(_S, "gb"), i))), Ops.elem(Ops.getattr(_S, "gg"), i))), unit)
        gbar1 = Ops.mul((Ops.add(Ops.add(Ops.mul(Ops.elem(Ops.getattr(sim.header, "Y_disk"), j), Ops.elem(Ops.getattr(_S, "gd"), i)), Ops.mul(Ops.elem(Ops.getattr(sim.header, "Y_bulge"), j), Ops.elem(Ops.getattr(_S, "gb"), i))), Ops.elem(Ops.getattr(_S, "gg"), i))), unit)
        f = Ops.div(Ops.elem(Ops.getattr(sim.header, "D"), j), Ops.elem(Ops.getattr(Sparc.sample.columns, "D"), g))
        sn = Ops.div(Ops.m_sin((Ops.div(Ops.mul(Ops.elem(Ops.getattr(Sparc.sample.columns, "Inc"), g), Math::PI), 180))), Ops.m_sin((Ops.div(Ops.mul(Ops.elem(Ops.getattr(sim.header, "Inc"), j), Math::PI), 180))))
        gobs0 = Ops.mul(Ops.div(Ops.mul(_V, _V), _R), unit)
        gobs1 = Ops.mul(Ops.div(Ops.mul((Ops.mul(_V, sn)), (Ops.mul(_V, sn))), (Ops.mul(_R, f))), unit)
        if (Ops.gt(gbar0, 0) && Ops.gt(gbar1, 0))
          s.fill_style("rgba(238,240,245,0.35)")
          s.fill_rect(Ops.sub(_X.(lg.(gbar0)), 0.7), Ops.sub(_Y.(lg.(gobs0)), 0.7), 1.4, 1.4)
          s.fill_style("rgba(159,211,245,0.8)")
          s.fill_rect(Ops.sub(_X.(lg.(gbar1)), 0.8), Ops.sub(_Y.(lg.(gobs1)), 0.8), 1.6, 1.6)
          m0 = Ops.elem(Ops.getattr(_S, "v0"), i)
          m1 = Ops.elem(Ops.getattr(_S, "v1"), i)
          if Ops.gt(m0, 0)
            Ops.m_push(spread0, Fmt.log10(Ops.div(m0, _V)))
          end
          if Ops.gt(m1, 0)
            Ops.m_push(spread1, Fmt.log10(Ops.div(m1, _V)))
          end
        end
      end
    end
    a0 = Ops.getattr(sim.header, "a0")
    s.stroke_style(Galaxies.MODEL)
    s.line_width(2)
    s.begin_path
    l = _XMIN
    while Ops.le(l, Ops.add(_XMAX, 0.000001))
      gN = Ops.mul(Ops.power(10, l), Galaxies.A0_DATA)
      y = lg.(Law.boost(gN, a0))
      if Ops.eq(l, _XMIN)
        s.move_to(_X.(l), _Y.(y))
      else
        s.line_to(_X.(l), _Y.(y))
      end
      l = Ops.add(l, 0.02)
    end
    s.stroke
    s.stroke_style(Galaxies.NEWT)
    s.dash([6, 5])
    s.begin_path
    s.move_to(_X.(Fmt.max(_XMIN, _YMIN)), _Y.(Fmt.max(_XMIN, _YMIN)))
    s.line_to(_X.(Fmt.min(_XMAX, _YMAX)), _Y.(Fmt.min(_XMAX, _YMAX)))
    s.stroke
    s.dash([])
    s.stroke_style("\#1b2130")
    s.stroke_rect(bx0, by0, Ops.sub(bx1, bx0), Ops.sub(by1, by0))
    s.text_align("left")
    s.font("13px ui-monospace, monospace")
    s.fill_style(Galaxies.SEEN)
    s.fill_text("THE RADIAL ACCELERATION RELATION, EVERY GALAXY RUN", bx0, 26)
    s.font("11px ui-monospace, monospace")
    s.fill_style(Galaxies.FAINT)
    off0 = Galaxies.percent(Simulation.rms(spread0))
    off1 = Galaxies.percent(Simulation.rms(spread1))
    a0_text = Fmt.exponential(a0, 3)
    deg_text = Fmt.fixed(Ops.getattr(sim.header, "deg"), 1)
    radii_n = spread0.length
    seen = Node.new
    sim.rows.times do |i|
      which = Ops.elem(Ops.getattr(_S, "galaxy"), i)
      if Ops.gt(Ops.elem(Ops.getattr(_S, "kept"), i), 0)
        Ops.setattr(seen, "#{which}", true)
      end
    end
    ids_n = Ops.filt(ids, ->(g) {
      return !Ops.eq(Ops.getattr(seen, "#{g}"), nil)
    }).length
    s.fill_text("#{radii_n} radii, #{ids_n} galaxies: #{off0} off in speed at the published Υ, D, i, #{off1} fitted (a₀ #{a0_text} m/s², DEG #{deg_text})", bx0, 44)
    s.fill_style("rgba(238,240,245,0.7)")
    s.fill_text("■ SPARC at its own freedoms", bx0, Ops.sub(s.height, 22))
    s.fill_style(Galaxies.FITTED)
    s.fill_text("■ the same radii with Υ, D, i fitted", Ops.add(bx0, 240), Ops.sub(s.height, 22))
    s.fill_style(Galaxies.MODEL)
    s.fill_text("— where the run puts them: the law, at the run's a₀", Ops.add(bx0, 520), Ops.sub(s.height, 22))
    s.fill_style(Galaxies.FAINT)
    s.text_align("center")
    return s.fill_text("g_baryons / 1.2e-10 m/s²", Ops.div((Ops.add(bx0, bx1)), 2), Ops.add(by1, 34))
  end
  def self.point
    return Galaxies.of("galaxy.point", "a galaxy as ONE source - the whole of its mass behind one face, so what it sends saturates at the face. Where the model puts galaxies, against every measurement", "A GALAXY AS ONE SOURCE")
  end
  def self.many
    return Galaxies.of("galaxy.many", "and as its stars - each thin enough to send all of itself, so what is sent is the total mass. The same axes, the same law, the other limit of the skin", "A GALAXY AS MANY SOURCES, ONE PER STAR")
  end
  __exposed
end

class Sweeping < Painter
