    args_.empty? ? @shown_frames : @shown_frames.(*args_)
  end
  attr_writer :shown_frames
  def frame(s, dt)
    k = Ops.elem(self.ks, (Ops.lt(self.shown_frames, self.ks.length) ? self.shown_frames : Ops.sub(self.ks.length, 1)))
    deg = Ops.elem(Ops.getattr(self.solved.header, "degs"), k)
    Galaxies.panel(s, Galaxies.frame_of(self.solved, k), self.title, deg, Galaxies.support_at(self.solved, k), Galaxies.possible_at(deg))
    self.shown_frames = Ops.add(self.shown_frames, 1)
  end
  __exposed
end

