  def box_side
    return Ops.add(self.side, Ops.mul(Ops.mul(2, self.resolution.margin), self.resolution.cells))
  end
  def box_cells
    return Ops.mul(self.box_side, self.box_side)
  end
  def reach
    return Ops.add(Ops.mul(3, self.resolution.cells), 4)
  end
  def tile_side
    return Ops.add(Ops.m_floor((Ops.div(Ops.sub(Ops.add(self.box_side, self.batching.tiles), 1), self.batching.tiles))), Ops.mul(Ops.mul(2, self.reach), self.batching.ticks))
  end
  def tile_cells
    return (Ops.eq(self.batching.tiles, 1) ? self.box_cells : Ops.mul(self.tile_side, self.tile_side))
  end
  def tile_sources
    return Ops.div(Ops.mul(self.sources, self.tile_cells), self.box_cells)
  end
  def parts
    c = self.tile_cells
    s = self.tile_sources
    r = self.resolution
    held = Ops.mul(Ops.mul(c, (Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.add(Ops.mul(Ops.mul(r.ways, r.keeps), 8), 1), r.ways), 12), 2), 4), 4), 9), r.near_list), 1), 1))), 4)
    each = (self.budget.compact ? 0 : Ops.add(Ops.add(Ops.add(12, 4), 2), 1))
    ledgers = Ops.mul((Ops.add(Ops.add(Ops.mul(c, Ops.add(Ops.add(11, 384), 2)), Ops.mul(s, each)), Ops.mul(Ops.mul(4096, 64), 4))), 4)
    lists = (self.budget.compact ? Ops.mul((Ops.add(Ops.mul(10, c), Ops.mul(1024, 1024))), 4) : Ops.mul((Ops.add(Ops.mul(2, c), s)), 4))
    base = [["held rays (a box)", held, true], ["held rays (the other)", held, true], ["ledgers and sources", ledgers, true], ["sources by cell", lists, true], ["planes", Ops.mul(Ops.mul(3, c), 4), true]]
    shards = (self.budget.compact ? Ops.filt(Ops.m_map(Ops.rng(8), ->(k) {
      return Fmt.max(0, Fmt.min(178956970, Ops.sub(s, Ops.mul(k, 178956970))))
    }), ->(n) {
      return Ops.gt(n, 0)
    }) : [])
    return Ops.m_concat(base, Ops.m_map(Ops.rng(shards.length), ->(k) {
      return ["sources (shard #{k})", Ops.mul(Ops.elem(shards, k), 12), true]
    }))
  end
  def total
    sum = 0
    Ops.list(self.parts).each do |p|
      sum = Ops.add(sum, Ops.elem(p, 1))
    end
    return sum
  end
  def per_source
    return (self.budget.compact ? 12 : Ops.mul(Ops.add(Ops.add(Ops.add(Ops.add(12, 4), 2), 1), 1), 4))
  end
  def fits(memory, binding)
    cap = (Ops.gt(self.budget.memory, 0) ? self.budget.memory : memory)
    one = (Ops.gt(self.budget.binding, 0) ? self.budget.binding : binding)
    return (Ops.le(self.total, cap) && Ops.m_every(self.parts, ->(p) {
      return Ops.le(Ops.elem(p, 1), one)
    }))
  end
  def report(memory, binding)
    cap = (Ops.gt(self.budget.memory, 0) ? self.budget.memory : memory)
    one = (Ops.gt(self.budget.binding, 0) ? self.budget.binding : binding)
    over = " - more than one binding holds (#{Fmt.fixed(Ops.div(one, 1048576), 0)} MiB)"
    lines = Ops.m_map(self.parts, ->(p) {
      tail = (Ops.gt(Ops.elem(p, 1), one) ? over : "")
      return "  #{Ops.elem(p, 0)}: #{Fmt.fixed(Ops.div(Ops.elem(p, 1), 1048576), 0)} MiB#{tail}"
    })
    head = "#{Fmt.fixed(self.sources, 0)} sources on a #{self.side}-cell view in a #{self.box_side}-cell box (#{Ops.mul(self.batching.tiles, self.batching.tiles)} tile(s), #{self.resolution.cells} cells to a c-bar, #{self.resolution.ways} ways): #{Fmt.fixed(Ops.div(self.total, 1073741824), 2)} GiB of #{Fmt.fixed(Ops.div(cap, 1073741824), 2)} GiB, #{Fmt.fixed(self.per_source, 0)} bytes a source"
    verdict = (self.fits(memory, binding) ? "  fits" : "  does not fit")
    return Ops.m_join(Ops.m_concat(Ops.m_concat([head], lines), [verdict]), "\n")
  end
  __exposed
end

class Annulus < Node
  def inner(*args_)
    args_.empty? ? @inner : @inner.(*args_)
  end
  attr_writer :inner
  def outer(*args_)
    args_.empty? ? @outer : @outer.(*args_)
  end
  attr_writer :outer
  def thick(*args_)
    args_.empty? ? @thick : @thick.(*args_)
  end
  attr_writer :thick
  def pull(r, nsub, nphi)
    total = 0
    weight = 0
    nsub.times do |s|
      rs = Ops.add(self.inner, Ops.div(Ops.mul((Ops.sub(self.outer, self.inner)), (Ops.add(s, 0.5))), nsub))
      ring = 0
      nphi.times do |p|
        half = Ops.m_sin((Ops.div(Ops.div(Ops.mul(Math::PI, (Ops.add(p, 0.5))), nphi), 2)))
        bend = Ops.mul(Ops.mul(2, half), half)
        d2 = Ops.add(Ops.add(Ops.mul((Ops.sub(r, rs)), (Ops.sub(r, rs))), Ops.mul(Ops.mul(Ops.mul(2, r), rs), bend)), Ops.mul(self.thick, self.thick))
        ring = Ops.add(ring, Ops.div((Ops.add((Ops.sub(r, rs)), Ops.mul(rs, bend))), (Ops.mul(d2, Ops.m_sqrt(d2)))))
      end
      total = Ops.add(total, Ops.div(Ops.mul(rs, ring), nphi))
      weight = Ops.add(weight, rs)
    end
    return (Ops.gt(weight, 0) ? Ops.div(total, weight) : 0)
  end
  def arrives(r, nsub, nphi)
    total = 0
    weight = 0
    nsub.times do |s|
      rs = Ops.add(self.inner, Ops.div(Ops.mul((Ops.sub(self.outer, self.inner)), (Ops.add(s, 0.5))), nsub))
      ring = 0
      nphi.times do |p|
        half = Ops.m_sin((Ops.div(Ops.div(Ops.mul(Math::PI, (Ops.add(p, 0.5))), nphi), 2)))
        d2 = Ops.add(Ops.add(Ops.mul((Ops.sub(r, rs)), (Ops.sub(r, rs))), Ops.mul(Ops.mul(Ops.mul(Ops.mul(4, r), rs), half), half)), Ops.mul(self.thick, self.thick))
        ring = Ops.add(ring, Ops.div(1, d2))
      end
      total = Ops.add(total, Ops.div(Ops.mul(rs, ring), nphi))
      weight = Ops.add(weight, rs)
    end
    return (Ops.gt(weight, 0) ? Ops.div(total, weight) : 0)
  end
  __exposed
end

