    return Ops.m_join(["fn boost(gN: f32, a0: f32) -> f32 {", "  let n: u32 = arrayLength(&L) / 2u;", "  let want: f32 = log(gN / a0);", "  if (want <= L[0]) { return exp(L[n]) * a0; }", "  if (want >= L[n - 1u]) { return exp(L[2u * n - 1u]) * a0; }", "  var lo: u32 = 0u;", "  var hi: u32 = n - 1u;", "  loop {", "    if (hi - lo <= 1u) { break; }", "    let mid: u32 = (lo + hi) / 2u;", "    if (L[mid] <= want) { lo = mid; } else { hi = mid; }", "  }", "  let t: f32 = (want - L[lo]) / (L[hi] - L[lo]);", "  return exp(L[n + lo] + t * (L[n + hi] - L[n + lo])) * a0;", "}", "fn felt(gN: f32, a0: f32) -> f32 {", "  if (gN > 0.0) { return boost(gN, a0); }", "  if (gN < 0.0) { return -boost(-gN, a0); }", "  return 0.0;", "}"], "\n")
