  def self.pull_kernel
    pi = Shaded.literal(Math::PI)
    return Ops.m_join(["// GENERATED from Simulation.ray: PULL - an annulus summed element by element at a radius in its plane, per unit of G M", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> T: array<f32>;", "@group(0) @binding(2) var<storage, read_write> O: array<f32>;", "#{Simulation.ENTRY} PULL#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let r: f32 = T[4u * i];", "  let e0: f32 = T[4u * i + 1u];", "  let e1: f32 = T[4u * i + 2u];", "  let h: f32 = T[4u * i + 3u];", "  var total: f32 = 0.0;", "  var weight: f32 = 0.0;", "  for (var s: u32 = 0u; s < P[1]; s = s + 1u) {", "    let rs: f32 = e0 + (e1 - e0) * (f32(s) + 0.5) / f32(P[1]);", "    var ring: f32 = 0.0;", "    for (var p: u32 = 0u; p < P[2]; p = p + 1u) {", "      let sh: f32 = sin(#{pi} * (f32(p) + 0.5) / f32(P[2]) / 2.0);", "      let bend: f32 = 2.0 * sh * sh;", "      let d2: f32 = (r - rs) * (r - rs) + 2.0 * r * rs * bend + h * h;", "      if (P[3] == 1u) { ring = ring + 1.0 / d2; } else { ring = ring + ((r - rs) + rs * bend) / (d2 * sqrt(d2)); }", "    }", "    total = total + rs * ring / f32(P[2]);", "    weight = weight + rs;", "  }", "  if (weight > 0.0) { O[i] = total / weight; } else { O[i] = 0.0; }", "}"], "\n")
  end
  def self.law_kernel
    return Ops.m_join(["// GENERATED from Simulation.ray: LAW - what is felt at every place of every galaxy", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> Q: array<f32>;", "@group(0) @binding(3) var<storage, read> N: array<f32>;", "@group(0) @binding(4) var<storage, read_write> O: array<f32>;", Simulation.law_wgsl, "#{Simulation.ENTRY} LAW#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let slot: u32 = u32(Q[6u * i]);", "  let gN: f32 = N[4u * slot] * Q[6u * i + 2u] + N[4u * slot + 1u] * Q[6u * i + 4u] + Q[6u * i + 3u];", "  O[i] = felt(gN, N[4u * slot + 2u]);", "}"], "\n")
  end
  def self.fit_kernel
    pi = Shaded.literal(Math::PI)
    ln10 = Shaded.literal(Ops.m_ln(10))
    lyd = Shaded.literal(Fmt.log10(Sparc.YD))
    lyb = Shaded.literal(Fmt.log10(Sparc.YB))
    py = Shaded.literal(Simulation.PRIOR_Y)
    return Ops.m_join(["// GENERATED from Simulation.ray: FIT - the log of the posterior of the data's own freedoms, on a grid", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> Q: array<f32>;", "@group(0) @binding(3) var<storage, read> G: array<f32>;", "@group(0) @binding(4) var<storage, read_write> O: array<f32>;", Simulation.law_wgsl, "#{Simulation.ENTRY} FIT#{Simulation.ID}", Simulation.THREAD, "  let n: u32 = P[1];", "  let C: u32 = n * n * n * n;", "  if (i >= P[0] * C) { return; }", "  let j: u32 = i / C;", "  let c: u32 = i % C;", "  let h: f32 = f32((n - 1u) / 2u);", "  let b: u32 = 16u * j;", "  let D: f32 = G[b + 2u];", "  let eD: f32 = G[b + 3u];", "  let inc: f32 = G[b + 4u];", "  let einc: f32 = G[b + 5u];", "  let a0: f32 = G[b + 6u];", "  let ly: f32 = G[b + 8u] + (f32(c % n) - h) * G[b + 12u];", "  let lb: f32 = G[b + 9u] + (f32((c / n) % n) - h) * G[b + 12u];", "  let Dp: f32 = G[b + 10u] + (f32((c / (n * n)) % n) - h) * G[b + 13u] * eD;", "  let ip: f32 = G[b + 11u] + (f32(c / (n * n * n)) - h) * G[b + 14u] * einc;", "  if (Dp <= 0.0 || ip <= 0.5 || ip > 90.0) { O[i] = -1e30; return; }", "  let YD: f32 = exp(ly * #{ln10});", "  let YB: f32 = exp(lb * #{ln10});", "  let f: f32 = Dp / D;", "  let s: f32 = sin(inc * #{pi} / 180.0) / sin(ip * #{pi} / 180.0);", "  var chi: f32 = 0.0;", "  let start: u32 = u32(G[b]);", "  let stop: u32 = start + u32(G[b + 1u]);", "  for (var p: u32 = start; p < stop; p = p + 1u) {", "    let q: u32 = 8u * p;", "    let g: f32 = felt(YD * Q[q + 3u] + YB * Q[q + 5u] + Q[q + 4u], a0);", "    let vm: f32 = sqrt(max(f * Q[q] * g, 0.0));", "    let d: f32 = (Q[q + 1u] * s - vm) / (Q[q + 2u] * s);", "    chi = chi + d * d;", "  }", "  let py: f32 = (ly - #{lyd}) / #{py};", "  let pb: f32 = G[b + 7u] * (lb - #{lyb}) / #{py};", "  var pd: f32 = 0.0;", "  if (eD > 0.0) { pd = (Dp - D) / eD; }", "  var pi_: f32 = 0.0;", "  if (einc > 0.0) { pi_ = (ip - inc) / einc; }", "  O[i] = -0.5 * (chi + py * py + pb * pb + pd * pd + pi_ * pi_);", "}"], "\n")
  end
  def self.best_kernel
    return Ops.m_join(["// GENERATED from Simulation.ray: BEST - each galaxy's best point of its grid", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> V: array<f32>;", "@group(0) @binding(2) var<storage, read_write> O: array<f32>;", "#{Simulation.ENTRY} BEST#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  var best: f32 = -3e38;", "  var pos: u32 = 0u;", "  for (var c: u32 = 0u; c < P[1]; c = c + 1u) {", "    let v: f32 = V[i * P[1] + c];", "    if (v > best) { best = v; pos = c; }", "  }", "  O[2u * i] = f32(pos);", "  O[2u * i + 1u] = best;", "}"], "\n")
  end
  def self.stars_kernel
    return Ops.m_join(["// GENERATED from Simulation.ray: STARS - tracers followed on every galaxy's field", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> GT: array<f32>;", "@group(0) @binding(3) var<storage, read> GI: array<f32>;", "@group(0) @binding(4) var<storage, read_write> S: array<f32>;", "@group(0) @binding(5) var<storage, read_write> F: array<f32>;", Simulation.law_wgsl, "fn g_at(j: u32, r: f32) -> f32 {", "  let rmax: f32 = GI[12u * j];", "  let T: u32 = P[2];", "  let base: u32 = j * T;", "  let u: f32 = r / rmax * f32(T);", "  if (u <= 1.0) { return GT[base] * u; }", "  if (u >= f32(T)) {", "    let q: f32 = rmax / r;", "    return felt(GI[12u * j + 5u] * q * q, GI[12u * j + 6u]);", "  }", "  let t0: u32 = u32(floor(u)) - 1u;", "  let fr: f32 = u - floor(u);", "  return GT[base + t0] * (1.0 - fr) + GT[base + t0 + 1u] * fr;", "}", "#{Simulation.ENTRY} START#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let j: u32 = i / P[1];", "  let k: u32 = 10u * i;", "  let r0: f32 = S[k];", "  let phi: f32 = S[k + 1u];", "  let sig: f32 = GI[12u * j + 9u];", "  let g: f32 = g_at(j, r0);", "  let vp: f32 = sqrt(max(r0 * g, 0.0)) + sig * S[k + 2u];", "  let vr: f32 = sig * S[k + 3u];", "  let c: f32 = cos(phi);", "  let s: f32 = sin(phi);", "  S[k] = r0 * c;", "  S[k + 1u] = r0 * s;", "  S[k + 2u] = vr * c - vp * s;", "  S[k + 3u] = vr * s + vp * c;", "  S[k + 4u] = 0.0 - g * c;", "  S[k + 5u] = 0.0 - g * s;", "  S[k + 6u] = 0.0;", "  S[k + 7u] = 0.0;", "  S[k + 8u] = 0.0;", "}", "#{Simulation.ENTRY} STEP#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let j: u32 = i / P[1];", "  let b: u32 = 12u * j;", "  let dt: f32 = GI[b + 1u];", "  let n: u32 = u32(GI[b + 2u]);", "  let avg_from: u32 = u32(GI[b + 3u]);", "  let film: f32 = GI[b + 4u];", "  let every: u32 = max(u32(GI[b + 7u]), 1u);", "  let ffrom: u32 = u32(GI[b + 8u]);", "  let k: u32 = 10u * i;", "  var x: f32 = S[k];", "  var y: f32 = S[k + 1u];", "  var vx: f32 = S[k + 2u];", "  var vy: f32 = S[k + 3u];", "  var ax: f32 = S[k + 4u];", "  var ay: f32 = S[k + 5u];", "  var sr: f32 = S[k + 6u];", "  var sv: f32 = S[k + 7u];", "  var sn: f32 = S[k + 8u];", "  let stop: u32 = min(P[4], n);", "  for (var t: u32 = P[3]; t < stop; t = t + 1u) {", "    vx = vx + 0.5 * ax * dt;", "    vy = vy + 0.5 * ay * dt;", "    x = x + vx * dt;", "    y = y + vy * dt;", "    let r: f32 = max(sqrt(x * x + y * y), 1e-6);", "    let g: f32 = g_at(j, r);", "    ax = 0.0 - g * x / r;", "    ay = 0.0 - g * y / r;", "    vx = vx + 0.5 * ax * dt;", "    vy = vy + 0.5 * ay * dt;", "    if (t >= avg_from) {", "      sr = sr + r;", "      sv = sv + (x * vy - y * vx) / r;", "      sn = sn + 1.0;", "    }", "    let kk: u32 = t + 1u;", "    if (film >= 0.0 && kk > ffrom && (kk - ffrom) % every == 0u) {", "      let fr: u32 = (kk - ffrom) / every - 1u;", "      if (fr < P[5]) {", "        let o: u32 = ((u32(film) * P[1] + i % P[1]) * P[5] + fr) * 2u;", "        F[o] = x;", "        F[o + 1u] = y;", "      }", "    }", "  }", "  S[k] = x;", "  S[k + 1u] = y;", "  S[k + 2u] = vx;", "  S[k + 3u] = vy;", "  S[k + 4u] = ax;", "  S[k + 5u] = ay;", "  S[k + 6u] = sr;", "  S[k + 7u] = sv;", "  S[k + 8u] = sn;", "}"], "\n")
  end
  def self.runnable
    _C = Sparc.curves.columns
    counts = Node.new
    Sparc.curves.rows.times do |i|
      g = Ops.elem(Ops.getattr(_C, "galaxy"), i)
      if (Ops.gt(Ops.elem(Ops.getattr(_C, "R"), i), 0) && Ops.gt(Ops.elem(Ops.getattr(_C, "Vobs"), i), 0))
        Ops.setattr(counts, "#{g}", Ops.add((Ops.or_else(Ops.getattr(counts, "#{g}")) { 0 }), 1))
      end
    end
    out = []
    Sparc.names.length.times do |g|
      if Ops.ge((Ops.or_else(Ops.getattr(counts, "#{g}")) { 0 }), 3)
        Ops.m_push(out, g)
      end
    end
    return out
  end
  def self.rows_of(g)
    _C = Sparc.curves.columns
    out = []
    Sparc.curves.rows.times do |i|
      if ((Ops.eq(Ops.elem(Ops.getattr(_C, "galaxy"), i), g) && Ops.gt(Ops.elem(Ops.getattr(_C, "R"), i), 0)) && Ops.gt(Ops.elem(Ops.getattr(_C, "Vobs"), i), 0))
        Ops.m_push(out, [Ops.elem(Ops.getattr(_C, "R"), i), Ops.elem(Ops.getattr(_C, "Vobs"), i), Ops.elem(Ops.getattr(_C, "e_Vobs"), i), Ops.elem(Ops.getattr(_C, "Vgas"), i), Ops.elem(Ops.getattr(_C, "Vdisk"), i), Ops.elem(Ops.getattr(_C, "Vbul"), i), (Simulation.kept(g, Ops.elem(Ops.getattr(_C, "Vobs"), i), Ops.elem(Ops.getattr(_C, "e_Vobs"), i)) ? 1 : 0)])
      end
    end
    return Ops.m_sorted_by(out, ->(r) {
      return Ops.elem(r, 0)
    })
  end
  def self.edges_of(rs)
    n = rs.length
    out = [0, Ops.div(Ops.elem(Ops.elem(rs, 0), 0), 2)]
    Ops.sub(n, 1).times do |i|
      Ops.m_push(out, Ops.div((Ops.add(Ops.elem(Ops.elem(rs, i), 0), Ops.elem(Ops.elem(rs, Ops.add(i, 1)), 0))), 2))
    end
    Ops.m_push(out, Ops.add(Ops.elem(Ops.elem(rs, Ops.sub(n, 1)), 0), Ops.div((Ops.sub(Ops.elem(Ops.elem(rs, Ops.sub(n, 1)), 0), Ops.elem(Ops.elem(rs, Ops.sub(n, 2)), 0))), 2)))
    return out
  end
  def self.bulge_arrives(rs, r, h)
    got = 0
    was = 0
    Ops.list(rs).each do |row|
      inside = Fmt.max(was, Ops.mul(Ops.mul(Ops.elem(row, 5), Ops.m_abs(Ops.elem(row, 5))), Ops.elem(row, 0)))
      m = Ops.sub(inside, was)
      a = Ops.elem(row, 0)
      if (Ops.gt(m, 0) && Ops.gt(r, 0))
        got = Ops.add(got, Ops.div(Ops.mul(m, Ops.m_ln((Ops.div((Ops.add(r, a)), Fmt.max(Ops.m_abs((Ops.sub(r, a))), h))))), (Ops.mul(Ops.mul(2, a), r))))
      end
      was = inside
    end
    return got
  end
  def self.bulge_at(rs, r)
    n = rs.length
    inside = []
    most = 0
    Ops.list(rs).each do |row|
      most = Fmt.max(most, Ops.mul(Ops.mul(Ops.elem(row, 5), Ops.m_abs(Ops.elem(row, 5))), Ops.elem(row, 0)))
      Ops.m_push(inside, most)
    end
    if (Ops.le(most, 0) || Ops.le(r, 0))
      return 0
    end
    if Ops.le(r, Ops.elem(Ops.elem(rs, 0), 0))
      return Ops.div(Ops.mul(Ops.elem(inside, 0), Ops.power((Ops.div(r, Ops.elem(Ops.elem(rs, 0), 0))), 3)), (Ops.mul(r, r)))
    end
    if Ops.ge(r, Ops.elem(Ops.elem(rs, Ops.sub(n, 1)), 0))
      return Ops.div(Ops.elem(inside, Ops.sub(n, 1)), (Ops.mul(r, r)))
    end
    k = 0
    while Ops.lt(Ops.elem(Ops.elem(rs, Ops.add(k, 1)), 0), r)
      k = Ops.add(k, 1)
    end
    f = Ops.div((Ops.sub(r, Ops.elem(Ops.elem(rs, k), 0))), (Ops.sub(Ops.elem(Ops.elem(rs, Ops.add(k, 1)), 0), Ops.elem(Ops.elem(rs, k), 0))))
    return Ops.div((Ops.add(Ops.mul(Ops.elem(inside, k), (Ops.sub(1, f))), Ops.mul(Ops.elem(inside, Ops.add(k, 1)), f))), (Ops.mul(r, r)))
  end
  def self.linear(_A, bv)
    n = bv.length
    _M = Ops.m_map(Ops.rng(n), ->(i) {
      return Ops.m_concat(Ops.m_map(Ops.rng(n), ->(j) {
        return Ops.elem(Ops.elem(_A, i), j)
      }), [Ops.elem(bv, i)])
    })
    n.times do |c|
      p = c
      Ops.sub(n, c).times do |k|
        if Ops.gt(Ops.m_abs(Ops.elem(Ops.elem(_M, Ops.add(c, k)), c)), Ops.m_abs(Ops.elem(Ops.elem(_M, p), c)))
          p = Ops.add(c, k)
        end
      end
      swap = Ops.elem(_M, c)
      Ops.set_at(_M, c, Ops.elem(_M, p))
      Ops.set_at(_M, p, swap)
      if !Ops.eq(Ops.elem(Ops.elem(_M, c), c), 0)
        Ops.sub(Ops.sub(n, c), 1).times do |k|
          r = Ops.add(Ops.add(c, 1), k)
          f = Ops.div(Ops.elem(Ops.elem(_M, r), c), Ops.elem(Ops.elem(_M, c), c))
          Ops.sub(Ops.add(n, 1), c).times do |m|
            Ops.set_at(Ops.elem(_M, r), Ops.add(c, m), Ops.sub(Ops.elem(Ops.elem(_M, r), Ops.add(c, m)), Ops.mul(f, Ops.elem(Ops.elem(_M, c), Ops.add(c, m)))))
          end
        end
      end
    end
    x = Ops.filled(n, 0)
    n.times do |k|
      r = Ops.sub(Ops.sub(n, 1), k)
      s = Ops.elem(Ops.elem(_M, r), n)
      Ops.sub(Ops.sub(n, r), 1).times do |m|
        s = Ops.sub(s, Ops.mul(Ops.elem(Ops.elem(_M, r), Ops.add(Ops.add(r, 1), m)), Ops.elem(x, Ops.add(Ops.add(r, 1), m))))
      end
      Ops.set_at(x, r, (!Ops.eq(Ops.elem(Ops.elem(_M, r), r), 0) ? Ops.div(s, Ops.elem(Ops.elem(_M, r), r)) : 0))
    end
    return x
  end
  def self.nnls(_K, want)
    m = want.length
    n = Ops.elem(_K, 0).length
    top = 0
    Ops.list(want).each do |t|
      top = Fmt.max(top, Ops.m_abs(t))
    end
    if Ops.le(top, 0)
      return Ops.filled(n, 0)
    end
    wt = Ops.m_map(want, ->(t) {
      return Ops.div(1, Fmt.max(Ops.m_abs(t), Ops.mul(0.02, top)))
    })
    _A = Ops.m_map(Ops.rng(n), ->(a) {
      return Ops.m_map(Ops.rng(n), ->(b) {
        s = 0
        m.times do |i|
          s = Ops.add(s, Ops.mul(Ops.mul(Ops.mul(Ops.elem(wt, i), Ops.elem(wt, i)), Ops.elem(Ops.elem(_K, i), a)), Ops.elem(Ops.elem(_K, i), b)))
        end
        return s
      })
    })
    bv = Ops.m_map(Ops.rng(n), ->(a) {
      s = 0
      m.times do |i|
        s = Ops.add(s, Ops.mul(Ops.mul(Ops.mul(Ops.elem(wt, i), Ops.elem(wt, i)), Ops.elem(Ops.elem(_K, i), a)), Ops.elem(want, i)))
      end
      return s
    })
    w = Ops.filled(n, 0)
    held = Ops.filled(n, false)
    most = 0
    Ops.list(bv).each do |v|
      most = Fmt.max(most, Ops.m_abs(v))
    end
    tol = Ops.mul(most, Ops.power(10, (Ops.sub(0, 12))))
    solved = ->(hold) {
      on = Ops.filt(Ops.rng(n), ->(a) {
        return Ops.elem(hold, a)
      })
      got = Simulation.linear(Ops.m_map(on, ->(a) {
        return Ops.m_map(on, ->(b) {
          return Ops.elem(Ops.elem(_A, a), b)
        })
      }), Ops.m_map(on, ->(a) {
        return Ops.elem(bv, a)
      }))
      z = Ops.filled(n, 0)
      on.length.times do |k|
        Ops.set_at(z, Ops.elem(on, k), Ops.elem(got, k))
      end
      return z
    }
    rounds = 0
    going = true
    while (going && Ops.lt(rounds, Ops.mul(3, n)))
      rounds = Ops.add(rounds, 1)
      grad = Ops.m_map(Ops.rng(n), ->(a) {
        s = Ops.elem(bv, a)
        n.times do |b|
          s = Ops.sub(s, Ops.mul(Ops.elem(Ops.elem(_A, a), b), Ops.elem(w, b)))
        end
        return s
      })
      pick = (-1)
      n.times do |a|
        if ((!(Ops.elem(held, a)) && Ops.gt(Ops.elem(grad, a), tol)) && ((Ops.lt(pick, 0) || Ops.gt(Ops.elem(grad, a), Ops.elem(grad, pick)))))
          pick = a
        end
      end
      if Ops.lt(pick, 0)
        going = false
      else
        Ops.set_at(held, pick, true)
        inner = true
        while inner
          z = solved.(held)
          if Ops.m_every(Ops.rng(n), ->(a) {
            return (!(Ops.elem(held, a)) || Ops.gt(Ops.elem(z, a), 0))
          })
            w = z
            inner = false
          else
            step = 1
            n.times do |a|
              if (Ops.elem(held, a) && Ops.le(Ops.elem(z, a), 0))
                step = Fmt.min(step, Ops.div(Ops.elem(w, a), (Ops.sub(Ops.elem(w, a), Ops.elem(z, a)))))
              end
            end
            n.times do |a|
              if Ops.elem(held, a)
                Ops.set_at(w, a, Ops.add(Ops.elem(w, a), Ops.mul(step, (Ops.sub(Ops.elem(z, a), Ops.elem(w, a))))))
              end
            end
            wtop = 0
            Ops.list(w).each do |v|
              wtop = Fmt.max(wtop, v)
            end
            n.times do |a|
              if (Ops.elem(held, a) && Ops.le(Ops.elem(w, a), Ops.mul(wtop, Ops.power(10, (Ops.sub(0, 12))))))
                Ops.set_at(held, a, false)
                Ops.set_at(w, a, 0)
              end
            end
            inner = Ops.m_some(Ops.rng(n), ->(a) {
              return Ops.elem(held, a)
            })
          end
        end
      end
    end
    return w
  end
