  def tasks
    out = []
    self.measured_at = []
    self.tabled_at = []
    self.ids.length.times do |j|
      rs = Ops.elem(self.rows, j)
      es = Ops.elem(self.edges, j)
      n = Ops.sub(es.length, 1)
      Ops.m_push(self.measured_at, Ops.m_floor((Ops.div(out.length, 4))))
      Ops.list(rs).each do |row|
        n.times do |a|
          Ops.m_push(out, Ops.elem(row, 0))
          Ops.m_push(out, Ops.elem(es, a))
          Ops.m_push(out, Ops.elem(es, Ops.add(a, 1)))
          Ops.m_push(out, Ops.elem(self.thick, j))
        end
      end
    end
    self.ids.length.times do |j|
      es = Ops.elem(self.edges, j)
      n = Ops.sub(es.length, 1)
      Ops.m_push(self.tabled_at, Ops.m_floor((Ops.div(out.length, 4))))
      Simulation.TABLE.times do |t|
        n.times do |a|
          Ops.m_push(out, self.table_r(j, t))
          Ops.m_push(out, Ops.elem(es, a))
          Ops.m_push(out, Ops.elem(es, Ops.add(a, 1)))
          Ops.m_push(out, Ops.elem(self.thick, j))
        end
      end
    end
    return out
  end
