  def solve(pulls)
    self.w_discs = []
    self.w_gases = []
    self.at_rows = []
    self.tables = []
    self.repro = []
    self.ids.length.times do |j|
      rs = Ops.elem(self.rows, j)
      m = rs.length
      n = Ops.sub(Ops.elem(self.edges, j).length, 1)
      _K = Ops.m_map(Ops.rng(m), ->(i) {
        return Ops.m_map(Ops.rng(n), ->(a) {
          return Ops.elem(pulls, Ops.add(Ops.add(Ops.elem(self.measured_at, j), Ops.mul(i, n)), a))
        })
      })
      want_gas = Ops.m_map(rs, ->(row) {
        return Ops.div(Ops.mul(Ops.elem(row, 3), Ops.m_abs(Ops.elem(row, 3))), Ops.elem(row, 0))
      })
      want_disc = Ops.m_map(rs, ->(row) {
        return Ops.div(Ops.mul(Ops.elem(row, 4), Ops.m_abs(Ops.elem(row, 4))), Ops.elem(row, 0))
      })
      w_gas = Simulation.nnls(_K, want_gas)
      w_disc = Simulation.nnls(_K, want_disc)
      sum_at = ->(row_of, w) {
        s = 0
        n.times do |a|
          s = Ops.add(s, Ops.mul(row_of.(a), Ops.elem(w, a)))
        end
        return s
      }
      here = []
      worst = 0
      top = 0
      m.times do |i|
        gd = sum_at.(->(a) {
          return Ops.elem(Ops.elem(_K, i), a)
        }, w_disc)
        gg = sum_at.(->(a) {
          return Ops.elem(Ops.elem(_K, i), a)
        }, w_gas)
        gb = Simulation.bulge_at(rs, Ops.elem(Ops.elem(rs, i), 0))
        Ops.m_push(here, [gd, gg, gb])
        _R = Ops.elem(Ops.elem(rs, i), 0)
        sp = ->(v) {
          return Ops.mul(Ops.m_sqrt(Ops.m_abs(v)), ((Ops.lt(v, 0) ? (-1) : 1)))
        }
        worst = Fmt.max(worst, Fmt.max(Ops.m_abs((Ops.sub(sp.(Ops.mul(gd, _R)), Ops.elem(Ops.elem(rs, i), 4)))), Ops.m_abs((Ops.sub(sp.(Ops.mul(gg, _R)), Ops.elem(Ops.elem(rs, i), 3))))))
        top = Fmt.max(top, Fmt.max(Ops.m_abs(Ops.elem(Ops.elem(rs, i), 4)), Ops.m_abs(Ops.elem(Ops.elem(rs, i), 3))))
      end
      Ops.m_push(self.at_rows, here)
      Ops.m_push(self.w_discs, w_disc)
      Ops.m_push(self.w_gases, w_gas)
      Ops.m_push(self.repro, (Ops.gt(top, 0) ? Ops.div(worst, top) : 0))
      tab = []
      Simulation.TABLE.times do |t|
        base = Ops.add(Ops.elem(self.tabled_at, j), Ops.mul(t, n))
        gd = sum_at.(->(a) {
          return Ops.elem(pulls, Ops.add(base, a))
        }, w_disc)
        gg = sum_at.(->(a) {
          return Ops.elem(pulls, Ops.add(base, a))
        }, w_gas)
        Ops.m_push(tab, [self.table_r(j, t), gd, gg, Simulation.bulge_at(rs, self.table_r(j, t))])
      end
      Ops.m_push(self.tables, tab)
    end
  end
