  def self.lift_coefficients(theory, deg)
    model = Model.new(theory: theory)
    e = model.settled(deg)
    line = model.fact("the space line nets")
    slope = (Ops.eq(line, nil) ? Float::NAN : model.at(Expr.d(line.to, "\\rho"), e))
    v = model.value_of("\\frac{a_{0}}{cH}", e)
    m = theory.medium(11, 96, 3, deg, 2)
    m.vacuum = true
    m.facing = true
    s = m.symbols(m.rho_inf, 0)
    rate = 0
    Ops.list(m.meets).each do |t|
      rate = Ops.add(rate, Ops.div(Ops.mul(m.share(t, s), t.doing.folds.at(s)), 2))
    end
    sf = Ops.mul(Ops.getattr(e, "\\sigma"), Ops.getattr(e, "F"))
    _D = theory.lattice.D
    return [Ops.div(Ops.mul(Ops.m_abs(slope), v), (Ops.mul(rate, _D))), Ops.div(Ops.mul(Ops.mul(4, sf), v), (Ops.mul(rate, _D))), Ops.m_abs(slope), v, rate, sf]
  end
  def self.hubble0
    return Ops.div(Ops.mul(Galaxies.H0, 1000), (Ops.mul(Sparc.KPC, 1000)))
  end
  def self.hubble_at(z)
    return Ops.mul(Simulation.hubble0, Ops.m_sqrt((Ops.sub(Ops.add(Ops.mul(Simulation.OMEGA_M, Ops.power((Ops.add(1, z)), 3)), 1), Simulation.OMEGA_M))))
  end
  def self.age_at(z)
    _L = Ops.sub(1, Simulation.OMEGA_M)
    x = Ops.mul(Ops.m_sqrt((Ops.div(_L, Simulation.OMEGA_M))), Ops.power((Ops.add(1, z)), (Ops.sub(0, 1.5))))
    return Ops.mul(Ops.div(2, (Ops.mul(Ops.mul(3, Simulation.hubble0), Ops.m_sqrt(_L)))), Ops.m_ln((Ops.add(x, Ops.m_sqrt((Ops.add(Ops.mul(x, x), 1)))))))
  end
  def self.a0_then(a0, z, how)
    if Ops.eq(how, "age")
      return Ops.div(Ops.mul(a0, Simulation.age_at(0)), Simulation.age_at(z))
    end
    if Ops.eq(how, "hubble")
      return Ops.div(Ops.mul(a0, Simulation.hubble_at(z)), Simulation.hubble0)
    end
    return a0
  end
  def self.epochs(shape, a0, how)
    return Ops.m_map(Sparc.discs, ->(d) {
      rd = Ops.div(d.Re, 1.678)
      gbar = Ops.mul(Ops.div(Ops.mul(Ops.mul(Ops.mul(Sparc.G_NEWTON, d.Mb), Ops.power(10, 11)), Sparc.MSUN), (Ops.power((Ops.mul(rd, Sparc.KPC)), 2))), Simulation.shape_at(shape, 1.678))
      a = Simulation.a0_then(a0, d.redshift, how)
      g = Ops.add(Ops.div(gbar, 2), Ops.m_sqrt((Ops.add(Ops.div(Ops.mul(gbar, gbar), 4), Ops.mul(gbar, a)))))
      return [d.redshift, gbar, d.fraction, d.err, (d.limit ? 1 : 0), Ops.sub(1, Ops.div(gbar, g))]
    })
  end
  def lift_test(kappa, a0)
    off = []
    self.ids.length.times do |j|
      Ops.elem(self.rows, j).length.times do |i|
        row = Ops.elem(Ops.elem(self.rows, j), i)
        if Ops.gt(Ops.elem(row, 6), 0)
          p = Ops.elem(Ops.elem(self.at_rows, j), i)
          q = Ops.elem(Ops.elem(self.seen_rows, j), i)
          gN = Ops.add(Ops.add(Ops.mul(Sparc.YD, Ops.elem(p, 0)), Ops.mul(Sparc.YB, Ops.elem(p, 2))), Ops.elem(p, 1))
          gs = Ops.add(Ops.add(Ops.mul(Sparc.YD, Ops.elem(q, 0)), Ops.mul(Sparc.YB, Ops.elem(q, 2))), Ops.elem(q, 1))
          a = Ops.add(a0, Ops.mul(kappa, Fmt.max(gs, 0)))
          g = (Ops.gt(gN, 0) ? Law.boost(gN, a) : ((Ops.lt(gN, 0) ? Ops.sub(0, Law.boost(Ops.sub(0, gN), a)) : 0)))
          v = Ops.m_sqrt(Fmt.max(Ops.mul(Ops.elem(row, 0), g), 0))
          if Ops.gt(v, 0)
            Ops.m_push(off, Fmt.log10(Ops.div(v, Ops.elem(row, 1))))
          end
        end
      end
    end
    return [Simulation.rms(off), Fmt.median(off)]
  end
  def law_table
    _A0 = Law.a0
    xs_ = Ops.getattr(Law.law.columns, "gN")
    ys_ = Ops.getattr(Law.law.columns, "g")
    n = Law.law.rows
    return Ops.m_concat(Ops.m_map(Ops.rng(n), ->(i) {
      return Ops.m_ln((Ops.div(Ops.elem(xs_, i), _A0)))
    }), Ops.m_map(Ops.rng(n), ->(i) {
      return Ops.m_ln((Ops.div(Ops.elem(ys_, i), _A0)))
    }))
  end
  def felt(gN)
