  def combo(j, c, n)
    _S = Sparc.sample.columns
    g = Ops.elem(self.ids, j)
    h = Ops.div((Ops.sub(n, 1)), 2)
    iy = Ops.mod(c, n)
    ib = Ops.mod(Ops.m_floor((Ops.div(c, n))), n)
    id = Ops.mod(Ops.m_floor((Ops.div(c, (Ops.mul(n, n))))), n)
    ii = Ops.m_floor((Ops.div(c, (Ops.mul(Ops.mul(n, n), n)))))
    return [Ops.add(Ops.elem(self.centre_y, j), Ops.mul(Ops.mul((Ops.sub(iy, h)), Simulation.STEP_Y), self.spacing)), Ops.add(Ops.elem(self.centre_b, j), Ops.mul(Ops.mul((Ops.sub(ib, h)), Simulation.STEP_Y), self.spacing)), Ops.add(Ops.elem(self.centre_d, j), Ops.mul(Ops.mul(Ops.mul((Ops.sub(id, h)), Simulation.STEP_D), self.spacing), Ops.elem(Ops.getattr(_S, "e_D"), g))), Ops.add(Ops.elem(self.centre_i, j), Ops.mul(Ops.mul(Ops.mul((Ops.sub(ii, h)), Simulation.STEP_I), self.spacing), Ops.elem(Ops.getattr(_S, "e_Inc"), g)))]
  end
  def logpost(j, at)
    _S = Sparc.sample.columns
    g = Ops.elem(self.ids, j)
    _D = Ops.elem(Ops.getattr(_S, "D"), g)
    eD = Ops.elem(Ops.getattr(_S, "e_D"), g)
    inc = Ops.elem(Ops.getattr(_S, "Inc"), g)
    einc = Ops.elem(Ops.getattr(_S, "e_Inc"), g)
    if ((Ops.le(Ops.elem(at, 2), 0) || Ops.le(Ops.elem(at, 3), 0.5)) || Ops.gt(Ops.elem(at, 3), 90))
      return Ops.mul((-1), Ops.power(10, 30))
    end
    _YD = Ops.power(10, Ops.elem(at, 0))
    _YB = Ops.power(10, Ops.elem(at, 1))
    f = Ops.div(Ops.elem(at, 2), _D)
    s = Ops.div(Ops.m_sin((Ops.div(Ops.mul(inc, Math::PI), 180))), Ops.m_sin((Ops.div(Ops.mul(Ops.elem(at, 3), Math::PI), 180))))
    chi = 0
    Ops.elem(self.rows, j).length.times do |i|
      row = Ops.elem(Ops.elem(self.rows, j), i)
      if Ops.gt(Ops.elem(row, 6), 0)
        p = Ops.elem(Ops.elem(self.at_rows, j), i)
        vm = Ops.m_sqrt(Fmt.max(Ops.mul(Ops.mul(f, Ops.elem(row, 0)), self.felt(Ops.add(Ops.add(Ops.mul(_YD, Ops.elem(p, 0)), Ops.mul(_YB, Ops.elem(p, 2))), Ops.elem(p, 1)))), 0))
        d = Ops.div((Ops.sub(Ops.mul(Ops.elem(row, 1), s), vm)), (Ops.mul(Ops.elem(row, 2), s)))
        chi = Ops.add(chi, Ops.mul(d, d))
      end
    end
    py = Ops.div((Ops.sub(Ops.elem(at, 0), Fmt.log10(Sparc.YD))), Simulation.PRIOR_Y)
    pb = (self.has_bulge(j) ? Ops.div((Ops.sub(Ops.elem(at, 1), Fmt.log10(Sparc.YB))), Simulation.PRIOR_Y) : 0)
    pd = (Ops.gt(eD, 0) ? Ops.div((Ops.sub(Ops.elem(at, 2), _D)), eD) : 0)
    pi = (Ops.gt(einc, 0) ? Ops.div((Ops.sub(Ops.elem(at, 3), inc)), einc) : 0)
    return Ops.mul((-0.5), (Ops.add(Ops.add(Ops.add(Ops.add(chi, Ops.mul(py, py)), Ops.mul(pb, pb)), Ops.mul(pd, pd)), Ops.mul(pi, pi))))
  end
  def settle_fit(best, n, last)
    self.ids.length.times do |j|
      at = self.combo(j, Ops.m_round(Ops.elem(best, Ops.mul(2, j))), n)
      Ops.set_at(self.centre_y, j, Ops.elem(at, 0))
      Ops.set_at(self.centre_b, j, Ops.elem(at, 1))
      Ops.set_at(self.centre_d, j, Ops.elem(at, 2))
      Ops.set_at(self.centre_i, j, Ops.elem(at, 3))
    end
    self.spacing = Ops.div(self.spacing, 4)
    if last
      self.best_y = Ops.m_map(self.centre_y, ->(v) {
        return Ops.power(10, v)
      })
      self.best_b = Ops.m_map(self.centre_b, ->(v) {
        return Ops.power(10, v)
      })
      self.best_d = Ops.m_map(self.centre_d, ->(v) {
        return v
      })
      self.best_i = Ops.m_map(self.centre_i, ->(v) {
        return v
      })
    end
  end
