  end
  def self.image_side
    _I = Simulation.pixels
    return (Ops.eq(_I, nil) ? 0 : Ops.m_round(Ops.m_sqrt((Ops.div(_I.rows, Sparc.names.length)))))
  end
  def face_on(g, j)
    _O = Simulation.orientation
    _I = Simulation.pixels
    if (Ops.eq(_O, nil) || Ops.eq(_I, nil))
      return [[], Float::NAN, (-1)]
    end
    which = Ops.elem(Ops.getattr(_O.columns, "survey"), g)
    if Ops.lt(which, 0)
      return [[], Float::NAN, (-1)]
    end
    _P = Simulation.image_side
    fov = Ops.elem(Ops.getattr(_O.columns, "fov"), g)
    _D = Ops.elem(Ops.getattr(Sparc.sample.columns, "D"), g)
    inc = Ops.div(Ops.mul(Ops.elem(Ops.getattr(Sparc.sample.columns, "Inc"), g), Math::PI), 180)
    per_pixel = Ops.mul(Ops.mul(Ops.div(Ops.mul(Ops.div(fov, _P), Math::PI), 180), _D), 1000)
    light = Ops.getattr(_I.columns, "light")
    base = Ops.mul(Ops.mul(g, _P), _P)
    edge = []
    _P.times do |r|
      _P.times do |c|
        if (((Ops.lt(r, Simulation.SKY_EDGE) || Ops.lt(c, Simulation.SKY_EDGE)) || Ops.ge(r, Ops.sub(_P, Simulation.SKY_EDGE))) || Ops.ge(c, Ops.sub(_P, Simulation.SKY_EDGE)))
          Ops.m_push(edge, Ops.elem(light, Ops.add(Ops.add(base, Ops.mul(r, _P)), c)))
        end
      end
    end
    sky = Fmt.median(edge)
    reach = Ops.elem(self.reach, j)
    east = ->(c) {
      return Ops.sub(0, Ops.mul((Ops.sub(Ops.add(c, 0.5), Ops.div(_P, 2))), per_pixel))
    }
    north = ->(r) {
      return Ops.mul((Ops.sub(Ops.add(r, 0.5), Ops.div(_P, 2))), per_pixel)
    }
    pa = Ops.elem(Ops.getattr(_O.columns, "pa"), g)
    if !(Fmt.finite(pa))
      xx = 0
      yy = 0
      xy = 0
      _P.times do |r|
        _P.times do |c|
          f = Fmt.max(Ops.sub(Ops.elem(light, Ops.add(Ops.add(base, Ops.mul(r, _P)), c)), sky), 0)
          e = east.(c)
          n = north.(r)
          if Ops.le(Fmt.hypot(e, n), reach)
            xx = Ops.add(xx, Ops.mul(Ops.mul(f, e), e))
            yy = Ops.add(yy, Ops.mul(Ops.mul(f, n), n))
            xy = Ops.add(xy, Ops.mul(Ops.mul(f, e), n))
          end
        end
      end
      pa = Ops.sub(90, Ops.div(Ops.mul(Ops.mul(0.5, Ops.m_atan2((Ops.mul(2, xy)), Ops.sub(xx, yy))), 180), Math::PI))
    end
    s = Ops.m_sin((Ops.div(Ops.mul(pa, Math::PI), 180)))
    co = Ops.m_cos((Ops.div(Ops.mul(pa, Math::PI), 180)))
    squash = Fmt.max(Ops.m_cos(inc), 0.2)
    out = []
    _P.times do |r|
      _P.times do |c|
        f = Ops.sub(Ops.elem(light, Ops.add(Ops.add(base, Ops.mul(r, _P)), c)), sky)
        e = east.(c)
        n = north.(r)
        x = Ops.add(Ops.mul(e, s), Ops.mul(n, co))
        y = Ops.div((Ops.add(Ops.sub(0, Ops.mul(e, co)), Ops.mul(n, s))), squash)
        if (Ops.gt(f, 0) && Ops.le(Fmt.hypot(x, y), reach))
          Ops.m_push(out, [x, y, f])
        end
      end
    end
    return [out, pa, which]
  end
  def film_seeds
    rng = Random.new(seed: 11)
    out = []
    self.film_sources = []
    self.film_angles = []
    stir = ->(unused) {
      mag = Ops.m_sqrt((Ops.mul((-2), Ops.m_ln(Fmt.max(rng.next, 0.000001)))))
      th = Ops.mul((2 * Math::PI), rng.next)
      return [Ops.mul(mag, Ops.m_cos(th)), Ops.mul(mag, Ops.m_sin(th))]
    }
    Ops.list(self.film_ids).each do |g|
      j = Ops.m_index_of(self.ids, g)
      laid = self.face_on(g, j)
      pixels = Ops.elem(laid, 0)
      if Ops.gt(pixels.length, 0)
        Ops.m_push(self.film_sources, Ops.elem(Simulation.SURVEY_NAMES, Ops.elem(laid, 2)))
        Ops.m_push(self.film_angles, Ops.elem(laid, 1))
        fs = Expr.sorted(Ops.m_map(pixels, ->(p) {
          return Ops.elem(p, 2)
        }))
        cap = Ops.elem(fs, Ops.m_floor((Ops.mul((Ops.sub(fs.length, 1)), Simulation.BRIGHTEST))))
        run = []
        total = 0
        Ops.list(pixels).each do |p|
          total = Ops.add(total, Fmt.min(Ops.elem(p, 2), cap))
          Ops.m_push(run, total)
        end
        _O = Simulation.orientation
        width = Ops.mul(Ops.mul(Ops.div(Ops.mul(Ops.div(Ops.elem(Ops.getattr(_O.columns, "fov"), g), Simulation.image_side), Math::PI), 180), Ops.elem(Ops.getattr(Sparc.sample.columns, "D"), g)), 1000)
        Simulation.FILM_STARS.times do |k|
          want = Ops.mul(rng.next, total)
          lo = 0
          hi = Ops.sub(run.length, 1)
          while Ops.lt(lo, hi)
            mid = Ops.m_floor((Ops.div((Ops.add(lo, hi)), 2)))
            if Ops.lt(Ops.elem(run, mid), want)
              lo = Ops.add(mid, 1)
            else
              hi = mid
            end
          end
          x = Ops.add(Ops.elem(Ops.elem(pixels, lo), 0), Ops.mul((Ops.sub(rng.next, 0.5)), width))
          y = Ops.add(Ops.elem(Ops.elem(pixels, lo), 1), Ops.mul((Ops.sub(rng.next, 0.5)), width))
          kick = stir.(0)
          Ops.list([Fmt.hypot(x, y), Ops.m_atan2(y, x), Ops.elem(kick, 0), Ops.elem(kick, 1), 0, 0, 0, 0, 0, 0]).each do |v|
            Ops.m_push(out, v)
          end
        end
      else
        Ops.m_push(self.film_sources, "the run's own annuli")
        Ops.m_push(self.film_angles, Float::NAN)
        es = Ops.elem(self.edges, j)
        rs = Ops.elem(self.rows, j)
        masses = []
        Ops.sub(es.length, 1).times do |a|
          Ops.m_push(masses, [Ops.elem(es, a), Ops.elem(es, Ops.add(a, 1)), Ops.add(Ops.mul(Sparc.YD, Ops.elem(Ops.elem(self.w_discs, j), a)), Ops.elem(Ops.elem(self.w_gases, j), a))])
        end
        last = 0
        rs.length.times do |i|
          inside = Ops.mul(Ops.mul(Ops.mul(Sparc.YB, Ops.elem(Ops.elem(rs, i), 5)), Ops.m_abs(Ops.elem(Ops.elem(rs, i), 5))), Ops.elem(Ops.elem(rs, i), 0))
          if Ops.gt(inside, last)
            Ops.m_push(masses, [(Ops.eq(i, 0) ? 0 : Ops.elem(Ops.elem(rs, Ops.sub(i, 1)), 0)), Ops.elem(Ops.elem(rs, i), 0), Ops.sub(inside, last)])
            last = inside
          end
        end
        run = []
        total = 0
        Ops.list(masses).each do |m|
          total = Ops.add(total, Fmt.max(Ops.elem(m, 2), 0))
          Ops.m_push(run, total)
        end
        Simulation.FILM_STARS.times do |k|
          want = Ops.mul(rng.next, total)
          a = 0
          while (Ops.lt(a, Ops.sub(run.length, 1)) && Ops.lt(Ops.elem(run, a), want))
            a = Ops.add(a, 1)
          end
          e0 = Ops.elem(Ops.elem(masses, a), 0)
          e1 = Ops.elem(Ops.elem(masses, a), 1)
          r = Ops.m_sqrt((Ops.add(Ops.mul(e0, e0), Ops.mul(rng.next, (Ops.sub(Ops.mul(e1, e1), Ops.mul(e0, e0)))))))
          kick = stir.(0)
          Ops.list([r, Ops.mul((2 * Math::PI), rng.next), Ops.elem(kick, 0), Ops.elem(kick, 1), 0, 0, 0, 0, 0, 0]).each do |v|
            Ops.m_push(out, v)
          end
        end
      end
    end
    return out
  end
  def film_table(felt_table)
    out = []
    Ops.list(self.film_ids).each do |g|
      j = Ops.m_index_of(self.ids, g)
      Simulation.TABLE.times do |t|
        Ops.m_push(out, Ops.elem(felt_table, Ops.add(Ops.mul(j, Simulation.TABLE), t)))
      end
    end
    return out
  end
  def film_runs(felt_table)
    out = []
    self.film_steps = []
    self.film_times = []
    self.film_ids.length.times do |k|
      j = Ops.m_index_of(self.ids, Ops.elem(self.film_ids, k))
      rs = Ops.elem(self.rows, j)
      inner = self.turn(felt_table, j, Ops.elem(Ops.elem(rs, 0), 0))
      outer = self.turn(felt_table, j, Ops.elem(Ops.elem(rs, Ops.sub(rs.length, 1)), 0))
      ok = ((Fmt.finite(inner) && Fmt.finite(outer)) && Ops.gt(inner, 0))
      total = (ok ? Ops.mul(Simulation.FILM_TURNS, outer) : 0)
      n = (ok ? Fmt.min(Simulation.CAP, Ops.add(Ops.m_floor((Ops.div(total, (Ops.div(inner, Simulation.PER_ORBIT))))), 1)) : 0)
      dt = (Ops.gt(n, 0) ? Ops.div(total, n) : 0)
      every = Fmt.max(1, Ops.m_floor((Ops.div(n, Simulation.FRAMES))))
      last = Ops.elem(Ops.elem(self.tables, j), Ops.sub(Simulation.TABLE, 1))
      edge = Ops.add(Ops.add(Ops.mul(Sparc.YD, Ops.elem(last, 1)), Ops.mul(Sparc.YB, Ops.elem(last, 3))), Ops.elem(last, 2))
      Ops.m_push(self.film_steps, Ops.mul(every, Simulation.FRAMES))
      Ops.m_push(self.film_times, Ops.mul(Ops.mul(Ops.mul(dt, every), Simulation.FRAMES), Simulation.MYR))
      Ops.list([Ops.elem(self.reach, j), dt, Ops.mul(every, Simulation.FRAMES), Ops.mul(every, Simulation.FRAMES), k, edge, self.a0, every, 0, Simulation.SIGMA, 0, 0]).each do |v|
        Ops.m_push(out, v)
      end
    end
    return out
  end
  def most_film_steps
    m = 0
    Ops.list(self.film_steps).each do |n|
      m = Fmt.max(m, n)
    end
    return m
  end
  def save(felt0, felt1, stars, frames)
    _S = Sparc.sample.columns
    _T = Simulation.TABLE
    nrows = 0
    Ops.list(self.rows).each do |rs|
      nrows = Ops.add(nrows, rs.length)
    end
    cols = Node.new
    names = ["galaxy", "R", "Vobs", "e_Vobs", "gd", "gg", "gb", "v0", "v1", "vs", "kept"]
    Ops.list(names).each do |nm_|
      Ops.set_at(cols, nm_, [])
    end
    rms0 = []
    rms1 = []
    k = 0
    self.ids.length.times do |j|
      g = Ops.elem(self.ids, j)
      rs = Ops.elem(self.rows, j)
      es = Ops.elem(self.edges, j)
      f = Ops.div(Ops.elem(self.best_d, j), Ops.elem(Ops.getattr(_S, "D"), g))
      s = Ops.div(Ops.m_sin((Ops.div(Ops.mul(Ops.elem(Ops.getattr(_S, "Inc"), g), Math::PI), 180))), Ops.m_sin((Ops.div(Ops.mul(Ops.elem(self.best_i, j), Math::PI), 180))))
      heap = Ops.m_map(Ops.rng(rs.length), ->(i) {
        return []
      })
      Simulation.STARS.times do |q|
        at = Ops.mul((Ops.add(Ops.mul(j, Simulation.STARS), q)), 10)
        if Ops.gt(Ops.elem(stars, Ops.add(at, 8)), 0)
          r = Ops.div(Ops.elem(stars, Ops.add(at, 6)), Ops.elem(stars, Ops.add(at, 8)))
          v = Ops.div(Ops.elem(stars, Ops.add(at, 7)), Ops.elem(stars, Ops.add(at, 8)))
          b = 0
          while (Ops.lt(b, rs.length) && Ops.lt(Ops.elem(es, Ops.add(b, 2)), r))
            b = Ops.add(b, 1)
          end
          if Ops.lt(b, rs.length)
            Ops.m_push(Ops.elem(heap, b), v)
          end
        end
      end
      o0 = []
      o1 = []
      rs.length.times do |i|
        row = Ops.elem(rs, i)
        p = Ops.elem(Ops.elem(self.at_rows, j), i)
        v0 = Ops.m_sqrt(Fmt.max(Ops.mul(Ops.elem(row, 0), Ops.elem(felt0, k)), 0))
        v1 = Ops.div(Ops.m_sqrt(Fmt.max(Ops.mul(Ops.mul(f, Ops.elem(row, 0)), Ops.elem(felt1, k)), 0)), s)
        vs = (Ops.m_empty(Ops.elem(heap, i)) ? Float::NAN : Fmt.median(Ops.elem(heap, i)))
        vals = [g, Ops.elem(row, 0), Ops.elem(row, 1), Ops.elem(row, 2), Ops.elem(p, 0), Ops.elem(p, 1), Ops.elem(p, 2), v0, v1, vs, Ops.elem(row, 6)]
        names.length.times do |c|
          Ops.m_push(Ops.elem(cols, Ops.elem(names, c)), Ops.elem(vals, c))
        end
        if ((Ops.gt(Ops.elem(row, 6), 0) && Ops.gt(v0, 0)) && Ops.gt(v1, 0))
          Ops.m_push(o0, Fmt.log10(Ops.div(v0, Ops.elem(row, 1))))
          Ops.m_push(o1, Fmt.log10(Ops.div(v1, Ops.elem(row, 1))))
        end
        k = Ops.add(k, 1)
      end
      Ops.m_push(rms0, Simulation.rms(o0))
      Ops.m_push(rms1, Simulation.rms(o1))
    end
    extra = Node.new
    Ops.setattr(extra, "deg", self.deg)
    Ops.setattr(extra, "a0", self.a0_si)
    Ops.setattr(extra, "unit", Simulation.UNIT_G)
    Ops.setattr(extra, "ids", self.ids)
    Ops.setattr(extra, "names", Ops.m_map(self.ids, ->(g) {
      return Ops.elem(Sparc.names, g)
    }))
    Ops.setattr(extra, "Y_disk", self.best_y)
    Ops.setattr(extra, "Y_bulge", self.best_b)
    Ops.setattr(extra, "D", self.best_d)
    Ops.setattr(extra, "Inc", self.best_i)
    Ops.setattr(extra, "rms0", rms0)
    Ops.setattr(extra, "rms1", rms1)
    Ops.setattr(extra, "repro", self.repro)
    Ops.setattr(extra, "stir", Simulation.SIGMA)
    Ops.setattr(extra, "about", "every measured radius of every galaxy run: the laid galaxy's disc, gas and bulge pull (mass-to-light one, (km/s)^2/kpc), the circular speed at SPARC's own freedoms (v0) and at the fitted ones as the data would see them (v1), what the tracers moved at (vs); per galaxy in the header the fitted freedoms and the rms in dex")
    Measure.save("galaxy.simulated", names, cols, extra)
    fields = Node.new
    fnames = ["galaxy", "r", "gd", "gg", "gb", "v0", "v1", "vN"]
    Ops.list(fnames).each do |nm_|
      Ops.set_at(fields, nm_, [])
    end
    self.ids.length.times do |j|
      g = Ops.elem(self.ids, j)
      f = Ops.div(Ops.elem(self.best_d, j), Ops.elem(Ops.getattr(_S, "D"), g))
      s = Ops.div(Ops.m_sin((Ops.div(Ops.mul(Ops.elem(Ops.getattr(_S, "Inc"), g), Math::PI), 180))), Ops.m_sin((Ops.div(Ops.mul(Ops.elem(self.best_i, j), Math::PI), 180))))
      _T.times do |t|
        row = Ops.elem(Ops.elem(self.tables, j), t)
        gN = Ops.add(Ops.add(Ops.mul(Sparc.YD, Ops.elem(row, 1)), Ops.mul(Sparc.YB, Ops.elem(row, 3))), Ops.elem(row, 2))
        v0 = Ops.m_sqrt(Fmt.max(Ops.mul(Ops.elem(row, 0), Ops.elem(felt0, Ops.add(k, t))), 0))
        v1 = Ops.div(Ops.m_sqrt(Fmt.max(Ops.mul(Ops.mul(f, Ops.elem(row, 0)), Ops.elem(felt1, Ops.add(k, t))), 0)), s)
        vals = [g, Ops.elem(row, 0), Ops.elem(row, 1), Ops.elem(row, 2), Ops.elem(row, 3), v0, v1, Ops.m_sqrt(Fmt.max(Ops.mul(Ops.elem(row, 0), gN), 0))]
        fnames.length.times do |c|
          Ops.m_push(Ops.elem(fields, Ops.elem(fnames, c)), Ops.elem(vals, c))
        end
      end
      k = Ops.add(k, _T)
    end
    fextra = Node.new
    Ops.setattr(fextra, "ids", self.ids)
    Ops.setattr(fextra, "table", _T)
    Ops.setattr(fextra, "about", "the laid galaxy's field on the table, every galaxy run: disc, gas and bulge at mass-to-light one, the circular speed at SPARC's freedoms (v0), at the fitted ones as the data would see them (v1), and Newton at SPARC's (vN)")
    Measure.save("galaxy.fields", fnames, fields, fextra)
    if !(Ops.m_empty(self.film_ids))
      film = Node.new
      Ops.setattr(film, "x", [])
      Ops.setattr(film, "y", [])
      Ops.m_floor((Ops.div(frames.length, 2))).times do |i|
        Ops.m_push(Ops.getattr(film, "x"), Ops.elem(frames, Ops.mul(2, i)))
        Ops.m_push(Ops.getattr(film, "y"), Ops.elem(frames, Ops.add(Ops.mul(2, i), 1)))
      end
      sextra = Node.new
      Ops.setattr(sextra, "film", self.film_ids)
      Ops.setattr(sextra, "names", Ops.m_map(self.film_ids, ->(g) {
        return Ops.elem(Sparc.names, g)
      }))
      Ops.setattr(sextra, "stars", Simulation.FILM_STARS)
      Ops.setattr(sextra, "frames", Simulation.FRAMES)
      Ops.setattr(sextra, "reach", Ops.m_map(self.film_ids, ->(g) {
        return Ops.elem(self.reach, Ops.m_index_of(self.ids, g))
      }))
      Ops.setattr(sextra, "source", self.film_sources)
      Ops.setattr(sextra, "pa", self.film_angles)
      Ops.setattr(sextra, "span", self.film_times)
      Ops.setattr(sextra, "about", "the filmed galaxies face on, their stars laid where the light is (or the laid mass, where there is no image): x and y in kpc, star after star, frame after frame, from the moment the picture was taken, over FILM_TURNS of the outermost radius; span in Myr")
      return Measure.save("galaxy.stars", ["x", "y"], film, sextra)
    end
  end
  def self.rms(xs_)
    if Ops.m_empty(xs_)
      return Float::NAN
    end
    s = 0
    Ops.list(xs_).each do |v|
      s = Ops.add(s, Ops.mul(v, v))
    end
    return Ops.m_sqrt((Ops.div(s, xs_.length)))
  end
  def self.shape_x(i)
    return Ops.power(10, (Ops.add((-2), Ops.div(Ops.mul(3.6, i), Ops.sub(Simulation.SHAPE_N, 1)))))
  end
  def self.shape_edge(a)
    return Ops.div(Ops.mul(15, a), Simulation.SHAPE_EDGES)
  end
  def self.shape_mass(a)
    e0 = Simulation.shape_edge(a)
    e1 = Simulation.shape_edge(Ops.add(a, 1))
    return Ops.sub(Ops.mul((Ops.add(1, e0)), Ops.m_exp((Ops.sub(0, e0)))), Ops.mul((Ops.add(1, e1)), Ops.m_exp((Ops.sub(0, e1)))))
  end
  def self.shape_tasks
    out = []
    Simulation.SHAPE_N.times do |i|
      Simulation.SHAPE_EDGES.times do |a|
        Ops.list([Simulation.shape_x(i), Simulation.shape_edge(a), Simulation.shape_edge(Ops.add(a, 1)), Simulation.SHAPE_H]).each do |v|
          Ops.m_push(out, v)
        end
      end
    end
    return out
  end
  def self.shape_of(pulls)
    return Ops.m_map(Ops.rng(Simulation.SHAPE_N), ->(i) {
      s = 0
      Simulation.SHAPE_EDGES.times do |a|
        s = Ops.add(s, Ops.mul(Simulation.shape_mass(a), Ops.elem(pulls, Ops.add(Ops.mul(i, Simulation.SHAPE_EDGES), a))))
      end
      return s
    })
  end
  def self.shape_at(shape, x)
    lx = Fmt.log10(x)
    u = Ops.mul(Ops.div((Ops.add(lx, 2)), 3.6), Ops.sub(Simulation.SHAPE_N, 1))
    if Ops.le(u, 0)
      return Ops.div(Ops.mul(Ops.elem(shape, 0), x), Simulation.shape_x(0))
    end
    if Ops.ge(u, Ops.sub(Simulation.SHAPE_N, 1))
      return Ops.mul(Ops.elem(shape, Ops.sub(Simulation.SHAPE_N, 1)), Ops.power((Ops.div(Simulation.shape_x(Ops.sub(Simulation.SHAPE_N, 1)), x)), 2))
    end
    i = Ops.m_floor(u)
    f = Ops.sub(u, i)
    return Ops.add(Ops.mul(Ops.elem(shape, i), (Ops.sub(1, f))), Ops.mul(Ops.elem(shape, Ops.add(i, 1)), f))
  end
  def self.axis(a, i)
    return Ops.add(Ops.elem(a, 0), Ops.div(Ops.mul((Ops.sub(Ops.elem(a, 1), Ops.elem(a, 0))), i), Ops.sub(Ops.elem(a, 2), 1)))
  end
  def self.possible_points(shape)
    out = []
    Ops.elem(Simulation.MASSES, 2).times do |which_m|
      _M = Ops.power(10, Simulation.axis(Simulation.MASSES, which_m))
      Ops.elem(Simulation.SCALES, 2).times do |which_s|
        rd = Ops.power(10, Simulation.axis(Simulation.SCALES, which_s))
        Ops.list(Simulation.GAS).each do |fg|
          Ops.list(Simulation.GAS_WIDE).each do |wide|
            Ops.list(Simulation.BULGE).each do |fb|
              _GM = Ops.mul(Simulation.G_KPC, _M)
              disc = Ops.mul(Ops.mul(_GM, (Ops.sub(1, fg))), (Ops.sub(1, fb)))
              gas = Ops.mul(_GM, fg)
              bul = Ops.mul(Ops.mul(_GM, (Ops.sub(1, fg))), fb)
              rg = Ops.mul(rd, wide)
              Simulation.RADII.times do |k|
                r = Ops.mul(rd, Ops.power(10, (Ops.add((-0.7), Ops.div(Ops.mul(1.6, k), Ops.sub(Simulation.RADII, 1))))))
                gN = Ops.add(Ops.add(Ops.mul(Ops.div(disc, (Ops.mul(rd, rd))), Simulation.shape_at(shape, Ops.div(r, rd))), Ops.mul(Ops.div(gas, (Ops.mul(rg, rg))), Simulation.shape_at(shape, Ops.div(r, rg)))), Ops.div(bul, (Ops.power((Ops.add(r, Ops.mul(Simulation.BULGE_A, rd))), 2))))
                Ops.list([0, r, gN, 0, 0, 0]).each do |v|
                  Ops.m_push(out, v)
                end
              end
            end
          end
        end
      end
    end
    return out
  end
  def self.binned(points, felt)
    n = Ops.add(Ops.m_round((Ops.div((Ops.sub(Galaxies.XMAX, Galaxies.XMIN)), Simulation.BIN))), 1)
    landed = Ops.filled(n, 0)
    heights = Ops.filled(n, 0)
    lo = Ops.filled(n, Float::NAN)
    hi = Ops.filled(n, Float::NAN)
    felt.length.times do |i|
      gN = Ops.elem(points, Ops.add(Ops.mul(6, i), 2))
      g = Ops.elem(felt, i)
      if (Ops.gt(gN, 0) && Ops.gt(g, 0))
        x = Fmt.log10(Ops.div(Ops.mul(gN, Simulation.UNIT_G), Galaxies.A0_DATA))
        y = Fmt.log10(Ops.div(Ops.mul(g, Simulation.UNIT_G), Galaxies.A0_DATA))
        b = Ops.m_round((Ops.div((Ops.sub(x, Galaxies.XMIN)), Simulation.BIN)))
        if (Ops.ge(b, 0) && Ops.lt(b, n))
          Ops.set_at(landed, b, Ops.add(Ops.elem(landed, b), 1))
          Ops.set_at(heights, b, Ops.add(Ops.elem(heights, b), y))
          Ops.set_at(lo, b, (Fmt.finite(Ops.elem(lo, b)) ? Fmt.min(Ops.elem(lo, b), y) : y))
          Ops.set_at(hi, b, (Fmt.finite(Ops.elem(hi, b)) ? Fmt.max(Ops.elem(hi, b), y) : y))
        end
      end
    end
    return [landed, Ops.m_map(Ops.rng(n), ->(b) {
      return (Ops.gt(Ops.elem(landed, b), 0) ? Ops.div(Ops.elem(heights, b), Ops.elem(landed, b)) : Float::NAN)
    }), lo, hi]
  end
  def self.save_possible(degs, a0s, bins)
    cols = Node.new
    Ops.setattr(cols, "deg", degs)
    Ops.setattr(cols, "a0", a0s)
    extra = Node.new
    Ops.setattr(extra, "bins", bins)
    Ops.setattr(extra, "from", Galaxies.XMIN)
    Ops.setattr(extra, "step", Simulation.BIN)
    Ops.setattr(extra, "axes", ["log M (Msun)", Simulation.MASSES, "log R_d (kpc)", Simulation.SCALES, "gas share", Simulation.GAS, "gas scale / R_d", Simulation.GAS_WIDE, "bulge share of the stars", Simulation.BULGE])
    Ops.setattr(extra, "about", "every galaxy there could be, run through the same field and law, per lattice: in bins of log(g_bar / 1.2e-10), how many (galaxy, radius) land there, and log(g / 1.2e-10) - mean, lowest, highest")
    return Measure.save("galaxy.possible", ["deg", "a0"], cols, extra)
  end
  __exposed
end

