  def seeds
    rng = Random.new(seed: 23)
    out = []
    self.discs_n.times do |g|
      rd = self.scale(g)
      top = Formed.inside(Formed.TRUNC)
      Formed.N.times do |k|
        want = Ops.mul(rng.next, top)
        lo = 0
        hi = Formed.TRUNC
        40.times do |it|
          mid = Ops.div((Ops.add(lo, hi)), 2)
          if Ops.lt(Formed.inside(mid), want)
            lo = mid
          else
            hi = mid
          end
        end
        r = Ops.mul(Ops.div((Ops.add(lo, hi)), 2), rd)
        th = Ops.mul((2 * Math::PI), rng.next)
        Ops.list([Ops.mul(r, Ops.m_cos(th)), Ops.mul(r, Ops.m_sin(th)), 0, 0]).each do |v|
          Ops.m_push(out, v)
