      end
    end
    return out
  end
  def constants
    out = []
    self.discs_n.times do |g|
      Ops.list([Ops.div(self.GM(g), Formed.N), self.soft(g), self.scale_a0, Formed.DT]).each do |v|
        Ops.m_push(out, v)
      end
    end
    return out
  end
  def accel_cpu(state, i)
    g = Ops.m_floor((Ops.div(i, Formed.N)))
    e2 = Ops.mul(self.soft(g), self.soft(g))
    px = Ops.elem(state, Ops.mul(4, i))
    py = Ops.elem(state, Ops.add(Ops.mul(4, i), 1))
    sx = 0
    sy = 0
    Formed.N.times do |k|
      j = Ops.add(Ops.mul(g, Formed.N), k)
      dx = Ops.sub(Ops.elem(state, Ops.mul(4, j)), px)
      dy = Ops.sub(Ops.elem(state, Ops.add(Ops.mul(4, j), 1)), py)
      r2 = Ops.add(Ops.add(Ops.mul(dx, dx), Ops.mul(dy, dy)), e2)
      w = Ops.div(1, (Ops.mul(r2, Ops.m_sqrt(r2))))
      sx = Ops.add(sx, Ops.mul(dx, w))
      sy = Ops.add(sy, Ops.mul(dy, w))
    end
    m = Ops.div(self.GM(g), Formed.N)
    gx = Ops.mul(m, sx)
    gy = Ops.mul(m, sy)
    mag = Fmt.hypot(gx, gy)
    f = (Ops.gt(mag, 0) ? ((self.newton ? mag : Law.boost(mag, self.a0))) : 0)
    return (Ops.gt(mag, 0) ? [Ops.mul(Ops.div(gx, mag), f), Ops.mul(Ops.div(gy, mag), f), mag, f] : [0, 0, 0, 0])
  end
  def launch(state, acc)
    rng = Random.new(seed: 29)
    out = Ops.m_map(state, ->(v) {
      return v
    })
    self.discs_n.times do |g|
      rd = self.scale(g)
      width = Ops.div(Ops.mul(Formed.TRUNC, rd), Formed.RINGS)
      pull = Ops.filled(Formed.RINGS, 0)
      lift = Ops.filled(Formed.RINGS, 0)
      many = Ops.filled(Formed.RINGS, 0)
      Formed.N.times do |k|
        i = Ops.add(Ops.mul(g, Formed.N), k)
        x = Ops.elem(state, Ops.mul(4, i))
        y = Ops.elem(state, Ops.add(Ops.mul(4, i), 1))
        r = Fmt.hypot(x, y)
        b = Ops.m_floor((Ops.div(r, width)))
        if (Ops.lt(b, Formed.RINGS) && Ops.gt(r, 0))
          Ops.set_at(pull, b, Ops.add(Ops.elem(pull, b), Ops.div((Ops.sub(Ops.sub(0, Ops.mul(Ops.elem(acc, Ops.mul(4, i)), x)), Ops.mul(Ops.elem(acc, Ops.add(Ops.mul(4, i), 1)), y))), r)))
          Ops.set_at(lift, b, Ops.add(Ops.elem(lift, b), ((Ops.gt(Ops.elem(acc, Ops.add(Ops.mul(4, i), 2)), 0) ? Ops.div(Ops.elem(acc, Ops.add(Ops.mul(4, i), 3)), Ops.elem(acc, Ops.add(Ops.mul(4, i), 2))) : 1))))
          Ops.set_at(many, b, Ops.add(Ops.elem(many, b), 1))
        end
      end
      ring_r = ->(b) {
        return Ops.mul((Ops.add(b, 0.5)), width)
      }
      omega2 = Ops.m_map(Ops.rng(Formed.RINGS), ->(b) {
        return (Ops.gt(Ops.elem(many, b), 0) ? Ops.div(Fmt.max(Ops.div(Ops.elem(pull, b), Ops.elem(many, b)), 0), ring_r.(b)) : 0)
      })
      nu = Ops.m_map(Ops.rng(Formed.RINGS), ->(b) {
        return (Ops.gt(Ops.elem(many, b), 0) ? Ops.div(Ops.elem(lift, b), Ops.elem(many, b)) : 1)
      })
      kappa2 = Ops.m_map(Ops.rng(Formed.RINGS), ->(b) {
        lo = Fmt.max(Ops.sub(b, 1), 0)
        hi = Fmt.min(Ops.add(b, 1), Ops.sub(Formed.RINGS, 1))
        slope = Ops.div((Ops.sub(Ops.elem(omega2, hi), Ops.elem(omega2, lo))), (Ops.sub(ring_r.(hi), ring_r.(lo))))
        return Fmt.max(Ops.add(Ops.mul(ring_r.(b), slope), Ops.mul(4, Ops.elem(omega2, b))), Ops.mul(0.25, Ops.elem(omega2, b)))
      })
      sigma_gm = Ops.div(self.GM(g), (Ops.mul(Ops.mul(Ops.mul(Ops.mul(2, Math::PI), rd), rd), Formed.inside(Formed.TRUNC))))
      Formed.N.times do |k|
        i = Ops.add(Ops.mul(g, Formed.N), k)
        x = Ops.elem(state, Ops.mul(4, i))
        y = Ops.elem(state, Ops.add(Ops.mul(4, i), 1))
        r = Fmt.hypot(x, y)
        b = Fmt.min(Ops.m_floor((Ops.div(r, width))), Ops.sub(Formed.RINGS, 1))
        o2 = Ops.elem(omega2, b)
        k2 = Ops.elem(kappa2, b)
        surface = Ops.mul(sigma_gm, Ops.m_exp((Ops.sub(0, Ops.div(r, rd)))))
        sr = (Ops.gt(k2, 0) ? Ops.div(Ops.mul(Ops.mul(Ops.mul(Formed.Q, 3.36), Ops.elem(nu, b)), surface), Ops.m_sqrt(k2)) : 0)
        sp = (Ops.gt(o2, 0) ? Ops.div(Ops.mul(sr, Ops.m_sqrt(k2)), (Ops.mul(2, Ops.m_sqrt(o2)))) : 0)
        vc2 = Ops.mul(Ops.mul(o2, r), r)
        vphi = Ops.m_sqrt(Fmt.max(Ops.add(vc2, Ops.mul(Ops.mul(sr, sr), (Ops.sub(Ops.sub(1, ((Ops.gt(o2, 0) ? Ops.div(k2, (Ops.mul(4, o2))) : 1))), Ops.div(Ops.mul(2, r), rd))))), 0))
        mag = Ops.m_sqrt((Ops.mul((-2), Ops.m_ln(Fmt.max(rng.next, 0.000001)))))
        th = Ops.mul((2 * Math::PI), rng.next)
        vr = Ops.mul(Ops.mul(sr, mag), Ops.m_cos(th))
        vt = Ops.add(vphi, Ops.mul(Ops.mul(sp, mag), Ops.m_sin(th)))
        ux = (Ops.gt(r, 0) ? Ops.div(x, r) : 1)
        uy = (Ops.gt(r, 0) ? Ops.div(y, r) : 0)
        Ops.set_at(out, Ops.add(Ops.mul(4, i), 2), Ops.sub(Ops.mul(vr, ux), Ops.mul(vt, uy)))
        Ops.set_at(out, Ops.add(Ops.mul(4, i), 3), Ops.add(Ops.mul(vr, uy), Ops.mul(vt, ux)))
      end
      4.times do |slot|
        mean = 0
        Formed.N.times do |k|
          mean = Ops.add(mean, Ops.elem(out, Ops.add(Ops.mul(4, (Ops.add(Ops.mul(g, Formed.N), k))), slot)))
        end
        mean = Ops.div(mean, Formed.N)
        Formed.N.times do |k|
          Ops.set_at(out, Ops.add(Ops.mul(4, (Ops.add(Ops.mul(g, Formed.N), k))), slot), Ops.sub(Ops.elem(out, Ops.add(Ops.mul(4, (Ops.add(Ops.mul(g, Formed.N), k))), slot)), mean))
        end
      end
    end
    return out
  end
  def middles(*args_)
