    out = Ops.filled(Ops.mul(Ops.mul(self.discs_n, _G), _G), 0)
    here = []
    self.discs_n.times do |g|
      half = Ops.mul(Formed.SPAN, self.scale(g))
      mid = [0, 0, 0, 0]
      Formed.N.times do |k|
        4.times do |slot|
          Ops.set_at(mid, slot, Ops.add(Ops.elem(mid, slot), Ops.div(Ops.elem(state, Ops.add(Ops.mul(4, (Ops.add(Ops.mul(g, Formed.N), k))), slot)), Formed.N)))
        end
      end
      Ops.m_push(here, mid)
      Formed.N.times do |k|
        i = Ops.add(Ops.mul(g, Formed.N), k)
        cx = Ops.m_floor((Ops.mul(Ops.div((Ops.add(Ops.sub(Ops.elem(state, Ops.mul(4, i)), Ops.elem(mid, 0)), half)), (Ops.mul(2, half))), _G)))
        cy = Ops.m_floor((Ops.mul(Ops.div((Ops.add(Ops.sub(Ops.elem(state, Ops.add(Ops.mul(4, i), 1)), Ops.elem(mid, 1)), half)), (Ops.mul(2, half))), _G)))
        if (((Ops.ge(cx, 0) && Ops.ge(cy, 0)) && Ops.lt(cx, _G)) && Ops.lt(cy, _G))
          at = Ops.add(Ops.add(Ops.mul(Ops.mul(g, _G), _G), Ops.mul(cy, _G)), cx)
          Ops.set_at(out, at, Ops.add(Ops.elem(out, at), 1))
        end
      end
    end
    Ops.m_push(self.middles, here)
