  def save(frames)
    _G = Formed.GRID
    density = []
    self.discs_n.times do |g|
      Ops.list(frames).each do |f|
        Ops.mul(_G, _G).times do |c|
          Ops.m_push(density, Ops.elem(f, Ops.add(Ops.mul(Ops.mul(g, _G), _G), c)))
        end
      end
    end
    cols = Node.new
    Ops.setattr(cols, "density", density)
    extra = Node.new
    Ops.setattr(extra, "names", Formed.WHAT)
    Ops.setattr(extra, "mass", Ops.m_map(Formed.DISCS, ->(d) {
      return Ops.power(10, Ops.elem(d, 0))
    }))
    Ops.setattr(extra, "scale", Ops.m_map(Formed.DISCS, ->(d) {
      return Ops.elem(d, 1)
    }))
    Ops.setattr(extra, "span", Ops.m_map(Formed.DISCS, ->(d) {
      return Ops.mul(Formed.SPAN, Ops.elem(d, 1))
    }))
    Ops.setattr(extra, "stars", Formed.N)
    Ops.setattr(extra, "Q", Formed.Q)
    Ops.setattr(extra, "frames", frames.length)
    Ops.setattr(extra, "grid", _G)
    Ops.setattr(extra, "gyr", Ops.div(Ops.mul(Ops.mul(Formed.STEPS, Formed.DT), Simulation.MYR), 1000))
    Ops.setattr(extra, "middles", self.middles)
    Ops.setattr(extra, "deg", self.deg)
    Ops.setattr(extra, "a0", Ops.mul(self.a0, Simulation.UNIT_G))
    Ops.setattr(extra, "about", "discs of stars that pull each other through the law, from smooth to whatever forms: star counts on grid x grid cells, span kpc either side of the middle, frame after frame, galaxy after galaxy")
