  end
  def self.kernel
    return Ops.m_join(["// GENERATED from Formed.ray: stars that pull each other through the law", "@group(0) @binding(0) var<storage, read> P: array<u32>;", "@group(0) @binding(1) var<storage, read> L: array<f32>;", "@group(0) @binding(2) var<storage, read> C: array<f32>;", "@group(0) @binding(3) var<storage, read_write> X: array<f32>;", "@group(0) @binding(4) var<storage, read_write> A: array<f32>;", "var<workgroup> tile: array<vec2<f32>, #{Formed.TILE}>;", Simulation.law_wgsl, "@compute @workgroup_size(#{Formed.TILE}) fn ACCEL(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {", "  let i: u32 = P[7] + gid.x;", "  let per: u32 = P[1];", "  let g: u32 = i / per;", "  let base: u32 = g * per;", "  let me: vec2<f32> = vec2<f32>(X[4u * i], X[4u * i + 1u]);", "  let e2: f32 = C[4u * g + 1u] * C[4u * g + 1u];", "  var s: vec2<f32> = vec2<f32>(0.0, 0.0);", "  for (var t: u32 = 0u; t < per; t = t + #{Formed.TILE}u) {", "    let j: u32 = base + t + lid.x;", "    tile[lid.x] = vec2<f32>(X[4u * j], X[4u * j + 1u]);", "    workgroupBarrier();", "    for (var k: u32 = 0u; k < #{Formed.TILE}u; k = k + 1u) {", "      let d: vec2<f32> = tile[k] - me;", "      let inv: f32 = inverseSqrt(dot(d, d) + e2);", "      s = s + d * (inv * inv * inv);", "    }", "    workgroupBarrier();", "  }", "  let gN: vec2<f32> = C[4u * g] * s;", "  let mag: f32 = length(gN);", "  var a: vec2<f32> = vec2<f32>(0.0, 0.0);", "  var f: f32 = 0.0;", "  if (mag > 0.0) {", "    f = mag;", "    if (C[4u * g + 2u] > 0.0) { f = felt(mag, C[4u * g + 2u]); }", "    a = gN / mag * f;", "  }", "  A[4u * i] = a.x;", "  A[4u * i + 1u] = a.y;", "  A[4u * i + 2u] = mag;", "  A[4u * i + 3u] = f;", "}", "#{Simulation.ENTRY} KICKDRIFT#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let dt: f32 = C[4u * (i / P[1]) + 3u];", "  X[4u * i + 2u] = X[4u * i + 2u] + 0.5 * A[4u * i] * dt;", "  X[4u * i + 3u] = X[4u * i + 3u] + 0.5 * A[4u * i + 1u] * dt;", "  X[4u * i] = X[4u * i] + X[4u * i + 2u] * dt;", "  X[4u * i + 1u] = X[4u * i + 1u] + X[4u * i + 3u] * dt;", "}", "#{Simulation.ENTRY} KICK#{Simulation.ID}", Simulation.THREAD, "  if (i >= P[0]) { return; }", "  let dt: f32 = C[4u * (i / P[1]) + 3u];", "  X[4u * i + 2u] = X[4u * i + 2u] + 0.5 * A[4u * i] * dt;", "  X[4u * i + 3u] = X[4u * i + 3u] + 0.5 * A[4u * i + 1u] * dt;", "}"], "\n")
  end
  __exposed
end

class Model < Node
  def theory(*args_)
    args_.empty? ? @theory : @theory.(*args_)
  end
  attr_writer :theory
  def self.NAMES
    @NAMES = (["\\langle\\rho\\rangle", "D", "DEG", "l.DEG", "\\nu", "\\sigma", "F", "\\bar{c}", "m'", "A'", "\\bar{R}'", "m_{\\Sigma}", "m_{\\Sigma}'", "\\mathcal{D}", "\\mathcal{D}'", "\\beta'", "\\beta\\cdot\\hat{d}", "\\beta'\\cdot\\hat{d}", "\\rho", "\\omega", "R", "r", "\\bar{r}", "\\bar{m}_{x}", "A", "\\bar{R}", "\\beta", "n_{f}", "\\sigma_{tr}", "L", "m", "\\delta", "g_{N}", "a_{0}", "\\Phi"]) unless instance_variable_defined?(:@NAMES)
    @NAMES
  end
  def self.NAMES=(v)
    @NAMES = v
  end
  def self.RD
    @RD = (30) unless instance_variable_defined?(:@RD)
    @RD
  end
  def self.RD=(v)
    @RD = v
  end
  def store(*args_)
    @store = (Prover.new(theory: self.theory).closure) unless instance_variable_defined?(:@store)
    args_.empty? ? @store : @store.(*args_)
  end
  attr_writer :store
  def cache(*args_)
    @cache = (Node.new) unless instance_variable_defined?(:@cache)
    args_.empty? ? @cache : @cache.(*args_)
  end
  attr_writer :cache
  def fact(of_)
    found = nil
    Ops.list(self.store.all("is")).each do |f|
      if (Ops.eq(found, nil) && Ops.eq(f.of, of_))
        found = f
      end
    end
    return found
  end
  def self.copy(env)
    out = Node.new
    Ops.list(Model.NAMES).each do |k|
      if !Ops.eq(Ops.elem(env, k), nil)
        Ops.set_at(out, k, Ops.elem(env, k))
      end
    end
    return out
  end
  def self.lattice(e)
    k = e.kind
    if (Ops.eq(k, "add") || Ops.eq(k, "mul"))
      out = Expr.new(kind: k)
      out.of = Ops.m_map(e.of, ->(x) {
        return Model.lattice(x)
      })
      return out
    end
    if Ops.eq(k, "pow")
      return Expr.to_power(Model.lattice(e.base), Model.lattice(e.power))
    end
    if ((((Ops.eq(k, "grad") || Ops.eq(k, "log")) || Ops.eq(k, "exp")) || Ops.eq(k, "root")) || Ops.eq(k, "limit"))
      out = Expr.new(kind: k)
      out.base = Model.lattice(e.base)
      out.bound = e.bound
      return out
    end
    if Ops.eq(k, "choose")
      return Expr.choose(Model.lattice(e.first_), Model.lattice(e.second_))
    end
    if Ops.eq(k, "gammaInc")
      return Expr.gamma_inc(Model.lattice(e.first_), Model.lattice(e.second_))
    end
    if Ops.eq(k, "call")
      inner = Model.lattice(e.base)
      return (Ops.eq(e.label, "l.choose") ? inner : Expr.call(e.label, inner))
    end
    return e
  end
  def self.unbound(e)
    out = []
    Model.walk_names(e, out)
    return out
  end
  def self.walk_names(e, out)
    k = e.kind
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      if !(Ops.m_contains(out, e.label))
        Ops.m_push(out, e.label)
      end
    else
      if (Ops.eq(k, "add") || Ops.eq(k, "mul"))
        Ops.list(e.of).each do |x|
          Model.walk_names(x, out)
        end
      else
        if Ops.eq(k, "pow")
          Model.walk_names(e.base, out)
          return Model.walk_names(e.power, out)
        else
          if ((((Ops.eq(k, "grad") || Ops.eq(k, "log")) || Ops.eq(k, "exp")) || Ops.eq(k, "root")) || Ops.eq(k, "limit"))
            return Model.walk_names(e.base, out)
          else
            if (Ops.eq(k, "choose") || Ops.eq(k, "gammaInc"))
              Model.walk_names(e.first_, out)
              return Model.walk_names(e.second_, out)
            else
              if Ops.eq(k, "call")
                called = "#{e.label}\\paren{...}"
                if !(Ops.m_contains(out, called))
                  Ops.m_push(out, called)
                end
                return Model.walk_names(e.base, out)
              end
            end
          end
        end
      end
    end
  end
  def resolved(e, env, seen)
    if Ops.gt(seen.length, 8)
      return e
    end
    missing = Ops.filt(Model.unbound(e), ->(n) {
      return ((Ops.eq(Ops.elem(env, n), nil) && !(Ops.m_contains(seen, n))) && !(Ops.m_ends_with(n, "\\paren{...}")))
    })
    out = e
    grew = false
    Ops.list(missing).each do |n|
      f = self.fact(n)
      if !Ops.eq(f, nil)
        out = Expr.replace(out, n, self.resolved(f.to, env, Ops.m_concat(seen, [n])))
        grew = true
      end
    end
    return (grew ? out : e)
  end
  def ready(*args_)
    @ready = (Node.new) unless instance_variable_defined?(:@ready)
    args_.empty? ? @ready : @ready.(*args_)
  end
  attr_writer :ready
  def prepared(e, env)
    bound = Ops.m_join(Ops.filt(Model.NAMES, ->(k) {
      return !Ops.eq(Ops.elem(env, k), nil)
    }), ",")
    shown = Expr.show(e)
    key = "#{shown}|#{bound}"
    hit = Ops.elem(self.ready, key)
    if !Ops.eq(hit, nil)
      return hit
    end
    out = Model.lattice(self.resolved(e, env, []))
    Ops.set_at(self.ready, key, out)
    return out
  end
  def at(e, env)
    return Expr.numeric(self.prepared(e, env), env)
  end
  def value_of(name, env)
    f = self.fact(name)
    return (Ops.eq(f, nil) ? Float::NAN : self.at(f.to, env))
  end
  def settled(_DEG = nil)
    deg = Ops.or_else(_DEG) { self.theory.lattice.DEG }
    base = Node.new
    Ops.setattr(base, "D", self.theory.lattice.D)
    Ops.setattr(base, "DEG", deg)
    Ops.setattr(base, "l.DEG", deg)
    Ops.setattr(base, "\\nu", 1)
    Ops.setattr(base, "\\sigma", 1)
    Ops.setattr(base, "F", 0.5)
    Ops.setattr(base, "\\bar{c}", 1)
    Ops.setattr(base, "m'", 1)
    Ops.setattr(base, "A'", 1)
    Ops.setattr(base, "\\bar{R}'", 1)
    Ops.setattr(base, "m_{\\Sigma}", 1)
    Ops.setattr(base, "m_{\\Sigma}'", 1)
    Ops.setattr(base, "\\mathcal{D}", 1)
    Ops.setattr(base, "\\mathcal{D}'", 1)
    Ops.setattr(base, "\\beta'", 0)
    Ops.setattr(base, "\\beta\\cdot\\hat{d}", 0)
    Ops.setattr(base, "\\beta'\\cdot\\hat{d}", 0)
    rho = self.fact("\\rho_{\\infty}")
    if !Ops.eq(rho, nil)
      Ops.setattr(base, "\\rho", self.at(rho.to, base))
    end
    om = self.fact("\\omega")
    if !Ops.eq(om, nil)
      Ops.setattr(base, "\\omega", self.at(om.to, base))
    end
    far = Model.copy(base)
    Ops.setattr(far, "R", Ops.power(10, 12))
    Ops.setattr(far, "r", Ops.power(10, 12))
    Ops.setattr(far, "\\bar{r}", Ops.power(10, 12))
    Ops.setattr(far, "\\bar{m}_{x}", 1)
    Ops.setattr(far, "A", 1)
    Ops.setattr(far, "\\bar{R}", 0)
    Ops.setattr(far, "\\beta", 0)
    Ops.list(["n_{f}", "\\sigma_{tr}", "L"]).each do |n|
      f = self.fact(n)
      if !Ops.eq(f, nil)
        Ops.set_at(far, n, self.at(f.to, far))
      end
    end
    return far
  end
  def a0_lattice
    if !Ops.eq(Ops.getattr(self.cache, "a0"), nil)
      return Ops.getattr(self.cache, "a0")
    end
    a0 = self.fact("a_{0}")
    Ops.setattr(self.cache, "a0", (Ops.eq(a0, nil) ? Float::NAN : self.at(a0.to, self.settled(self.theory.lattice.DEG))))
    return Ops.getattr(self.cache, "a0")
  end
  def boost(gN, a0)
    _F = self.fact("F_{g}")
    if Ops.eq(_F, nil)
      return Float::NAN
    end
    env = Node.new
    Ops.setattr(env, "D", self.theory.lattice.D)
    Ops.setattr(env, "DEG", self.theory.lattice.DEG)
    Ops.setattr(env, "g_{N}", gN)
    Ops.setattr(env, "a_{0}", a0)
    got = self.at(_F.to, env)
    if (((!(Fmt.finite(got)) && Fmt.finite(gN)) && Ops.gt(gN, 0)) && Fmt.finite(a0))
      left = Model.unbound(Expr.simplify(Expr.evaluate(_F.to, env)))
      leans = (Ops.m_empty(left) ? "something" : Ops.m_join(left, ", "))
      fail.("the law came to #{got} at g_N = #{gN}: #{_F.of} leans on #{leans} and this seam binds none of it. Its derived form has changed - bind the new name here or fix the rule.")
    end
    return got
  end
  def delivered_by(sep, m, _A)
    key = "#{Fmt.exponential(sep, 2)}|#{m}|#{_A}"
    hit = Ops.elem(self.cache, key)
    if !Ops.eq(hit, nil)
      return hit
    end
    e = Node.new
    Ops.setattr(e, "D", self.theory.lattice.D)
    Ops.setattr(e, "DEG", self.theory.lattice.DEG)
    Ops.setattr(e, "\\bar{c}", 1)
    Ops.setattr(e, "\\bar{m}_{x}", 1)
    Ops.setattr(e, "\\beta", 0)
    Ops.setattr(e, "m'", 1)
    Ops.setattr(e, "A'", 1)
    Ops.setattr(e, "m_{\\Sigma}", 1)
    Ops.setattr(e, "m_{\\Sigma}'", 1)
    Ops.setattr(e, "\\beta'", 0)
    Ops.setattr(e, "\\beta\\cdot\\hat{d}", 0)
    Ops.setattr(e, "\\beta'\\cdot\\hat{d}", 0)
    Ops.setattr(e, "R", sep)
    Ops.setattr(e, "r", sep)
    Ops.setattr(e, "\\bar{r}", sep)
    Ops.setattr(e, "A", _A)
    Ops.setattr(e, "m", m)
    Ops.setattr(e, "\\bar{R}", Ops.div(m, _A))
    Ops.list(["\\nu", "\\sigma", "F"]).each do |rate|
      g = self.fact(rate)
      if !Ops.eq(g, nil)
        Ops.set_at(e, rate, self.at(g.to, e))
      end
    end
    rho = self.fact("\\rho_{\\infty}")
    if !Ops.eq(rho, nil)
      Ops.setattr(e, "\\rho", self.at(rho.to, e))
    end
    step = ->(name, into) {
      g = self.fact(name)
      if !Ops.eq(g, nil)
        Ops.set_at(e, into, self.at(g.to, e))
      end
    }
    step.("n_{f}", "n_{f}")
    step.("\\sigma_{tr}", "\\sigma_{tr}")
    step.("L", "L")
    step.("what a body puts into the medium", "\\delta")
    step.("\\rho at R", "\\rho")
    step.("n_{f}", "n_{f}")
    step.("\\sigma_{tr}", "\\sigma_{tr}")
    step.("L", "L")
    step.("g_{N}", "g_{N}")
    step.("a_{0}", "a_{0}")
    out = [Ops.getattr(e, "g_{N}"), Ops.getattr(e, "a_{0}")]
    Ops.set_at(self.cache, key, out)
    return out
  end
  def self.surface(r, _M, rd)
    return Ops.div(Ops.mul(_M, Ops.m_exp((Ops.sub(0, Ops.div(r, rd))))), (Ops.mul(Ops.mul(Ops.mul(2, Math::PI), rd), rd)))
  end
  def as_point_parts(_R, _M, rd)
    one_ = self.delivered_by(_R, _M, Ops.mul(Ops.mul(Math::PI, rd), rd))
    return [Ops.elem(one_, 0), self.boost(Ops.elem(one_, 0), Ops.elem(one_, 1))]
  end
  def as_stars_parts(_R, _M, rd)
    rings = 16
    spokes = 24
    rmax = Ops.mul(8, rd)
    gN = 0
    rings.times do |i|
      r = Ops.div(Ops.mul(rmax, (Ops.add(i, 0.5))), rings)
      dr = Ops.div(rmax, rings)
      dm = Ops.mul(Ops.mul(Ops.mul(Ops.mul(2, Math::PI), r), dr), Model.surface(r, _M, rd))
      if Ops.gt(dm, 0)
        spokes.times do |k|
          th = Ops.div(Ops.mul(Ops.mul(2, Math::PI), (Ops.add(k, 0.5))), spokes)
          dx = Ops.sub(_R, Ops.mul(r, Ops.m_cos(th)))
          dy = Ops.sub(0, Ops.mul(r, Ops.m_sin(th)))
          sep = Fmt.hypot(dx, dy)
          if Ops.ge(sep, 1)
            one_ = self.delivered_by(sep, 1, 1)
            if Fmt.finite(Ops.elem(one_, 0))
              gN = Ops.add(gN, Ops.mul(Ops.mul((Ops.div(dm, spokes)), Ops.elem(one_, 0)), (Ops.div(dx, sep))))
            end
          end
        end
      end
    end
    a0 = Ops.elem(self.delivered_by(_R, _M, Ops.mul(Ops.mul(Math::PI, rd), rd)), 1)
    return [gN, self.boost(gN, a0)]
  end
  def self.speed(g, _R)
    return (Ops.gt(g, 0) ? Ops.m_sqrt((Ops.mul(_R, g))) : Float::NAN)
  end
  __exposed
end

class Axis < Node
  def lo(*args_)
    args_.empty? ? @lo : @lo.(*args_)
  end
  attr_writer :lo
  def hi(*args_)
    args_.empty? ? @hi : @hi.(*args_)
  end
  attr_writer :hi
  def n(*args_)
    args_.empty? ? @n : @n.(*args_)
  end
  attr_writer :n
  def linear(*args_)
    @linear = (false) unless instance_variable_defined?(:@linear)
    args_.empty? ? @linear : @linear.(*args_)
  end
  attr_writer :linear
  def value(i)
    t = (Ops.gt(self.n, 1) ? Ops.div(i, (Ops.sub(self.n, 1))) : 0.5)
    v = Ops.add(self.lo, Ops.mul((Ops.sub(self.hi, self.lo)), t))
    return (self.linear ? v : Ops.power(10, v))
  end
  def mid
    v = Ops.add(self.lo, Ops.mul((Ops.sub(self.hi, self.lo)), 0.5))
    return (self.linear ? v : Ops.power(10, v))
  end
  def values
    return Ops.m_map(Ops.rng(self.n), ->(i) {
      return self.value(i)
    })
  end
  __exposed
end

class Shaded < Node
  def self.literal(n)
    if !Ops.eq(n, n)
      return "1e30"
    end
    if Ops.gt(Ops.m_abs(n), Ops.power(10, 300))
      return (Ops.lt(n, 0) ? "(-1e30)" : "1e30")
    end
    if (Ops.eq(n, Ops.m_floor(n)) && Ops.lt(Ops.m_abs(n), 1000000000))
      return "(#{n}.0)"
    end
    return "(#{n})"
  end
  def self.wgsl(e, names, bound)
    k = e.kind
    if Ops.eq(k, "num")
      return Shaded.literal(e.value)
    end
    if (Ops.eq(k, "sym") || Ops.eq(k, "field"))
      if (!Ops.eq(bound, nil) && Ops.eq(e.label, bound))
        return "x"
      end
      i = Ops.m_index_of(names, e.label)
      if Ops.eq(i, nil)
        fail.("the law stands on #{e.label}, which the sweep does not bind")
      end
      return "e[#{i}]"
    end
    if Ops.eq(k, "add")
      parts = Ops.m_map(e.of, ->(x) {
        return Shaded.wgsl(x, names, bound)
      })
      summed = Ops.m_join(parts, " + ")
      return "(#{summed})"
    end
    if Ops.eq(k, "mul")
      parts = Ops.m_map(e.of, ->(x) {
        return Shaded.wgsl(x, names, bound)
      })
      multiplied = Ops.m_join(parts, " * ")
      return "(#{multiplied})"
    end
    if Ops.eq(k, "pow")
      base = Shaded.wgsl(e.base, names, bound)
      if Ops.eq(e.power.kind, "num")
        n = e.power.value
        if Ops.eq(n, 0.5)
          return "sqrt(#{base})"
        end
        if (Ops.eq(n, Ops.m_floor(n)) && Ops.le(Ops.m_abs(n), 64))
          return "powi(#{base}, #{Ops.m_round(n)})"
        end
        return "pow(#{base}, #{Shaded.literal(n)})"
      end
      return "pow(#{base}, #{Shaded.wgsl(e.power, names, bound)})"
    end
    if Ops.eq(k, "log")
      return "log(#{Shaded.wgsl(e.base, names, bound)})"
    end
    if Ops.eq(k, "exp")
      return "exp(#{Shaded.wgsl(e.base, names, bound)})"
    end
    if Ops.eq(k, "choose")
      return "choose(#{Shaded.wgsl(e.first_, names, bound)}, #{Shaded.wgsl(e.second_, names, bound)})"
    end
    return fail.("a #{k} cannot be written as shader code - only a root at the top of a law is solved there")
  end
  def self.helpers
    return "fn powi(b: f32, n: i32) -> f32 {\n  var r: f32 = 1.0;\n  let m: i32 = abs(n);\n  for (var i: i32 = 0; i < m; i = i + 1) { r = r * b; }\n  if (n < 0) { return 1.0 / r; }\n  return r;\n}\nfn choose(n: f32, k: f32) -> f32 {\n  var r: f32 = 1.0;\n  var i: f32 = 0.0;\n  for (var c: i32 = 0; c < 64; c = c + 1) { if (i < k) { r = r * (n - i) / (i + 1.0); i = i + 1.0; } }\n  return r;\n}\nfn finite(v: f32) -> bool { return abs(v) < 1e30 && v == v; }"
  end
  def self.points
    points = []
    i = 1
    while Ops.le(i, 120)
      Ops.m_push(points, Ops.div(i, 120))
      i = Ops.add(i, 1)
    end
    ex = 0
    while Ops.le(ex, 24)
      k = 1
      while Ops.lt(k, 8)
        Ops.m_push(points, Ops.mul((Ops.power(10, (Ops.sub(ex, 12)))), (Ops.add(1, Ops.div(k, 2)))))
        k = Ops.add(k, 1)
      end
      ex = Ops.add(ex, 1)
    end
    return Expr.sorted(points)
  end
  def self.solver(name, f)
    pts = Shaded.points
    lits = Ops.m_join(Ops.m_map(pts, ->(v) {
      return Shaded.literal(v)
    }), ", ")
    return "const PTS_#{name}: array<f32, #{pts.length}> = array<f32, #{pts.length}>(#{lits});\nfn #{name}() -> f32 {\n  var lo: f32 = 0.0;\n  var hi: f32 = 0.0;\n  var found: bool = false;\n  var px: f32 = PTS_#{name}[0];\n  var pf: f32 = #{f}(px);\n  for (var j: i32 = 1; j < #{pts.length}; j = j + 1) {\n    let cx: f32 = PTS_#{name}[j];\n    let cf: f32 = #{f}(cx);\n    if (!found && finite(pf) && finite(cf) && pf * cf <= 0.0) { lo = px; hi = cx; found = true; }\n    px = cx;\n    pf = cf;\n  }\n  if (!found) { return 1e30; }\n  var flo: f32 = #{f}(lo);\n  for (var n: i32 = 0; n < 60; n = n + 1) {\n    let mid: f32 = (lo + hi) / 2.0;\n    let fm: f32 = #{f}(mid);\n    if (!finite(fm)) { break; }\n    if (flo * fm <= 0.0) { hi = mid; } else { lo = mid; flo = fm; }\n  }\n  return (lo + hi) / 2.0;\n}"
  end
  __exposed
end

