  attr_writer :env
  def self.base_env(model)
    base = Node.new
    Ops.setattr(base, "D", model.theory.lattice.D)
    Ops.setattr(base, "DEG", model.theory.lattice.DEG)
    Ops.setattr(base, "\\bar{c}", 1)
    Ops.setattr(base, "m'", 1)
    Ops.setattr(base, "A'", 1)
    Ops.setattr(base, "\\bar{R}'", 1)
    Ops.setattr(base, "m_{\\Sigma}", 1)
    Ops.setattr(base, "m_{\\Sigma}'", 1)
    Ops.setattr(base, "\\mathcal{D}", 1)
    Ops.setattr(base, "\\mathcal{D}'", 1)
    Ops.setattr(base, "\\beta'", 0)
    Ops.setattr(base, "\\beta\\cdot\\hat{d}", 0)
    Ops.setattr(base, "\\beta'\\cdot\\hat{d}", 0)
    Ops.list(["\\nu", "\\sigma", "F"]).each do |rate|
      g = model.fact(rate)
      if !Ops.eq(g, nil)
        Ops.set_at(base, rate, model.at(g.to, base))
      end
    end
    rho = model.fact("\\rho_{\\infty}")
    if !Ops.eq(rho, nil)
      Ops.setattr(base, "\\rho", model.at(rho.to, base))
    end
    om = model.fact("\\omega")
    if !Ops.eq(om, nil)
      Ops.setattr(base, "\\omega", model.at(om.to, base))
    end
    Ops.setattr(base, "\\bar{m}_{x}", 1)
    Ops.setattr(base, "A", 1)
    Ops.setattr(base, "\\bar{R}", 0)
    Ops.setattr(base, "\\beta", 0)
    return base
  end
  def self.axes_of
    axes = Node.new
    Ops.setattr(axes, "mass", Axis.new(lo: 2, hi: 9, n: 46))
    Ops.setattr(axes, "face", Axis.new(lo: 1, hi: 6, n: 28))
    moving = Axis.new(lo: 0, hi: 0.9, n: 5)
    moving.linear = true
    Ops.setattr(axes, "moving", moving)
    Ops.setattr(axes, "radiating", Axis.new(lo: (-2), hi: 2, n: 5))
    return axes
  end
  def dx
    return Ops.div((Ops.sub(self.X1, self.X0)), (Ops.sub(self.XS, 1)))
  end
  def dy
    return Ops.div((Ops.sub(self.Y1, self.Y0)), (Ops.sub(self.YS, 1)))
  end
  def point(k, m, _A, beta, _S0)
    e = Model.copy(Ops.elem(self.env, k))
    Ops.setattr(e, "m", m)
    Ops.setattr(e, "A", _A)
    Ops.setattr(e, "\\bar{R}", Ops.div(m, _A))
    Ops.setattr(e, "\\beta", beta)
    Ops.setattr(e, "m_{\\Sigma}", _S0)
    Ops.setattr(e, "m_{\\Sigma}'", _S0)
    return e
  end
  def crossed(m, _A)
    out = Ops.filled(self.RS, 0)
    total = 0
    last = 0
    self.RS.times do |k|
      e = self.point(k, m, _A, 0, 1)
      r = self.model.at(self.rho_at.to, e)
      here = (((Fmt.finite(r) && Ops.gt(r, 0)) && Ops.le(r, 1)) ? r : Ops.getattr(self.base, "\\rho"))
      if Ops.gt(k, 0)
        total = Ops.add(total, Ops.mul(Ops.mul(0.5, (Ops.add(here, last))), (Ops.sub(Ops.elem(self.rad, k), Ops.elem(self.rad, Ops.sub(k, 1))))))
      end
      last = here
      Ops.set_at(out, k, (Ops.eq(k, 0) ? here : Ops.div(total, Ops.elem(self.rad, k))))
    end
    return out
  end
  def landing(k, m, _A, beta, _S0, avg_k)
    e = self.point(k, m, _A, beta, _S0)
    gN = self.model.at(self.arrival.to, e)
    Ops.setattr(e, "g_{N}", gN)
    Ops.setattr(e, "\\langle\\rho\\rangle", avg_k)
    Ops.setattr(e, "a_{0}", self.model.at(self.scale.to, e))
    g = self.model.at(self.felt.to, e)
    return [(Ops.gt(gN, 0) ? Fmt.log10(Ops.div(gN, self.a0)) : Float::NAN), (Ops.gt(g, 0) ? Fmt.log10(Ops.div(g, self.a0)) : Float::NAN)]
  end
  def steps(vary, k)
    return (Ops.m_contains(vary, k) ? Ops.elem(self.axes, k).n : 1)
  end
  def pick(vary, k, i)
    return (Ops.m_contains(vary, k) ? Ops.elem(self.axes, k).value(i) : Ops.elem(self.axes, k).mid)
  end
  def rasterise(xs_, ys_, tracks)
    grid = Ops.filled(Ops.mul(self.XS, self.YS), 0)
    dx = self.dx
    dy = self.dy
    _RS = self.RS
    tracks.times do |tr|
      at0 = Ops.mul(tr, _RS)
      Ops.sub(_RS, 1).times do |k|
        xa = Ops.elem(xs_, Ops.add(at0, k))
        xb = Ops.elem(xs_, Ops.add(Ops.add(at0, k), 1))
        ya = Ops.elem(ys_, Ops.add(at0, k))
        yb = Ops.elem(ys_, Ops.add(Ops.add(at0, k), 1))
        if (((Fmt.finite(xa) && Fmt.finite(xb)) && Fmt.finite(ya)) && Fmt.finite(yb))
          st = Fmt.max(1, Ops.sub(0, Ops.m_floor((Ops.sub(0, Fmt.max(Ops.div(Ops.m_abs((Ops.sub(xb, xa))), dx), Ops.div(Ops.m_abs((Ops.sub(yb, ya))), dy)))))))
          st.times do |t|
            f = Ops.div((Ops.add(t, 0.5)), st)
            gx = Ops.m_round((Ops.div((Ops.sub(Ops.add(xa, Ops.mul(f, (Ops.sub(xb, xa)))), self.X0)), dx)))
            gy = Ops.m_round((Ops.div((Ops.sub(Ops.add(ya, Ops.mul(f, (Ops.sub(yb, ya)))), self.Y0)), dy)))
            if !(((((Ops.lt(gx, 0) || Ops.lt(gy, 0)) || Ops.ge(gx, self.XS)) || Ops.ge(gy, self.YS))))
              Ops.set_at(grid, Ops.add(Ops.mul(gy, self.XS), gx), Ops.add(Ops.elem(grid, Ops.add(Ops.mul(gy, self.XS), gx)), Ops.div(1, st)))
            end
          end
        end
      end
    end
    return grid
  end
  def tracks(vary)
    nM = self.steps(vary, "mass")
    nA = self.steps(vary, "face")
    nB = self.steps(vary, "moving")
    nS = self.steps(vary, "radiating")
    xs_ = []
    ys_ = []
    nM.times do |mi|
      m = self.pick(vary, "mass", mi)
      nA.times do |ai|
        _A = self.pick(vary, "face", ai)
        avg = self.crossed(m, _A)
        nB.times do |bi|
          beta = self.pick(vary, "moving", bi)
          nS.times do |si|
            _S0 = self.pick(vary, "radiating", si)
            self.RS.times do |k|
              got = self.landing(k, m, _A, beta, _S0, Ops.elem(avg, k))
              Ops.m_push(xs_, Ops.elem(got, 0))
              Ops.m_push(ys_, Ops.elem(got, 1))
            end
          end
        end
      end
    end
    out = Node.new
    Ops.setattr(out, "xs", xs_)
    Ops.setattr(out, "ys", ys_)
    Ops.setattr(out, "tracks", Ops.mul(Ops.mul(Ops.mul(nM, nA), nB), nS))
    return out
  end
  def needs(grid, without)
    need = Ops.filled(Ops.mul(self.XS, self.YS), 0)
    without.length.times do |k|
      g = Ops.elem(without, k)
      need.length.times do |i|
        if (Ops.gt(Ops.elem(grid, i), 0) && !((Ops.gt(Ops.elem(g, i), 0))))
          Ops.set_at(need, i, Ops.add(Ops.elem(need, i), Ops.power(2, k)))
        end
      end
    end
    return need
  end
  def save(id, grid, need)
    x = []
    y = []
    p = []
    by = []
    self.YS.times do |gy|
      self.XS.times do |gx|
        Ops.m_push(x, Ops.add(self.X0, Ops.mul(gx, self.dx)))
        Ops.m_push(y, Ops.add(self.Y0, Ops.mul(gy, self.dy)))
        Ops.m_push(p, Ops.elem(grid, Ops.add(Ops.mul(gy, self.XS), gx)))
        Ops.m_push(by, Ops.elem(need, Ops.add(Ops.mul(gy, self.XS), gx)))
      end
    end
    most = 0
    Ops.list(p).each do |v|
      if Ops.gt(v, most)
        most = v
      end
    end
    columns = Node.new
    Ops.setattr(columns, "x", x)
    Ops.setattr(columns, "y", y)
    Ops.setattr(columns, "p", p)
    Ops.setattr(columns, "by", by)
    extra = Node.new
    Ops.setattr(extra, "a0", self.a0)
    Ops.setattr(extra, "arrangement", self.how)
    Ops.setattr(extra, "most", most)
    arrives = Node.new
    Ops.setattr(arrives, "from", self.X0)
    Ops.setattr(arrives, "to", self.X1)
    Ops.setattr(arrives, "n", self.XS)
    felt_axis = Node.new
    Ops.setattr(felt_axis, "from", self.Y0)
    Ops.setattr(felt_axis, "to", self.Y1)
    Ops.setattr(felt_axis, "n", self.YS)
    grid_meta = Node.new
    Ops.setattr(grid_meta, "arrives", arrives)
    Ops.setattr(grid_meta, "felt", felt_axis)
    Ops.setattr(extra, "grid", grid_meta)
    Ops.setattr(extra, "freedoms", self.order)
    Ops.setattr(extra, "stages", ["nought is: reachable several ways; otherwise one bit per freedom, in the order of `freedoms`, for each one that is NECESSARY there"])
    Ops.setattr(extra, "about", "how much of the possible lands at each pair of what arrives and what is felt, and `by` is which freedom that cell NEEDS - found by taking each one away in turn, so it does not depend on any order they might be added in")
    return Measure.save(id, ["x", "y", "p", "by"], columns, extra)
  end
  def probe
    e = self.point(0, 1, 1, 0, 1)
    Ops.setattr(e, "g_{N}", 1)
    Ops.setattr(e, "a_{0}", 1)
    return e
  end
  def names
    out = []
    e0 = self.probe
    Ops.list([self.model.prepared(self.rho_at.to.base, e0), self.model.prepared(self.arrival.to, e0), self.model.prepared(self.felt.to, e0), self.model.prepared(self.scale.to, e0)]).each do |x|
      Ops.list(Model.unbound(x)).each do |n|
        if !(Ops.m_contains(out, n))
          Ops.m_push(out, n)
        end
      end
    end
    Ops.list(["g_{N}", "a_{0}", "\\rho", "\\langle\\rho\\rangle"]).each do |n|
      if !(Ops.m_contains(out, n))
        Ops.m_push(out, n)
      end
    end
    return out
  end
  def constants
    return Ops.m_map(self.names, ->(n) {
      return (Ops.eq(Ops.elem(self.base, n), nil) ? Float::NAN : Ops.elem(self.base, n))
    })
  end
  def slot(n)
    i = Ops.m_index_of(self.names, n)
    return (Ops.eq(i, nil) ? (-1) : i)
  end
  def radii
    out = []
    self.RS.times do |k|
      e = Ops.elem(self.env, k)
      Ops.m_push(out, Ops.elem(self.rad, k))
      Ops.m_push(out, Ops.or_else(Ops.getattr(e, "n_{f}")) { Float::NAN })
      Ops.m_push(out, Ops.or_else(Ops.getattr(e, "\\sigma_{tr}")) { Float::NAN })
      Ops.m_push(out, Ops.or_else(Ops.getattr(e, "L")) { Float::NAN })
    end
    return out
  end
  def kernel
    names = self.names
    _NV = names.length
    e0 = self.probe
    f_rho = Shaded.wgsl(self.model.prepared(self.rho_at.to.base, e0), names, self.rho_at.to.bound)
    f_arr = Shaded.wgsl(self.model.prepared(self.arrival.to, e0), names, nil)
    f_felt = Shaded.wgsl(self.model.prepared(self.felt.to, e0), names, nil)
    f_scale = Shaded.wgsl(self.model.prepared(self.scale.to, e0), names, nil)
    savg = self.slot("\\langle\\rho\\rangle")
    sR = self.slot("R")
    sr = self.slot("r")
    srb = self.slot("\\bar{r}")
    snf = self.slot("n_{f}")
    sst = self.slot("\\sigma_{tr}")
    sL = self.slot("L")
    sm = self.slot("m")
    sA = self.slot("A")
    sRb = self.slot("\\bar{R}")
    sb = self.slot("\\beta")
    sS = self.slot("m_{\\Sigma}")
    sS2 = self.slot("m_{\\Sigma}'")
    sgN = self.slot("g_{N}")
    sa0 = self.slot("a_{0}")
    srho = self.slot("\\rho")
    set = ->(i, v) {
      return (Ops.lt(i, 0) ? "" : "e[#{i}] = #{v};")
    }
    helpers = Shaded.helpers
    solver = Shaded.solver("solve_rho", "f_rho")
    sigma = Ops.getattr(self.base, "\\sigma")
    ambient = Ops.getattr(self.base, "\\rho")
    r_R = set.(sR, "rad[4u * k]")
    r_r = set.(sr, "rad[4u * k]")
    r_rb = set.(srb, "rad[4u * k]")
    r_nf = set.(snf, "rad[4u * k + 1u]")
    r_st = set.(sst, "rad[4u * k + 2u]")
    r_L = set.(sL, "rad[4u * k + 3u]")
    radius = "#{r_R} #{r_r} #{r_rb} #{r_nf} #{r_st} #{r_L}"
    s_m = set.(sm, "m")
    s_A = set.(sA, "A")
    s_Rb = set.(sRb, "m / A")
    s_b = set.(sb, "beta")
    s_S = set.(sS, "S0")
    s_S2 = set.(sS2, "S0")
    source = "#{s_m} #{s_A} #{s_Rb} #{s_b} #{s_S} #{s_S2}"
    set_gN = set.(sgN, "gN")
    sigma_lit = Shaded.literal(sigma)
    set_avg = set.(savg, "avg[pair * P.RS + k]")
    scale_call = "f_scale()"
    set_scale = set.(sa0, scale_call)
    set_a0 = "#{set_avg} #{set_scale}"
    ambient_lit = Shaded.literal(ambient)
    a0_lit = Shaded.literal(self.a0)
    fill = "for (var i: u32 = 0u; i < #{_NV}u; i = i + 1u) { e[i] = C[i]; }"
    return Ops.m_join(["// GENERATED by `npx ray measure` from the closed theory: the possibility space, swept on the device", "struct Par { RS: u32, nM: u32, nA: u32, nB: u32, nS: u32, pad0: u32, pad1: u32, pad2: u32 }", "@group(0) @binding(0) var<storage, read> P: Par;", "@group(0) @binding(1) var<storage, read> C: array<f32>;", "@group(0) @binding(2) var<storage, read> rad: array<f32>;", "@group(0) @binding(3) var<storage, read> ax: array<f32>;", "@group(0) @binding(4) var<storage, read_write> avg: array<f32>;", "@group(0) @binding(5) var<storage, read_write> xs: array<f32>;", "@group(0) @binding(6) var<storage, read_write> ys: array<f32>;", "var<private> e: array<f32, #{_NV}>;", helpers, "fn f_rho(x: f32) -> f32 { return #{f_rho}; }", "fn f_arrival() -> f32 { return #{f_arr}; }", "fn f_felt() -> f32 { return #{f_felt}; }", "fn f_scale() -> f32 { return #{f_scale}; }", solver, "@compute @workgroup_size(64) fn PROFILE(@builtin(global_invocation_id) gid: vec3<u32>) {\n  let i: u32 = gid.y * 1024u * 64u + gid.x;\n  if (i >= P.nM * P.nA) { return; }\n  let mi: u32 = i / P.nA;\n  let ai: u32 = i % P.nA;\n  let m: f32 = ax[mi];\n  let A: f32 = ax[P.nM + ai];\n  let beta: f32 = 0.0;\n  let S0: f32 = 1.0;\n  #{fill}\n  var total: f32 = 0.0;\n  var last: f32 = 0.0;\n  for (var k: u32 = 0u; k < P.RS; k = k + 1u) {\n    #{radius}\n    #{source}\n    let r: f32 = solve_rho();\n    var here: f32 = #{ambient_lit};\n    if (finite(r) && r > 0.0 && r <= 1.0) { here = r; }\n    if (k > 0u) { total = total + 0.5 * (here + last) * (rad[4u * k] - rad[4u * (k - 1u)]); }\n    last = here;\n    if (k == 0u) { avg[i * P.RS + k] = here; } else { avg[i * P.RS + k] = total / rad[4u * k]; }\n  }\n}", "@compute @workgroup_size(64) fn TRACK(@builtin(global_invocation_id) gid: vec3<u32>) {\n  let i: u32 = gid.y * 1024u * 64u + gid.x;\n  let per: u32 = P.nB * P.nS * P.RS;\n  if (i >= P.nM * P.nA * per) { return; }\n  let pair: u32 = i / per;\n  let rest: u32 = i % per;\n  let bi: u32 = rest / (P.nS * P.RS);\n  let si: u32 = (rest / P.RS) % P.nS;\n  let k: u32 = rest % P.RS;\n  let mi: u32 = pair / P.nA;\n  let ai: u32 = pair % P.nA;\n  let m: f32 = ax[mi];\n  let A: f32 = ax[P.nM + ai];\n  let beta: f32 = ax[P.nM + P.nA + bi];\n  let S0: f32 = ax[P.nM + P.nA + P.nB + si];\n  #{fill}\n  #{radius}\n  #{source}\n  let gN: f32 = f_arrival();\n  #{set_gN}\n  #{set_a0}\n  let g: f32 = f_felt();\n  var lx: f32 = 1e30;\n  var ly: f32 = 1e30;\n  if (finite(gN) && gN > 0.0) { lx = log(gN / #{a0_lit}) / log(10.0); }\n  if (finite(g) && g > 0.0) { ly = log(g / #{a0_lit}) / log(10.0); }\n  xs[i] = lx;\n  ys[i] = ly;\n}"], "\n\n")
  end
  __exposed
end

class Measure < Node
  def self.save(id, names, columns, extra)
    rows = Ops.elem(columns, Ops.elem(names, 0)).length
    Ops.list(names).each do |n|
      if !Ops.eq(Ops.elem(columns, n).length, rows)
        fail.("#{id}: #{n} has #{Ops.elem(columns, n).length} rows where #{Ops.elem(names, 0)} has #{rows}")
      end
      if !(Ops.m_some(Ops.elem(columns, n), ->(v) {
        return Fmt.finite(v)
      }))
        fail.("#{id}: column #{n} is not a number anywhere - the model did not answer, and a field of NaN drawn as a blank panel is worse than a failed run")
      end
    end
    return Measured.save("visuals", id, id, names, columns, extra)
  end
  def self.density(model, id, how)
    sweep = Sweep.new(model: model, how: how)
    if ((Ops.eq(sweep.arrival, nil) || Ops.eq(sweep.felt, nil)) || Ops.eq(sweep.rho_at, nil))
      fail.("#{id}: nothing derived to integrate")
    end
    lay = ->(vary) {
      got = sweep.tracks(vary)
      return sweep.rasterise(Ops.getattr(got, "xs"), Ops.getattr(got, "ys"), Ops.getattr(got, "tracks"))
    }
    grid = lay.(sweep.order)
    without = Ops.m_map(sweep.order, ->(held) {
      return lay.(Ops.filt(sweep.order, ->(n) {
        return !Ops.eq(n, held)
      }))
    })
    return sweep.save(id, grid, sweep.needs(grid, without))
  end
  def self.law(model)
    a0 = model.a0_lattice
    gN = []
    g = []
    901.times do |i|
      x = Ops.mul(Ops.power(10, (Ops.add((-5), Ops.div(Ops.mul(9, i), 900)))), a0)
      Ops.m_push(gN, x)
      Ops.m_push(g, model.boost(x, a0))
    end
    _DEG = model.theory.lattice.DEG
    e = model.settled(_DEG)
    Ops.setattr(e, "D", model.theory.lattice.D)
    Ops.setattr(e, "DEG", _DEG)
    symbols = Node.new
    Ops.setattr(symbols, "DEG", _DEG)
    Ops.setattr(symbols, "\\nu", Ops.getattr(e, "\\nu"))
    Ops.setattr(symbols, "\\sigma", Ops.getattr(e, "\\sigma"))
    Ops.setattr(symbols, "F", Ops.getattr(e, "F"))
    om = model.value_of("\\omega", e)
    Ops.setattr(symbols, "\\omega", (Fmt.finite(om) ? om : Ops.getattr(e, "\\omega")))
    Ops.setattr(symbols, "\\beta", 0)
    Ops.setattr(symbols, "\\rho", Ops.getattr(e, "\\rho"))
    Ops.list(["\\lambda", "n_{f}", "\\bar{m}_{l}"]).each do |n|
      v = model.value_of(n, e)
      if Fmt.finite(v)
        Ops.set_at(symbols, n, v)
      end
    end
    Ops.setattr(symbols, "\\bar{m}_{x}", 1)
    columns = Node.new
    Ops.setattr(columns, "gN", gN)
    Ops.setattr(columns, "g", g)
    extra = Node.new
    Ops.setattr(extra, "a0", a0)
    Ops.setattr(extra, "theory", model.theory.name)
    Ops.setattr(extra, "symbols", symbols)
    Ops.setattr(extra, "about", "what arrives against what is felt, both in units of a_0")
    Ops.setattr(extra, "carries", Aggregate.of(model.theory, _DEG, model.theory.lattice.D).carries)
    return Measure.save("law", ["gN", "g"], columns, extra)
  end
  def self.run(theory, only)
    model = Model.new(theory: theory)
    want = ->(n) {
      return (Ops.m_empty(only) || Ops.m_some(only, ->(o) {
        return Ops.m_contains(n, o)
      }))
    }
    if want.("galaxy.point")
      Measure.density(model, "galaxy.point", "gathered")
    end
    if want.("galaxy.many")
      Measure.density(model, "galaxy.many", "scattered")
    end
    if want.("law")
      Measure.law(model)
    end
  end
  __exposed
end

class GTheory < Theory
  def name(*args_)
    @name = ("G") unless instance_variable_defined?(:@name)
    args_.empty? ? @name : @name.(*args_)
  end
  attr_writer :name
  def lattice
    return Physics.BCC8
  end
  RULE_1 = Rule.new(id: "/1", name: "Annihilation", rate: "σ", over: "Edge", single: true, where: ->(it) {
    return it.active
  }, source: "\"rule /1 \\\"Annihilation\\\" | σ (x: 1 Edge{active}) => x.ANNIHILATE\"", body: ->(x) {
    return x.ANNIHILATE
  })
  RULE_2 = Rule.new(id: "/2", name: "Creation", rate: "ν", over: "Vertex", single: true, where: ->(it) {
    return it.neutral
  }, source: "\"rule /2 \\\"Creation\\\" | ν (x: Vertex{neutral}) => x.CREATE\"", body: ->(x) {
    return x.CREATE
  })
  RULE_c = Rule.new(id: "/c", name: "Movement", rate: "σ", over: "Ray", single: false, where: ->(it) {
    return it.active
  }, source: "\"rule /c \\\"Movement\\\" | σ (x: Ray{active}) => x.MOVE\"", body: ->(x) {
    return x.MOVE
  })
  RULE_4 = Rule.new(id: "/4", name: "Arrival", rate: nil, over: "Ray", single: false, where: nil, source: "\"rule /4 \\\"Arrival\\\" (x: Ray) => x.SETTLE\"", body: ->(x) {
    return x.SETTLE
  })
  RULE_S_1 = Rule.new(id: "/S.1", name: "Emission", rate: nil, over: "Boundary", single: true, where: ->(it) {
    return (it.emits && it.vertex.source.spare)
  }, source: "\"rule /S.1 \\\"Emission\\\" (x: 1 Boundary{emits & vertex.source.spare}) => {\\n  s := x.vertex.source\\n  out := x.ray.steps\\n  if out != None { ... }\\n}\"", body: ->(x) {
    s = x.vertex.source
    out = x.ray.steps
    if !Ops.eq(out, nil)
      out.activate
      s.momentum = Ops.sub(s.momentum, x.ray.along)
    end
  })
  def strip(id)
    ink = Ink.new()
    if Ops.eq(id, "rule.annihilation")
      return Strip.of(id, "two rays meet on the edge between two points and annihilate, leaving one neutral point - the other folded into it, and which way it was kept (G/1)", self, ["/1"], [Strip.meeting], ink)
    end
    return Strip.of(id, "a point nothing stands on is handed back a point of space - the one it held - and every exit it has is lit (G/2): annihilation, run backwards", self, ["/2"], [->(t) {
      return Strip.left(t, Strip.meeting, ["/1"])
    }], ink)
  end
  def movement_film
    ink = Ink.new()
    ink.every = true
    w = Strip.line(self, 10)
    Strip.light(w, 0, 1)
    lanes = [Strip.lane(w, ink)]
    8.times do |t|
      Strip.begin(w)
      Strip.run(w, ["/c", "/4"])
      Ops.m_push(lanes, Strip.lane(w, ink))
    end
    return Strip.tell("rule.movement", "every active ray goes one step along its own exit, c-bar, into its neighbour, every tick (G/c, settled by G/4)", lanes, ink)
  end
  def emission_film
    ink = Ink.new()
    ink.every = true
    ink.top = 36
    w = Strip.line(self, 17)
    w.add(Scripted.new(at: Vector.new(components: [8]), plan: ["", "+", "-", "", "+-", "", "+", "-"], weight: 1))
    lanes = [Strip.lane(w, ink)]
    8.times do |t|
      Strip.begin(w)
      Strip.run(w, ["/c", "/4"])
      moved = Strip.lane(w, ink)
      Strip.run(w, ["/S.1"])
      now = Strip.lane(w, ink)
      now.says = Strip.emitting(moved, now)
      Ops.m_push(lanes, now)
    end
    return Strip.tell("rule.emission", "a source on a line, held, choosing each tick whether to light a way and which: nothing, left, right or both - what it lights is the NEIGHBOUR's ray on that heading, and every ray already out moves on a step a tick (G/S.1, with G/c and G/4)", lanes, ink)
  end
  def transport_film
    ink = Ink.new()
    ink.every = true
    ink.top = 36
    w = Strip.line(self, 21)
    s = w.add(Scripted.new(at: Vector.new(components: [9]), plan: ["+-", "", "", "", "+-"], weight: 4))
    s.moves = true
    s.momentum = Vector.new(components: [1])
    lanes = [Strip.lane(w, ink)]
    9.times do |t|
      Strip.begin(w)
      Strip.run(w, ["/c", "/4"])
      moved = Strip.lane(w, ink)
      Strip.run(w, ["/S.1"])
      emitted = Strip.emitting(moved, Strip.lane(w, ink))
      Strip.run(w, ["/S.v"])
      now = Strip.lane(w, ink)
      went = ""
      if s.stepped
        went = (Ops.gt(Ops.elem(w.geometry.V(s.moved_along).components, 0), 0) ? "steps right" : "steps left")
      end
      now.says = (Ops.m_empty(went) ? emitted : ((Ops.m_empty(emitted) ? went : "#{went}, #{emitted}")))
      Ops.m_push(lanes, now)
    end
    return Strip.tell("rule.transport", "a source carrying a quarter of a step a tick: it stands still while the rays it lit run off at c-bar, and steps once it has earned a whole step - its choice each tick is to stand still or to go (G/S.v, with G/S.1, G/c and G/4)", lanes, ink)
  end
  def expansion
    ink = Ink.new()
    ink.every = true
    return Strip.film("space.expansion", "one point on a line and nothing else, and every rule of the vacuum run on it a tick at a time: it splits (G/2), its rays go out a step a tick (G/c), and where two meet they fold back into one (G/1) - the ends have nothing to meet and are new space, so the line grows by a point each way every tick", self, Strip.point, 8, ink)
  end
  def shadow
    env = Node.new
    Ops.setattr(env, "\\bar{m}", 1)
    _MODEL = Model.new(theory: self).value_of("b_{c}", env)
    _GR = Ops.mul(3, Ops.m_sqrt(3))
    _CRIT = [_GR, _MODEL]
    _W = 900
    _H = 420
    _SPAN = 12
    _BACK = "\#08090d"
    what = "the same mass, the same camera - general relativity left of the seam, this model right. The bright ring is where rays pile up; the dashed arcs are the two critical impact parameters, #{Fmt.fixed(_GR, 3)} and #{Fmt.fixed(_MODEL, 3)} m-bar, and the step at the seam is the #{Fmt.fixed(Ops.mul(100, (Ops.sub(Ops.div(_MODEL, _GR), 1))), 2)} per cent the metric gives"
    return Picture.still("gravity.shadow", what, _W, _H, ->(s) {
      s.clear_rect(0, 0, _W, _H)
      s.fill_style(_BACK)
      s.fill_rect(0, 0, _W, _H)
      cx = Ops.div(_W, 2)
      cy = Ops.div(_H, 2)
      k = Ops.div(Fmt.min(_W, _H), (Ops.mul(2, _SPAN)))
      s.line_width(1.6)
      2.times do |side|
        crit = Ops.elem(_CRIT, side)
        from_ = (Ops.eq(side, 0) ? Ops.div(Math::PI, 2) : Ops.sub(0, Ops.div(Math::PI, 2)))
        px = Ops.add(Ops.m_floor(Fmt.hypot(cx, cy)), 1)
        while Ops.ge(px, 0)
          b_ = Ops.div(px, k)
          colour = "rgb(0,0,0)"
          if Ops.ge(b_, crit)
            ring = Fmt.max(0, Ops.sub(1, Ops.div(Ops.m_abs((Ops.sub(b_, crit))), 0.45)))
            glow = Ops.mul(0.30, Fmt.min(1, Ops.div(3.2, (Ops.add(Ops.sub(b_, crit), 1.6)))))
            v = Fmt.min(1, Ops.add(Ops.mul(ring, 0.95), glow))
            colour = "rgb(#{Ops.m_round(Fmt.min(255, Ops.add(8, Ops.mul(v, 250))))},#{Ops.m_round(Fmt.min(255, Ops.add(9, Ops.mul(v, 175))))},#{Ops.m_round(Fmt.min(255, Ops.add(13, Ops.mul(v, 105))))})"
          end
          s.stroke_style(colour)
          s.begin_path
          s.arc(cx, cy, px, from_, Ops.add(from_, Math::PI))
          s.stroke
          px = Ops.sub(px, 1)
        end
      end
      s.stroke_style("rgba(140,147,168,0.35)")
      s.line_width(1)
      s.begin_path
      s.move_to(cx, 0)
      s.line_to(cx, _H)
      s.stroke
      s.dash([3, 4])
      s.stroke_style("rgba(140,147,168,0.65)")
      2.times do |side|
        from_ = (Ops.eq(side, 0) ? Ops.div(Math::PI, 2) : Ops.sub(0, Ops.div(Math::PI, 2)))
        s.begin_path
        s.arc(cx, cy, Ops.mul(Ops.elem(_CRIT, side), k), from_, Ops.add(from_, Math::PI))
        s.stroke
      end
      s.dash([])
      s.font("11px system-ui, sans-serif")
      s.fill_style("rgba(140,147,168,0.9)")
      s.text_align("right")
      s.fill_text("general relativity · #{Fmt.fixed(_GR, 3)} m̄", Ops.sub(cx, 10), Ops.sub(_H, 12))
      s.text_align("left")
      return s.fill_text("this model · #{Fmt.fixed(_MODEL, 3)} m̄", Ops.add(cx, 10), Ops.sub(_H, 12))
    })
  end
  def pair(id, how, what)
    _VIEW = 20
    _MARGIN = 20
    _GAP = 20
    _WAYS = 4096
    _MX = 0.00006
    _V_PASS = 0.02
    _PASS_GAP = 16
    _TICKS = (Ops.eq(how, "thrown") ? 64 : ((Ops.eq(how, "passing") ? 16 : 2)))
    _V0 = 0.3
    _RUN = (Ops.eq(how, "rest") ? 2 : ((Ops.eq(how, "passing") ? 120 : 150)))
    _K = 3
    _N = Ops.add(Ops.mul(Ops.mul(2, (Ops.add(_VIEW, _MARGIN))), _K), 1)
    coarse = Ops.add(Ops.mul(2, (Ops.add(_VIEW, _MARGIN))), 1)
    _ORBIT_R = (Ops.eq(how, "rest") ? 12 : 36)
    _NEAR_R = Ops.div(_ORBIT_R, 3)
    _BURN = Ops.mul(2, (Ops.add(_VIEW, _MARGIN)))
    _LAW = Aggregate.of(self)
    _TURNS = 3
    _MEAN_R = Ops.div((Ops.add(_ORBIT_R, _NEAR_R)), 2)
    _V_MEAN = _LAW.circling(Ops.mul(_MX, _WAYS), _MEAN_R, Ops.div(_MEAN_R, 2))
    _PERIOD = (Fmt.finite(_V_MEAN) ? Ops.div(Ops.mul((2 * Math::PI), (Ops.div(_MEAN_R, 2))), _V_MEAN) : Ops.mul(64, _RUN))
    _TICKS = (Ops.eq(how, "thrown") ? Ops.mul(2, (Ops.add(Ops.m_floor((Ops.div(Ops.mul(_TURNS, _PERIOD), Ops.mul(2, _RUN)))), 1))) : _TICKS)
    _V_ORBIT = Ops.elem(_LAW.launches([Ops.mul(_MX, _WAYS), Ops.mul(_MX, _WAYS)], [0, _ORBIT_R], [0, _NEAR_R], false, 3), 1)
    world = "#{self.lattice.name}/D#{self.lattice.D}/slice"
    stamp = "#{world}/#{coarse}/#{_WAYS}/#{_GAP}/#{_MX}/#{_TICKS}/#{_V0}/#{_VIEW}"
    stamp = (Ops.eq(how, "held") ? "#{stamp}/held/#{_N}/#{_TICKS}/#{_RUN}" : ((Ops.eq(how, "passing") ? "#{stamp}/passing/#{_V_PASS}/#{_PASS_GAP}/#{_N}/#{_TICKS}/#{_RUN}" : "#{stamp}/orbit-derived")))
    p = Setup.new(id: id, what: what, width: 900, height: 460, theory: self, view: ->(t) {
      return (Ops.eq(how, "passing") ? _VIEW : Fmt.max(Ops.add(Ops.div(_GAP, 2), 6), Fmt.min(_VIEW, Ops.add(Ops.add(Ops.div(_GAP, 2), 6), t))))
    }, place: ->(setup) {
      _R = _ORBIT_R
      _V = (Fmt.finite(_V_ORBIT) ? _V_ORBIT : 0)
      return Ops.m_map([(-1), 1], ->(sign) {
        b_ = Body.new(x: Ops.div(Ops.mul(sign, _GAP), 2), y: 0, mx: _MX, ways: _WAYS)
        b_.tag = Ops.add(Ops.div((Ops.add(sign, 1)), 2), 1)
        if (Ops.eq(how, "thrown") || Ops.eq(how, "rest"))
          b_.x = Ops.div(Ops.mul(sign, _R), 2)
          b_.y = 0
          b_.moves = true
          b_.py = (Ops.eq(how, "rest") ? 0 : Ops.sub(0, Ops.mul(Ops.mul(Ops.mul(sign, _V), _MX), _WAYS)))
          if Ops.eq(how, "thrown")
            b_.launch = "orbit"
            b_.ecc = Ops.div(Ops.sub(_ORBIT_R, _NEAR_R), Ops.add(_ORBIT_R, _NEAR_R))
            b_.py = Ops.sub(0, sign)
          end
        end
        if Ops.eq(how, "passing")
          b_.x = Ops.sub(0, Ops.mul(sign, (Ops.sub(_VIEW, 2))))
          b_.y = Ops.div(Ops.mul(sign, _PASS_GAP), 2)
          b_.moves = true
          b_.px = Ops.mul(Ops.mul(Ops.mul(sign, _V_PASS), _MX), _WAYS)
          b_.py = 0
        end
        return b_
      })
    })
    p.found = [[_ORBIT_R, _V_ORBIT, _LAW.pull(Ops.mul(_MX, _WAYS), _ORBIT_R), (Fmt.finite(_V_ORBIT) ? 1 : 0), _NEAR_R]]
    p.VIEW = _VIEW
    p.MARGIN = _MARGIN
    p.GAP = _GAP
    p.A = 8
    p.K = _K
    p.PIX = _K
    p.TICKS = _TICKS
    p.RUN = _RUN
    p.BURN = _BURN
    p.tags = 3
    p.bodies = 2
    p.stamp = stamp
    p.spent = ->(at) {
      if (Ops.eq(how, "thrown") || Ops.eq(how, "passing"))
        Ops.m_every(at, ->(b_) {
          return Ops.gt(Fmt.hypot(b_.x, b_.y), _VIEW)
        })
      end
    }
    return Panel.of(p)
  end
  def solar
    _SOLAR = Measured.of("solar-inner")
    if Ops.eq(_SOLAR, nil)
      fail.("solar-inner is not on disk - run `npx ray data` and try again")
    end
    _NAMES = Ops.getattr(_SOLAR.header, "names")
    _GM = Ops.getattr(_SOLAR.columns, "GM")
    _AX = Ops.getattr(_SOLAR.columns, "a")
    _EC = Ops.getattr(_SOLAR.columns, "e")
    _PER = Ops.getattr(_SOLAR.columns, "period")
    _RAD = Ops.getattr(_SOLAR.columns, "radius")
    _COLOUR = Node.new
    Ops.setattr(_COLOUR, "Mercury", "\#9a9a9a")
    Ops.setattr(_COLOUR, "Venus", "\#e8d3a0")
    Ops.setattr(_COLOUR, "Earth", "\#4a90e2")
    Ops.setattr(_COLOUR, "Mars", "\#c1440e")
    _PLANETS = Ops.filt(Ops.rng(_NAMES.length), ->(i) {
      return Ops.gt(Ops.elem(_PER, i), 0)
    })
    _AU = 149597870.7
    _CKM = 299792.458
    _REACH = 0
    Ops.list(_PLANETS).each do |i|
      _REACH = Fmt.max(_REACH, Ops.mul(Ops.elem(_AX, i), (Ops.add(1, Ops.elem(_EC, i)))))
    end
    _INNER = 1000000
    Ops.list(_PLANETS).each do |i|
      _INNER = Fmt.min(_INNER, Ops.elem(_AX, i))
    end
    _VIEW = Ops.m_round((Ops.div(Ops.mul(12, _REACH), _INNER)))
    _MARGIN = Ops.m_round((Ops.div(_VIEW, 3)))
    _ANGLES = 8
    _PER_C = 3
    _N = Ops.add(Ops.mul(Ops.mul(2, (Ops.add(_VIEW, _MARGIN))), _PER_C), 1)
    _CELL_AU = Ops.div(_REACH, _VIEW)
    cells = ->(au) {
      return Ops.div(au, _CELL_AU)
    }
    _TICKS = 16
    _RUN = 400
    _SUN_PULSE = 0.00006
    _WAYS_SUN = 4096
    _WAYS_PLANET = 8
    ways = ->(i) {
      return (Ops.eq(i, 0) ? _WAYS_SUN : _WAYS_PLANET)
    }
    pulse = ->(i) {
      return (Ops.eq(i, 0) ? _SUN_PULSE : Ops.div(Ops.mul(Ops.div(Ops.mul(_SUN_PULSE, _WAYS_SUN), _WAYS_PLANET), Ops.elem(_GM, i)), Ops.elem(_GM, 0)))
    }
    per_planet = Ops.m_join(Ops.m_map(_PLANETS, ->(i) {
      a_text = Fmt.fixed(Ops.elem(_AX, i), 4)
      return "#{Ops.elem(_NAMES, i)}:#{a_text}:#{ways.(i)}:#{Fmt.fixed(Ops.div(Ops.elem(_GM, i), Ops.elem(_GM, 0)), 12)}"
    }), ",")
    world = "#{self.lattice.name}/D#{self.lattice.D}/slice"
    stamp = "#{world}/#{_N}/#{_VIEW}/#{_RUN}/#{_TICKS}/#{_WAYS_SUN}/#{_SUN_PULSE}/#{_WAYS_PLANET}/#{per_planet}/solved"
    p = Setup.new(id: "solar.inner", what: "JPL's inner solar system laid on the derivation's own scale: the Sun held, each planet at its semi-major axis and launched at the circling speed the record's slope there gives (the recorder prints v times the root of R for each, one number under an inverse-square pull) - and left to the medium, so where the planets go is what the derivation says, against Kepler", width: 900, height: 460, theory: self, view: ->(t) {
      return _VIEW
    }, place: ->(setup) {
      sun = Body.new(x: 0, y: 0, mx: pulse.(0), ways: ways.(0))
      sun.tag = 1
      out = [sun]
      _PLANETS.length.times do |k|
        i = Ops.elem(_PLANETS, k)
        b_ = Body.new(x: cells.(Ops.mul(Ops.elem(_AX, i), (Ops.add(1, Ops.elem(_EC, i))))), y: 0, mx: pulse.(i), ways: ways.(i))
        b_.tag = Ops.add(2, k)
        b_.moves = true
        v = ((Ops.gt(setup.found.length, k) && Fmt.finite(Ops.elem(Ops.elem(setup.found, k), 1))) ? Ops.elem(Ops.elem(setup.found, k), 1) : 0)
        b_.py = Ops.sub(0, Ops.mul(Ops.mul(v, pulse.(i)), ways.(i)))
        b_.launch = "orbit"
        b_.ecc = Ops.elem(_EC, i)
        b_.py = Ops.sub(0, 1)
        Ops.m_push(out, b_)
      end
      return out
    })
    _BURN = Ops.mul(2, (Ops.add(_VIEW, _MARGIN)))
    _LAW = Aggregate.of(self)
    _SUN = Ops.mul(pulse.(0), ways.(0))
    _OUTER = Ops.m_last(_PLANETS)
    _A_OUT = cells.(Ops.elem(_AX, _OUTER))
    _V_OUT = _LAW.circling(_SUN, _A_OUT, _A_OUT)
    _YEAR = (Fmt.finite(_V_OUT) ? Ops.div(Ops.mul((2 * Math::PI), _A_OUT), _V_OUT) : Ops.mul(16, _RUN))
    _TICKS = Ops.add(Ops.m_floor((Ops.div(_YEAR, _RUN))), 1)
    _MASSES = Ops.m_concat([_SUN], Ops.m_map(_PLANETS, ->(i) {
      return Ops.mul(pulse.(i), ways.(i))
    }))
    _FARS = Ops.m_concat([0], Ops.m_map(_PLANETS, ->(i) {
      return cells.(Ops.mul(Ops.elem(_AX, i), (Ops.add(1, Ops.elem(_EC, i)))))
    }))
    _NEARS = Ops.m_concat([0], Ops.m_map(_PLANETS, ->(i) {
      return cells.(Ops.mul(Ops.elem(_AX, i), (Ops.sub(1, Ops.elem(_EC, i)))))
    }))
    _SPEEDS = _LAW.launches(_MASSES, _FARS, _NEARS, true, 3)
    p.found = Ops.m_map(_PLANETS, ->(i) {
      k = Ops.add(Ops.m_index_of(_PLANETS, i), 1)
      return [Ops.elem(_FARS, k), Ops.elem(_SPEEDS, k), _LAW.pull(_SUN, Ops.elem(_FARS, k)), (Ops.gt(Ops.elem(_SPEEDS, k), 0) ? 1 : 0), Ops.elem(_NEARS, k)]
    })
    p.VIEW = _VIEW
    p.MARGIN = _MARGIN
    p.A = _ANGLES
    p.K = _PER_C
    p.PIX = _PER_C
    p.TICKS = _TICKS
    p.RUN = _RUN
    p.BURN = _BURN
    p.tags = Ops.add(2, _PLANETS.length)
    p.bodies = Ops.add(1, _PLANETS.length)
    p.GAP = Ops.mul(2, _VIEW)
    p.stamp = "#{stamp}/#{_TICKS}"
    p.colours = Ops.m_map(_PLANETS, ->(i) {
      return Ops.or_else(Ops.elem(_COLOUR, Ops.elem(_NAMES, i))) { "\#eef0f5" }
    })
    p.ring = ->(k) {
      return (Ops.eq(k, 0) ? "\#f0b429" : (Ops.or_else(Ops.elem(_COLOUR, Ops.elem(_NAMES, Ops.elem(_PLANETS, Ops.sub(k, 1))))) { "\#eef0f5" }))
    }
    return Panel.of(p)
  end
